package signals

import (
	"crypto/sha256"
	"encoding/binary"
	"errors"
)

// UnitNormalizeFixed projects a non-zero integer/fixed-point vector onto the unit sphere
// of radius Scale (1_000_000), deterministically across all validators.
func UnitNormalizeFixed(vec []int64) ([]int64, error) {
	if len(vec) == 0 {
		return nil, errors.New("vector cannot be empty")
	}
	// Downscale if max abs coordinate exceeds 1_000_000 to prevent uint64 overflow in sum of squares.
	var maxAbs uint64
	for _, v := range vec {
		a := uint64(Abs64(v))
		if a > maxAbs {
			maxAbs = a
		}
	}
	if maxAbs == 0 {
		return nil, errors.New("zero vector cannot be normalized")
	}

	shift := uint(0)
	for (maxAbs >> shift) > 1000000 {
		shift++
	}

	var sqSum uint64
	for _, v := range vec {
		a := uint64(Abs64(v)) >> shift
		sqSum += a * a
	}
	norm := ISqrt64(sqSum)
	if norm == 0 {
		return nil, errors.New("zero norm after scaling")
	}

	unit := make([]int64, len(vec))
	for i, v := range vec {
		neg := v < 0
		a := uint64(Abs64(v)) >> shift
		val := int64((a * uint64(Scale)) / norm)
		if neg {
			val = -val
		}
		unit[i] = val
	}
	return unit, nil
}

func validateAndNormalizeSet(vectors [][]int64) ([][]int64, error) {
	if len(vectors) < 2 {
		return nil, errors.New("coherence requires at least 2 vectors")
	}
	dim := len(vectors[0])
	if dim == 0 {
		return nil, errors.New("vectors must have positive dimension")
	}
	units := make([][]int64, len(vectors))
	for i, v := range vectors {
		if len(v) != dim {
			return nil, errors.New("all vectors in set must share the same dimension")
		}
		u, err := UnitNormalizeFixed(v)
		if err != nil {
			return nil, err
		}
		units[i] = u
	}
	return units, nil
}

// MeanResultantLengthFixed computes ||mean(unit(v_i))|| in [0, Scale].
// Strictly order-invariant and O(n * d): 1.0*Scale when all vectors align, 0 when they cancel.
func MeanResultantLengthFixed(vectors [][]int64) (int64, error) {
	units, err := validateAndNormalizeSet(vectors)
	if err != nil {
		return 0, err
	}
	n := int64(len(units))
	dim := len(units[0])
	var sqSum uint64
	for j := 0; j < dim; j++ {
		var colSum int64
		for i := 0; i < len(units); i++ {
			colSum += units[i][j]
		}
		meanJ := colSum / n
		am := uint64(Abs64(meanJ))
		sqSum += am * am
	}
	res := int64(ISqrt64(sqSum))
	if res > Scale {
		res = Scale
	}
	return res, nil
}

// MeanPairwiseCosineFixed computes the exact mean cosine over all n*(n-1) distinct pairs
// in O(n * d) using the resultant identity: (||sum(u_i)||^2 - n) / (n * (n - 1)).
// Returns fixed-point value in [-Scale, +Scale], strictly order-invariant.
func MeanPairwiseCosineFixed(vectors [][]int64) (int64, error) {
	units, err := validateAndNormalizeSet(vectors)
	if err != nil {
		return 0, err
	}
	n := int64(len(units))
	dim := len(units[0])

	// sumNormSqFixed = ||sum(u_i)||^2 / Scale (in Scale units, where each u_i has ||u_i||^2 = Scale^2).
	var sumNormSqFixed int64
	for j := 0; j < dim; j++ {
		var colSum int64
		for i := 0; i < len(units); i++ {
			colSum += units[i][j]
		}
		sumNormSqFixed += MulFixed(colSum, colSum)
	}
	// Result = (sumNormSqFixed - n*Scale) / (n * (n - 1))
	num := sumNormSqFixed - n*Scale
	den := n * (n - 1)
	res := num / den
	if res > Scale {
		res = Scale
	}
	if res < -Scale {
		res = -Scale
	}
	return res, nil
}

// CoherenceGate evaluates whether a retrieved memory / context embedding batch is coherent
// enough to inject into an agent's reasoning window (blocking cross-session memory poisoning).
func CoherenceGate(vectors [][]int64, thresholdFixed int64, usePairwise bool) (bool, int64, SignalEvidence, error) {
	var (
		score int64
		err   error
		mode  int64
	)
	if usePairwise {
		mode = 1
		score, err = MeanPairwiseCosineFixed(vectors)
	} else {
		mode = 0
		score, err = MeanResultantLengthFixed(vectors)
	}
	if err != nil {
		return false, 0, SignalEvidence{}, err
	}
	pass := score >= thresholdFixed

	// Order-invariant digest over sorted vector hashes so input digest matches set semantics.
	inDigest := digestVectorSet(vectors)
	detail := "coherent_pass"
	if !pass {
		detail = "coherence_below_threshold"
	}
	ev := SignalEvidence{
		Primitive:    "signals.coherence_gate",
		Version:      "1",
		ParamsDigest: hashInt64s("coherence_gate", thresholdFixed, mode),
		InputDigest:  inDigest,
		OutputFixed:  score,
		Alarm:        !pass,
		Detail:       detail,
	}
	return pass, score, ev, nil
}

func digestVectorSet(vectors [][]int64) [32]byte {
	// XOR-independent canonical accumulation over vector hashes sorted lexicographically.
	hashes := make([][32]byte, len(vectors))
	for i, v := range vectors {
		buf := make([]byte, 0, 8+len(v)*8)
		buf = binary.BigEndian.AppendUint64(buf, uint64(len(v)))
		for _, x := range v {
			buf = binary.BigEndian.AppendUint64(buf, uint64(x))
		}
		hashes[i] = sha256.Sum256(buf)
	}
	// Simple deterministic insertion sort on 32-byte hashes (no extra imports needed).
	for i := 1; i < len(hashes); i++ {
		key := hashes[i]
		j := i - 1
		for j >= 0 && bytesLess(key, hashes[j]) {
			hashes[j+1] = hashes[j]
			j--
		}
		hashes[j+1] = key
	}
	all := make([]byte, 0, 16+len(hashes)*32)
	all = appendStr(all, "vecset-v1")
	for _, h := range hashes {
		all = append(all, h[:]...)
	}
	return sha256.Sum256(all)
}

func bytesLess(a, b [32]byte) bool {
	for i := 0; i < 32; i++ {
		if a[i] != b[i] {
			return a[i] < b[i]
		}
	}
	return false
}

// GeometricMedianFixed computes the deterministic fixed-point L1 Geometric Median on the
// unit sphere via Weiszfeld's iterative reweighting (50% breakdown point against coordinated
// outlier clusters; pure integer arithmetic, zero floats, strictly order-invariant).
//
// Mathematical basis: Weiszfeld (1937) / Vardi & Zhang (2000), solving sum_j (u_j - m)/||u_j - m|| = 0,
// independently validated in Experiment E5 after cross-referencing pairwise unit-difference
// relational fields (Johannes Geisen / @frintroper, Relational-Jerk-Dynamics).
func GeometricMedianFixed(vectors [][]int64, iters int) ([]int64, error) {
	units, err := validateAndNormalizeSet(vectors)
	if err != nil {
		return nil, err
	}
	if iters <= 0 {
		iters = 8
	}
	dim := len(units[0])
	n := len(units)

	// Initialize from the normalized arithmetic mean.
	sum := make([]int64, dim)
	for i := 0; i < n; i++ {
		for j := 0; j < dim; j++ {
			sum[j] += units[i][j]
		}
	}
	med, err := UnitNormalizeFixed(sum)
	if err != nil {
		// Symmetric cancellation fallback: start from first unit vector.
		med = make([]int64, dim)
		copy(med, units[0])
	}

	const epsDist int64 = 1000 // 0.001 in Scale units prevents 0/0 singularity
	for it := 0; it < iters; it++ {
		num := make([]int64, dim)
		var den int64
		for i := 0; i < n; i++ {
			var sq uint64
			for j := 0; j < dim; j++ {
				d := Abs64(units[i][j] - med[j])
				// Scale down by 1000 so d^2 fits safely inside uint64 for high dimensions.
				ds := uint64(d / 1000)
				sq += ds * ds
			}
			dist := int64(ISqrt64(sq)) * 1000
			if dist < epsDist {
				dist = epsDist
			}
			// Inverse-distance weight w = Scale^2 / dist (clamped via epsDist <= 1e9)
			w := (Scale * 1000) / (dist / 1000)
			if w <= 0 {
				w = 1
			}
			den += w
			for j := 0; j < dim; j++ {
				num[j] += (w * units[i][j]) / Scale
			}
		}
		if den == 0 {
			break
		}
		next, nErr := UnitNormalizeFixed(num)
		if nErr != nil {
			break
		}
		med = next
	}
	return med, nil
}

package signals

import "errors"

// Baseline holds fixed-point reference mean and standard deviation estimated from a quiet window.
type Baseline struct {
	MeanFixed int64
	SDFixed   int64
}

// BaselineFromSlice computes the sample mean and unbiased sample SD (ddof=1) in fixed-point.
func BaselineFromSlice(quiet []int64) (Baseline, error) {
	n := len(quiet)
	if n < 10 {
		return Baseline{}, errors.New("baseline requires at least 10 samples")
	}
	var sum int64
	for _, v := range quiet {
		sum += v
	}
	mean := sum / int64(n)

	var sqSum uint64
	for _, v := range quiet {
		d := Abs64(v - mean)
		// Compute (d*d)/Scale carefully in uint64 to retain full fixed-point variance precision.
		ud := uint64(d)
		s := uint64(Scale)
		dh, dl := ud/s, ud%s
		sqFixed := dh*dh*s + 2*dh*dl + (dl*dl)/s
		sqSum += sqFixed
	}
	varFixed := int64(sqSum / uint64(n-1))
	sd := SqrtFixed(varFixed)
	if sd < MinSDFixed {
		sd = MinSDFixed
	}
	return Baseline{MeanFixed: mean, SDFixed: sd}, nil
}

// CusumDetector implements deterministic one-sided upper CUSUM on standardized fixed-point samples:
//   z = (x - mean) / sd
//   S = max(0, S + z - k)
//   alarm when S > h
// Default k = 1*Scale targets 2-sigma upward shifts.
type CusumDetector struct {
	base   Baseline
	hFixed int64
	kFixed int64
	stat   int64
	alarms uint64
	steps  uint64
}

func NewCusum(base Baseline, hFixed, kFixed int64) (*CusumDetector, error) {
	if base.SDFixed <= 0 {
		return nil, errors.New("baseline SDFixed must be > 0")
	}
	if hFixed <= 0 {
		return nil, errors.New("threshold hFixed must be > 0")
	}
	if kFixed <= 0 {
		kFixed = Scale // default 1.0 sigma
	}
	return &CusumDetector{
		base:   base,
		hFixed: hFixed,
		kFixed: kFixed,
	}, nil
}

func (c *CusumDetector) Update(xFixed int64) (bool, int64, SignalEvidence) {
	c.steps++
	z := DivFixed(xFixed-c.base.MeanFixed, c.base.SDFixed)
	next := c.stat + z - c.kFixed
	if next < 0 {
		next = 0
	}
	c.stat = next
	alarm := c.stat > c.hFixed
	detail := "within_bound"
	if alarm {
		c.alarms++
		detail = "cusum_drift_alarm"
	}
	ev := SignalEvidence{
		Primitive:    "signals.cusum",
		Version:      "1",
		ParamsDigest: hashInt64s("cusum", c.base.MeanFixed, c.base.SDFixed, c.hFixed, c.kFixed),
		InputDigest:  hashInt64s("in", xFixed),
		OutputFixed:  c.stat,
		Alarm:        alarm,
		Detail:       detail,
	}
	return alarm, c.stat, ev
}

func (c *CusumDetector) Statistic() int64 { return c.stat }
func (c *CusumDetector) Alarms() uint64   { return c.alarms }
func (c *CusumDetector) Reset()           { c.stat = 0 }

// PageHinkleyDetector implements deterministic Page-Hinkley upward shift detection:
//   runningMean += (z - runningMean) / n
//   m += z - runningMean - delta
//   mMin = min(mMin, m)
//   alarm when (m - mMin) > lambda
type PageHinkleyDetector struct {
	base        Baseline
	lambdaFixed int64
	deltaFixed  int64
	n           int64
	runningMean int64
	m           int64
	mMin        int64
	alarms      uint64
}

func NewPageHinkley(base Baseline, lambdaFixed, deltaFixed int64) (*PageHinkleyDetector, error) {
	if base.SDFixed <= 0 {
		return nil, errors.New("baseline SDFixed must be > 0")
	}
	if lambdaFixed <= 0 {
		return nil, errors.New("lambdaFixed must be > 0")
	}
	if deltaFixed <= 0 {
		deltaFixed = 500000 // default 0.5 sigma
	}
	return &PageHinkleyDetector{
		base:        base,
		lambdaFixed: lambdaFixed,
		deltaFixed:  deltaFixed,
	}, nil
}

func (p *PageHinkleyDetector) Update(xFixed int64) (bool, int64, SignalEvidence) {
	z := DivFixed(xFixed-p.base.MeanFixed, p.base.SDFixed)
	p.n++
	p.runningMean += (z - p.runningMean) / p.n
	p.m += z - p.runningMean - p.deltaFixed
	if p.m < p.mMin {
		p.mMin = p.m
	}
	stat := p.m - p.mMin
	alarm := stat > p.lambdaFixed
	detail := "within_bound"
	if alarm {
		p.alarms++
		detail = "page_hinkley_drift_alarm"
	}
	ev := SignalEvidence{
		Primitive:    "signals.page_hinkley",
		Version:      "1",
		ParamsDigest: hashInt64s("page_hinkley", p.base.MeanFixed, p.base.SDFixed, p.lambdaFixed, p.deltaFixed),
		InputDigest:  hashInt64s("in", xFixed),
		OutputFixed:  stat,
		Alarm:        alarm,
		Detail:       detail,
	}
	return alarm, stat, ev
}

func (p *PageHinkleyDetector) Statistic() int64 { return p.m - p.mMin }
func (p *PageHinkleyDetector) Reset() {
	p.n, p.runningMean, p.m, p.mMin = 0, 0, 0, 0
}

// HampelCusumDetector composes a causal Hampel spike filter ahead of a standardized CUSUM
// detector. Isolated +/-10sigma oracle or sensor spikes are clamped before entering CUSUM,
// eliminating transient false circuit-breaker trips while still catching sustained shifts.
type HampelCusumDetector struct {
	smoother *RobustSmoother
	cusum    *CusumDetector
}

func NewHampelCusum(base Baseline, hFixed, kFixed int64, window int, hampelKFixed int64) (*HampelCusumDetector, error) {
	sm, err := NewRobustSmoother(window, hampelKFixed, Scale)
	if err != nil {
		return nil, err
	}
	cu, err := NewCusum(base, hFixed, kFixed)
	if err != nil {
		return nil, err
	}
	return &HampelCusumDetector{smoother: sm, cusum: cu}, nil
}

func (hc *HampelCusumDetector) Update(xFixed int64) (alarm bool, stat int64, spikeClamped bool, ev SignalEvidence) {
	cleaned, replaced := hc.smoother.HampelOnly(xFixed)
	alarm, stat, ev = hc.cusum.Update(cleaned)
	ev.Primitive = "signals.hampel_cusum"
	ev.InputDigest = hashInt64s("in", xFixed)
	if replaced && !alarm {
		ev.Detail = "spike_clamped_no_drift"
	}
	return alarm, stat, replaced, ev
}

func (hc *HampelCusumDetector) Statistic() int64     { return hc.cusum.Statistic() }
func (hc *HampelCusumDetector) SpikesClamped() uint64 { return hc.smoother.Replaced() }
func (hc *HampelCusumDetector) Reset()               { hc.cusum.Reset() }

package signals

import "errors"

// CausalMedian computes the trailing-window median causally (each output depends only
// on the current and past samples; initial samples warm up using the first value).
type CausalMedian struct {
	window int
	buf    []int64
}

func NewCausalMedian(window int) (*CausalMedian, error) {
	if window < 1 {
		return nil, errors.New("window must be >= 1")
	}
	return &CausalMedian{window: window}, nil
}

func (m *CausalMedian) Update(x int64) (int64, SignalEvidence) {
	if len(m.buf) == 0 {
		m.buf = make([]int64, m.window)
		for i := range m.buf {
			m.buf[i] = x
		}
	} else {
		copy(m.buf, m.buf[1:])
		m.buf[len(m.buf)-1] = x
	}
	y := MedianFixed(m.buf)
	ev := SignalEvidence{
		Primitive:    "signals.causal_median",
		Version:      "1",
		ParamsDigest: hashInt64s("causal_median", int64(m.window)),
		InputDigest:  hashInt64s("in", x),
		OutputFixed:  y,
		Alarm:        false,
		Detail:       "ok",
	}
	return y, ev
}

// RobustSmoother implements Arobi's measured-best causal filter for spiky telemetry:
// Hampel outlier rejection (default window=5, k=3.0*Scale) followed by EMA (alpha=0.2*Scale).
// Streaming Update() is bit-for-bit identical to batch Hampel -> EMA.
type RobustSmoother struct {
	window     int
	kFixed     int64
	alphaFixed int64
	buf        []int64
	hasY       bool
	y          int64
	replaced   uint64
	count      uint64
}

// NewRobustSmoother creates a deterministic causal Hampel + EMA filter.
// Defaults when zeros are passed: window=5, k=3*Scale, alpha=200_000 (0.2).
func NewRobustSmoother(window int, kFixed, alphaFixed int64) (*RobustSmoother, error) {
	if window == 0 {
		window = 5
	}
	if kFixed == 0 {
		kFixed = 3 * Scale
	}
	if alphaFixed == 0 {
		alphaFixed = 200000 // 0.2
	}
	if window < 2 {
		return nil, errors.New("window must be >= 2")
	}
	if kFixed <= 0 {
		return nil, errors.New("kFixed must be > 0")
	}
	if alphaFixed <= 0 || alphaFixed > Scale {
		return nil, errors.New("alphaFixed must be in (0, Scale]")
	}
	return &RobustSmoother{
		window:     window,
		kFixed:     kFixed,
		alphaFixed: alphaFixed,
	}, nil
}

// Update processes one fixed-point sample x and returns (smoothedY, wasOutlier, SignalEvidence).
func (r *RobustSmoother) Update(x int64) (int64, bool, SignalEvidence) {
	if len(r.buf) == 0 {
		r.buf = make([]int64, r.window)
		for i := range r.buf {
			r.buf[i] = x
		}
	} else {
		copy(r.buf, r.buf[1:])
		r.buf[len(r.buf)-1] = x
	}
	r.count++

	med := MedianFixed(r.buf)
	absDevs := make([]int64, len(r.buf))
	for i, v := range r.buf {
		absDevs[i] = Abs64(v - med)
	}
	mad := MulFixed(MADScale, MedianFixed(absDevs))
	if mad < MinSDFixed {
		mad = MinSDFixed
	}
	thresh := MulFixed(r.kFixed, mad)

	cleaned := x
	outlier := Abs64(x-med) > thresh
	if outlier {
		cleaned = med
		r.replaced++
	}

	if !r.hasY {
		r.y = cleaned
		r.hasY = true
	} else {
		// y_t = alpha*cleaned + (1 - alpha)*y_{t-1}
		r.y = MulFixed(r.alphaFixed, cleaned) + MulFixed(Scale-r.alphaFixed, r.y)
	}

	detail := "clean"
	if outlier {
		detail = "spike_replaced"
	}
	ev := SignalEvidence{
		Primitive:    "signals.robust_smooth",
		Version:      "1",
		ParamsDigest: hashInt64s("robust_smooth", int64(r.window), r.kFixed, r.alphaFixed),
		InputDigest:  hashInt64s("in", x),
		OutputFixed:  r.y,
		Alarm:        outlier,
		Detail:       detail,
	}
	return r.y, outlier, ev
}

// HampelOnly processes one sample through the Hampel spike gate without EMA lag.
// Ideal as a spike-resistant pre-filter ahead of CUSUM drift detection.
func (r *RobustSmoother) HampelOnly(x int64) (int64, bool) {
	if len(r.buf) == 0 {
		r.buf = make([]int64, r.window)
		for i := range r.buf {
			r.buf[i] = x
		}
	} else {
		copy(r.buf, r.buf[1:])
		r.buf[len(r.buf)-1] = x
	}
	r.count++
	med := MedianFixed(r.buf)
	absDevs := make([]int64, len(r.buf))
	for i, v := range r.buf {
		absDevs[i] = Abs64(v - med)
	}
	mad := MulFixed(MADScale, MedianFixed(absDevs))
	if mad < MinSDFixed {
		mad = MinSDFixed
	}
	if Abs64(x-med) > MulFixed(r.kFixed, mad) {
		r.replaced++
		return med, true
	}
	return x, false
}

// Replaced returns how many spike samples were replaced so far.
func (r *RobustSmoother) Replaced() uint64 {
	return r.replaced
}

// Value returns the latest smoothed output.
func (r *RobustSmoother) Value() int64 {
	return r.y
}

// BatchRobustSmooth applies RobustSmoother across an entire slice and returns the smoothed series.
func BatchRobustSmooth(series []int64, window int, kFixed, alphaFixed int64) ([]int64, uint64, error) {
	if len(series) == 0 {
		return nil, 0, errors.New("series cannot be empty")
	}
	sm, err := NewRobustSmoother(window, kFixed, alphaFixed)
	if err != nil {
		return nil, 0, err
	}
	out := make([]int64, len(series))
	for i, v := range series {
		y, _, _ := sm.Update(v)
		out[i] = y
	}
	return out, sm.Replaced(), nil
}

// Package signals implements consensus-safe, deterministic fixed-point statistical
// assurance primitives in pure Gno (zero floating-point operations).
//
// All values use fixed-point micro-units (Scale = 1_000_000, i.e. 1.0 == 1_000_000).
// Every primitive can emit a canonically encoded SignalEvidence record whose RFC 6962
// leaf hash chains directly into gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance accumulators.
package signals

import (
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
)

const (
	// Scale is 1.0 in fixed-point micro-units (6 decimal digits).
	Scale int64 = 1000000
	// MADScale is 1.4826 * Scale, making MAD a consistent Gaussian sigma estimator.
	MADScale int64 = 1482600
	// MinSDFixed prevents division by zero on flat telemetry baselines (1e-6).
	MinSDFixed int64 = 1
)

// Abs64 returns |x| for int64 (safe for normal fixed-point ranges).
func Abs64(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

// MulFixed computes round-toward-zero (a * b) / Scale using split-word arithmetic
// to avoid intermediate int64 overflow for large fixed-point operands.
func MulFixed(a, b int64) int64 {
	neg := false
	var ua, ub uint64
	if a < 0 {
		neg = !neg
		ua = uint64(-a)
	} else {
		ua = uint64(a)
	}
	if b < 0 {
		neg = !neg
		ub = uint64(-b)
	} else {
		ub = uint64(b)
	}
	s := uint64(Scale)
	ah, al := ua/s, ua%s
	bh, bl := ub/s, ub%s
	// (ah*s + al)*(bh*s + bl) / s = ah*bh*s + ah*bl + al*bh + (al*bl)/s
	res := ah*bh*s + ah*bl + al*bh + (al*bl)/s
	if neg {
		return -int64(res)
	}
	return int64(res)
}

// DivFixed computes (a * Scale) / b with overflow-safe splitting on a.
func DivFixed(a, b int64) int64 {
	if b == 0 {
		panic("signals: division by zero")
	}
	neg := false
	var ua, ub uint64
	if a < 0 {
		neg = !neg
		ua = uint64(-a)
	} else {
		ua = uint64(a)
	}
	if b < 0 {
		neg = !neg
		ub = uint64(-b)
	} else {
		ub = uint64(b)
	}
	s := uint64(Scale)
	// Write ua = q*ub + r, then (ua*s)/ub = q*s + (r*s)/ub.
	q := ua / ub
	r := ua % ub
	var frac uint64
	if r <= (^uint64(0))/s {
		frac = (r * s) / ub
	} else {
		// Fallback for huge remainders (ub > ~1.8e13): scale down both safely.
		frac = ((r / 1000) * s) / (ub / 1000)
	}
	res := q*s + frac
	if neg {
		return -int64(res)
	}
	return int64(res)
}

// ISqrt64 returns floor(sqrt(n)) deterministically using Newton's method.
func ISqrt64(n uint64) uint64 {
	if n < 2 {
		return n
	}
	// Initial power-of-two upper estimate.
	x := uint64(1)
	tmp := n
	for tmp > 0 {
		tmp >>= 2
		x <<= 1
	}
	for {
		next := (x + n/x) >> 1
		if next >= x {
			return x
		}
		x = next
	}
}

// SqrtFixed computes sqrt(xFixed) in fixed-point Scale units (xFixed >= 0).
// sqrt(x * Scale) * sqrt(Scale) == sqrt(xFixed * Scale).
func SqrtFixed(xFixed int64) int64 {
	if xFixed <= 0 {
		return 0
	}
	u := uint64(xFixed)
	s := uint64(Scale)
	if u <= (^uint64(0))/s {
		return int64(ISqrt64(u * s))
	}
	// For very large xFixed (> 1.8e13), sqrt(u) * sqrt(Scale) = sqrt(u) * 1000.
	return int64(ISqrt64(u) * 1000)
}

// MedianFixed computes the exact deterministic median of a non-empty int64 slice.
func MedianFixed(vals []int64) int64 {
	n := len(vals)
	if n == 0 {
		return 0
	}
	cp := make([]int64, n)
	copy(cp, vals)
	for i := 1; i < n; i++ {
		key := cp[i]
		j := i - 1
		for j >= 0 && cp[j] > key {
			cp[j+1] = cp[j]
			j--
		}
		cp[j+1] = key
	}
	mid := n / 2
	if n%2 == 1 {
		return cp[mid]
	}
	// Overflow-safe average of two middle elements.
	a, b := cp[mid-1], cp[mid]
	return a + (b-a)/2
}

// SignalEvidence is the tamper-evident audit record emitted by any deterministic primitive.
type SignalEvidence struct {
	Primitive    string
	Version      string
	ParamsDigest [32]byte
	InputDigest  [32]byte
	OutputFixed  int64
	Alarm        bool
	Detail       string
}

const (
	DomainSignalEvidence = "arobi-signal-evidence-v1"
	SignalEncodingVer    = uint8(1)
)

// Encode serializes SignalEvidence into canonical big-endian bytes.
func (e SignalEvidence) Encode() []byte {
	out := make([]byte, 0, 160)
	out = appendStr(out, DomainSignalEvidence)
	out = append(out, SignalEncodingVer)
	out = appendStr(out, e.Primitive)
	out = appendStr(out, e.Version)
	out = append(out, e.ParamsDigest[:]...)
	out = append(out, e.InputDigest[:]...)
	out = binary.BigEndian.AppendUint64(out, uint64(e.OutputFixed))
	if e.Alarm {
		out = append(out, 1)
	} else {
		out = append(out, 0)
	}
	out = appendStr(out, e.Detail)
	return out
}

// LeafHash computes the RFC 6962 leaf hash SHA-256(0x00 || Encode()).
func (e SignalEvidence) LeafHash() [32]byte {
	raw := e.Encode()
	buf := make([]byte, 0, 1+len(raw))
	buf = append(buf, 0x00)
	buf = append(buf, raw...)
	return sha256.Sum256(buf)
}

// Hex formats a 32-byte digest as 64 lowercase hex chars.
func Hex(d [32]byte) string {
	return hex.EncodeToString(d[:])
}

func hashInt64s(domain string, vals ...int64) [32]byte {
	buf := make([]byte, 0, len(domain)+8+len(vals)*8)
	buf = appendStr(buf, domain)
	for _, v := range vals {
		buf = binary.BigEndian.AppendUint64(buf, uint64(v))
	}
	return sha256.Sum256(buf)
}

func appendStr(out []byte, s string) []byte {
	out = binary.BigEndian.AppendUint32(out, uint32(len(s)))
	return append(out, []byte(s)...)
}

// Package assurance implements the Arobi Assurance Agent SDK natively in Gno.
//
// Every agent tool invocation passes through a deterministic, fail-closed pipeline:
//
//   PolicyInputProjection -> PolicyEngine -> DecisionReceipt
//        -> EffectWarrant (single-use) -> ToolHandler -> EffectClosure
//        -> RFC 6962 / RFC 9162 Merkle Accumulator -> Gno.land Anchor
//
// Plaintext secrets never need to touch the chain: every receipt and closure is
// canonically binary-encoded, SHA-256 domain-separated, hash-chained, and provable
// offline with zero trust in the executor.
package assurance

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
)

var (
	errDigest     = errors.New("digest must be 64 lowercase hexadecimal characters")
	errProofRange = errors.New("index must be below size, and size at most the number of leaves")
)

// HashBytes returns SHA-256(data).
func HashBytes(data []byte) [32]byte {
	return sha256.Sum256(data)
}

// HashString returns SHA-256([]byte(s)).
func HashString(s string) [32]byte {
	return sha256.Sum256([]byte(s))
}

// LeafHash is the RFC 6962 / RFC 9162 leaf hash: SHA-256(0x00 || data).
func LeafHash(data []byte) [32]byte {
	buf := make([]byte, 0, 1+len(data))
	buf = append(buf, 0x00)
	buf = append(buf, data...)
	return sha256.Sum256(buf)
}

// NodeHash is the RFC 6962 / RFC 9162 interior node hash: SHA-256(0x01 || left || right).
func NodeHash(left, right [32]byte) [32]byte {
	buf := make([]byte, 0, 65)
	buf = append(buf, 0x01)
	buf = append(buf, left[:]...)
	buf = append(buf, right[:]...)
	return sha256.Sum256(buf)
}

// ParseDigest parses a 64-character lowercase hexadecimal SHA-256 digest.
func ParseDigest(s string) ([32]byte, error) {
	var d [32]byte
	if len(s) != 64 {
		return d, errDigest
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			return d, errDigest
		}
	}
	b, err := hex.DecodeString(s)
	if err != nil {
		return d, errDigest
	}
	copy(d[:], b)
	return d, nil
}

// Hex formats a 32-byte digest as 64 lowercase hexadecimal characters.
func Hex(d [32]byte) string {
	return hex.EncodeToString(d[:])
}

// ZeroDigest returns the all-zero 32-byte digest.
func ZeroDigest() [32]byte {
	return [32]byte{}
}

// Accumulator is an append-only RFC 6962 / RFC 9162 Merkle tree over 32-byte leaf hashes.
// It maintains a compact power-of-two frontier for O(log n) Root() updates while keeping
// all leaves so historical inclusion proofs can be reconstructed at any past tree size.
type Accumulator struct {
	leaves   [][32]byte
	frontier []subtree
}

type subtree struct {
	hash [32]byte
	size uint64
}

// Size returns the number of appended leaves.
func (a *Accumulator) Size() uint64 {
	return uint64(len(a.leaves))
}

// Append adds a leaf hash and returns its 0-based index.
func (a *Accumulator) Append(leaf [32]byte) uint64 {
	index := uint64(len(a.leaves))
	a.leaves = append(a.leaves, leaf)
	a.frontier = append(a.frontier, subtree{hash: leaf, size: 1})
	for len(a.frontier) >= 2 {
		n := len(a.frontier)
		left, right := a.frontier[n-2], a.frontier[n-1]
		if left.size != right.size {
			break
		}
		a.frontier = append(a.frontier[:n-2], subtree{
			hash: NodeHash(left.hash, right.hash),
			size: left.size * 2,
		})
	}
	return index
}

// Root returns the RFC 6962 Merkle Tree Head over every leaf appended so far.
// The empty tree root is SHA-256("").
func (a *Accumulator) Root() [32]byte {
	n := len(a.frontier)
	if n == 0 {
		return sha256.Sum256(nil)
	}
	root := a.frontier[n-1].hash
	for i := n - 2; i >= 0; i-- {
		root = NodeHash(a.frontier[i].hash, root)
	}
	return root
}

// Leaf returns the leaf hash at index.
func (a *Accumulator) Leaf(index uint64) ([32]byte, bool) {
	if index >= uint64(len(a.leaves)) {
		return [32]byte{}, false
	}
	return a.leaves[index], true
}

// RootAt returns the Merkle Tree Head over the first size leaves.
func (a *Accumulator) RootAt(size uint64) ([32]byte, error) {
	if size > uint64(len(a.leaves)) {
		return [32]byte{}, errProofRange
	}
	return mth(a.leaves[:size]), nil
}

// Proof returns the RFC 6962 audit path for leaf index in a tree of size leaves.
func (a *Accumulator) Proof(index, size uint64) ([][32]byte, error) {
	if index >= size || size > uint64(len(a.leaves)) {
		return nil, errProofRange
	}
	return auditPath(int(index), a.leaves[:size]), nil
}

// VerifyInclusion verifies an RFC 9162 section 2.1.3.2 inclusion proof against root.
func VerifyInclusion(index, size uint64, leaf [32]byte, proof [][32]byte, root [32]byte) bool {
	if index >= size {
		return false
	}
	fn, sn := index, size-1
	r := leaf
	for _, p := range proof {
		if sn == 0 {
			return false
		}
		if fn&1 == 1 || fn == sn {
			r = NodeHash(p, r)
			if fn&1 == 0 {
				for fn&1 == 0 && fn != 0 {
					fn >>= 1
					sn >>= 1
				}
			}
		} else {
			r = NodeHash(r, p)
		}
		fn >>= 1
		sn >>= 1
	}
	return sn == 0 && r == root
}

func mth(leaves [][32]byte) [32]byte {
	n := len(leaves)
	if n == 0 {
		return sha256.Sum256(nil)
	}
	if n == 1 {
		return leaves[0]
	}
	k := splitPoint(n)
	return NodeHash(mth(leaves[:k]), mth(leaves[k:]))
}

func auditPath(m int, leaves [][32]byte) [][32]byte {
	n := len(leaves)
	if n <= 1 {
		return nil
	}
	k := splitPoint(n)
	if m < k {
		return append(auditPath(m, leaves[:k]), mth(leaves[k:]))
	}
	return append(auditPath(m-k, leaves[k:]), mth(leaves[:k]))
}

func splitPoint(n int) int {
	k := 1
	for k*2 < n {
		k *= 2
	}
	return k
}

package assurance

import (
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"strconv"

	"gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/signals"
)

// DriftGuardPolicy is a stateful, deterministic behavioral drift circuit breaker
// powered by gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/signals.
//
// It monitors each action's spend/budget stream (in fixed-point Scale units) through
// either a Hampel-guarded CUSUM detector (default when HampelWindow >= 2, rejecting
// single-tick +/-10sigma spikes) or raw CUSUM. On sustained behavioral drift above
// threshold hFixed, it fails closed with VerdictEscalate (or VerdictDeny if StrictDeny).
type DriftGuardPolicy struct {
	PolicyID     string
	Base         signals.Baseline
	HFixed       int64
	KFixed       int64
	HampelWindow int
	HampelKFixed int64
	StrictDeny   bool
	LatchOnAlarm bool

	latched    bool
	hc         *signals.HampelCusumDetector
	raw        *signals.CusumDetector
	lastEv     signals.SignalEvidence
	hasLastEv  bool
	alarmCount uint64
}

// NewDriftGuardPolicy constructs a deterministic drift circuit breaker policy.
func NewDriftGuardPolicy(
	policyID string,
	base signals.Baseline,
	hFixed int64,
	kFixed int64,
	hampelWindow int,
	hampelKFixed int64,
	strictDeny bool,
	latchOnAlarm bool,
) (*DriftGuardPolicy, error) {
	if policyID == "" {
		policyID = "drift-guard-v1"
	}
	if kFixed <= 0 {
		kFixed = signals.Scale
	}
	p := &DriftGuardPolicy{
		PolicyID:     policyID,
		Base:         base,
		HFixed:       hFixed,
		KFixed:       kFixed,
		HampelWindow: hampelWindow,
		HampelKFixed: hampelKFixed,
		StrictDeny:   strictDeny,
		LatchOnAlarm: latchOnAlarm,
	}
	if hampelWindow >= 2 {
		if hampelKFixed <= 0 {
			hampelKFixed = 3 * signals.Scale
		}
		p.HampelKFixed = hampelKFixed
		hc, err := signals.NewHampelCusum(base, hFixed, kFixed, hampelWindow, hampelKFixed)
		if err != nil {
			return nil, err
		}
		p.hc = hc
	} else {
		cu, err := signals.NewCusum(base, hFixed, kFixed)
		if err != nil {
			return nil, err
		}
		p.raw = cu
	}
	return p, nil
}

func (p *DriftGuardPolicy) ID() string {
	if p.PolicyID != "" {
		return p.PolicyID
	}
	return "drift-guard-v1"
}

func (p *DriftGuardPolicy) Digest() [32]byte {
	out := make([]byte, 0, 112)
	out = appendString(out, "policy:drift-guard-v1")
	out = appendString(out, p.ID())
	out = binary.BigEndian.AppendUint64(out, uint64(p.Base.MeanFixed))
	out = binary.BigEndian.AppendUint64(out, uint64(p.Base.SDFixed))
	out = binary.BigEndian.AppendUint64(out, uint64(p.HFixed))
	out = binary.BigEndian.AppendUint64(out, uint64(p.KFixed))
	out = binary.BigEndian.AppendUint64(out, uint64(p.HampelWindow))
	out = binary.BigEndian.AppendUint64(out, uint64(p.HampelKFixed))
	out = append(out, boolByte(p.StrictDeny), boolByte(p.LatchOnAlarm))
	return sha256.Sum256(out)
}

func (p *DriftGuardPolicy) Evaluate(in PolicyInputProjection) PolicyDecision {
	d := p.Digest()
	verdict := VerdictEscalate
	if p.StrictDeny {
		verdict = VerdictDeny
	}
	if p.latched {
		return PolicyDecision{
			Verdict:      verdict,
			PolicyID:     p.ID(),
			PolicyDigest: d,
			ReasonCode:   "DRIFT_CIRCUIT_BREAKER_LATCHED",
			Reason:       "agent halted by latched behavioral drift circuit breaker; principal reset required",
		}
	}

	xFixed := in.BudgetUgnot * signals.Scale
	var (
		alarm bool
		stat  int64
		ev    signals.SignalEvidence
	)
	if p.hc != nil {
		alarm, stat, _, ev = p.hc.Update(xFixed)
	} else if p.raw != nil {
		alarm, stat, ev = p.raw.Update(xFixed)
	} else {
		return PolicyDecision{
			Verdict:      VerdictDeny,
			PolicyID:     p.ID(),
			PolicyDigest: d,
			ReasonCode:   "DRIFT_DETECTOR_UNINITIALIZED",
			Reason:       "uninitialized drift detector fails closed",
		}
	}
	p.lastEv = ev
	p.hasLastEv = true

	if alarm {
		p.alarmCount++
		if p.LatchOnAlarm {
			p.latched = true
		}
		return PolicyDecision{
			Verdict:      verdict,
			PolicyID:     p.ID(),
			PolicyDigest: d,
			ReasonCode:   "BEHAVIORAL_DRIFT_ALARM",
			Reason:       "behavioral drift statistic " + strconv.FormatInt(stat, 10) + " exceeded threshold " + strconv.FormatInt(p.HFixed, 10),
		}
	}
	return PolicyDecision{
		Verdict:       VerdictAllow,
		PolicyID:      p.ID(),
		PolicyDigest:  d,
		ReasonCode:    "DRIFT_WITHIN_BOUNDS",
		Reason:        "behavioral telemetry within calibrated baseline",
		MaxSpendUgnot: in.BudgetUgnot,
	}
}

// Reset clears a latched circuit breaker and zeroes the CUSUM accumulator (principal action).
func (p *DriftGuardPolicy) Reset() {
	p.latched = false
	if p.hc != nil {
		p.hc.Reset()
	}
	if p.raw != nil {
		p.raw.Reset()
	}
}

func (p *DriftGuardPolicy) Latched() bool                       { return p.latched }
func (p *DriftGuardPolicy) AlarmCount() uint64                  { return p.alarmCount }
func (p *DriftGuardPolicy) LastEvidence() (signals.SignalEvidence, bool) { return p.lastEv, p.hasLastEv }
func (p *DriftGuardPolicy) Statistic() int64 {
	if p.hc != nil {
		return p.hc.Statistic()
	}
	if p.raw != nil {
		return p.raw.Statistic()
	}
	return 0
}

// CoherenceGuardPolicy enforces pre-action memory/context coherence using deterministic
// spherical coherence (MeanResultantLength or MeanPairwiseCosine in gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/signals).
//
// Prevents cross-session memory poisoning and context-injection attacks: if a pending
// context batch scores below ThresholdFixed, execution fails closed before side effects.
type CoherenceGuardPolicy struct {
	PolicyID         string
	ThresholdFixed   int64
	UsePairwise      bool
	StrictDeny       bool
	RequireOnAllCall bool // if true, missing context vectors fails closed

	hasPending bool
	pendingOk  bool
	pendingSc  int64
	lastEv     signals.SignalEvidence
	hasLastEv  bool
}

func NewCoherenceGuardPolicy(policyID string, thresholdFixed int64, usePairwise, strictDeny, requireOnAllCall bool) (*CoherenceGuardPolicy, error) {
	if thresholdFixed < -signals.Scale || thresholdFixed > signals.Scale {
		return nil, errors.New("thresholdFixed out of [-Scale, Scale] range")
	}
	if policyID == "" {
		policyID = "coherence-guard-v1"
	}
	return &CoherenceGuardPolicy{
		PolicyID:         policyID,
		ThresholdFixed:   thresholdFixed,
		UsePairwise:      usePairwise,
		StrictDeny:       strictDeny,
		RequireOnAllCall: requireOnAllCall,
	}, nil
}

// StageContext evaluates contextVectors deterministically and stages the result for the next Execute().
func (c *CoherenceGuardPolicy) StageContext(vectors [][]int64) (bool, int64, signals.SignalEvidence, error) {
	ok, score, ev, err := signals.CoherenceGate(vectors, c.ThresholdFixed, c.UsePairwise)
	if err != nil {
		c.hasPending = true
		c.pendingOk = false
		c.pendingSc = 0
		return false, 0, signals.SignalEvidence{}, err
	}
	c.hasPending = true
	c.pendingOk = ok
	c.pendingSc = score
	c.lastEv = ev
	c.hasLastEv = true
	return ok, score, ev, nil
}

// StageScore stages a pre-computed deterministic coherence score (useful for lightweight on-chain calls).
func (c *CoherenceGuardPolicy) StageScore(scoreFixed int64) {
	c.hasPending = true
	c.pendingSc = scoreFixed
	c.pendingOk = scoreFixed >= c.ThresholdFixed
}

func (c *CoherenceGuardPolicy) ID() string {
	if c.PolicyID != "" {
		return c.PolicyID
	}
	return "coherence-guard-v1"
}

func (c *CoherenceGuardPolicy) Digest() [32]byte {
	out := make([]byte, 0, 80)
	out = appendString(out, "policy:coherence-guard-v1")
	out = appendString(out, c.ID())
	out = binary.BigEndian.AppendUint64(out, uint64(c.ThresholdFixed))
	out = append(out, boolByte(c.UsePairwise), boolByte(c.StrictDeny), boolByte(c.RequireOnAllCall))
	return sha256.Sum256(out)
}

func (c *CoherenceGuardPolicy) Evaluate(in PolicyInputProjection) PolicyDecision {
	d := c.Digest()
	verdict := VerdictRequireApproval
	if c.StrictDeny {
		verdict = VerdictDeny
	}

	// Consume staged context once so stale coherence scores can never be replayed across calls.
	staged := c.hasPending
	ok := c.pendingOk
	score := c.pendingSc
	c.hasPending = false
	c.pendingOk = false
	c.pendingSc = 0

	if !staged {
		if c.RequireOnAllCall {
			return PolicyDecision{
				Verdict:      verdict,
				PolicyID:     c.ID(),
				PolicyDigest: d,
				ReasonCode:   "CONTEXT_COHERENCE_MISSING",
				Reason:       "coherence guard requires staged context embeddings before execution",
			}
		}
		return PolicyDecision{
			Verdict:       VerdictAllow,
			PolicyID:      c.ID(),
			PolicyDigest:  d,
			ReasonCode:    "COHERENCE_NOT_REQUIRED",
			Reason:        "no context batch attached",
			MaxSpendUgnot: in.BudgetUgnot,
		}
	}

	if !ok {
		return PolicyDecision{
			Verdict:      verdict,
			PolicyID:     c.ID(),
			PolicyDigest: d,
			ReasonCode:   "CONTEXT_COHERENCE_LOW",
			Reason:       "context coherence " + strconv.FormatInt(score, 10) + " below threshold " + strconv.FormatInt(c.ThresholdFixed, 10) + " (possible memory poisoning)",
		}
	}
	return PolicyDecision{
		Verdict:       VerdictAllow,
		PolicyID:      c.ID(),
		PolicyDigest:  d,
		ReasonCode:    "CONTEXT_COHERENT",
		Reason:        "retrieved context passed spherical coherence gate",
		MaxSpendUgnot: in.BudgetUgnot,
	}
}

func (c *CoherenceGuardPolicy) LastEvidence() (signals.SignalEvidence, bool) {
	return c.lastEv, c.hasLastEv
}

package assurance

import (
	"errors"
	"strconv"
)

// MinSamplesForMeasuredScore mirrors Arobi's measured-assurance discipline:
// never invent fake constant scores when real activity is below threshold.
const MinSamplesForMeasuredScore uint64 = 3

// ToolSpec declares a governed capability exposed by an Agent.
type ToolSpec struct {
	Name           string
	Description    string
	RiskTier       RiskTier
	MaxBudgetUgnot int64
}

// ToolHandler executes a governed effect after receiving a freshly minted EffectWarrant.
// It returns output bytes, optional independent witness bytes, actual ugnot spent, and any error.
type ToolHandler func(w EffectWarrant, input []byte) (output []byte, witness []byte, spentUgnot int64, err error)

type registeredTool struct {
	spec    ToolSpec
	handler ToolHandler
}

// AgentConfig configures an Arobi-assured Gno Agent runtime.
type AgentConfig struct {
	AgentID          string
	ChainID          string
	Realm            string
	Principal        string
	WarrantTTLBlocks int64
}

// CheckpointSummary is the compact evidence state submitted to gno.land/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance.
type CheckpointSummary struct {
	AgentID        string
	CheckpointRoot [32]byte
	LastHash       [32]byte
	LeafCount      uint64
	ReceiptCount   uint64
	ClosureCount   uint64
}

// AssuranceMetrics reports strictly measured assurance factors derived from real receipts.
// If Measured is false, the factor has too few samples and must be displayed as UNMEASURED.
type AssuranceMetrics struct {
	Measured            bool
	TotalDecisions      uint64
	AllowedDecisions    uint64
	RefusedDecisions    uint64
	ExecutedClosures    uint64
	FailedClosures      uint64
	GovernanceBps       uint64 // 0..10000: warranted & policy-gated / total
	ClosureIntegrityBps uint64 // 0..10000: cleanly executed closures / allowed decisions
	RefusalIntegrityBps uint64 // 0..10000: clean refusals with zero spend / refused decisions
	AnchorLagBlocks     int64  // -1 if never anchored
}

// Agent is the out-of-the-box Arobi Assurance SDK runtime in Gno.
// Every action emits a hash-chained DecisionReceipt and EffectClosure inside an
// RFC 6962 Merkle Accumulator ready for anchoring on gno.land.
type Agent struct {
	cfg      AgentConfig
	policy   Policy
	paused   bool
	tools    []registeredTool
	seq      uint64
	warrantN uint64
	lastHash [32]byte
	acc      Accumulator
	receipts []DecisionReceipt
	closures []EffectClosure
	warrants []EffectWarrant
	// Track order of leaf types ("receipt" or "closure") so VerifyChain can walk linearly.
	chainKinds []string
}

// NewAgent creates a governed agent runtime with fail-closed defaults.
func NewAgent(cfg AgentConfig, policy Policy) *Agent {
	if cfg.WarrantTTLBlocks <= 0 {
		cfg.WarrantTTLBlocks = 5
	}
	return &Agent{
		cfg:    cfg,
		policy: policy,
	}
}

// Config returns the agent's configuration.
func (a *Agent) Config() AgentConfig {
	return a.cfg
}

// PolicyDigest returns the current policy's digest, or zero if unset (fail-closed).
func (a *Agent) PolicyDigest() [32]byte {
	if a.policy == nil {
		return ZeroDigest()
	}
	return a.policy.Digest()
}

// SetPolicy updates the agent's active policy.
func (a *Agent) SetPolicy(policy Policy) {
	a.policy = policy
}

// Pause halts all tool execution (new requests record fail-closed refusal receipts).
func (a *Agent) Pause() {
	a.paused = true
}

// Resume re-enables governed tool execution.
func (a *Agent) Resume() {
	a.paused = false
}

// RegisterTool registers a named tool and handler with its RiskTier and spend ceiling.
func (a *Agent) RegisterTool(spec ToolSpec, handler ToolHandler) error {
	if spec.Name == "" {
		return errors.New("tool name is required")
	}
	if handler == nil {
		return errors.New("tool handler is required")
	}
	if spec.RiskTier == "" {
		spec.RiskTier = RiskMedium
	}
	if spec.MaxBudgetUgnot < 0 {
		return errors.New("tool max budget cannot be negative")
	}
	for i := range a.tools {
		if a.tools[i].spec.Name == spec.Name {
			a.tools[i] = registeredTool{spec: spec, handler: handler}
			return nil
		}
	}
	a.tools = append(a.tools, registeredTool{spec: spec, handler: handler})
	return nil
}

func (a *Agent) findTool(name string) (registeredTool, bool) {
	for i := range a.tools {
		if a.tools[i].spec.Name == name {
			return a.tools[i], true
		}
	}
	return registeredTool{}, false
}

// Execute runs a governed tool invocation through the complete Arobi Assurance pipeline:
// projection -> fail-closed policy gate -> hash-chained DecisionReceipt -> single-use
// EffectWarrant -> execution -> EffectClosure -> RFC 6962 proofs in EvidenceBundle.
func (a *Agent) Execute(
	caller string,
	action string,
	target string,
	input []byte,
	contextBytes []byte,
	budgetUgnot int64,
	height int64,
) ([]byte, EvidenceBundle, error) {
	tool, hasTool := a.findTool(action)
	risk := RiskHigh
	if hasTool {
		risk = tool.spec.RiskTier
	}

	proj := PolicyInputProjection{
		ChainID:       a.cfg.ChainID,
		Realm:         a.cfg.Realm,
		AgentID:       a.cfg.AgentID,
		Principal:     a.cfg.Principal,
		Caller:        caller,
		Action:        action,
		Target:        target,
		InputDigest:   HashBytes(input),
		ContextDigest: HashBytes(contextBytes),
		BudgetUgnot:   budgetUgnot,
		RiskTier:      risk,
		Height:        height,
	}
	projDigest := proj.Digest()

	// Step 1: Fail-closed policy evaluation.
	var dec PolicyDecision
	switch {
	case a.paused:
		dec = PolicyDecision{
			Verdict:      VerdictDeny,
			PolicyID:     "runtime-killswitch",
			PolicyDigest: a.PolicyDigest(),
			ReasonCode:   "AGENT_PAUSED",
			Reason:       "agent is paused by governance kill switch",
		}
	case !hasTool:
		dec = PolicyDecision{
			Verdict:      VerdictDeny,
			PolicyID:     "runtime-registry",
			PolicyDigest: a.PolicyDigest(),
			ReasonCode:   "TOOL_UNREGISTERED",
			Reason:       "tool " + action + " is not registered",
		}
	case a.policy == nil:
		dec = PolicyDecision{
			Verdict:      VerdictDeny,
			PolicyID:     "runtime-fail-closed",
			PolicyDigest: ZeroDigest(),
			ReasonCode:   "POLICY_UNSET",
			Reason:       "no policy configured; failing closed",
		}
	case budgetUgnot > tool.spec.MaxBudgetUgnot:
		dec = PolicyDecision{
			Verdict:      VerdictDeny,
			PolicyID:     "tool-spec-cap",
			PolicyDigest: a.policy.Digest(),
			ReasonCode:   "TOOL_BUDGET_EXCEEDED",
			Reason:       "budget exceeds tool spec ceiling",
		}
	default:
		dec = a.policy.Evaluate(proj)
	}

	// Step 2: If allowed, mint a single-use EffectWarrant bound to exact projection + policy.
	var warrant EffectWarrant
	hasWarrant := false
	warrantIdx := -1
	warrantDigest := ZeroDigest()
	if dec.Verdict == VerdictAllow {
		a.warrantN++
		capUgnot := budgetUgnot
		if dec.MaxSpendUgnot >= 0 && dec.MaxSpendUgnot < capUgnot {
			capUgnot = dec.MaxSpendUgnot
		}
		warrant = EffectWarrant{
			ID:               a.warrantN,
			AgentID:          a.cfg.AgentID,
			ProjectionDigest: projDigest,
			PolicyDigest:     dec.PolicyDigest,
			Action:           action,
			Target:           target,
			MaxSpendUgnot:    capUgnot,
			IssuedHeight:     height,
			ExpiryHeight:     height + a.cfg.WarrantTTLBlocks,
			Consumed:         false,
		}
		warrantIdx = len(a.warrants)
		a.warrants = append(a.warrants, warrant)
		hasWarrant = true
		warrantDigest = warrant.Digest()
	}

	// Step 3: Record immutable hash-chained DecisionReceipt into RFC 6962 Accumulator.
	a.seq++
	rec := DecisionReceipt{
		Seq:              a.seq,
		PrevHash:         a.lastHash,
		ChainID:          a.cfg.ChainID,
		Realm:            a.cfg.Realm,
		AgentID:          a.cfg.AgentID,
		Caller:           caller,
		ProjectionDigest: projDigest,
		PolicyDigest:     dec.PolicyDigest,
		Verdict:          dec.Verdict,
		ReasonCode:       dec.ReasonCode,
		WarrantDigest:    warrantDigest,
		Height:           height,
	}
	recLeaf := rec.LeafHash()
	recIndex := a.acc.Append(recLeaf)
	a.receipts = append(a.receipts, rec)
	a.chainKinds = append(a.chainKinds, "receipt")
	a.lastHash = recLeaf

	// Step 4: Execute ONLY when warranted; otherwise record an immutable REFUSED closure.
	var (
		output     []byte
		witness    []byte
		spentUgnot int64
		outcome    Outcome
		execErr    error
	)

	if !hasWarrant {
		outcome = OutcomeRefused
		execErr = errors.New("action refused (" + string(dec.Verdict) + ": " + dec.ReasonCode + "): " + dec.Reason)
	} else {
		if warrantIdx < 0 || warrantIdx >= len(a.warrants) || a.warrants[warrantIdx].Consumed {
			outcome = OutcomeFailed
			execErr = errors.New("warrant already consumed or missing")
		} else if height > a.warrants[warrantIdx].ExpiryHeight {
			outcome = OutcomeFailed
			execErr = errors.New("warrant expired before execution")
		} else {
			// Mark warrant consumed BEFORE handler runs (single-use, reentrancy-safe).
			a.warrants[warrantIdx].Consumed = true
			warrant.Consumed = true
			out, wit, spent, err := tool.handler(warrant, input)
			output = out
			witness = wit
			spentUgnot = spent
			switch {
			case err != nil:
				outcome = OutcomeFailed
				execErr = err
			case spent < 0 || spent > warrant.MaxSpendUgnot:
				outcome = OutcomeFailed
				execErr = errors.New("tool handler violated warrant spend ceiling: spent " +
					strconv.FormatInt(spent, 10) + "ugnot > max " + strconv.FormatInt(warrant.MaxSpendUgnot, 10) + "ugnot")
			default:
				outcome = OutcomeExecuted
			}
		}
	}

	// Step 5: Record immutable hash-chained EffectClosure into RFC 6962 Accumulator.
	a.seq++
	closure := EffectClosure{
		Seq:              a.seq,
		PrevHash:         a.lastHash,
		AgentID:          a.cfg.AgentID,
		WarrantDigest:    warrantDigest,
		DecisionLeafHash: recLeaf,
		OutputDigest:     HashBytes(output),
		WitnessDigest:    HashBytes(witness),
		Outcome:          outcome,
		SpentUgnot:       spentUgnot,
		Height:           height,
	}
	closureLeaf := closure.LeafHash()
	closureIndex := a.acc.Append(closureLeaf)
	a.closures = append(a.closures, closure)
	a.chainKinds = append(a.chainKinds, "closure")
	a.lastHash = closureLeaf

	// Step 6: Build self-verifying EvidenceBundle with RFC 6962 inclusion proofs.
	size := a.acc.Size()
	root := a.acc.Root()
	recProof, _ := a.acc.Proof(recIndex, size)
	closureProof, _ := a.acc.Proof(closureIndex, size)

	bundle := EvidenceBundle{
		Projection:       proj,
		Decision:         dec,
		HasWarrant:       hasWarrant,
		Warrant:          warrant,
		Receipt:          rec,
		Closure:          closure,
		ReceiptLeafIndex: recIndex,
		ClosureLeafIndex: closureIndex,
		AccumulatorSize:  size,
		AccumulatorRoot:  root,
		ReceiptProof:     recProof,
		ClosureProof:     closureProof,
	}

	return output, bundle, execErr
}

// ExecuteDelegated runs a sub-agent action under a strictly attenuated DelegatedWarrant.
// Enforces child identity binding, spend ceiling, expiry height, and single-use replay
// protection, while chaining the parent warrant digest into the child's ContextDigest so
// multi-agent provenance is cryptographically verifiable end-to-end.
func (a *Agent) ExecuteDelegated(
	delegated DelegatedWarrant,
	caller string,
	input []byte,
	contextBytes []byte,
	budgetUgnot int64,
	height int64,
) ([]byte, EvidenceBundle, error) {
	if delegated.ChildAgentID != a.cfg.AgentID {
		return nil, EvidenceBundle{}, errors.New("delegated warrant is bound to child agent " + delegated.ChildAgentID + ", not " + a.cfg.AgentID)
	}
	if height > delegated.ExpiryHeight {
		return nil, EvidenceBundle{}, errors.New("delegated warrant expired at height " + strconv.FormatInt(delegated.ExpiryHeight, 10))
	}
	if budgetUgnot < 0 || budgetUgnot > delegated.MaxSpendUgnot {
		return nil, EvidenceBundle{}, errors.New("requested budget exceeds delegated warrant ceiling")
	}
	// Bind the delegated warrant digest into contextBytes so the child's DecisionReceipt
	// cryptographically links back to the coordinator's parent EffectWarrant.
	dDigest := delegated.Digest()
	boundCtx := make([]byte, 0, len(contextBytes)+64)
	boundCtx = append(boundCtx, delegated.ParentWarrantDigest[:]...)
	boundCtx = append(boundCtx, dDigest[:]...)
	boundCtx = append(boundCtx, contextBytes...)
	return a.Execute(caller, delegated.Action, delegated.Target, input, boundCtx, budgetUgnot, height)
}

// Checkpoint returns the compact root and counters ready to anchor on gno.land.
func (a *Agent) Checkpoint() CheckpointSummary {
	return CheckpointSummary{
		AgentID:        a.cfg.AgentID,
		CheckpointRoot: a.acc.Root(),
		LastHash:       a.lastHash,
		LeafCount:      a.acc.Size(),
		ReceiptCount:   uint64(len(a.receipts)),
		ClosureCount:   uint64(len(a.closures)),
	}
}

// Accumulator returns a read-oriented pointer to the underlying RFC 6962 accumulator.
func (a *Agent) Accumulator() *Accumulator {
	return &a.acc
}

// Receipts returns a copy of all DecisionReceipts recorded by this agent.
func (a *Agent) Receipts() []DecisionReceipt {
	out := make([]DecisionReceipt, len(a.receipts))
	copy(out, a.receipts)
	return out
}

// Closures returns a copy of all EffectClosures recorded by this agent.
func (a *Agent) Closures() []EffectClosure {
	out := make([]EffectClosure, len(a.closures))
	copy(out, a.closures)
	return out
}

// Metrics computes strictly measured assurance metrics from real recorded evidence.
func (a *Agent) Metrics(currentHeight, lastAnchoredHeight int64) AssuranceMetrics {
	total := uint64(len(a.receipts))
	var allowed, refused, governed, executed, failed, cleanRefusals uint64
	for i, r := range a.receipts {
		if r.PolicyDigest != ZeroDigest() {
			governed++
		}
		if r.Verdict == VerdictAllow {
			allowed++
		} else {
			refused++
		}
		if i < len(a.closures) {
			c := a.closures[i]
			switch c.Outcome {
			case OutcomeExecuted:
				executed++
			case OutcomeFailed:
				failed++
			case OutcomeRefused:
				if c.SpentUgnot == 0 && c.WarrantDigest == ZeroDigest() {
					cleanRefusals++
				}
			}
		}
	}

	lag := int64(-1)
	if lastAnchoredHeight > 0 && currentHeight >= lastAnchoredHeight {
		lag = currentHeight - lastAnchoredHeight
	}

	m := AssuranceMetrics{
		Measured:         total >= MinSamplesForMeasuredScore,
		TotalDecisions:   total,
		AllowedDecisions: allowed,
		RefusedDecisions: refused,
		ExecutedClosures: executed,
		FailedClosures:   failed,
		AnchorLagBlocks:  lag,
	}
	if !m.Measured {
		return m
	}

	m.GovernanceBps = (governed * 10000) / total
	if allowed > 0 {
		m.ClosureIntegrityBps = (executed * 10000) / allowed
	} else {
		m.ClosureIntegrityBps = 10000
	}
	if refused > 0 {
		m.RefusalIntegrityBps = (cleanRefusals * 10000) / refused
	} else {
		m.RefusalIntegrityBps = 10000
	}
	return m
}

// VerifyChain walks the entire hash chain and recomputes the RFC 6962 accumulator from leaf 0.
func (a *Agent) VerifyChain() error {
	var checkAcc Accumulator
	prev := ZeroDigest()
	rIdx, cIdx := 0, 0
	for i, kind := range a.chainKinds {
		var leaf [32]byte
		switch kind {
		case "receipt":
			if rIdx >= len(a.receipts) {
				return errors.New("receipt slice truncated")
			}
			r := a.receipts[rIdx]
			if r.PrevHash != prev {
				return errors.New("broken receipt hash chain at leaf " + strconv.Itoa(i))
			}
			leaf = r.LeafHash()
			rIdx++
		case "closure":
			if cIdx >= len(a.closures) {
				return errors.New("closure slice truncated")
			}
			c := a.closures[cIdx]
			if c.PrevHash != prev {
				return errors.New("broken closure hash chain at leaf " + strconv.Itoa(i))
			}
			leaf = c.LeafHash()
			cIdx++
		default:
			return errors.New("unknown leaf kind: " + kind)
		}
		accLeaf, ok := a.acc.Leaf(uint64(i))
		if !ok || accLeaf != leaf {
			return errors.New("accumulator leaf mismatch at index " + strconv.Itoa(i))
		}
		checkAcc.Append(leaf)
		prev = leaf
	}
	if checkAcc.Root() != a.acc.Root() {
		return errors.New("recomputed Merkle root does not match accumulator root")
	}
	if prev != a.lastHash {
		return errors.New("chain tip hash mismatch")
	}
	return nil
}

package assurance

import (
	"errors"

	"gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/signals"
)

// AgentBuilder is the fluent Immaculate SDK Agent Builder for constructing governed
// Gno agents with fail-closed policies, single-use warrants, and RFC 6962 evidence
// out of the box.
type AgentBuilder struct {
	cfg            AgentConfig
	policyID       string
	allowedActions []string
	allowedTargets []string
	maxBudgetUgnot int64
	hasBudgetCap   bool
	riskGate       *RiskGatePolicy
	driftGuard     *DriftGuardPolicy
	coherenceGuard *CoherenceGuardPolicy
	extraPolicies  []Policy
	tools          []registeredTool
	buildErr       error
}

// NewAgentBuilder starts building a governed agent with safe fail-closed defaults:
// risk gating enabled (LOW/MEDIUM auto-allow, HIGH requires approval, CRITICAL escalates).
func NewAgentBuilder(agentID string) *AgentBuilder {
	return &AgentBuilder{
		cfg: AgentConfig{
			AgentID:          agentID,
			ChainID:          "gnoland-testnet",
			Realm:            "gno.land/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance",
			WarrantTTLBlocks: 10,
		},
		policyID: agentID + "-policy-v1",
		riskGate: &RiskGatePolicy{
			PolicyID:     agentID + "-risk-gate",
			AllowHigh:    false,
			DenyCritical: false,
		},
	}
}

func (b *AgentBuilder) WithChain(chainID, realmPath string) *AgentBuilder {
	b.cfg.ChainID = chainID
	b.cfg.Realm = realmPath
	return b
}

func (b *AgentBuilder) WithPrincipal(principal string) *AgentBuilder {
	b.cfg.Principal = principal
	return b
}

func (b *AgentBuilder) WithWarrantTTL(blocks int64) *AgentBuilder {
	b.cfg.WarrantTTLBlocks = blocks
	return b
}

func (b *AgentBuilder) WithPolicyID(id string) *AgentBuilder {
	b.policyID = id
	return b
}

func (b *AgentBuilder) AllowActions(actions ...string) *AgentBuilder {
	b.allowedActions = append(b.allowedActions, actions...)
	return b
}

func (b *AgentBuilder) AllowTargets(targets ...string) *AgentBuilder {
	b.allowedTargets = append(b.allowedTargets, targets...)
	return b
}

func (b *AgentBuilder) WithBudgetCap(maxPerCallUgnot int64) *AgentBuilder {
	b.maxBudgetUgnot = maxPerCallUgnot
	b.hasBudgetCap = true
	return b
}

func (b *AgentBuilder) WithRiskGate(allowHigh, denyCritical bool) *AgentBuilder {
	b.riskGate = &RiskGatePolicy{
		PolicyID:     b.cfg.AgentID + "-risk-gate",
		AllowHigh:    allowHigh,
		DenyCritical: denyCritical,
	}
	return b
}

func (b *AgentBuilder) WithPolicy(p Policy) *AgentBuilder {
	if p != nil {
		b.extraPolicies = append(b.extraPolicies, p)
	}
	return b
}

// WithDriftGuard attaches a deterministic Hampel-guarded CUSUM behavioral drift circuit breaker.
func (b *AgentBuilder) WithDriftGuard(base signals.Baseline, hFixed, kFixed int64, hampelWindow int, strictDeny, latchOnAlarm bool) *AgentBuilder {
	dg, err := NewDriftGuardPolicy(b.cfg.AgentID+"-drift-guard", base, hFixed, kFixed, hampelWindow, 3*signals.Scale, strictDeny, latchOnAlarm)
	if err != nil {
		b.buildErr = err
		return b
	}
	b.driftGuard = dg
	return b
}

// WithCoherenceGuard attaches a deterministic spherical context coherence gate to block memory poisoning.
func (b *AgentBuilder) WithCoherenceGuard(thresholdFixed int64, usePairwise, strictDeny, requireOnAllCall bool) *AgentBuilder {
	cg, err := NewCoherenceGuardPolicy(b.cfg.AgentID+"-coherence-guard", thresholdFixed, usePairwise, strictDeny, requireOnAllCall)
	if err != nil {
		b.buildErr = err
		return b
	}
	b.coherenceGuard = cg
	return b
}

// DriftGuard returns the configured DriftGuardPolicy (nil if unset).
func (b *AgentBuilder) DriftGuard() *DriftGuardPolicy { return b.driftGuard }

// CoherenceGuard returns the configured CoherenceGuardPolicy (nil if unset).
func (b *AgentBuilder) CoherenceGuard() *CoherenceGuardPolicy { return b.coherenceGuard }

func (b *AgentBuilder) WithTool(spec ToolSpec, handler ToolHandler) *AgentBuilder {
	if spec.Name == "" || handler == nil {
		b.buildErr = errors.New("tool requires non-empty name and handler")
		return b
	}
	if spec.RiskTier == "" {
		spec.RiskTier = RiskMedium
	}
	b.tools = append(b.tools, registeredTool{spec: spec, handler: handler})
	return b
}

// Build validates configuration, assembles a fail-closed CompositePolicy, registers all
// tools, and returns a ready-to-execute governed Agent.
func (b *AgentBuilder) Build() (*Agent, error) {
	if b.buildErr != nil {
		return nil, b.buildErr
	}
	if b.cfg.AgentID == "" {
		return nil, errors.New("agentID is required")
	}
	if b.cfg.Principal == "" {
		return nil, errors.New("principal address is required")
	}

	var rules []Policy
	if len(b.allowedActions) > 0 || len(b.allowedTargets) > 0 {
		rules = append(rules, &AllowListPolicy{
			PolicyID:       b.cfg.AgentID + "-allowlist",
			AllowedActions: b.allowedActions,
			AllowedTargets: b.allowedTargets,
		})
	}
	if b.hasBudgetCap {
		rules = append(rules, &BudgetCapPolicy{
			PolicyID:        b.cfg.AgentID + "-budget",
			MaxPerCallUgnot: b.maxBudgetUgnot,
		})
	}
	if b.riskGate != nil {
		rules = append(rules, b.riskGate)
	}
	if b.driftGuard != nil {
		rules = append(rules, b.driftGuard)
	}
	if b.coherenceGuard != nil {
		rules = append(rules, b.coherenceGuard)
	}
	rules = append(rules, b.extraPolicies...)

	policy := &CompositePolicy{
		PolicyID: b.policyID,
		Rules:    rules,
	}

	ag := NewAgent(b.cfg, policy)
	for _, t := range b.tools {
		if err := ag.RegisterTool(t.spec, t.handler); err != nil {
			return nil, err
		}
	}
	return ag, nil
}

// BuildFamiliar builds the governed Agent and wraps it as an owner-bonded Familiar with
// a poison-resistant Hybrid RRF MemoryVault, attenuated CapabilityToken, and Wilson TrustLedger.
func (b *AgentBuilder) BuildFamiliar(
	capMask uint32,
	maxSpendUgnot int64,
	maxCallsPerWindow uint64,
	windowBlocks int64,
	issuedHeight int64,
	expiryHeight int64,
	quarantineThresholdFixed int64,
	minTrustFloorFixed int64,
) (*Familiar, error) {
	ag, err := b.Build()
	if err != nil {
		return nil, err
	}
	vault := NewMemoryVault(MemoryVaultConfig{
		VaultID:                  b.cfg.AgentID + "-memory",
		QuarantineThresholdFixed: quarantineThresholdFixed,
		MinTrustedAnchors:        2,
		HalfLifeBlocks:           1000,
		RRFK:                     DefaultRRFK,
	})
	tok := CapabilityToken{
		ID:                1,
		FamiliarID:        b.cfg.AgentID,
		Owner:             b.cfg.Principal,
		GrantMask:         capMask,
		MaxSpendUgnot:     maxSpendUgnot,
		MaxCallsPerWindow: maxCallsPerWindow,
		WindowBlocks:      windowBlocks,
		IssuedHeight:      issuedHeight,
		ExpiryHeight:      expiryHeight,
	}
	return NewFamiliar(b.cfg.AgentID, b.cfg.Principal, ag, vault, b.coherenceGuard, tok, minTrustFloorFixed)
}

package assurance

import (
	"crypto/sha256"
	"encoding/binary"
	"errors"
)

const DomainDelegation = "arobi-assurance-delegated-warrant-v1"

// DelegatedWarrant represents a strictly attenuated sub-agent authorization derived
// from an active parent EffectWarrant. A child warrant can NEVER amplify spend, extend
// expiry, switch to an unauthorized action, or redirect to an unauthorized target.
type DelegatedWarrant struct {
	ID                  uint64
	ParentWarrantID     uint64
	ParentWarrantDigest [32]byte
	ParentAgentID       string
	ChildAgentID        string
	Action              string
	Target              string
	MaxSpendUgnot       int64
	IssuedHeight        int64
	ExpiryHeight        int64
}

// Encode serializes DelegatedWarrant into canonical big-endian bytes.
func (d DelegatedWarrant) Encode() []byte {
	out := make([]byte, 0, 192)
	out = appendString(out, DomainDelegation)
	out = append(out, EncodingVersion)
	out = binary.BigEndian.AppendUint64(out, d.ID)
	out = binary.BigEndian.AppendUint64(out, d.ParentWarrantID)
	out = append(out, d.ParentWarrantDigest[:]...)
	out = appendString(out, d.ParentAgentID)
	out = appendString(out, d.ChildAgentID)
	out = appendString(out, d.Action)
	out = appendString(out, d.Target)
	out = binary.BigEndian.AppendUint64(out, uint64(d.MaxSpendUgnot))
	out = binary.BigEndian.AppendUint64(out, uint64(d.IssuedHeight))
	out = binary.BigEndian.AppendUint64(out, uint64(d.ExpiryHeight))
	return out
}

// Digest returns SHA-256(Encode()).
func (d DelegatedWarrant) Digest() [32]byte {
	return sha256.Sum256(d.Encode())
}

// AttenuateWarrant derives a strictly attenuated child warrant from parent.
// Any attempted privilege escalation (spend, TTL, action, or target) fails closed.
func AttenuateWarrant(
	parent EffectWarrant,
	childWarrantID uint64,
	childAgentID string,
	action string,
	target string,
	maxSpendUgnot int64,
	issuedHeight int64,
	expiryHeight int64,
) (DelegatedWarrant, error) {
	if childAgentID == "" {
		return DelegatedWarrant{}, errors.New("childAgentID is required")
	}
	if childAgentID == parent.AgentID {
		return DelegatedWarrant{}, errors.New("cannot delegate warrant to the same agent")
	}
	if maxSpendUgnot < 0 || maxSpendUgnot > parent.MaxSpendUgnot {
		return DelegatedWarrant{}, errors.New("delegation cannot amplify spend ceiling above parent warrant")
	}
	if issuedHeight < parent.IssuedHeight {
		return DelegatedWarrant{}, errors.New("delegation issuedHeight precedes parent warrant")
	}
	if expiryHeight < issuedHeight || expiryHeight > parent.ExpiryHeight {
		return DelegatedWarrant{}, errors.New("delegation cannot extend expiry beyond parent warrant")
	}
	if parent.Action != "" && action != parent.Action {
		return DelegatedWarrant{}, errors.New("delegation cannot escalate to different action: " + action)
	}
	if parent.Target != "" && target != parent.Target {
		return DelegatedWarrant{}, errors.New("delegation cannot redirect target from " + parent.Target + " to " + target)
	}
	return DelegatedWarrant{
		ID:                  childWarrantID,
		ParentWarrantID:     parent.ID,
		ParentWarrantDigest: parent.Digest(),
		ParentAgentID:       parent.AgentID,
		ChildAgentID:        childAgentID,
		Action:              action,
		Target:              target,
		MaxSpendUgnot:       maxSpendUgnot,
		IssuedHeight:        issuedHeight,
		ExpiryHeight:        expiryHeight,
	}, nil
}

// VerifyAgainst checks that this DelegatedWarrant is a valid, non-amplified attenuation of parent.
func (d DelegatedWarrant) VerifyAgainst(parent EffectWarrant) error {
	if d.ParentWarrantID != parent.ID {
		return errors.New("parent warrant ID mismatch")
	}
	if d.ParentWarrantDigest != parent.Digest() {
		return errors.New("parent warrant digest mismatch")
	}
	if d.ParentAgentID != parent.AgentID {
		return errors.New("parent agent ID mismatch")
	}
	if d.MaxSpendUgnot < 0 || d.MaxSpendUgnot > parent.MaxSpendUgnot {
		return errors.New("delegated spend exceeds parent warrant ceiling")
	}
	if d.ExpiryHeight > parent.ExpiryHeight || d.ExpiryHeight < d.IssuedHeight {
		return errors.New("delegated expiry exceeds parent warrant lifetime")
	}
	if parent.Action != "" && d.Action != parent.Action {
		return errors.New("delegated action does not match parent warrant")
	}
	if parent.Target != "" && d.Target != parent.Target {
		return errors.New("delegated target does not match parent warrant")
	}
	return nil
}

package assurance

import (
	"crypto/sha256"
	"encoding/binary"
	"errors"

	"gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/signals"
)

const (
	DomainCapability = "arobi-assurance-capability-v1"
	DomainFamiliar   = "arobi-assurance-familiar-v1"

	// Bitmask object-capabilities for Immaculate Familiars & cross-harness sub-agents.
	CapReadMemory   uint32 = 1 << 0
	CapWriteMemory  uint32 = 1 << 1
	CapInvokeTool   uint32 = 1 << 2
	CapDelegate     uint32 = 1 << 3
	CapSendWhisper  uint32 = 1 << 4
	CapManageEscrow uint32 = 1 << 5
	CapAll          uint32 = CapReadMemory | CapWriteMemory | CapInvokeTool | CapDelegate | CapSendWhisper | CapManageEscrow

	// z^2 = 1.96^2 = 3.8416 scaled by signals.Scale (95% Wilson score lower bound).
	wilsonZ2Fixed int64 = 3841600
)

// CapabilityToken is an unforgeable, strictly attenuable object-capability lease governing
// what a Familiar (or delegated gnosh.ai / Ullumii / Whisper worker) is authorized to do.
type CapabilityToken struct {
	ID                uint64
	FamiliarID        string
	Owner             string
	GrantMask         uint32
	MaxSpendUgnot     int64
	MaxCallsPerWindow uint64
	WindowBlocks      int64
	IssuedHeight      int64
	ExpiryHeight      int64
	ParentDigest      [32]byte
}

// Digest returns canonical SHA-256 over the CapabilityToken fields.
func (c CapabilityToken) Digest() [32]byte {
	out := make([]byte, 0, 160)
	out = appendString(out, DomainCapability)
	out = append(out, EncodingVersion)
	out = binary.BigEndian.AppendUint64(out, c.ID)
	out = appendString(out, c.FamiliarID)
	out = appendString(out, c.Owner)
	out = binary.BigEndian.AppendUint32(out, c.GrantMask)
	out = binary.BigEndian.AppendUint64(out, uint64(c.MaxSpendUgnot))
	out = binary.BigEndian.AppendUint64(out, c.MaxCallsPerWindow)
	out = binary.BigEndian.AppendUint64(out, uint64(c.WindowBlocks))
	out = binary.BigEndian.AppendUint64(out, uint64(c.IssuedHeight))
	out = binary.BigEndian.AppendUint64(out, uint64(c.ExpiryHeight))
	out = append(out, c.ParentDigest[:]...)
	return sha256.Sum256(out)
}

// Has checks whether all bits in required are granted by this CapabilityToken.
func (c CapabilityToken) Has(required uint32) bool {
	return (c.GrantMask & required) == required
}

// AttenuateCapability derives a strictly attenuated child CapabilityToken from parent.
// Any attempt to amplify capability bits, spend limit, call cadence, or expiry FAILS CLOSED.
func AttenuateCapability(
	parent CapabilityToken,
	childID uint64,
	childFamiliarID string,
	childMask uint32,
	childMaxSpendUgnot int64,
	childMaxCalls uint64,
	nowHeight int64,
	childExpiry int64,
) (CapabilityToken, error) {
	if !parent.Has(CapDelegate) {
		return CapabilityToken{}, errors.New("parent capability lacks CapDelegate")
	}
	if childFamiliarID == "" || childFamiliarID == parent.FamiliarID {
		return CapabilityToken{}, errors.New("child familiar must be distinct and non-empty")
	}
	if childMask == 0 {
		return CapabilityToken{}, errors.New("child capability mask must be non-empty")
	}
	if (childMask &^ parent.GrantMask) != 0 {
		return CapabilityToken{}, errors.New("capability amplification denied: child requests bits outside parent grant")
	}
	if childMaxSpendUgnot < 0 || childMaxSpendUgnot > parent.MaxSpendUgnot {
		return CapabilityToken{}, errors.New("spend amplification denied: childMaxSpend exceeds parent")
	}
	if parent.MaxCallsPerWindow > 0 && (childMaxCalls == 0 || childMaxCalls > parent.MaxCallsPerWindow) {
		return CapabilityToken{}, errors.New("rate amplification denied: childMaxCalls exceeds parent")
	}
	if nowHeight < parent.IssuedHeight || nowHeight > parent.ExpiryHeight {
		return CapabilityToken{}, errors.New("parent capability is inactive or expired")
	}
	if childExpiry < nowHeight || childExpiry > parent.ExpiryHeight {
		return CapabilityToken{}, errors.New("expiry amplification denied: child expiry exceeds parent")
	}
	return CapabilityToken{
		ID:                childID,
		FamiliarID:        childFamiliarID,
		Owner:             parent.Owner,
		GrantMask:         childMask,
		MaxSpendUgnot:     childMaxSpendUgnot,
		MaxCallsPerWindow: childMaxCalls,
		WindowBlocks:      parent.WindowBlocks,
		IssuedHeight:      nowHeight,
		ExpiryHeight:      childExpiry,
		ParentDigest:      parent.Digest(),
	}, nil
}

// VerifyCapabilityAttenuation verifies that child is a strictly valid attenuation of parent.
func VerifyCapabilityAttenuation(parent, child CapabilityToken) error {
	if child.ParentDigest != parent.Digest() {
		return errors.New("capability parent digest mismatch")
	}
	if !parent.Has(CapDelegate) {
		return errors.New("parent lacks CapDelegate")
	}
	if (child.GrantMask &^ parent.GrantMask) != 0 {
		return errors.New("child capability mask exceeds parent")
	}
	if child.MaxSpendUgnot > parent.MaxSpendUgnot {
		return errors.New("child spend limit exceeds parent")
	}
	if child.ExpiryHeight > parent.ExpiryHeight {
		return errors.New("child expiry exceeds parent")
	}
	return nil
}

// WilsonLowerBoundFixed computes the 95% Wilson score lower confidence bound for
// successes / total in fixed-point [0, signals.Scale], using pure integer math (zero floats).
// Returns 0 when total == 0 (conservative unmeasured floor).
func WilsonLowerBoundFixed(successes, total uint64) int64 {
	if total == 0 || successes == 0 {
		return 0
	}
	if successes > total {
		successes = total
	}
	n := int64(total)
	p := (int64(successes) * signals.Scale) / n // in [0, Scale]
	z2OverN := wilsonZ2Fixed / n                // z^2 / n in Scale units

	// Numerator center: p + z^2 / (2n)
	center := p + z2OverN/2

	// Variance term inside sqrt: (p*(1-p)/n) + (z^2 / (4*n^2))
	// Multiply by z^2 and compute sqrt in Scale units:
	// margin = sqrt(z^2 * (p*(1-p)/n + z^2/(4*n^2)))
	pOneMinusP := signals.MulFixed(p, signals.Scale-p) // in [0, 0.25*Scale]
	term1 := signals.MulFixed(wilsonZ2Fixed, pOneMinusP/n)
	term2 := signals.MulFixed(z2OverN, z2OverN) / 4
	radicand := term1 + term2
	if radicand < 0 {
		radicand = 0
	}
	// sqrt(radicand / Scale) * Scale = isqrt(radicand * Scale)
	margin := int64(signals.ISqrt64(uint64(radicand) * uint64(signals.Scale)))

	denom := signals.Scale + z2OverN
	num := center - margin
	if num <= 0 {
		return 0
	}
	res := signals.DivFixed(num, denom)
	if res > signals.Scale {
		res = signals.Scale
	}
	return res
}

// TrustLedger tracks a Familiar's empirical execution reliability using Wilson lower bounds.
type TrustLedger struct {
	Successes          uint64
	Violations         uint64
	MinTrustFloorFixed int64 // if > 0 and Total >= MinSamples, lower bound below floor triggers auto-halt
	MinSamples         uint64
}

// Total returns total observed actions.
func (t *TrustLedger) Total() uint64 { return t.Successes + t.Violations }

// LowerBoundFixed returns the 95% Wilson lower confidence bound in [0, Scale].
func (t *TrustLedger) LowerBoundFixed() int64 {
	return WilsonLowerBoundFixed(t.Successes, t.Total())
}

// Healthy returns true if the Familiar has not breached its calibrated trust floor.
func (t *TrustLedger) Healthy() bool {
	if t.MinTrustFloorFixed <= 0 || t.Total() < t.MinSamples {
		return true
	}
	return t.LowerBoundFixed() >= t.MinTrustFloorFixed
}

// Familiar is a persistent, owner-bonded autonomous companion agent combining:
//   - Governed Agent runtime + RFC 6962 evidence accumulator
//   - Poison-resistant Hybrid RRF MemoryVault
//   - Strictly attenuable Object-Capability lease (CapabilityToken)
//   - Paced sliding-window rate governor + Wilson-calibrated TrustLedger
type Familiar struct {
	ID             string
	Owner          string
	Agent          *Agent
	Memory         *MemoryVault
	CoherenceGuard *CoherenceGuardPolicy
	Capability     CapabilityToken
	Trust          TrustLedger
	Revoked        bool

	windowStartHeight int64
	windowCalls       uint64
	childCapSeq       uint64
}

// NewFamiliar constructs a governed Familiar with fail-closed defaults.
func NewFamiliar(
	id string,
	owner string,
	agent *Agent,
	memory *MemoryVault,
	coherenceGuard *CoherenceGuardPolicy,
	capToken CapabilityToken,
	minTrustFloorFixed int64,
) (*Familiar, error) {
	if id == "" || owner == "" || agent == nil {
		return nil, errors.New("familiar requires non-empty id, owner, and agent")
	}
	if memory == nil {
		memory = NewMemoryVault(MemoryVaultConfig{VaultID: id + "-memory"})
	}
	if capToken.FamiliarID == "" {
		capToken.FamiliarID = id
	}
	if capToken.Owner == "" {
		capToken.Owner = owner
	}
	return &Familiar{
		ID:             id,
		Owner:          owner,
		Agent:          agent,
		Memory:         memory,
		CoherenceGuard: coherenceGuard,
		Capability:     capToken,
		Trust: TrustLedger{
			MinTrustFloorFixed: minTrustFloorFixed,
			MinSamples:         5,
		},
	}, nil
}

// Revoke permanently halts this Familiar (fail-closed kill switch).
func (f *Familiar) Revoke() {
	f.Revoked = true
	f.Agent.Pause()
}

// Remember ingests a memory episode through the Familiar's capability check and spherical
// quarantine firewall. Quarantined injections increment Trust.Violations.
func (f *Familiar) Remember(
	kind string,
	content []byte,
	embedding []int64,
	salienceFixed int64,
	height int64,
) (MemoryIngestReceipt, error) {
	if f.Revoked {
		return MemoryIngestReceipt{}, errors.New("familiar is revoked")
	}
	if !f.Capability.Has(CapWriteMemory) {
		return MemoryIngestReceipt{}, errors.New("familiar lacks CapWriteMemory")
	}
	if height > f.Capability.ExpiryHeight {
		return MemoryIngestReceipt{}, errors.New("familiar capability expired")
	}
	cp := f.Agent.Checkpoint()
	receipt, err := f.Memory.Ingest(kind, f.ID, content, embedding, salienceFixed, height, cp.LastHash)
	if err != nil {
		return MemoryIngestReceipt{}, err
	}
	if receipt.Quarantined {
		f.Trust.Violations++
	}
	return receipt, nil
}

// ExecuteWithCapability checks capability bits, expiry, paced rate limit, and calibrated
// trust floor, optionally retrieves Top-K hybrid memories, and runs the governed action.
func (f *Familiar) ExecuteWithCapability(
	requiredCap uint32,
	caller string,
	action string,
	target string,
	input []byte,
	queryEmbedding []int64,
	queryText string,
	topK int,
	budgetUgnot int64,
	height int64,
) ([]byte, EvidenceBundle, MemoryRecallProof, error) {
	if f.Revoked {
		return nil, EvidenceBundle{}, MemoryRecallProof{}, errors.New("familiar is revoked")
	}
	if !f.Capability.Has(requiredCap | CapInvokeTool) {
		f.Trust.Violations++
		return nil, EvidenceBundle{}, MemoryRecallProof{}, errors.New("capability denied: familiar lacks required grant bits")
	}
	if height < f.Capability.IssuedHeight || height > f.Capability.ExpiryHeight {
		f.Trust.Violations++
		return nil, EvidenceBundle{}, MemoryRecallProof{}, errors.New("capability expired or not yet active")
	}
	if budgetUgnot > f.Capability.MaxSpendUgnot {
		f.Trust.Violations++
		return nil, EvidenceBundle{}, MemoryRecallProof{}, errors.New("budget exceeds familiar capability MaxSpendUgnot")
	}
	if !f.Trust.Healthy() {
		return nil, EvidenceBundle{}, MemoryRecallProof{}, errors.New("familiar suspended: Wilson trust lower bound below floor")
	}

	// Paced sliding-window rate governor.
	if f.Capability.MaxCallsPerWindow > 0 && f.Capability.WindowBlocks > 0 {
		if f.windowStartHeight == 0 || height-f.windowStartHeight >= f.Capability.WindowBlocks {
			f.windowStartHeight = height
			f.windowCalls = 0
		}
		if f.windowCalls >= f.Capability.MaxCallsPerWindow {
			f.Trust.Violations++
			return nil, EvidenceBundle{}, MemoryRecallProof{}, errors.New("familiar rate limit exceeded for current block window")
		}
		f.windowCalls++
	}

	// If memory read is requested and queryEmbedding provided, bind deterministic recall proof.
	if len(queryEmbedding) > 0 && topK > 0 {
		if !f.Capability.Has(CapReadMemory) {
			f.Trust.Violations++
			return nil, EvidenceBundle{}, MemoryRecallProof{}, errors.New("familiar lacks CapReadMemory")
		}
		out, bundle, recallProof, err := f.Agent.ExecuteWithMemory(
			f.Memory, f.CoherenceGuard, caller, action, target, input, queryEmbedding, queryText, topK, budgetUgnot, height,
		)
		if err != nil {
			f.Trust.Violations++
		} else {
			f.Trust.Successes++
		}
		return out, bundle, recallProof, err
	}

	capDig := f.Capability.Digest()
	out, bundle, err := f.Agent.Execute(caller, action, target, input, capDig[:], budgetUgnot, height)
	if err != nil {
		f.Trust.Violations++
	} else {
		f.Trust.Successes++
	}
	return out, bundle, MemoryRecallProof{}, err
}

// MintSubCapability derives a strictly attenuated CapabilityToken for a sub-familiar or
// remote harness worker (gnosh.ai, Ullumii, Whisper Agent Bus).
func (f *Familiar) MintSubCapability(
	childFamiliarID string,
	childMask uint32,
	childMaxSpend int64,
	childMaxCalls uint64,
	nowHeight int64,
	childExpiry int64,
) (CapabilityToken, error) {
	if f.Revoked {
		return CapabilityToken{}, errors.New("revoked familiar cannot delegate")
	}
	f.childCapSeq++
	return AttenuateCapability(
		f.Capability,
		f.childCapSeq,
		childFamiliarID,
		childMask,
		childMaxSpend,
		childMaxCalls,
		nowHeight,
		childExpiry,
	)
}

package assurance

import (
	"crypto/sha256"
	"encoding/binary"
	"errors"
)

const (
	HarnessGnosh      = "gnosh.ai"
	HarnessUllumii    = "ullumii"
	HarnessWhisperBus = "whisper-bus"
	HarnessGnoRealm   = "gno-realm"
	DomainHarness     = "arobi-assurance-harness-frame-v1"
)

// HarnessFrame binds an external agent harness execution frame (such as a gnosh.ai Gno `mem`
// stack frame or an Ullumii governed work handoff / MCP tool call) into the Arobi Assurance
// evidence spine so every frame transition is cryptographically anchored on Gno.land.
type HarnessFrame struct {
	Harness       string // HarnessGnosh, HarnessUllumii, HarnessWhisperBus, HarnessGnoRealm
	SessionID     string
	FrameID       string
	ParentFrameID string
	Action        string
	Target        string
	Height        int64
}

// Encode serializes HarnessFrame into canonical big-endian bytes.
func (f HarnessFrame) Encode() []byte {
	out := make([]byte, 0, 160)
	out = appendString(out, DomainHarness)
	out = append(out, EncodingVersion)
	out = appendString(out, f.Harness)
	out = appendString(out, f.SessionID)
	out = appendString(out, f.FrameID)
	out = appendString(out, f.ParentFrameID)
	out = appendString(out, f.Action)
	out = appendString(out, f.Target)
	out = binary.BigEndian.AppendUint64(out, uint64(f.Height))
	return out
}

// Digest returns SHA-256(Encode()).
func (f HarnessFrame) Digest() [32]byte {
	return sha256.Sum256(f.Encode())
}

// ExecuteHarnessFrame executes an action originating from gnosh.ai, Ullumii, or a cross-shell
// Whisper Agent Bus dispatch. The canonical HarnessFrame digest is folded into ContextDigest
// before policy evaluation so the resulting DecisionReceipt, EffectWarrant, and EffectClosure
// are cryptographically bound to the exact harness session and stack frame.
func (a *Agent) ExecuteHarnessFrame(
	frame HarnessFrame,
	caller string,
	input []byte,
	extraContext []byte,
	budgetUgnot int64,
) ([]byte, EvidenceBundle, error) {
	if frame.Harness == "" || frame.SessionID == "" || frame.FrameID == "" {
		return nil, EvidenceBundle{}, errors.New("harness frame requires non-empty Harness, SessionID, and FrameID")
	}
	fDig := frame.Digest()
	boundCtx := make([]byte, 0, 32+len(extraContext))
	boundCtx = append(boundCtx, fDig[:]...)
	boundCtx = append(boundCtx, extraContext...)
	return a.Execute(caller, frame.Action, frame.Target, input, boundCtx, budgetUgnot, frame.Height)
}

package assurance

import (
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"strings"

	"gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/signals"
)

const (
	DomainMemoryRecord = "arobi-assurance-memory-record-v1"
	DomainMemoryRecall = "arobi-assurance-memory-recall-v1"

	MemoryKindEpisodic   = "episodic"
	MemoryKindSemantic   = "semantic"
	MemoryKindProcedural = "procedural"

	// DefaultRRFK is the standard Reciprocal Rank Fusion smoothing constant (k = 60).
	DefaultRRFK int64 = 60
)

// MemoryRecord is an immutable, provenance-bound memory entry stored in a deterministic
// fixed-point MemoryVault. Every record carries both a quantized unit embedding (for dense
// cosine retrieval and spherical poisoning defense) and normalized lexical terms (for hybrid
// Reciprocal Rank Fusion retrieval).
type MemoryRecord struct {
	ID             uint64
	Kind           string
	SourceAgent    string
	ContentDigest  [32]byte
	ProvenanceLeaf [32]byte
	Terms          []string
	UnitVec        []int64
	SalienceFixed  int64 // [0, signals.Scale]
	CreatedHeight  int64
	Quarantined    bool
	CosToCentroid  int64 // fixed-point cosine similarity vs trusted centroid at ingest time
}

// Digest returns the canonical SHA-256 digest of a MemoryRecord.
func (r MemoryRecord) Digest() [32]byte {
	out := make([]byte, 0, 192)
	out = appendString(out, DomainMemoryRecord)
	out = append(out, EncodingVersion)
	out = binary.BigEndian.AppendUint64(out, r.ID)
	out = appendString(out, r.Kind)
	out = appendString(out, r.SourceAgent)
	out = append(out, r.ContentDigest[:]...)
	out = append(out, r.ProvenanceLeaf[:]...)
	out = binary.BigEndian.AppendUint64(out, uint64(r.SalienceFixed))
	out = binary.BigEndian.AppendUint64(out, uint64(r.CreatedHeight))
	out = binary.BigEndian.AppendUint32(out, uint32(len(r.UnitVec)))
	for _, v := range r.UnitVec {
		out = binary.BigEndian.AppendUint64(out, uint64(v))
	}
	return sha256.Sum256(out)
}

// MemoryIngestReceipt proves whether a candidate memory was admitted or quarantined by the
// spherical poisoning firewall, without floating-point nondeterminism.
type MemoryIngestReceipt struct {
	RecordID           uint64
	RecordDigest       [32]byte
	Admitted           bool
	Quarantined        bool
	ReasonCode         string
	CosToCentroidFixed int64
	CoherenceFixed     int64
}

// ScoredMemory pairs a retrieved MemoryRecord with its deterministic hybrid scores.
type ScoredMemory struct {
	Record       MemoryRecord
	DenseFixed   int64
	LexicalFixed int64
	RRFFixed     int64
	FinalFixed   int64
}

// MemoryRecallProof cryptographically binds a deterministic Top-K hybrid retrieval result
// into an agent's PolicyInputProjection.ContextDigest and RFC 6962 evidence log.
type MemoryRecallProof struct {
	VaultID          string
	QueryDigest      [32]byte
	Height           int64
	CandidateCount   uint64
	QuarantinedCount uint64
	ReturnedIDs      []uint64
	ReturnedDigests  [][32]byte
	BatchCoherence   int64
}

// Digest returns SHA-256 over the canonical encoding of MemoryRecallProof.
func (p MemoryRecallProof) Digest() [32]byte {
	out := make([]byte, 0, 160+len(p.ReturnedDigests)*40)
	out = appendString(out, DomainMemoryRecall)
	out = append(out, EncodingVersion)
	out = appendString(out, p.VaultID)
	out = append(out, p.QueryDigest[:]...)
	out = binary.BigEndian.AppendUint64(out, uint64(p.Height))
	out = binary.BigEndian.AppendUint64(out, p.CandidateCount)
	out = binary.BigEndian.AppendUint64(out, p.QuarantinedCount)
	out = binary.BigEndian.AppendUint64(out, uint64(p.BatchCoherence))
	out = binary.BigEndian.AppendUint32(out, uint32(len(p.ReturnedIDs)))
	for i, id := range p.ReturnedIDs {
		out = binary.BigEndian.AppendUint64(out, id)
		out = append(out, p.ReturnedDigests[i][:]...)
	}
	return sha256.Sum256(out)
}

// MemoryVaultConfig configures a consensus-safe Governed MemoryVault.
type MemoryVaultConfig struct {
	VaultID                  string
	QuarantineThresholdFixed int64 // minimum cosine vs trusted centroid in [-Scale, Scale]; default 550000 (0.55)
	MinTrustedAnchors        int   // records required before quarantine activates; default 2
	HalfLifeBlocks           int64 // linear-decay half-life in blocks (0 = no decay)
	RRFK                     int64 // Reciprocal Rank Fusion k constant (default 60)
	MaxActiveRecords         int   // bounded capacity for deterministic GnoVM gas (default 256)
}

// MemoryVault is a consensus-safe, poison-resistant episodic/semantic memory store for Gno
// agents and Familiars. It guards writes with an ingestion-time spherical quarantine gate
// and answers queries with deterministic fixed-point Hybrid RRF (Dense Cosine + Lexical).
type MemoryVault struct {
	cfg           MemoryVaultConfig
	nextID        uint64
	dim           int
	centroidSum   []int64
	active        []MemoryRecord
	quarantined   []MemoryRecord
	vaultRootHash [32]byte
}

// NewMemoryVault creates a governed deterministic MemoryVault.
func NewMemoryVault(cfg MemoryVaultConfig) *MemoryVault {
	if cfg.VaultID == "" {
		cfg.VaultID = "memory-vault-v1"
	}
	if cfg.QuarantineThresholdFixed == 0 {
		cfg.QuarantineThresholdFixed = 550000 // 0.55 cosine alignment floor
	}
	if cfg.MinTrustedAnchors <= 0 {
		cfg.MinTrustedAnchors = 2
	}
	if cfg.RRFK <= 0 {
		cfg.RRFK = DefaultRRFK
	}
	if cfg.MaxActiveRecords <= 0 {
		cfg.MaxActiveRecords = 256
	}
	return &MemoryVault{cfg: cfg}
}

// ActiveCount returns the number of admitted trusted memory records.
func (v *MemoryVault) ActiveCount() int { return len(v.active) }

// QuarantinedCount returns the number of blocked/quarantined memory records.
func (v *MemoryVault) QuarantinedCount() int { return len(v.quarantined) }

// RootHash returns the rolling SHA-256 commitment over all admitted records.
func (v *MemoryVault) RootHash() [32]byte { return v.vaultRootHash }

// ActiveEmbeddings returns copies of active unit vectors for downstream coherence checks.
func (v *MemoryVault) ActiveEmbeddings() [][]int64 {
	out := make([][]int64, len(v.active))
	for i := range v.active {
		out[i] = v.active[i].UnitVec
	}
	return out
}

// CosineFixed computes the deterministic fixed-point dot product of two unit-normalized
// vectors (each scaled to signals.Scale), returning a value in [-Scale, +Scale].
func CosineFixed(u, w []int64) (int64, error) {
	if len(u) == 0 || len(u) != len(w) {
		return 0, errors.New("vectors must be non-empty and have matching dimensions")
	}
	var sum int64
	for i := range u {
		sum += signals.MulFixed(u[i], w[i])
	}
	if sum > signals.Scale {
		sum = signals.Scale
	}
	if sum < -signals.Scale {
		sum = -signals.Scale
	}
	return sum, nil
}

// NormalizeTerms extracts deterministic deduplicated lowercase alphanumeric tokens.
func NormalizeTerms(text string) []string {
	low := strings.ToLower(text)
	var tokens []string
	var cur []byte
	for i := 0; i < len(low); i++ {
		c := low[i]
		isAlnum := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_' || c == '-'
		if isAlnum {
			cur = append(cur, c)
		} else if len(cur) > 0 {
			if len(cur) >= 2 {
				tokens = appendUniqueTerm(tokens, string(cur))
			}
			cur = cur[:0]
		}
	}
	if len(cur) >= 2 {
		tokens = appendUniqueTerm(tokens, string(cur))
	}
	return tokens
}

func appendUniqueTerm(list []string, term string) []string {
	for _, existing := range list {
		if existing == term {
			return list
		}
	}
	return append(list, term)
}

func (v *MemoryVault) trustedCentroidUnit() ([]int64, bool) {
	if len(v.active) == 0 || len(v.centroidSum) == 0 {
		return nil, false
	}
	u, err := signals.UnitNormalizeFixed(v.centroidSum)
	if err != nil {
		return nil, false
	}
	return u, true
}

// Ingest validates, unit-normalizes, and runs the spherical quarantine firewall before
// admitting a memory record. Adversarial off-manifold memories are quarantined immediately
// so they never contaminate the centroid or Top-K retrieval.
func (v *MemoryVault) Ingest(
	kind string,
	sourceAgent string,
	content []byte,
	embedding []int64,
	salienceFixed int64,
	height int64,
	provenanceLeaf [32]byte,
) (MemoryIngestReceipt, error) {
	if kind == "" {
		kind = MemoryKindEpisodic
	}
	unit, err := signals.UnitNormalizeFixed(embedding)
	if err != nil {
		return MemoryIngestReceipt{}, err
	}
	if v.dim == 0 {
		v.dim = len(unit)
		v.centroidSum = make([]int64, v.dim)
	} else if len(unit) != v.dim {
		return MemoryIngestReceipt{}, errors.New("embedding dimension mismatch for memory vault")
	}
	if salienceFixed <= 0 {
		salienceFixed = signals.Scale
	}
	if salienceFixed > signals.Scale {
		salienceFixed = signals.Scale
	}

	v.nextID++
	rec := MemoryRecord{
		ID:             v.nextID,
		Kind:           kind,
		SourceAgent:    sourceAgent,
		ContentDigest:  HashBytes(content),
		ProvenanceLeaf: provenanceLeaf,
		Terms:          NormalizeTerms(string(content)),
		UnitVec:        unit,
		SalienceFixed:  salienceFixed,
		CreatedHeight:  height,
		CosToCentroid:  signals.Scale,
	}

	coherence := signals.Scale
	if len(v.active) >= v.cfg.MinTrustedAnchors && v.cfg.QuarantineThresholdFixed > -signals.Scale {
		centroid, ok := v.trustedCentroidUnit()
		if ok {
			cos, cErr := CosineFixed(unit, centroid)
			if cErr != nil {
				return MemoryIngestReceipt{}, cErr
			}
			rec.CosToCentroid = cos
			coherence = cos
			if cos < v.cfg.QuarantineThresholdFixed {
				rec.Quarantined = true
				v.quarantined = append(v.quarantined, rec)
				return MemoryIngestReceipt{
					RecordID:           rec.ID,
					RecordDigest:       rec.Digest(),
					Admitted:           false,
					Quarantined:        true,
					ReasonCode:         "MEMORY_SPHERICAL_QUARANTINE",
					CosToCentroidFixed: cos,
					CoherenceFixed:     coherence,
				}, nil
			}
		}
	}

	// Evict oldest active entry if vault reached MaxActiveRecords (updating centroid sum cleanly).
	if len(v.active) >= v.cfg.MaxActiveRecords {
		evicted := v.active[0]
		v.active = v.active[1:]
		for j := 0; j < v.dim; j++ {
			v.centroidSum[j] -= evicted.UnitVec[j]
		}
	}

	v.active = append(v.active, rec)
	for j := 0; j < v.dim; j++ {
		v.centroidSum[j] += unit[j]
	}

	recDig := rec.Digest()
	var buf [64]byte
	copy(buf[:32], v.vaultRootHash[:])
	copy(buf[32:], recDig[:])
	v.vaultRootHash = sha256.Sum256(buf[:])

	return MemoryIngestReceipt{
		RecordID:           rec.ID,
		RecordDigest:       recDig,
		Admitted:           true,
		Quarantined:        false,
		ReasonCode:         "MEMORY_ADMITTED",
		CosToCentroidFixed: rec.CosToCentroid,
		CoherenceFixed:     coherence,
	}, nil
}

// RetrieveTopK performs deterministic fixed-point Hybrid Retrieval combining:
//  1. Quantized Dense Cosine Similarity (weighted by salience)
//  2. Deterministic Lexical Token-Overlap Score (exact ID/term matching)
//  3. Reciprocal Rank Fusion (RRF, k = 60) + optional integer recency decay
//
// Returns the Top-K scored records and a canonical MemoryRecallProof ready to bind into
// Agent.Execute / PolicyInputProjection.ContextDigest.
func (v *MemoryVault) RetrieveTopK(
	queryEmbedding []int64,
	queryText string,
	k int,
	currentHeight int64,
) ([]ScoredMemory, MemoryRecallProof, error) {
	if k <= 0 {
		return nil, MemoryRecallProof{}, errors.New("k must be positive")
	}
	qUnit, err := signals.UnitNormalizeFixed(queryEmbedding)
	if err != nil {
		return nil, MemoryRecallProof{}, err
	}
	if v.dim > 0 && len(qUnit) != v.dim {
		return nil, MemoryRecallProof{}, errors.New("query embedding dimension mismatch")
	}

	qTerms := NormalizeTerms(queryText)
	qHashInput := make([]byte, 0, len(queryText)+len(qUnit)*8)
	qHashInput = append(qHashInput, []byte(queryText)...)
	for _, x := range qUnit {
		qHashInput = binary.BigEndian.AppendUint64(qHashInput, uint64(x))
	}
	qDigest := sha256.Sum256(qHashInput)

	n := len(v.active)
	if n == 0 {
		return nil, MemoryRecallProof{
			VaultID:          v.cfg.VaultID,
			QueryDigest:      qDigest,
			Height:           currentHeight,
			CandidateCount:   0,
			QuarantinedCount: uint64(len(v.quarantined)),
			BatchCoherence:   0,
		}, nil
	}

	// Compute dense and lexical scores for every active memory.
	denseScores := make([]int64, n)
	lexScores := make([]int64, n)
	denseOrder := make([]int, n)
	lexOrder := make([]int, n)

	for i := 0; i < n; i++ {
		rec := v.active[i]
		cos, cErr := CosineFixed(qUnit, rec.UnitVec)
		if cErr != nil {
			return nil, MemoryRecallProof{}, cErr
		}
		denseScores[i] = signals.MulFixed(cos, rec.SalienceFixed)
		lexScores[i] = lexicalOverlapFixed(qTerms, rec.Terms)
		denseOrder[i] = i
		lexOrder[i] = i
	}

	// Deterministic insertion sort (descending score, tie-break by smaller Record.ID).
	sortOrderDesc(denseOrder, denseScores, v.active)
	sortOrderDesc(lexOrder, lexScores, v.active)

	denseRank := make([]int, n)
	lexRank := make([]int, n)
	for rank := 0; rank < n; rank++ {
		denseRank[denseOrder[rank]] = rank + 1
		lexRank[lexOrder[rank]] = rank + 1
	}

	// Overlap-Weighted Reciprocal Rank Fusion (RRF, k = cfg.RRFK) + optional recency decay.
	// Weighting the lexical RRF term by fractional query-term coverage preserves exact-ID
	// precision on small-to-medium vaults where plain unweighted RRF(k=60) flattens rank 1 vs 2.
	scored := make([]ScoredMemory, n)
	rrfK := v.cfg.RRFK
	for i := 0; i < n; i++ {
		rec := v.active[i]
		rrfDense := signals.Scale / (rrfK + int64(denseRank[i]))
		rrfLex := int64(0)
		if lexScores[i] > 0 {
			rrfLex = signals.MulFixed(signals.Scale/(rrfK+int64(lexRank[i])), lexScores[i])
		}
		rrf := rrfDense + rrfLex

		finalScore := rrf
		if v.cfg.HalfLifeBlocks > 0 && currentHeight > rec.CreatedHeight {
			age := currentHeight - rec.CreatedHeight
			// Smooth fixed-point decay: score * HalfLife / (HalfLife + age)
			finalScore = (rrf * v.cfg.HalfLifeBlocks) / (v.cfg.HalfLifeBlocks + age)
		}

		scored[i] = ScoredMemory{
			Record:       rec,
			DenseFixed:   denseScores[i],
			LexicalFixed: lexScores[i],
			RRFFixed:     rrf,
			FinalFixed:   finalScore,
		}
	}

	// Sort scored memories deterministically by FinalFixed desc, DenseFixed desc, ID asc.
	for i := 1; i < len(scored); i++ {
		cur := scored[i]
		j := i - 1
		for j >= 0 && scoredLess(scored[j], cur) {
			scored[j+1] = scored[j]
			j--
		}
		scored[j+1] = cur
	}

	if k > len(scored) {
		k = len(scored)
	}
	top := scored[:k]

	ids := make([]uint64, k)
	digests := make([][32]byte, k)
	vecs := make([][]int64, k)
	for i := 0; i < k; i++ {
		ids[i] = top[i].Record.ID
		digests[i] = top[i].Record.Digest()
		vecs[i] = top[i].Record.UnitVec
	}

	batchCoherence := signals.Scale
	if k >= 2 {
		if rVal, rErr := signals.MeanResultantLengthFixed(vecs); rErr == nil {
			batchCoherence = rVal
		}
	}

	proof := MemoryRecallProof{
		VaultID:          v.cfg.VaultID,
		QueryDigest:      qDigest,
		Height:           currentHeight,
		CandidateCount:   uint64(n),
		QuarantinedCount: uint64(len(v.quarantined)),
		ReturnedIDs:      ids,
		ReturnedDigests:  digests,
		BatchCoherence:   batchCoherence,
	}
	return top, proof, nil
}

func lexicalOverlapFixed(qTerms, docTerms []string) int64 {
	if len(qTerms) == 0 || len(docTerms) == 0 {
		return 0
	}
	var hits int64
	for _, qt := range qTerms {
		for _, dt := range docTerms {
			if qt == dt {
				hits++
				break
			}
		}
	}
	if hits == 0 {
		return 0
	}
	return (hits * signals.Scale) / int64(len(qTerms))
}

func sortOrderDesc(order []int, scores []int64, records []MemoryRecord) {
	for i := 1; i < len(order); i++ {
		idx := order[i]
		j := i - 1
		for j >= 0 {
			prev := order[j]
			if scores[prev] < scores[idx] || (scores[prev] == scores[idx] && records[prev].ID > records[idx].ID) {
				order[j+1] = prev
				j--
			} else {
				break
			}
		}
		order[j+1] = idx
	}
}

func scoredLess(a, b ScoredMemory) bool {
	if a.FinalFixed != b.FinalFixed {
		return a.FinalFixed < b.FinalFixed
	}
	if a.DenseFixed != b.DenseFixed {
		return a.DenseFixed < b.DenseFixed
	}
	return a.Record.ID > b.Record.ID
}

// ExecuteWithMemory retrieves Top-K memories from vault, binds the deterministic
// MemoryRecallProof digest into ContextDigest, optionally stages retrieved vectors into
// coherenceGuard, and executes the governed action with full RFC 6962 evidence.
func (a *Agent) ExecuteWithMemory(
	vault *MemoryVault,
	coherenceGuard *CoherenceGuardPolicy,
	caller string,
	action string,
	target string,
	input []byte,
	queryEmbedding []int64,
	queryText string,
	topK int,
	budgetUgnot int64,
	height int64,
) ([]byte, EvidenceBundle, MemoryRecallProof, error) {
	if vault == nil {
		return nil, EvidenceBundle{}, MemoryRecallProof{}, errors.New("memory vault cannot be nil")
	}
	top, proof, err := vault.RetrieveTopK(queryEmbedding, queryText, topK, height)
	if err != nil {
		return nil, EvidenceBundle{}, MemoryRecallProof{}, err
	}
	if coherenceGuard != nil && len(top) >= 2 {
		vecs := make([][]int64, len(top))
		for i := range top {
			vecs[i] = top[i].Record.UnitVec
		}
		if _, _, _, sErr := coherenceGuard.StageContext(vecs); sErr != nil {
			return nil, EvidenceBundle{}, proof, sErr
		}
	}
	pDig := proof.Digest()
	out, bundle, execErr := a.Execute(caller, action, target, input, pDig[:], budgetUgnot, height)
	return out, bundle, proof, execErr
}

// AuditAndPurgeWithGeometricMedian computes the deterministic fixed-point L1 Geometric Median
// (50% breakdown point) over all currently active memories and quarantines any record whose
// alignment to the geometric median falls below thresholdFixed. Returns count of purged records.
func (v *MemoryVault) AuditAndPurgeWithGeometricMedian(thresholdFixed int64) (int, error) {
	if len(v.active) < 3 {
		return 0, nil
	}
	vecs := make([][]int64, len(v.active))
	for i := range v.active {
		vecs[i] = v.active[i].UnitVec
	}
	gm, err := signals.GeometricMedianFixed(vecs, 8)
	if err != nil {
		return 0, err
	}
	var kept []MemoryRecord
	newSum := make([]int64, v.dim)
	purged := 0
	for i := range v.active {
		rec := v.active[i]
		cos, cErr := CosineFixed(rec.UnitVec, gm)
		if cErr != nil {
			return purged, cErr
		}
		if cos < thresholdFixed {
			rec.Quarantined = true
			rec.CosToCentroid = cos
			v.quarantined = append(v.quarantined, rec)
			purged++
			continue
		}
		kept = append(kept, rec)
		for j := 0; j < v.dim; j++ {
			newSum[j] += rec.UnitVec[j]
		}
	}
	v.active = kept
	v.centroidSum = newSum
	return purged, nil
}

package assurance

import (
	"crypto/sha256"
	"encoding/binary"
	"sort"
	"strconv"
)

// Policy evaluates a canonical PolicyInputProjection and emits a fail-closed PolicyDecision.
type Policy interface {
	ID() string
	Digest() [32]byte
	Evaluate(p PolicyInputProjection) PolicyDecision
}

// AllowListPolicy permits only explicitly listed actions (and optional targets).
// Any unlisted action or target fails closed with VerdictDeny.
type AllowListPolicy struct {
	PolicyID       string
	AllowedActions []string
	AllowedTargets []string // empty means any non-empty target is allowed
}

func (p *AllowListPolicy) ID() string {
	if p.PolicyID != "" {
		return p.PolicyID
	}
	return "allowlist-v1"
}

func (p *AllowListPolicy) Digest() [32]byte {
	actions := sortedCopy(p.AllowedActions)
	targets := sortedCopy(p.AllowedTargets)
	out := make([]byte, 0, 128)
	out = appendString(out, "policy:allowlist-v1")
	out = appendString(out, p.ID())
	out = binary.BigEndian.AppendUint32(out, uint32(len(actions)))
	for _, a := range actions {
		out = appendString(out, a)
	}
	out = binary.BigEndian.AppendUint32(out, uint32(len(targets)))
	for _, t := range targets {
		out = appendString(out, t)
	}
	return sha256.Sum256(out)
}

func (p *AllowListPolicy) Evaluate(in PolicyInputProjection) PolicyDecision {
	d := p.Digest()
	if in.Action == "" {
		return PolicyDecision{
			Verdict:      VerdictDeny,
			PolicyID:     p.ID(),
			PolicyDigest: d,
			ReasonCode:   "ACTION_EMPTY",
			Reason:       "action name is required",
		}
	}
	if !containsString(p.AllowedActions, in.Action) {
		return PolicyDecision{
			Verdict:      VerdictDeny,
			PolicyID:     p.ID(),
			PolicyDigest: d,
			ReasonCode:   "ACTION_NOT_ALLOWED",
			Reason:       "action " + in.Action + " is not in policy allowlist",
		}
	}
	if len(p.AllowedTargets) > 0 && !containsString(p.AllowedTargets, in.Target) {
		return PolicyDecision{
			Verdict:      VerdictDeny,
			PolicyID:     p.ID(),
			PolicyDigest: d,
			ReasonCode:   "TARGET_NOT_ALLOWED",
			Reason:       "target " + in.Target + " is not in policy allowlist",
		}
	}
	return PolicyDecision{
		Verdict:       VerdictAllow,
		PolicyID:      p.ID(),
		PolicyDigest:  d,
		ReasonCode:    "ALLOWLIST_MATCH",
		Reason:        "action and target permitted",
		MaxSpendUgnot: in.BudgetUgnot,
	}
}

// BudgetCapPolicy enforces a per-call ugnot spend cap.
type BudgetCapPolicy struct {
	PolicyID        string
	MaxPerCallUgnot int64
}

func (p *BudgetCapPolicy) ID() string {
	if p.PolicyID != "" {
		return p.PolicyID
	}
	return "budget-cap-v1"
}

func (p *BudgetCapPolicy) Digest() [32]byte {
	out := make([]byte, 0, 64)
	out = appendString(out, "policy:budget-cap-v1")
	out = appendString(out, p.ID())
	out = binary.BigEndian.AppendUint64(out, uint64(p.MaxPerCallUgnot))
	return sha256.Sum256(out)
}

func (p *BudgetCapPolicy) Evaluate(in PolicyInputProjection) PolicyDecision {
	d := p.Digest()
	if in.BudgetUgnot < 0 {
		return PolicyDecision{
			Verdict:      VerdictDeny,
			PolicyID:     p.ID(),
			PolicyDigest: d,
			ReasonCode:   "NEGATIVE_BUDGET",
			Reason:       "budget cannot be negative",
		}
	}
	if p.MaxPerCallUgnot < 0 || in.BudgetUgnot > p.MaxPerCallUgnot {
		return PolicyDecision{
			Verdict:      VerdictDeny,
			PolicyID:     p.ID(),
			PolicyDigest: d,
			ReasonCode:   "BUDGET_EXCEEDED",
			Reason:       "requested " + strconv.FormatInt(in.BudgetUgnot, 10) + "ugnot exceeds cap " + strconv.FormatInt(p.MaxPerCallUgnot, 10) + "ugnot",
		}
	}
	return PolicyDecision{
		Verdict:       VerdictAllow,
		PolicyID:      p.ID(),
		PolicyDigest:  d,
		ReasonCode:    "BUDGET_OK",
		Reason:        "within budget cap",
		MaxSpendUgnot: in.BudgetUgnot,
	}
}

// RiskGatePolicy gates execution based on RiskTier.
// By default: LOW/MEDIUM -> ALLOW, HIGH -> REQUIRE_APPROVAL, CRITICAL -> ESCALATE.
type RiskGatePolicy struct {
	PolicyID          string
	AllowHigh         bool
	DenyCritical      bool
	RequireApprovalHi bool // default true when AllowHigh is false
}

func (p *RiskGatePolicy) ID() string {
	if p.PolicyID != "" {
		return p.PolicyID
	}
	return "risk-gate-v1"
}

func (p *RiskGatePolicy) Digest() [32]byte {
	out := make([]byte, 0, 64)
	out = appendString(out, "policy:risk-gate-v1")
	out = appendString(out, p.ID())
	out = append(out, boolByte(p.AllowHigh), boolByte(p.DenyCritical), boolByte(p.RequireApprovalHi))
	return sha256.Sum256(out)
}

func (p *RiskGatePolicy) Evaluate(in PolicyInputProjection) PolicyDecision {
	d := p.Digest()
	switch in.RiskTier {
	case RiskLow, RiskMedium:
		return PolicyDecision{
			Verdict:       VerdictAllow,
			PolicyID:      p.ID(),
			PolicyDigest:  d,
			ReasonCode:    "RISK_WITHIN_THRESHOLD",
			Reason:        "risk tier " + string(in.RiskTier) + " permitted for autonomous execution",
			MaxSpendUgnot: in.BudgetUgnot,
		}
	case RiskHigh:
		if p.AllowHigh {
			return PolicyDecision{
				Verdict:       VerdictAllow,
				PolicyID:      p.ID(),
				PolicyDigest:  d,
				ReasonCode:    "RISK_HIGH_ALLOWED",
				Reason:        "high risk explicitly permitted by policy",
				MaxSpendUgnot: in.BudgetUgnot,
			}
		}
		return PolicyDecision{
			Verdict:      VerdictRequireApproval,
			PolicyID:     p.ID(),
			PolicyDigest: d,
			ReasonCode:   "HIGH_RISK_APPROVAL_REQUIRED",
			Reason:       "high risk actions require explicit principal approval",
		}
	case RiskCritical:
		if p.DenyCritical {
			return PolicyDecision{
				Verdict:      VerdictDeny,
				PolicyID:     p.ID(),
				PolicyDigest: d,
				ReasonCode:   "CRITICAL_RISK_DENIED",
				Reason:       "critical risk actions are denied",
			}
		}
		return PolicyDecision{
			Verdict:      VerdictEscalate,
			PolicyID:     p.ID(),
			PolicyDigest: d,
			ReasonCode:   "CRITICAL_RISK_ESCALATED",
			Reason:       "critical risk actions must escalate to human governance",
		}
	default:
		return PolicyDecision{
			Verdict:      VerdictDeny,
			PolicyID:     p.ID(),
			PolicyDigest: d,
			ReasonCode:   "UNKNOWN_RISK_TIER",
			Reason:       "unrecognized risk tier fails closed",
		}
	}
}

// CompositePolicy evaluates all child policies in order and fails closed:
// the strictest verdict wins (DENY > ESCALATE > REQUIRE_APPROVAL > ALLOW).
// An empty CompositePolicy always fails closed with DENY.
type CompositePolicy struct {
	PolicyID string
	Rules    []Policy
}

func (c *CompositePolicy) ID() string {
	if c.PolicyID != "" {
		return c.PolicyID
	}
	return "composite-v1"
}

func (c *CompositePolicy) Digest() [32]byte {
	out := make([]byte, 0, 64+len(c.Rules)*32)
	out = appendString(out, "policy:composite-v1")
	out = appendString(out, c.ID())
	out = binary.BigEndian.AppendUint32(out, uint32(len(c.Rules)))
	for _, r := range c.Rules {
		if r == nil {
			z := ZeroDigest()
			out = append(out, z[:]...)
			continue
		}
		d := r.Digest()
		out = append(out, d[:]...)
	}
	return sha256.Sum256(out)
}

func (c *CompositePolicy) Evaluate(in PolicyInputProjection) PolicyDecision {
	cd := c.Digest()
	if len(c.Rules) == 0 {
		return PolicyDecision{
			Verdict:      VerdictDeny,
			PolicyID:     c.ID(),
			PolicyDigest: cd,
			ReasonCode:   "EMPTY_POLICY",
			Reason:       "composite policy with zero rules fails closed",
		}
	}
	worst := PolicyDecision{
		Verdict:       VerdictAllow,
		PolicyID:      c.ID(),
		PolicyDigest:  cd,
		ReasonCode:    "ALL_RULES_PASSED",
		Reason:        "all composite rules permitted execution",
		MaxSpendUgnot: in.BudgetUgnot,
	}
	for _, rule := range c.Rules {
		if rule == nil {
			return PolicyDecision{
				Verdict:      VerdictDeny,
				PolicyID:     c.ID(),
				PolicyDigest: cd,
				ReasonCode:   "NIL_RULE",
				Reason:       "nil policy rule fails closed",
			}
		}
		res := rule.Evaluate(in)
		if VerdictSeverity(res.Verdict) > VerdictSeverity(worst.Verdict) {
			worst = PolicyDecision{
				Verdict:       res.Verdict,
				PolicyID:      c.ID(),
				PolicyDigest:  cd,
				ReasonCode:    res.ReasonCode,
				Reason:        res.Reason,
				MaxSpendUgnot: 0,
			}
		} else if res.Verdict == VerdictAllow && worst.Verdict == VerdictAllow {
			if res.MaxSpendUgnot < worst.MaxSpendUgnot {
				worst.MaxSpendUgnot = res.MaxSpendUgnot
			}
		}
	}
	return worst
}

func containsString(list []string, target string) bool {
	for _, s := range list {
		if s == target {
			return true
		}
	}
	return false
}

func sortedCopy(in []string) []string {
	out := make([]string, len(in))
	copy(out, in)
	sort.Strings(out)
	return out
}

func boolByte(b bool) byte {
	if b {
		return 1
	}
	return 0
}

package assurance

import (
	"crypto/sha256"
	"encoding/binary"
	"errors"
)

// EncodingVersion is fixed for all v1 canonical structures.
// Any wire-format change increments this version rather than mutating v1.
const EncodingVersion uint8 = 1

const (
	DomainProjection = "arobi-assurance-projection-v1"
	DomainWarrant    = "arobi-assurance-warrant-v1"
	DomainReceipt    = "arobi-assurance-decision-receipt-v1"
	DomainClosure    = "arobi-assurance-effect-closure-v1"
	DomainAnchor     = "arobi-assurance-anchor-v1"
)

// Verdict is the fail-closed decision emitted by a Policy.
type Verdict string

const (
	VerdictAllow           Verdict = "ALLOW"
	VerdictDeny            Verdict = "DENY"
	VerdictRequireApproval Verdict = "REQUIRE_APPROVAL"
	VerdictEscalate        Verdict = "ESCALATE"
)

// VerdictSeverity ranks verdicts from least to most restrictive for fail-closed composition.
func VerdictSeverity(v Verdict) int {
	switch v {
	case VerdictAllow:
		return 0
	case VerdictRequireApproval:
		return 1
	case VerdictEscalate:
		return 2
	case VerdictDeny:
		return 3
	default:
		// Unknown verdicts fail closed as DENY.
		return 3
	}
}

// RiskTier classifies the blast radius of a governed agent tool.
type RiskTier string

const (
	RiskLow      RiskTier = "LOW"
	RiskMedium   RiskTier = "MEDIUM"
	RiskHigh     RiskTier = "HIGH"
	RiskCritical RiskTier = "CRITICAL"
)

// Outcome classifies how a warranted or refused effect closed.
type Outcome string

const (
	OutcomeExecuted   Outcome = "EXECUTED"
	OutcomeFailed     Outcome = "FAILED"
	OutcomeRolledBack Outcome = "ROLLED_BACK"
	OutcomeRefused    Outcome = "REFUSED"
)

// PolicyInputProjection is the canonical, deterministic snapshot of everything a policy
// inspects before an agent acts. Its Digest() binds receipts and warrants to exact inputs.
type PolicyInputProjection struct {
	ChainID       string
	Realm         string
	AgentID       string
	Principal     string
	Caller        string
	Action        string
	Target        string
	InputDigest   [32]byte
	ContextDigest [32]byte
	BudgetUgnot   int64
	RiskTier      RiskTier
	Height        int64
}

// Encode serializes PolicyInputProjection into canonical length-prefixed big-endian bytes.
func (p PolicyInputProjection) Encode() []byte {
	out := make([]byte, 0, 256)
	out = appendString(out, DomainProjection)
	out = append(out, EncodingVersion)
	out = appendString(out, p.ChainID)
	out = appendString(out, p.Realm)
	out = appendString(out, p.AgentID)
	out = appendString(out, p.Principal)
	out = appendString(out, p.Caller)
	out = appendString(out, p.Action)
	out = appendString(out, p.Target)
	out = append(out, p.InputDigest[:]...)
	out = append(out, p.ContextDigest[:]...)
	out = binary.BigEndian.AppendUint64(out, uint64(p.BudgetUgnot))
	out = appendString(out, string(p.RiskTier))
	out = binary.BigEndian.AppendUint64(out, uint64(p.Height))
	return out
}

// Digest returns SHA-256(Encode()).
func (p PolicyInputProjection) Digest() [32]byte {
	return sha256.Sum256(p.Encode())
}

// PolicyDecision is the deterministic result of evaluating a Policy against a projection.
type PolicyDecision struct {
	Verdict       Verdict
	PolicyID      string
	PolicyDigest  [32]byte
	ReasonCode    string
	Reason        string
	MaxSpendUgnot int64
}

// EffectWarrant is a single-use cryptographic authorization bound to one exact projection
// and policy evaluation. A tool cannot execute without an unconsumed, unexpired warrant.
type EffectWarrant struct {
	ID               uint64
	AgentID          string
	ProjectionDigest [32]byte
	PolicyDigest     [32]byte
	Action           string
	Target           string
	MaxSpendUgnot    int64
	IssuedHeight     int64
	ExpiryHeight     int64
	Consumed         bool
}

// Encode serializes the immutable fields of EffectWarrant (excluding mutable Consumed flag).
func (w EffectWarrant) Encode() []byte {
	out := make([]byte, 0, 192)
	out = appendString(out, DomainWarrant)
	out = append(out, EncodingVersion)
	out = binary.BigEndian.AppendUint64(out, w.ID)
	out = appendString(out, w.AgentID)
	out = append(out, w.ProjectionDigest[:]...)
	out = append(out, w.PolicyDigest[:]...)
	out = appendString(out, w.Action)
	out = appendString(out, w.Target)
	out = binary.BigEndian.AppendUint64(out, uint64(w.MaxSpendUgnot))
	out = binary.BigEndian.AppendUint64(out, uint64(w.IssuedHeight))
	out = binary.BigEndian.AppendUint64(out, uint64(w.ExpiryHeight))
	return out
}

// Digest returns SHA-256(Encode()).
func (w EffectWarrant) Digest() [32]byte {
	return sha256.Sum256(w.Encode())
}

// DecisionReceipt is an immutable, hash-chained record of a policy gate evaluation.
type DecisionReceipt struct {
	Seq              uint64
	PrevHash         [32]byte
	ChainID          string
	Realm            string
	AgentID          string
	Caller           string
	ProjectionDigest [32]byte
	PolicyDigest     [32]byte
	Verdict          Verdict
	ReasonCode       string
	WarrantDigest    [32]byte // zero digest when not ALLOW
	Height           int64
}

// Encode serializes DecisionReceipt into canonical bytes.
func (r DecisionReceipt) Encode() []byte {
	out := make([]byte, 0, 256)
	out = appendString(out, DomainReceipt)
	out = append(out, EncodingVersion)
	out = binary.BigEndian.AppendUint64(out, r.Seq)
	out = append(out, r.PrevHash[:]...)
	out = appendString(out, r.ChainID)
	out = appendString(out, r.Realm)
	out = appendString(out, r.AgentID)
	out = appendString(out, r.Caller)
	out = append(out, r.ProjectionDigest[:]...)
	out = append(out, r.PolicyDigest[:]...)
	out = appendString(out, string(r.Verdict))
	out = appendString(out, r.ReasonCode)
	out = append(out, r.WarrantDigest[:]...)
	out = binary.BigEndian.AppendUint64(out, uint64(r.Height))
	return out
}

// LeafHash returns RFC 6962 LeafHash(Encode()).
func (r DecisionReceipt) LeafHash() [32]byte {
	return LeafHash(r.Encode())
}

// EffectClosure binds the execution result (or refusal) back to its DecisionReceipt and Warrant.
type EffectClosure struct {
	Seq              uint64
	PrevHash         [32]byte
	AgentID          string
	WarrantDigest    [32]byte // zero digest when OutcomeRefused
	DecisionLeafHash [32]byte
	OutputDigest     [32]byte
	WitnessDigest    [32]byte
	Outcome          Outcome
	SpentUgnot       int64
	Height           int64
}

// Encode serializes EffectClosure into canonical bytes.
func (c EffectClosure) Encode() []byte {
	out := make([]byte, 0, 256)
	out = appendString(out, DomainClosure)
	out = append(out, EncodingVersion)
	out = binary.BigEndian.AppendUint64(out, c.Seq)
	out = append(out, c.PrevHash[:]...)
	out = appendString(out, c.AgentID)
	out = append(out, c.WarrantDigest[:]...)
	out = append(out, c.DecisionLeafHash[:]...)
	out = append(out, c.OutputDigest[:]...)
	out = append(out, c.WitnessDigest[:]...)
	out = appendString(out, string(c.Outcome))
	out = binary.BigEndian.AppendUint64(out, uint64(c.SpentUgnot))
	out = binary.BigEndian.AppendUint64(out, uint64(c.Height))
	return out
}

// LeafHash returns RFC 6962 LeafHash(Encode()).
func (c EffectClosure) LeafHash() [32]byte {
	return LeafHash(c.Encode())
}

// AnchorRecord is the canonical on-chain record stored by gno.land/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance.
type AnchorRecord struct {
	ChainID        string
	Realm          string
	AnchorID       uint64
	AgentID        string
	Caller         string
	Height         int64
	PrevRoot       [32]byte
	CheckpointRoot [32]byte
	LeafCount      uint64
	ReceiptCount   uint64
	ClosureCount   uint64
}

// Encode serializes AnchorRecord into canonical bytes.
func (a AnchorRecord) Encode() []byte {
	out := make([]byte, 0, 224)
	out = appendString(out, DomainAnchor)
	out = append(out, EncodingVersion)
	out = appendString(out, a.ChainID)
	out = appendString(out, a.Realm)
	out = binary.BigEndian.AppendUint64(out, a.AnchorID)
	out = appendString(out, a.AgentID)
	out = appendString(out, a.Caller)
	out = binary.BigEndian.AppendUint64(out, uint64(a.Height))
	out = append(out, a.PrevRoot[:]...)
	out = append(out, a.CheckpointRoot[:]...)
	out = binary.BigEndian.AppendUint64(out, a.LeafCount)
	out = binary.BigEndian.AppendUint64(out, a.ReceiptCount)
	out = binary.BigEndian.AppendUint64(out, a.ClosureCount)
	return out
}

// LeafHash returns RFC 6962 LeafHash(Encode()).
func (a AnchorRecord) LeafHash() [32]byte {
	return LeafHash(a.Encode())
}

// EvidenceBundle is the self-verifying artifact returned out of the box by every
// governed agent action. Any third party can call Verify() without trusting the agent.
type EvidenceBundle struct {
	Projection       PolicyInputProjection
	Decision         PolicyDecision
	HasWarrant       bool
	Warrant          EffectWarrant
	Receipt          DecisionReceipt
	Closure          EffectClosure
	ReceiptLeafIndex uint64
	ClosureLeafIndex uint64
	AccumulatorSize  uint64
	AccumulatorRoot  [32]byte
	ReceiptProof     [][32]byte
	ClosureProof     [][32]byte
}

// Verify independently recomputes every digest, hash-chain link, warrant binding,
// and RFC 6962 Merkle inclusion proof contained in the bundle.
func (b EvidenceBundle) Verify() error {
	projDigest := b.Projection.Digest()
	if b.Receipt.ProjectionDigest != projDigest {
		return errors.New("receipt projection digest mismatch")
	}
	if b.Receipt.PolicyDigest != b.Decision.PolicyDigest {
		return errors.New("receipt policy digest mismatch")
	}
	if b.Receipt.Verdict != b.Decision.Verdict {
		return errors.New("receipt verdict mismatch")
	}

	if b.Decision.Verdict == VerdictAllow {
		if !b.HasWarrant {
			return errors.New("allowed decision missing warrant")
		}
		if b.Warrant.ProjectionDigest != projDigest {
			return errors.New("warrant projection digest mismatch")
		}
		if b.Warrant.PolicyDigest != b.Decision.PolicyDigest {
			return errors.New("warrant policy digest mismatch")
		}
		wDigest := b.Warrant.Digest()
		if b.Receipt.WarrantDigest != wDigest {
			return errors.New("receipt warrant digest mismatch")
		}
		if b.Closure.WarrantDigest != wDigest {
			return errors.New("closure warrant digest mismatch")
		}
	} else {
		if b.HasWarrant {
			return errors.New("non-allow decision must not issue a warrant")
		}
		if b.Receipt.WarrantDigest != ZeroDigest() || b.Closure.WarrantDigest != ZeroDigest() {
			return errors.New("non-allow decision must have zero warrant digest")
		}
		if b.Closure.Outcome != OutcomeRefused {
			return errors.New("non-allow decision must close as REFUSED")
		}
	}

	rLeaf := b.Receipt.LeafHash()
	if b.Closure.DecisionLeafHash != rLeaf {
		return errors.New("closure decision leaf hash mismatch")
	}
	if b.Closure.PrevHash != rLeaf {
		return errors.New("closure hash-chain PrevHash does not point to its decision receipt")
	}

	cLeaf := b.Closure.LeafHash()
	if !VerifyInclusion(b.ReceiptLeafIndex, b.AccumulatorSize, rLeaf, b.ReceiptProof, b.AccumulatorRoot) {
		return errors.New("decision receipt RFC 6962 inclusion proof failed")
	}
	if !VerifyInclusion(b.ClosureLeafIndex, b.AccumulatorSize, cLeaf, b.ClosureProof, b.AccumulatorRoot) {
		return errors.New("effect closure RFC 6962 inclusion proof failed")
	}
	return nil
}

func appendString(out []byte, s string) []byte {
	out = binary.BigEndian.AppendUint32(out, uint32(len(s)))
	return append(out, []byte(s)...)
}

// Package assurance is the public on-chain Gno.land Agent Passport Registry and
// RFC 6962 Evidence Anchor for the Immaculate Agent SDK Builder.
//
// Any agent built with gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance can register an owner-bound passport,
// anchor hash-chained evidence checkpoints (paying AnchorFeeUgnot in GNOT), optionally
// subscribe to the Pro Agent Plan in GNOT for 1-block high-frequency anchoring, and let
// any third party verify RFC 6962 inclusion proofs on-chain or offline.
//
// Settlement privacy: service fees are enforced on-chain in GNOT while operator
// settlement routing is configured privately at deployment time and never hardcoded or
// publicly disclosed in source code, chain events, or gnoweb pages.
package assurance

