			if pp.Revoked {
				status = "REVOKED"
			}
			tip := sdk.Hex(pp.LastRoot)[:16] + "..."
			b.WriteString("| [" + pp.AgentID + "](/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance:agent/" + pp.AgentID + ") | " +
				pp.DisplayName + " | " + status + " | " +
				strconv.FormatUint(pp.AnchorCount, 10) + " | " +
				strconv.FormatUint(pp.TotalLeaves, 10) + " | `" + tip + "` |\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("## Recent Anchored Checkpoints\n\n")
	if len(anchors) == 0 {
		b.WriteString("_No checkpoints anchored yet._\n")
	} else {
		start := 0
		if len(anchors) > 20 {
			start = len(anchors) - 20
		}
		for i := len(anchors) - 1; i >= start; i-- {
			a := anchors[i]
			idStr := strconv.FormatUint(a.AnchorID, 10)
			b.WriteString("- [Checkpoint #" + idStr + "](/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance:checkpoint/" + idStr + ") — agent `" +
