package whisper

import (
	"crypto/sha256"
	"encoding/binary"
	"errors"

	"gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance"
)

const (
	DomainAgentBus = "arobi-whisper-agent-bus-v1"

	// Standard cross-shell / cross-environment / cross-harness message kinds.
	AgentKindTaskDispatch    = "task_dispatch"
	AgentKindWarrantDelegate = "warrant_delegate"
	AgentKindEvidenceReceipt = "evidence_receipt"
	AgentKindStatusReply     = "status_reply"
	AgentKindHandoff         = "handoff"
	AgentKindHaltSignal      = "halt_signal"
	AgentKindCapabilityLease = "capability_lease"
	AgentKindMemorySync      = "memory_sync"
)

// AgentBusRoute describes the authenticated routing metadata for an encrypted cross-shell,
// cross-environment, or cross-harness agent/Familiar packet carried inside a Whisper SealedEnvelope.
// Plaintext prompts, code, and secrets stay encrypted inside SealedEnvelope.CiphertextB64.
type AgentBusRoute struct {
	FromHarness           string // e.g. "ullumii", "gnosh.ai", "shell", "mcp", "gno-realm", "local-llm"
	FromEnv               string // e.g. "linux-docker", "windows-pwsh", "wsl", "cloud-worker"
	FromAgentID           string
	ToHarness             string
	ToEnv                 string
	ToAgentID             string
	Kind                  string // AgentKind*
	CorrelationID         string
	ParentWarrantDigest   string // optional 64-hex digest linking to gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance
	EvidenceRootHex       string // optional 64-hex RFC 6962 accumulator root
	CapabilityDigestHex   string // optional 64-hex Familiar CapabilityToken digest
	MemoryRecallDigestHex string // optional 64-hex MemoryRecallProof digest
}

// Validate checks routing metadata fields before hashing or sealing.
func (r AgentBusRoute) Validate() error {
	if r.FromHarness == "" || r.FromAgentID == "" {
		return errors.New("fromHarness and fromAgentID are required")
	}
	if r.ToHarness == "" || r.ToAgentID == "" {
		return errors.New("toHarness and toAgentID are required")
	}
	switch r.Kind {
	case AgentKindTaskDispatch, AgentKindWarrantDelegate, AgentKindEvidenceReceipt,
		AgentKindStatusReply, AgentKindHandoff, AgentKindHaltSignal,
		AgentKindCapabilityLease, AgentKindMemorySync:
	default:
		return errors.New("unsupported agent bus message kind: " + r.Kind)
	}
	if r.CorrelationID == "" || len(r.CorrelationID) > 64 {
		return errors.New("correlationID must be 1..64 characters")
	}
	if r.ParentWarrantDigest != "" {
		if _, err := assurance.ParseDigest(r.ParentWarrantDigest); err != nil {
			return errors.New("parentWarrantDigest: " + err.Error())
		}
	}
	if r.EvidenceRootHex != "" {
		if _, err := assurance.ParseDigest(r.EvidenceRootHex); err != nil {
			return errors.New("evidenceRootHex: " + err.Error())
		}
	}
	if r.CapabilityDigestHex != "" {
		if _, err := assurance.ParseDigest(r.CapabilityDigestHex); err != nil {
			return errors.New("capabilityDigestHex: " + err.Error())
		}
	}
	if r.MemoryRecallDigestHex != "" {
		if _, err := assurance.ParseDigest(r.MemoryRecallDigestHex); err != nil {
			return errors.New("memoryRecallDigestHex: " + err.Error())
		}
	}
	return nil
}

// Encode serializes AgentBusRoute into canonical length-prefixed big-endian bytes.
func (r AgentBusRoute) Encode() []byte {
	out := make([]byte, 0, 256)
	out = appendStr(out, DomainAgentBus)
	out = append(out, EncodingVersion)
	out = appendStr(out, r.FromHarness)
	out = appendStr(out, r.FromEnv)
	out = appendStr(out, r.FromAgentID)
	out = appendStr(out, r.ToHarness)
	out = appendStr(out, r.ToEnv)
	out = appendStr(out, r.ToAgentID)
	out = appendStr(out, r.Kind)
	out = appendStr(out, r.CorrelationID)
	out = appendStr(out, r.ParentWarrantDigest)
	out = appendStr(out, r.EvidenceRootHex)
	out = appendStr(out, r.CapabilityDigestHex)
	out = appendStr(out, r.MemoryRecallDigestHex)
	return out
}

// Digest returns SHA-256(Encode()) for binding route metadata to encrypted envelopes.
func (r AgentBusRoute) Digest() [32]byte {
	return sha256.Sum256(r.Encode())
}

// LeafHash returns the RFC 6962 leaf hash of this cross-harness route commitment.
func (r AgentBusRoute) LeafHash() [32]byte {
	return assurance.LeafHash(r.Encode())
}

// BindAgentEnvelopeCommitment computes SHA-256(routeDigest || payloadCommitment) so both
// the encrypted ciphertext and the cross-harness route metadata are tamper-evident together.
func BindAgentEnvelopeCommitment(route AgentBusRoute, payloadCommitmentHex string) (string, error) {
	if err := route.Validate(); err != nil {
		return "", err
	}
	pDig, err := assurance.ParseDigest(payloadCommitmentHex)
	if err != nil {
		return "", err
	}
	rDig := route.Digest()
	buf := make([]byte, 0, 8+64)
	buf = binary.BigEndian.AppendUint32(buf, 64)
	buf = append(buf, rDig[:]...)
	buf = append(buf, pDig[:]...)
	return assurance.Hex(sha256.Sum256(buf)), nil
}

// Package whisper defines the canonical E2E-encrypted envelope, handle validation,
// and DeFi escrow evidence primitives for Arobi Whisper on Gno.land.
//
// Wire-compatible with live Arobi Whisper (aura-genesis.org/whisper):
//   - Client generates local X25519 (encryption) + Ed25519 (optional signing) keypairs.
//   - Each message is sealed client-side with an ephemeral X25519 key + HKDF-SHA256
//     (domain "arobi-whisper-x25519-xchacha-v1") + XChaCha20-Poly1305 (24-byte nonce).
//   - Commitment = SHA-256(ciphertext_bytes || ephemeralPk_bytes || nonce_bytes).
//   - Only ciphertext, ephemeral public key, nonce, and commitment ever touch chain state.
//
// Built on gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance for RFC 6962 / RFC 9162 Merkle evidence anchoring.
package whisper

import (
	"crypto/sha256"
	"encoding/base64"
	"encoding/binary"
	"errors"
	"strings"

	"gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance"
)

const (
	EncodingVersion uint8 = 1
	DomainEnvelope        = "arobi-whisper-gno-envelope-v1"
	DomainEscrow          = "arobi-whisper-gno-escrow-v1"

	// MaxCiphertextB64Len bounds on-chain encrypted payload size (16 KiB base64 ~ 12 KiB ciphertext).
	MaxCiphertextB64Len = 16384
)

// EscrowStatus tracks the lifecycle of a conditional DeFi escrow attached to an encrypted message.
type EscrowStatus string

const (
	EscrowOpen     EscrowStatus = "OPEN"
	EscrowClaimed  EscrowStatus = "CLAIMED"
	EscrowRefunded EscrowStatus = "REFUNDED"
)

var reservedHandles = map[string]bool{
	"arobi": true, "admin": true, "administrator": true, "support": true,
	"help": true, "security": true, "root": true, "system": true,
	"official": true, "whisper": true, "aura": true, "arobiteam": true,
	"moderator": true, "mod": true, "staff": true, "billing": true,
	"payments": true, "noreply": true, "ullumii": true, "treasury": true,
}

// ValidateKeyHex validates a 32-byte (64 lowercase hex char) X25519 or Ed25519 public key.
func ValidateKeyHex(s string) error {
	_, err := assurance.ParseDigest(s)
	if err != nil {
		return errors.New("public key must be 64 lowercase hexadecimal characters (32 bytes)")
	}
	return nil
}

// ValidateNonceHex validates a 24-byte (48 lowercase hex char) XChaCha20-Poly1305 nonce.
func ValidateNonceHex(s string) error {
	if len(s) != 48 {
		return errors.New("nonce must be 48 lowercase hexadecimal characters (24 bytes)")
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			return errors.New("nonce must be 48 lowercase hexadecimal characters (24 bytes)")
		}
	}
	return nil
}

// ValidateCiphertextB64 verifies non-empty, bounded, canonical Base64 ciphertext.
func ValidateCiphertextB64(s string) error {
	if len(s) == 0 || len(s) > MaxCiphertextB64Len {
		return errors.New("ciphertext base64 length out of range (1..16384)")
	}
	if len(s)%4 != 0 {
		return errors.New("ciphertext must be canonical padded base64")
	}
	raw, err := base64.StdEncoding.DecodeString(s)
	if err != nil || len(raw) < 17 {
		// XChaCha20-Poly1305 carries a 16-byte Poly1305 auth tag + >= 1 byte plaintext.
		return errors.New("invalid ciphertext base64 or shorter than 16-byte AEAD tag")
	}
	if base64.StdEncoding.EncodeToString(raw) != s {
		return errors.New("ciphertext is not canonical base64")
	}
	return nil
}

// NormalizeHandle validates and normalizes a Whisper handle (3..20 lowercase a-z0-9_, no __).
func NormalizeHandle(raw string) (string, error) {
	u := strings.ToLower(strings.TrimSpace(raw))
	u = strings.TrimLeft(u, "@")
	if len(u) < 3 || len(u) > 20 {
		return "", errors.New("handle must be 3..20 characters")
	}
	if u[0] == '_' || u[len(u)-1] == '_' || strings.Contains(u, "__") {
		return "", errors.New("handle cannot start/end with underscore or contain double underscores")
	}
	for i := 0; i < len(u); i++ {
		c := u[i]
		ok := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_'
		if !ok {
			return "", errors.New("handle may only contain lowercase letters, digits, and single underscores")
		}
	}
	if reservedHandles[u] {
		return "", errors.New("handle is reserved: " + u)
	}
	return u, nil
}

// SealedEnvelope is one end-to-end encrypted message stored on-chain (ciphertext only).
type SealedEnvelope struct {
	ID              uint64
	ChainID         string
	Realm           string
	From            string
	To              string
	EphemeralPubHex string
	NonceHex        string
	CiphertextB64   string
	CommitmentHex   string
	TipUgnot        int64
	EscrowID        uint64
	Height          int64
	LeafIndex       uint64
}

// Encode serializes SealedEnvelope into canonical length-prefixed big-endian bytes.
func (e SealedEnvelope) Encode() []byte {
	out := make([]byte, 0, 256)
	out = appendStr(out, DomainEnvelope)
	out = append(out, EncodingVersion)
	out = binary.BigEndian.AppendUint64(out, e.ID)
	out = appendStr(out, e.ChainID)
	out = appendStr(out, e.Realm)
	out = appendStr(out, e.From)
	out = appendStr(out, e.To)
	out = appendStr(out, e.EphemeralPubHex)
	out = appendStr(out, e.NonceHex)
	ctHash := sha256.Sum256([]byte(e.CiphertextB64))
	out = append(out, ctHash[:]...)
	out = appendStr(out, e.CommitmentHex)
	out = binary.BigEndian.AppendUint64(out, uint64(e.TipUgnot))
	out = binary.BigEndian.AppendUint64(out, e.EscrowID)
	out = binary.BigEndian.AppendUint64(out, uint64(e.Height))
	return out
}

// LeafHash returns the RFC 6962 leaf hash via gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance.
func (e SealedEnvelope) LeafHash() [32]byte {
	return assurance.LeafHash(e.Encode())
}

// EscrowRecord represents a conditional GNOT escrow attached to an encrypted Whisper message.
type EscrowRecord struct {
	ID            uint64
	MessageID     uint64
	Sender        string
	Recipient     string
	AmountUgnot   int64
	HashLockHex   string // empty = open recipient claim; 64-hex = SHA-256(preimage) HTLC
	ExpiryHeight  int64
	Status        EscrowStatus
	CreatedHeight int64
	SettledHeight int64
}

// Encode serializes EscrowRecord state for RFC 6962 evidence anchoring.
func (r EscrowRecord) Encode() []byte {
	out := make([]byte, 0, 224)
	out = appendStr(out, DomainEscrow)
	out = append(out, EncodingVersion)
	out = binary.BigEndian.AppendUint64(out, r.ID)
	out = binary.BigEndian.AppendUint64(out, r.MessageID)
	out = appendStr(out, r.Sender)
	out = appendStr(out, r.Recipient)
	out = binary.BigEndian.AppendUint64(out, uint64(r.AmountUgnot))
	out = appendStr(out, r.HashLockHex)
	out = binary.BigEndian.AppendUint64(out, uint64(r.ExpiryHeight))
	out = appendStr(out, string(r.Status))
	out = binary.BigEndian.AppendUint64(out, uint64(r.CreatedHeight))
	out = binary.BigEndian.AppendUint64(out, uint64(r.SettledHeight))
	return out
}

// LeafHash returns the RFC 6962 leaf hash via gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance.
func (r EscrowRecord) LeafHash() [32]byte {
	return assurance.LeafHash(r.Encode())
}

// ComputeHashLock computes SHA-256(preimage) as 64 lowercase hex characters for HTLC escrows.
func ComputeHashLock(preimage string) string {
	return assurance.Hex(assurance.HashString(preimage))
}

func appendStr(out []byte, s string) []byte {
	out = binary.BigEndian.AppendUint32(out, uint32(len(s)))
	return append(out, []byte(s)...)
}

package whisper

import (
	"strconv"
	"strings"

	"gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance"
)

// Render serves the gnoweb explorer for Arobi Whisper on Gno.land.
//
// Routes:
//   /                      Directory, global RFC 6962 commitment root, escrow stats
//   /u/<handle-or-addr>    Public X25519 keycard & inbox policy
//   /inbox/<handle-or-addr> Public encrypted envelopes & commitments (zero plaintext)
//   /escrow/<id>           DeFi conditional escrow status & settlement audit
func Render(path string) string {
	clean := strings.Trim(path, "/")
	if clean == "" {
		return renderHome()
	}
	if strings.HasPrefix(clean, "u/") {
		return renderUser(strings.TrimPrefix(clean, "u/"))
	}
	if strings.HasPrefix(clean, "inbox/") {
		return renderInbox(strings.TrimPrefix(clean, "inbox/"))
	}
	if strings.HasPrefix(clean, "escrow/") {
		return renderEscrow(strings.TrimPrefix(clean, "escrow/"))
	}
	return "# Not Found\n\nUnknown path `" + clean + "`.\n\n[Back to Arobi Whisper](/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/whisper)"
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Arobi Whisper — End-to-End Encrypted DeFi Chat on Gno.land\n\n")
	b.WriteString("Client-side `X25519 + HKDF-SHA256 + XChaCha20-Poly1305` sealed boxes paired with native GNOT ")
	b.WriteString("tipping, hash-locked DeFi escrows, programmable anti-spam inbox policies, and RFC 6962 ")
	b.WriteString("evidence proofs powered by `gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance`. Plaintext never touches chain state.\n\n")

	b.WriteString("| Metric | Value |\n| --- | --- |\n")
	b.WriteString("| Free Tier | `" + strconv.FormatInt(FreePeriodCredits, 10) + "` credits, `4 KiB` max ciphertext |\n")
	b.WriteString("| Pro Subscription (30 days) | `" + strconv.FormatInt(subscriptionPriceUgnot, 10) + "ugnot` (`" + strconv.FormatInt(ProPeriodCredits, 10) + "` credits, `16 KiB` ciphertext, DeFi HTLC escrows) |\n")
	b.WriteString("| Overage / Escrow Settlement Fee | `" + strconv.FormatInt(overageFeeUgnot, 10) + "ugnot` per overage msg · `" + strconv.FormatInt(escrowFeeBps, 10) + " bps` on claimed escrows |\n")
	b.WriteString("| Registered Identities | " + strconv.Itoa(len(identityOrder)) + " |\n")
	b.WriteString("| Encrypted Messages | " + strconv.Itoa(len(messages)) + " |\n")
	b.WriteString("| DeFi Escrows Created | " + strconv.Itoa(len(escrows)) + " |\n")
	b.WriteString("| Total Direct Tips | `" + strconv.FormatInt(totalTips, 10) + "ugnot` |\n")
	b.WriteString("| Total Escrowed Volume | `" + strconv.FormatInt(totalEscrowed, 10) + "ugnot` |\n")
	b.WriteString("| Evidence Accumulator Leaves | " + strconv.FormatUint(evidenceAcc.Size(), 10) + " |\n")
	b.WriteString("| Global RFC 6962 Root | `" + assurance.Hex(evidenceAcc.Root()) + "` |\n\n")

	b.WriteString("## Public X25519 Key Directory\n\n")
	if len(identityOrder) == 0 {
		b.WriteString("_No identities registered yet. Call `RegisterIdentity` to publish your X25519 public key._\n")
		return b.String()
	}

	b.WriteString("| Handle | Address | Min Tip | Allowlist | Inbox | Keycard |\n")
	b.WriteString("| --- | --- | ---: | --- | ---: | --- |\n")
	for _, addr := range identityOrder {
		id, ok := identities.Get(addr).(*Identity)
		if !ok || id == nil {
			continue
		}
		hLabel := "_none_"
		linkKey := id.Address.String()
		if id.Handle != "" {
			hLabel = "@" + id.Handle
			linkKey = id.Handle
		}
		b.WriteString("| " + hLabel + " | `" + id.Address.String() + "` | `" +
			strconv.FormatInt(id.MinTipUgnot, 10) + "ugnot` | `" +
			strconv.FormatBool(id.AllowListOnly) + "` | " +
			"[View (" + strconv.Itoa(len(id.InboxIDs)) + ")](/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/whisper:inbox/" + linkKey + ") | " +
			"[Keycard](/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/whisper:u/" + linkKey + ") |\n")
	}
	return b.String()
}

func renderUser(q string) string {
	id, ok := tryResolveIdentity(q)
	if !ok {
		return "# Identity Not Found\n\nNo Whisper identity for `" + q + "`.\n\n[Back](/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/whisper)"
	}
	var b strings.Builder
	title := id.Address.String()
	if id.Handle != "" {
		title = "@" + id.Handle + " (`" + id.Address.String() + "`)"
	}
	b.WriteString("# Whisper Keycard: " + title + "\n\n")
	if id.DisplayName != "" {
		b.WriteString("- **Display Name:** " + id.DisplayName + "\n")
	}
	b.WriteString("- **X25519 Encryption Public Key:** `" + id.EncPubHex + "`\n")
	if id.SignPubHex != "" {
		b.WriteString("- **Ed25519 Signing Public Key:** `" + id.SignPubHex + "`\n")
	}
	b.WriteString("- **Minimum Anti-Spam Tip:** `" + strconv.FormatInt(id.MinTipUgnot, 10) + "ugnot`\n")
	b.WriteString("- **Allowlist Only:** `" + strconv.FormatBool(id.AllowListOnly) + "`\n")
	b.WriteString("- **Messages Received:** `" + strconv.Itoa(len(id.InboxIDs)) + "` | **Sent:** `" + strconv.Itoa(len(id.SentIDs)) + "`\n\n")
	linkKey := id.Address.String()
	if id.Handle != "" {
		linkKey = id.Handle
	}
	b.WriteString("[Inspect Encrypted Inbox](/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/whisper:inbox/" + linkKey + ") · [Back to Directory](/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/whisper)\n")
	return b.String()
}

func renderInbox(q string) string {
	id, ok := tryResolveIdentity(q)
	if !ok {
		return "# Inbox Not Found\n\nNo Whisper inbox for `" + q + "`.\n\n[Back](/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/whisper)"
	}
	var b strings.Builder
	b.WriteString("# Encrypted Inbox: `" + id.Address.String() + "`\n\n")
	b.WriteString("_All payloads below are client-sealed `XChaCha20-Poly1305` ciphertexts. Only the holder of the matching local X25519 secret key can decrypt them._\n\n")
	if len(id.InboxIDs) == 0 {
		b.WriteString("_Inbox is empty._\n\n[Back](/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/whisper)")
		return b.String()
	}
	start := 0
	if len(id.InboxIDs) > 20 {
		start = len(id.InboxIDs) - 20
	}
	for i := len(id.InboxIDs) - 1; i >= start; i-- {
		env := messages[id.InboxIDs[i]-1]
		b.WriteString("- **Msg #" + strconv.FormatUint(env.ID, 10) + "** from `" + env.From +
			"` at height `" + strconv.FormatInt(env.Height, 10) + "` | commitment `" +
			env.CommitmentHex[:16] + "...` | tip `" + strconv.FormatInt(env.TipUgnot, 10) + "ugnot`")
		if env.EscrowID > 0 {
			eid := strconv.FormatUint(env.EscrowID, 10)
			b.WriteString(" | [Escrow #" + eid + "](/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/whisper:escrow/" + eid + ")")
		}
		b.WriteString("\n")
	}
	b.WriteString("\n[Back to Directory](/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/whisper)\n")
	return b.String()
}

func renderEscrow(idStr string) string {
	id, err := strconv.ParseUint(idStr, 10, 64)
	if err != nil || id == 0 || id > uint64(len(escrows)) {
		return "# Escrow Not Found\n\nInvalid escrow id `" + idStr + "`.\n\n[Back](/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/whisper)"
	}
	e := escrows[id-1]
	var b strings.Builder
	b.WriteString("# Whisper DeFi Escrow #" + idStr + "\n\n")
	b.WriteString("- **Status:** `" + string(e.Status) + "`\n")
	b.WriteString("- **Linked Encrypted Message:** `#" + strconv.FormatUint(e.MessageID, 10) + "`\n")
	b.WriteString("- **Sender:** `" + e.Sender + "`\n")
	b.WriteString("- **Recipient:** `" + e.Recipient + "`\n")
	b.WriteString("- **Locked Amount:** `" + strconv.FormatInt(e.AmountUgnot, 10) + "ugnot`\n")
	if e.HashLockHex != "" {
		b.WriteString("- **HTLC Hashlock (SHA-256):** `" + e.HashLockHex + "`\n")
	} else {
		b.WriteString("- **HTLC Hashlock:** _none (recipient direct claim)_\n")
	}
	b.WriteString("- **Expiry Height:** `" + strconv.FormatInt(e.ExpiryHeight, 10) + "`\n")
	if e.SettledHeight > 0 {
		b.WriteString("- **Settled Height:** `" + strconv.FormatInt(e.SettledHeight, 10) + "`\n")
	}
	b.WriteString("\n[Back to Directory](/r/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/whisper)\n")
	return b.String()
}

func tryResolveIdentity(q string) (*Identity, bool) {
	trim := strings.TrimSpace(q)
	if id, ok := identities.Get(trim).(*Identity); ok && id != nil {
		return id, true
	}
	clean := strings.ToLower(strings.TrimLeft(trim, "@"))
	if addr, ok := handles.Get(clean).(string); ok && addr != "" {
		if id, ok2 := identities.Get(addr).(*Identity); ok2 && id != nil {
			return id, true
		}
	}
	return nil, false
}

// Package whisper is the stateful Gno.land realm for Arobi Whisper — an end-to-end
// encrypted DeFi messenger with tiered subscriptions paid in GNOT (mirroring
// aura-genesis.org/whisper: Free 110 credits vs Pro 2,500 credits / 30 days),
// pay-per-message overage, native GNOT tipping, conditional HTLC/expiry escrows,
// programmable anti-spam inbox gating, and RFC 6962 cryptographic evidence proofs
// built directly on gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance.
//
// Zero plaintext or secret keys ever touch chain state. Clients seal messages locally
// using X25519 + HKDF-SHA256 + XChaCha20-Poly1305 (exact Arobi Whisper v1 wire format).
//
// Settlement privacy: service subscription and protocol fees are enforced on-chain in
// GNOT, while operator settlement routing is configured privately at deployment time
// and never hardcoded or publicly disclosed in source code, events, or gnoweb pages.
package whisper

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/assurance"
	pw "gno.land/p/g1jdc6h96he7wf7xfycu6u7wqhv5j762qtxu5k5t/whisper"
	"gno.land/p/nt/avl/v0"
)

const (
	denom = "ugnot"

	// Tier quotas mirroring live Arobi Whisper (aura-genesis.org/whisper).
	TierFree = "free"
	TierPro  = "pro"

	FreePeriodCredits int64 = 110
	ProPeriodCredits  int64 = 2500
	FreeMaxCipherB64  int   = 4096  // 4 KiB base64 on Free tier
	ProMaxCipherB64   int   = 16384 // 16 KiB base64 on Pro tier

	// ~30 days at ~2s/block.
	SubscriptionPeriodBlocks int64 = 1296000

	// Escrow safety bounds.
	MinEscrowUgnot     int64 = 1000
	MinEscrowTTLBlocks int64 = 5
	MaxEscrowTTLBlocks int64 = 15000000
	MaxEscrowFeeBps    int64 = 500 // hard protocol cap: never > 5%
)

// Identity binds a native Gno g1... address to local X25519/Ed25519 messaging keys,
// an optional claim-once @handle, subscription tier & credits, and anti-spam rules.
type Identity struct {
	Address          address
	EncPubHex        string // 32-byte X25519 public key (hex)
	SignPubHex       string // 32-byte Ed25519 public key (hex, optional cross-chain parity)
	Handle           string // optional claim-once handle
	DisplayName      string
	Tier             string // TierFree or TierPro
	Credits          int64
	SubExpiresHeight int64
	MinTipUgnot      int64
	AllowListOnly    bool
	Allowed          *avl.Tree // senderAddr -> bool
	InboxIDs         []uint64
	SentIDs          []uint64
	CreatedHeight    int64
	UpdatedHeight    int64
}

var (
	// Service pricing in ugnot (configurable by operator; zero hardcoded payout wallets).
	subscriptionPriceUgnot int64 = 25000000 // 25 GNOT per 30-day Pro period
	overageFeeUgnot        int64 = 10000    // 0.01 GNOT pay-per-message when credits == 0
	escrowFeeBps           int64 = 100      // 1.00% settlement fee on claimed DeFi escrows

	// Private operator & opaque settlement vault (never printed in Render or emitted in events).
	operator           address
	settlementSink     address
	accruedServiceFees int64

	identities    = avl.NewTree() // addr.String() -> *Identity
	handles       = avl.NewTree() // handle -> addr.String()
	identityOrder []string

	messages []*pw.SealedEnvelope
	escrows  []*pw.EscrowRecord

	// Append-only RFC 6962 accumulator over every message envelope & escrow transition.
	evidenceAcc   assurance.Accumulator
	totalTips     int64
	totalEscrowed int64
)

// ── Private Operator & Settlement Configuration ──────────────────────────────

// InitOperator claims one-time deployer operator control after package deployment.
func InitOperator(cur realm) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("init operator with a direct user call")
	}
	if operator != "" {
		panic("operator already initialized")
	}
	operator = prev.Address()
}

// TransferOperator transfers operator control to a new address (operator only).
func TransferOperator(cur realm, next address) {
	mustOperator(cur)
	if !next.IsValid() {
		panic("invalid operator address")
	}
	operator = next
}

// SetSettlementSink privately sets an optional direct settlement sink for service fees
// (operator only; never exposed in Render() or public chain events).
func SetSettlementSink(cur realm, sink address) {
	mustOperator(cur)
	if sink != "" && !sink.IsValid() {
		panic("invalid settlement address")
	}
	settlementSink = sink
}

// SetPricing updates GNOT service pricing (operator only; escrowFeeBps capped at 5%).
func SetPricing(cur realm, subPriceUgnot, overageUgnot, escFeeBps int64) {
	mustOperator(cur)
	if subPriceUgnot < 0 || overageUgnot < 0 {
		panic("prices cannot be negative")
	}
	if escFeeBps < 0 || escFeeBps > MaxEscrowFeeBps {
		panic("escrowFeeBps out of range (0..500)")
	}
	subscriptionPriceUgnot = subPriceUgnot
	overageFeeUgnot = overageUgnot
	escrowFeeBps = escFeeBps
}

// CollectServiceFees withdraws ONLY accrued service fees (subscriptions, overages,
// settled escrow fees) to an operator-specified destination. Strictly isolated from
// user-locked DeFi escrows.
func CollectServiceFees(cur realm, to address) int64 {
	mustOperator(cur)
	if !to.IsValid() {
		panic("invalid destination address")
	}
	amount := accruedServiceFees
	if amount <= 0 {
		return 0
	}
	accruedServiceFees = 0
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), to, chain.Coins{chain.NewCoin(denom, amount)})
	return amount
}

// ── Public Pricing Queries (no payout addresses exposed) ─────────────────────

func SubscriptionPriceUgnot() int64 { return subscriptionPriceUgnot }
func OverageFeeUgnot() int64        { return overageFeeUgnot }
func EscrowFeeBps() int64           { return escrowFeeBps }

// ── Identity, Tier & Subscription Lifecycle ──────────────────────────────────

// RegisterIdentity registers (or updates displayName/keys for) the caller's E2EE identity.
// New accounts start on the Free tier (110 credits) matching aura-genesis.org/whisper.
// Handles are strictly claim-once: once claimed, a handle cannot be changed or stolen.
func RegisterIdentity(cur realm, encPubHex, signPubHex, handle, displayName string) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("register identity with a direct user call")
	}
	if err := pw.ValidateKeyHex(encPubHex); err != nil {
		panic("encPubHex: " + err.Error())
	}
	if signPubHex != "" {
		if err := pw.ValidateKeyHex(signPubHex); err != nil {
			panic("signPubHex: " + err.Error())
		}
	}
	if len(displayName) > 64 {
		panic("displayName too long (max 64)")
	}

	caller := prev.Address()
	key := caller.String()
	height := runtime.ChainHeight()

	var normHandle string
	if strings.TrimSpace(handle) != "" {
		var err error
		normHandle, err = pw.NormalizeHandle(handle)
		if err != nil {
			panic("handle: " + err.Error())
		}
	}

	if id, exists := identities.Get(key).(*Identity); exists && id != nil {
		if normHandle != "" {
			if id.Handle != "" && id.Handle != normHandle {
				panic("identity already owns @" + id.Handle + "; handles cannot be reassigned")
			}
			if id.Handle == "" {
				if handles.Has(normHandle) {
					panic("handle @" + normHandle + " is already taken")
				}
				handles.Set(normHandle, key)
				id.Handle = normHandle
			}
		}
		id.EncPubHex = encPubHex
		id.SignPubHex = signPubHex
		if displayName != "" {
			id.DisplayName = displayName
		}
		id.UpdatedHeight = height
		chain.Emit("WhisperIdentityUpdated", "addr", key, "handle", id.Handle, "enc_pub", encPubHex)
		return
	}

	if normHandle != "" {
		if handles.Has(normHandle) {
			panic("handle @" + normHandle + " is already taken")
		}
		handles.Set(normHandle, key)
	}

	id := &Identity{
		Address:       caller,
		EncPubHex:     encPubHex,
		SignPubHex:    signPubHex,
		Handle:        normHandle,
		DisplayName:   displayName,
		Tier:          TierFree,
		Credits:       FreePeriodCredits,
		Allowed:       avl.NewTree(),
		CreatedHeight: height,
		UpdatedHeight: height,
	}
	identities.Set(key, id)
	identityOrder = append(identityOrder, key)

	chain.Emit("WhisperIdentityRegistered",
		"addr", key,
		"handle", normHandle,
		"tier", TierFree,
		"credits", strconv.FormatInt(FreePeriodCredits, 10),
		"enc_pub", encPubHex,
		"height", strconv.FormatInt(height, 10),
	)
}

// Subscribe upgrades or extends the caller's Whisper identity to the Pro tier for 30 days
// (2,500 credits, 16 KiB envelopes, and DeFi HTLC escrows) by paying exact SubscriptionPriceUgnot in GNOT.
func Subscribe(cur realm) int64 {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("subscribe with a direct user call")
	}
	id := mustIdentity(prev.Address().String())
	paid := sentUgnot()
	if paid != subscriptionPriceUgnot {
		panic("send exact subscription price " + strconv.FormatInt(subscriptionPriceUgnot, 10) + denom +
			"; got " + strconv.FormatInt(paid, 10) + denom)
	}

	height := runtime.ChainHeight()
	baseExpiry := height
	if id.SubExpiresHeight > height {
		baseExpiry = id.SubExpiresHeight
	}
	id.Tier = TierPro
	id.SubExpiresHeight = baseExpiry + SubscriptionPeriodBlocks
	id.Credits = ProPeriodCredits
	id.UpdatedHeight = height

	settleServiceFee(cur, paid)

	chain.Emit("WhisperSubscribed",
		"addr", id.Address.String(),
		"tier", TierPro,
		"paid_ugnot", strconv.FormatInt(paid, 10),
		"credits", strconv.FormatInt(id.Credits, 10),
		"expires_height", strconv.FormatInt(id.SubExpiresHeight, 10),
	)
	return id.SubExpiresHeight
}

// EffectiveTier returns TierPro if the identity has an active subscription, else TierFree.
func EffectiveTier(addrOrHandle string) string {
	id := mustResolveIdentity(addrOrHandle)
	return effectiveTierOf(id, runtime.ChainHeight())
}

// RotateKeys rotates the caller's X25519 / Ed25519 keys without losing handle, subscription, or inbox history.
func RotateKeys(cur realm, newEncPubHex, newSignPubHex string) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("rotate keys with a direct user call")
	}
	if err := pw.ValidateKeyHex(newEncPubHex); err != nil {
		panic("newEncPubHex: " + err.Error())
	}
	if newSignPubHex != "" {
		if err := pw.ValidateKeyHex(newSignPubHex); err != nil {
			panic("newSignPubHex: " + err.Error())
		}
	}
	id := mustIdentity(prev.Address().String())
	id.EncPubHex = newEncPubHex
	id.SignPubHex = newSignPubHex
	id.UpdatedHeight = runtime.ChainHeight()
	chain.Emit("WhisperKeysRotated", "addr", id.Address.String(), "enc_pub", newEncPubHex)
}

// SetInboxPolicy configures programmable DeFi anti-spam rules on the caller's inbox.
func SetInboxPolicy(cur realm, minTipUgnot int64, allowListOnly bool) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("set inbox policy with a direct user call")
	}
	if minTipUgnot < 0 {
		panic("minTipUgnot cannot be negative")
	}
	id := mustIdentity(prev.Address().String())
	id.MinTipUgnot = minTipUgnot
	id.AllowListOnly = allowListOnly
	id.UpdatedHeight = runtime.ChainHeight()
	chain.Emit("WhisperInboxPolicy",
		"addr", id.Address.String(),
		"min_tip_ugnot", strconv.FormatInt(minTipUgnot, 10),
		"allowlist_only", strconv.FormatBool(allowListOnly),
	)
}

// SetAllowedSender adds or removes a sender address from the caller's inbox allowlist.
func SetAllowedSender(cur realm, senderAddr string, allowed bool) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("set allowed sender with a direct user call")
	}
	id := mustIdentity(prev.Address().String())
	if allowed {
		id.Allowed.Set(senderAddr, true)
	} else {
		id.Allowed.Remove(senderAddr)
	}
	id.UpdatedHeight = runtime.ChainHeight()
}

// ── E2EE Messaging + GNOT Tipping & Tier Metering ────────────────────────────

// SendMessage delivers a client-sealed E2EE ciphertext envelope on-chain.
// Consumes 1 message credit from the sender's tier quota; if credits are exhausted,
// collects OverageFeeUgnot in GNOT automatically. Any remaining attached GNOT
// (required >= recipient.MinTipUgnot) forwards 100% straight to recipient.
func SendMessage(
	cur realm,
	toAddrOrHandle string,
	ephemeralPubHex string,
	nonceHex string,
	ciphertextB64 string,
	commitmentHex string,
) uint64 {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("send message with a direct user call")
	}
	sender := mustIdentity(prev.Address().String())
	recipient := mustResolveIdentity(toAddrOrHandle)
	checkCanSend(sender, recipient)
	validateEnvelopeFields(ephemeralPubHex, nonceHex, ciphertextB64, commitmentHex)

	height := runtime.ChainHeight()
	tier := effectiveTierOf(sender, height)
	maxCT := FreeMaxCipherB64
	if tier == TierPro {
		maxCT = ProMaxCipherB64
	}
	if len(ciphertextB64) > maxCT {
		panic("ciphertext exceeds " + tier + " tier payload limit (" + strconv.Itoa(maxCT) + " chars); subscribe to Pro for 16 KiB")
	}

	sent := sentUgnot()
	var serviceFee int64
	if sender.Credits > 0 {
		sender.Credits--
	} else {
		if sent < overageFeeUgnot {
			panic("message credits exhausted: subscribe to Pro or attach at least " +
				strconv.FormatInt(overageFeeUgnot, 10) + denom + " overage fee")
		}
		serviceFee = overageFeeUgnot
	}

	tip := sent - serviceFee
	if tip < recipient.MinTipUgnot {
		panic("recipient requires minimum tip of " + strconv.FormatInt(recipient.MinTipUgnot, 10) + denom +
			"; got " + strconv.FormatInt(tip, 10) + denom + " after service fee")
	}

	msgID := uint64(len(messages)) + 1
	env := &pw.SealedEnvelope{
		ID:              msgID,
		ChainID:         runtime.ChainID(),
		Realm:           cur.PkgPath(),
		From:            sender.Address.String(),
		To:              recipient.Address.String(),
		EphemeralPubHex: ephemeralPubHex,
		NonceHex:        nonceHex,
		CiphertextB64:   ciphertextB64,
		CommitmentHex:   commitmentHex,
		TipUgnot:        tip,
		EscrowID:        0,
		Height:          height,
	}
	leaf := env.LeafHash()
	env.LeafIndex = evidenceAcc.Append(leaf)
	messages = append(messages, env)
	recipient.InboxIDs = append(recipient.InboxIDs, msgID)
	sender.SentIDs = append(sender.SentIDs, msgID)

	if serviceFee > 0 {
		settleServiceFee(cur, serviceFee)
	}
	if tip > 0 {
		totalTips += tip
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(cur.Address(), recipient.Address, chain.Coins{chain.NewCoin(denom, tip)})
	}

	chain.Emit("WhisperMessage",
		"id", strconv.FormatUint(msgID, 10),
		"from", env.From,
		"to", env.To,
		"tier", tier,
		"commitment", commitmentHex,
		"tip_ugnot", strconv.FormatInt(tip, 10),
		"service_fee_ugnot", strconv.FormatInt(serviceFee, 10),
		"leaf_index", strconv.FormatUint(env.LeafIndex, 10),
		"acc_root", assurance.Hex(evidenceAcc.Root()),
	)
	return msgID
}

// ── DeFi Encrypted Conditional Escrows (Pro Tier + 1% Settlement Fee) ────────

// SendEscrowMessage sends an E2EE ciphertext envelope paired with a locked DeFi GNOT escrow.
// Requires an active Pro subscription (matching Whisper's paid tier for advanced DeFi flows).
func SendEscrowMessage(
	cur realm,
	toAddrOrHandle string,
	ephemeralPubHex string,
	nonceHex string,
	ciphertextB64 string,
	commitmentHex string,
	hashLockHex string,
	ttlBlocks int64,
) (uint64, uint64) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("send escrow message with a direct user call")
	}
	sender := mustIdentity(prev.Address().String())
	height := runtime.ChainHeight()
	if effectiveTierOf(sender, height) != TierPro {
		panic("DeFi encrypted escrows require an active Pro subscription (call Subscribe with " +
			strconv.FormatInt(subscriptionPriceUgnot, 10) + denom + ")")
	}
	recipient := mustResolveIdentity(toAddrOrHandle)
	if sender.Address == recipient.Address {
		panic("cannot create escrow to self")
	}
	checkCanSend(sender, recipient)
	validateEnvelopeFields(ephemeralPubHex, nonceHex, ciphertextB64, commitmentHex)

	if hashLockHex != "" {
		if _, err := assurance.ParseDigest(hashLockHex); err != nil {
			panic("hashLockHex: " + err.Error())
		}
	}
	if ttlBlocks < MinEscrowTTLBlocks || ttlBlocks > MaxEscrowTTLBlocks {
		panic("ttlBlocks out of allowed range")
	}

	amount := sentUgnot()
	if amount < MinEscrowUgnot {
		panic("escrow requires at least " + strconv.FormatInt(MinEscrowUgnot, 10) + denom)
	}
	if amount < recipient.MinTipUgnot {
		panic("escrow amount below recipient min tip")
	}

	if sender.Credits > 0 {
		sender.Credits--
	}

	msgID := uint64(len(messages)) + 1
	escID := uint64(len(escrows)) + 1

	env := &pw.SealedEnvelope{
		ID:              msgID,
		ChainID:         runtime.ChainID(),
		Realm:           cur.PkgPath(),
		From:            sender.Address.String(),
		To:              recipient.Address.String(),
		EphemeralPubHex: ephemeralPubHex,
		NonceHex:        nonceHex,
		CiphertextB64:   ciphertextB64,
		CommitmentHex:   commitmentHex,
		TipUgnot:        0,
		EscrowID:        escID,
		Height:          height,
	}
	env.LeafIndex = evidenceAcc.Append(env.LeafHash())
	messages = append(messages, env)
	recipient.InboxIDs = append(recipient.InboxIDs, msgID)
	sender.SentIDs = append(sender.SentIDs, msgID)

	esc := &pw.EscrowRecord{
		ID:            escID,
		MessageID:     msgID,
		Sender:        sender.Address.String(),
		Recipient:     recipient.Address.String(),
		AmountUgnot:   amount,
		HashLockHex:   hashLockHex,
		ExpiryHeight:  height + ttlBlocks,
		Status:        pw.EscrowOpen,
		CreatedHeight: height,
	}
	escLeafIdx := evidenceAcc.Append(esc.LeafHash())
	escrows = append(escrows, esc)
	totalEscrowed += amount

	chain.Emit("WhisperEscrowCreated",
		"escrow_id", strconv.FormatUint(escID, 10),
		"msg_id", strconv.FormatUint(msgID, 10),
		"from", esc.Sender,
		"to", esc.Recipient,
		"amount_ugnot", strconv.FormatInt(amount, 10),
		"hash_lock", hashLockHex,
		"expiry_height", strconv.FormatInt(esc.ExpiryHeight, 10),
		"leaf_index", strconv.FormatUint(escLeafIdx, 10),
		"acc_root", assurance.Hex(evidenceAcc.Root()),
	)
	return msgID, escID
}

// ClaimEscrow settles an open DeFi escrow to its recipient (verifying preimage if hash-locked).
// Collects EscrowFeeBps (default 1%) service settlement fee in GNOT; remainder forwards to recipient.
func ClaimEscrow(cur realm, escrowID uint64, preimage string) int64 {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("claim escrow with a direct user call")
	}
	esc := mustEscrow(escrowID)
	if esc.Status != pw.EscrowOpen {
		panic("escrow is already " + string(esc.Status))
	}
	caller := prev.Address()
	if caller.String() != esc.Recipient {
		panic("only recipient " + esc.Recipient + " may claim escrow")
	}
	if esc.HashLockHex != "" {
		if pw.ComputeHashLock(preimage) != esc.HashLockHex {
			panic("invalid hashlock preimage")
		}
	}

	fee := (esc.AmountUgnot * escrowFeeBps) / 10000
	if fee >= esc.AmountUgnot {
		fee = 0
	}
	payout := esc.AmountUgnot - fee

	esc.Status = pw.EscrowClaimed
	esc.SettledHeight = runtime.ChainHeight()

	leafIdx := evidenceAcc.Append(esc.LeafHash())

	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), caller, chain.Coins{chain.NewCoin(denom, payout)})
	if fee > 0 {
		settleServiceFee(cur, fee)
	}

	chain.Emit("WhisperEscrowClaimed",
		"escrow_id", strconv.FormatUint(esc.ID, 10),
		"recipient", esc.Recipient,
		"payout_ugnot", strconv.FormatInt(payout, 10),
		"service_fee_ugnot", strconv.FormatInt(fee, 10),
		"leaf_index", strconv.FormatUint(leafIdx, 10),
		"acc_root", assurance.Hex(evidenceAcc.Root()),
	)
	return payout
}

// RefundEscrow returns 100% of an expired, unclaimed DeFi escrow back to its sender (zero fee).
func RefundEscrow(cur realm, escrowID uint64) int64 {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("refund escrow with a direct user call")
	}
	esc := mustEscrow(escrowID)
	if esc.Status != pw.EscrowOpen {
		panic("escrow is already " + string(esc.Status))
	}
	caller := prev.Address()
	if caller.String() != esc.Sender {
		panic("only sender " + esc.Sender + " may refund escrow")
	}
	height := runtime.ChainHeight()
	if height < esc.ExpiryHeight {
		panic("escrow has not expired yet; unlocks at height " + strconv.FormatInt(esc.ExpiryHeight, 10))
	}

	esc.Status = pw.EscrowRefunded
	esc.SettledHeight = height
	leafIdx := evidenceAcc.Append(esc.LeafHash())

	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), caller, chain.Coins{chain.NewCoin(denom, esc.AmountUgnot)})

	chain.Emit("WhisperEscrowRefunded",
		"escrow_id", strconv.FormatUint(esc.ID, 10),
		"sender", esc.Sender,
		"refund_ugnot", strconv.FormatInt(esc.AmountUgnot, 10),
		"leaf_index", strconv.FormatUint(leafIdx, 10),
		"acc_root", assurance.Hex(evidenceAcc.Root()),
	)
	return esc.AmountUgnot
}

// ── Public Read & Proof Queries ──────────────────────────────────────────────

// ResolveRecipient returns the public directory record for an address or @handle.
func ResolveRecipient(addrOrHandle string) string {
	id := mustResolveIdentity(addrOrHandle)
	tier := effectiveTierOf(id, runtime.ChainHeight())
	return id.Address.String() + "|" + id.EncPubHex + "|" + id.Handle + "|" + tier + "|" +
		strconv.FormatInt(id.MinTipUgnot, 10) + "|" + strconv.FormatBool(id.AllowListOnly)
}

func Root() string            { return assurance.Hex(evidenceAcc.Root()) }
func AccumulatorSize() uint64 { return evidenceAcc.Size() }
func MessageCount() uint64    { return uint64(len(messages)) }
func EscrowCount() uint64     { return uint64(len(escrows)) }

func MessageLeafHex(msgID uint64) string {
	if msgID == 0 || msgID > uint64(len(messages)) {
		panic("no message " + strconv.FormatUint(msgID, 10))
	}
	return assurance.Hex(messages[msgID-1].LeafHash())
}

func ProofForLeaf(leafIndex, treeSize uint64) string {
	proof, err := evidenceAcc.Proof(leafIndex, treeSize)
	if err != nil {
		panic(err.Error())
	}
	parts := make([]string, len(proof))
	for i, h := range proof {
		parts[i] = assurance.Hex(h)
	}
	return strings.Join(parts, ",")
}

func VerifyLeafProof(leafIndex, treeSize uint64, leafHex, proofCSV string) bool {
	if leafIndex >= treeSize || treeSize > evidenceAcc.Size() {
		return false
	}
	leaf, err := assurance.ParseDigest(leafHex)
	if err != nil {
		return false
	}
	rootAt, err := evidenceAcc.RootAt(treeSize)
	if err != nil {
		return false
	}
	var proof [][32]byte
	if strings.TrimSpace(proofCSV) != "" {
		for _, tok := range strings.Split(proofCSV, ",") {
			d, err := assurance.ParseDigest(strings.TrimSpace(tok))
			if err != nil {
				return false
			}
			proof = append(proof, d)
		}
	}
	return assurance.VerifyInclusion(leafIndex, treeSize, leaf, proof, rootAt)
}

// ── Internal Helpers ─────────────────────────────────────────────────────────

func settleServiceFee(cur realm, amount int64) {
	if amount <= 0 {
		return
	}
	if settlementSink != "" {
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(cur.Address(), settlementSink, chain.Coins{chain.NewCoin(denom, amount)})
		return
	}
	accruedServiceFees += amount
}

func mustOperator(cur realm) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("operator action requires a direct user call")
	}
	if operator == "" {
		panic("operator not initialized")
	}
	if prev.Address() != operator {
		panic("unauthorized: operator only")
	}
}

func effectiveTierOf(id *Identity, height int64) string {
	if id.Tier == TierPro && id.SubExpiresHeight > height {
		return TierPro
	}
	return TierFree
}

func mustIdentity(addr string) *Identity {
	id, ok := identities.Get(addr).(*Identity)
	if !ok || id == nil {
		panic("identity not registered for " + addr)
	}
	return id
}

func mustResolveIdentity(addrOrHandle string) *Identity {
	q := strings.TrimSpace(addrOrHandle)
	if id, ok := identities.Get(q).(*Identity); ok && id != nil {
		return id
	}
	clean := strings.ToLower(strings.TrimLeft(q, "@"))
	if targetAddr, ok := handles.Get(clean).(string); ok && targetAddr != "" {
		return mustIdentity(targetAddr)
	}
	panic("recipient not found: " + addrOrHandle)
}

func mustEscrow(id uint64) *pw.EscrowRecord {
	if id == 0 || id > uint64(len(escrows)) {
		panic("escrow not found: " + strconv.FormatUint(id, 10))
	}
	return escrows[id-1]
}

func checkCanSend(sender, recipient *Identity) {
	if recipient.AllowListOnly && sender.Address != recipient.Address {
		if !recipient.Allowed.Has(sender.Address.String()) {
			panic("recipient only accepts messages from allowlisted senders")
		}
	}
}

func validateEnvelopeFields(ephemeralPubHex, nonceHex, ciphertextB64, commitmentHex string) {
	if err := pw.ValidateKeyHex(ephemeralPubHex); err != nil {
		panic("ephemeralPubHex: " + err.Error())
	}
	if err := pw.ValidateNonceHex(nonceHex); err != nil {
		panic("nonceHex: " + err.Error())
	}
	if err := pw.ValidateCiphertextB64(ciphertextB64); err != nil {
		panic("ciphertextB64: " + err.Error())
	}
	if _, err := assurance.ParseDigest(commitmentHex); err != nil {
		panic("commitmentHex: " + err.Error())
	}
}

func sentUgnot() int64 {
	var total int64
	for _, c := range unsafe.OriginSend() {
		if c.Amount == 0 {
			continue
		}
		if c.Denom != denom || c.Amount < 0 {
			panic("only " + denom + " is accepted")
		}
		total += c.Amount
	}
	return total
}

