func escapeAttrVal(s string) string {
	s = strings.ReplaceAll(s, "\r", "")
	s = strings.ReplaceAll(s, "\n", " ")
	return sanitize.HTMLEscape(s)
}

func escapeTextareaVal(s string) string {
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	s = sanitize.HTMLEscape(s)
	s = strings.ReplaceAll(s, "\t", `\t`)
	s = strings.ReplaceAll(s, "\n", `\n`)
	return s
}

func chipLibraryBetter(a, b *ChipEntry) bool {
	if a.ReuseCount != b.ReuseCount {
		return a.ReuseCount > b.ReuseCount
	}
	if a.NANDCount != b.NANDCount {
		return a.NANDCount < b.NANDCount
	}
	return a.Slug < b.Slug
}

func formatPinVals(names []string, vals []bool) string {
	parts := make([]string, len(names))
	for i := 0; i < len(names); i++ {
		bit := "0"
		if vals[i] {
			bit = "1"
		}
		parts[i] = names[i] + "=" + bit
	}
	return strings.Join(parts, " ")
}

package nandloom

import (
	nl "gno.land/p/g1jxrrf695x7r3h0wqvmkq2vyyqy39wjraxyph3j/nandloom/v0"
)

const (
	MaxTitleLen     = 64
	MaxNotesLen     = 200
	MaxImportersCap = 64
)

// ChipEntry stores an immutable verified circuit published on-chain.
// Immutability guarantees that higher-level chips importing chip:<slug> never
// break retroactively.
type ChipEntry struct {
	Slug          string
	ChallengeID   string
	Title         string
	Notes         string
	Author        address
	BlockHeight   int64
	Netlist       string
	AST           *nl.Circuit
	Compiled      *nl.CompiledCircuit
	NANDCount     int
	Depth         int
	ModuleCount   int
	ImportedChips []string
	ReuseCount    int
	Importers     []string
}

// ChallengeState tracks the specification, current record holder, and all
// verified chips solving a challenge.
type ChallengeState struct {
	Spec            nl.ChallengeSpec
	BestSlug        string
	BestNANDs       int
	BestDepth       int
	BestAuthor      address
	SubmissionSlugs []string
}

// BuilderProfile tracks objective, deterministic builder achievements.
type BuilderProfile struct {
	Address          address
	ChipsSubmitted   int
	RecordsHeld      int
	TotalReuses      int
	SolvedChallenges map[string]bool
}

// Package tavernlogic holds the pure game rules of the Gnome Tavern:
// the menu, the level ladder, the rotating daily quest board and the
// per-gnome state machine (serving drinks, claiming quests, feasting).
//
// It is a pure package (gno.land/p/...): it owns no chain state of its
// own. The Gnome Tavern realm keeps the state (a *Gnome per player) and
// calls into these functions, which keeps every rule unit-testable
// without a chain.
package tavernlogic

import "errors"

// DayBlocks is the length of one tavern day, in blocks. Quest boards,
// daily serve counters and feast allowances all reset when the day rolls
// over. A short day keeps the game lively on a testnet: at Onyx's block
// pace a tavern day lasts roughly an hour.
const DayBlocks int64 = 2000

// MaxServesPerDay caps how many items one gnome may serve per tavern day.
const MaxServesPerDay = 40

// FeastCost and FeastXP describe the Gnome Feast: a coin sink that lets a
// hard-working gnome convert earnings into experience, once per day.
const (
	FeastCost = 50
	FeastXP   = 15
)

// DayAt maps a chain height to its tavern day number.
func DayAt(height int64) int64 {
	if height < 0 {
		return 0
	}
	return height / DayBlocks
}

// --- Levels ---------------------------------------------------------------

// XPPerLevel is the amount of XP between consecutive levels.
const XPPerLevel = 40

// LevelForXP returns the level of a gnome holding xp experience points.
// Level 1 is the starting level; every XPPerLevel XP earns a new level.
func LevelForXP(xp int) int {
	if xp < 0 {
		xp = 0
	}
	return 1 + xp/XPPerLevel
}

// XPForLevel returns the cumulative XP at which level l is reached.
func XPForLevel(l int) int {
	if l <= 1 {
		return 0
	}
	return (l - 1) * XPPerLevel
}

// --- Menu -----------------------------------------------------------------

// MenuItem is one serveable entry on the tavern menu. Serving it pays the
// gnome Coins tavern coins and XP experience, and requires MinLevel.
type MenuItem struct {
	ID       int
	Name     string
	Detail   string
	MinLevel int
	Coins    int
	XP       int
}

var menu = []MenuItem{
	{0, "Barley Soup", "A humble bowl that never empties.", 1, 3, 2},
	{1, "Gnomebrew Ale", "Foamy, nutty, proudly gnome-sized.", 1, 5, 3},
	{2, "Honeyed Ham", "Glazed with wildflower honey.", 2, 9, 5},
	{3, "Emberwhisky", "Warms the beard from the inside.", 3, 14, 8},
	{4, "Moonpetal Tea", "Brewed under a full moon, allegedly.", 4, 20, 12},
	{5, "Dragonfire Stew", "Sign the waiver. Then enjoy.", 5, 30, 18},
}

// Menu returns the full tavern menu, in serving order.
func Menu() []MenuItem {
	return menu
}

// MenuItemByID looks up a menu item by its ID.
func MenuItemByID(id int) (MenuItem, bool) {
	if id < 0 || id >= len(menu) {
		return MenuItem{}, false
	}
	return menu[id], true
}

// --- Quests ---------------------------------------------------------------

// Quest kinds: what the progress counter measures.
const (
	QuestTotalServes = 0 // serve Count items of any kind today
	QuestItemServes  = 1 // serve Count of item ItemID today
)

// Quest is one entry on the daily quest board.
type Quest struct {
	ID         int
	Title      string
	Desc       string
	Kind       int
	ItemID     int // only for QuestItemServes
	Count      int
	CoinReward int
	XPReward   int
}

var questPool = []Quest{
	{0, "First Round", "Serve 4 items today.", QuestTotalServes, 0, 4, 15, 8},
	{1, "Ale Baron", "Serve 4 Gnomebrew Ales today.", QuestItemServes, 1, 4, 25, 12},
	{2, "Morning Rush", "Serve 8 items today.", QuestTotalServes, 0, 8, 30, 15},
	{3, "Ham It Up", "Serve 3 Honeyed Hams today.", QuestItemServes, 2, 3, 30, 14},
	{4, "Full House", "Serve 14 items today.", QuestTotalServes, 0, 14, 55, 26},
	{5, "Whisky Business", "Serve 3 Emberwhiskies today.", QuestItemServes, 3, 3, 45, 22},
	{6, "Tea Ceremony", "Serve 3 Moonpetal Teas today.", QuestItemServes, 4, 3, 60, 30},
	{7, "Dragon Slayer's Feast", "Serve 2 Dragonfire Stews today.", QuestItemServes, 5, 2, 70, 36},
}

// QuestPool returns every quest that can appear on the board.
func QuestPool() []Quest {
	return questPool
}

// QuestsForDay deterministically picks the 3 quests on the board for a
// tavern day. The same day always yields the same board, on every node,
// with no randomness source beyond the day number itself (a small LCG).
func QuestsForDay(day int64) [3]Quest {
	var out [3]Quest
	state := day*2654435761 + 97
	used := map[int]bool{}
	for slot := 0; slot < 3; slot++ {
		for {
			state = state*1103515245 + 12345
			idx := int(((state >> 16) & 0x7fffffff) % int64(len(questPool)))
			if !used[idx] {
				used[idx] = true
				out[slot] = questPool[idx]
				break
			}
		}
	}
	return out
}

// --- Gnome state ----------------------------------------------------------

// Gnome is one player's tavern career. The realm owns one *Gnome per
// registered address; all fields are plain data so the realm can persist
// it directly.
type Gnome struct {
	Name string
	XP   int
	Coins int

	TotalServes int

	// Daily counters; they belong to LastDay and reset on rollover.
	LastDay      int64
	ServesToday  int
	ItemToday    map[int]int
	ClaimedToday map[int]bool // quest IDs already claimed today
	FeastedToday bool
}

// NewGnome creates a fresh gnome registered under the given name.
func NewGnome(name string, day int64) *Gnome {
	return &Gnome{
		Name:         name,
		LastDay:      day,
		ItemToday:    map[int]int{},
		ClaimedToday: map[int]bool{},
	}
}

// Level returns the gnome's current level.
func (g *Gnome) Level() int {
	return LevelForXP(g.XP)
}

// rollover resets the daily counters when a new tavern day has begun.
func (g *Gnome) rollover(day int64) {
	if g.LastDay == day {
		return
	}
	g.LastDay = day
	g.ServesToday = 0
	g.ItemToday = map[int]int{}
	g.ClaimedToday = map[int]bool{}
	g.FeastedToday = false
}

// Serve records the gnome serving one menu item on the given day and
// returns what was earned. It enforces the menu's level requirement and
// the daily serve cap.
func (g *Gnome) Serve(day int64, itemID int) (coinsEarned, xpEarned int, err error) {
	item, ok := MenuItemByID(itemID)
	if !ok {
		return 0, 0, errors.New("no such menu item")
	}
	g.rollover(day)
	if g.Level() < item.MinLevel {
		return 0, 0, errors.New("your level is too low for this item")
	}
	if g.ServesToday >= MaxServesPerDay {
		return 0, 0, errors.New("you have served enough for one day; come back tomorrow")
	}
	g.ServesToday++
	g.TotalServes++
	g.ItemToday[itemID]++
	g.Coins += item.Coins
	g.XP += item.XP
	return item.Coins, item.XP, nil
}

// ProgressFor reports the gnome's progress toward a quest today.
func (g *Gnome) ProgressFor(day int64, q Quest) int {
	if g.LastDay != day {
		return 0
	}
	if q.Kind == QuestItemServes {
		return g.ItemToday[q.ItemID]
	}
	return g.ServesToday
}

// ClaimQuest pays out the quest in board slot (0-2) for the given day, if
// the gnome has met its requirement and has not claimed it yet today.
func (g *Gnome) ClaimQuest(day int64, slot int) (Quest, error) {
	if slot < 0 || slot > 2 {
		return Quest{}, errors.New("quest slot must be 0, 1 or 2")
	}
	g.rollover(day)
	q := QuestsForDay(day)[slot]
	if g.ClaimedToday[q.ID] {
		return Quest{}, errors.New("you already claimed this quest today")
	}
	if g.ProgressFor(day, q) < q.Count {
		return Quest{}, errors.New("quest requirement not met yet")
	}
	g.ClaimedToday[q.ID] = true
	g.Coins += q.CoinReward
	g.XP += q.XPReward
	return q, nil
}

// Feast lets the gnome spend FeastCost coins on a Gnome Feast, gaining
// FeastXP experience. Once per tavern day.
func (g *Gnome) Feast(day int64) error {
	g.rollover(day)
	if g.FeastedToday {
		return errors.New("you already feasted today")
	}
	if g.Coins < FeastCost {
		return errors.New("not enough coins for a feast")
	}
	g.Coins -= FeastCost
	g.XP += FeastXP
	g.FeastedToday = true
	return nil
}

package tavernlogic

import "testing"

func TestLevelForXP(t *testing.T) {
	cases := []struct{ xp, want int }{
		{0, 1}, {1, 1}, {XPPerLevel - 1, 1}, {XPPerLevel, 2},
		{2 * XPPerLevel, 3}, {4 * XPPerLevel, 5}, {-10, 1},
	}
	for _, c := range cases {
		if got := LevelForXP(c.xp); got != c.want {
			t.Fatalf("LevelForXP(%d) = %d, want %d", c.xp, got, c.want)
		}
	}
	if XPForLevel(1) != 0 || XPForLevel(2) != XPPerLevel || XPForLevel(5) != 4*XPPerLevel {
		t.Fatalf("XPForLevel thresholds are wrong")
	}
}

func TestMenuLadder(t *testing.T) {
	menu := Menu()
	if len(menu) != 6 {
		t.Fatalf("menu has %d items, want 6", len(menu))
	}
	prevLevel, prevCoins := 0, 0
	for i, item := range menu {
		if item.ID != i {
			t.Fatalf("menu item %d has ID %d", i, item.ID)
		}
		if item.MinLevel < prevLevel {
			t.Fatalf("menu levels are not a ladder at %q", item.Name)
		}
		if item.Coins <= prevCoins {
			t.Fatalf("menu payouts are not increasing at %q", item.Name)
		}
		// Every menu item must be unlockable: its MinLevel must be
		// reachable and consistent with the quest pool referencing it.
		if LevelForXP(XPForLevel(item.MinLevel)) != item.MinLevel {
			t.Fatalf("MinLevel %d of %q is not reachable", item.MinLevel, item.Name)
		}
		prevLevel, prevCoins = item.MinLevel, item.Coins
	}
	if _, ok := MenuItemByID(-1); ok {
		t.Fatalf("MenuItemByID(-1) should not exist")
	}
	if _, ok := MenuItemByID(len(menu)); ok {
		t.Fatalf("MenuItemByID(len) should not exist")
	}
}

func TestQuestsDeterministic(t *testing.T) {
	for _, day := range []int64{0, 1, 2, 7, 42, 1000, 987654} {
		a := QuestsForDay(day)
		b := QuestsForDay(day)
		if a != b {
			t.Fatalf("QuestsForDay(%d) is not deterministic", day)
		}
		seen := map[int]bool{}
		for _, q := range a {
			if seen[q.ID] {
				t.Fatalf("day %d board repeats quest %d", day, q.ID)
			}
			seen[q.ID] = true
			if q.Count <= 0 || q.Count > MaxServesPerDay {
				t.Fatalf("quest %q count %d cannot fit in a day", q.Title, q.Count)
			}
			if q.Kind == QuestItemServes {
				if _, ok := MenuItemByID(q.ItemID); !ok {
					t.Fatalf("quest %q references missing item %d", q.Title, q.ItemID)
				}
			}
		}
	}
	// Different days should (usually) show different boards.
	same := 0
	for day := int64(0); day < 20; day++ {
		if QuestsForDay(day) == QuestsForDay(day+1) {
			same++
		}
	}
	if same > 5 {
		t.Fatalf("quest board barely rotates: %d/20 consecutive days identical", same)
	}
}

func TestServeEarnsAndLevels(t *testing.T) {
	g := NewGnome("Bram", 0)
	coins, xp, err := g.Serve(0, 0)
	if err != nil {
		t.Fatalf("serve soup: %v", err)
	}
	if coins != 3 || xp != 2 || g.Coins != 3 || g.XP != 2 {
		t.Fatalf("after soup: earned (%d,%d), gnome (%d coins, %d xp)", coins, xp, g.Coins, g.XP)
	}
	if g.ServesToday != 1 || g.TotalServes != 1 || g.ItemToday[0] != 1 {
		t.Fatalf("counters wrong after one serve: %+v", g)
	}
	// Level gate: a level-1 gnome cannot serve Honeyed Ham (min level 2).
	if _, _, err := g.Serve(0, 2); err == nil {
		t.Fatalf("level-1 gnome served a level-2 item")
	}
	// Unknown item.
	if _, _, err := g.Serve(0, 99); err == nil {
		t.Fatalf("served a nonexistent item")
	}
	// Earn enough XP to reach level 2, then the ham unlocks.
	for g.Level() < 2 {
		if _, _, err := g.Serve(0, 1); err != nil {
			t.Fatalf("serve ale: %v", err)
		}
	}
	if _, _, err := g.Serve(0, 2); err != nil {
		t.Fatalf("level-2 gnome could not serve ham: %v", err)
	}
}

func TestServeDailyCapAndRollover(t *testing.T) {
	g := NewGnome("Cap", 0)
	for i := 0; i < MaxServesPerDay; i++ {
		if _, _, err := g.Serve(0, 0); err != nil {
			t.Fatalf("serve %d of the day failed: %v", i, err)
		}
	}
	if _, _, err := g.Serve(0, 0); err == nil {
		t.Fatalf("served beyond the daily cap")
	}
	// Next day: counters reset, serving works again, totals keep counting.
	coinsBefore := g.Coins
	if _, _, err := g.Serve(1, 0); err != nil {
		t.Fatalf("serve on day 1 failed: %v", err)
	}
	if g.ServesToday != 1 || g.TotalServes != MaxServesPerDay+1 {
		t.Fatalf("rollover counters wrong: today=%d total=%d", g.ServesToday, g.TotalServes)
	}
	if g.Coins != coinsBefore+3 {
		t.Fatalf("coins did not carry over the rollover")
	}
	if got := g.ProgressFor(0, Quest{Kind: QuestTotalServes}); got != 0 {
		t.Fatalf("progress for a past day = %d, want 0", got)
	}
}

func TestClaimQuest(t *testing.T) {
	g := NewGnome("Questy", 0)
	g.XP = 1000 // claim logic is under test here, not level gating
	board := QuestsForDay(0)
	// Find the cheapest total-serves quest on today's board and work it.
	slot := -1
	for i, q := range board {
		if q.Kind == QuestTotalServes && (slot == -1 || q.Count < board[slot].Count) {
			slot = i
		}
	}
	if slot == -1 {
		// Fall back: work whichever quest is in slot 0 via its item.
		slot = 0
		q := board[0]
		for g.ProgressFor(0, q) < q.Count {
			if _, _, err := g.Serve(0, q.ItemID); err != nil {
				t.Fatalf("working quest: %v", err)
			}
		}
	} else {
		for g.ProgressFor(0, board[slot]) < board[slot].Count {
			if _, _, err := g.Serve(0, 0); err != nil {
				t.Fatalf("working quest: %v", err)
			}
		}
	}
	// Claiming an unfinished quest must fail: pick a slot we did not finish,
	// if any, and confirm; otherwise skip that half of the check.
	for i, q := range board {
		if i != slot && g.ProgressFor(0, q) < q.Count {
			if _, err := g.ClaimQuest(0, i); err == nil {
				t.Fatalf("claimed unfinished quest %q", q.Title)
			}
			break
		}
	}
	coinsBefore, xpBefore := g.Coins, g.XP
	q, err := g.ClaimQuest(0, slot)
	if err != nil {
		t.Fatalf("claim finished quest: %v", err)
	}
	if g.Coins != coinsBefore+q.CoinReward || g.XP != xpBefore+q.XPReward {
		t.Fatalf("quest payout wrong: got +%d coins +%d xp, want +%d +%d",
			g.Coins-coinsBefore, g.XP-xpBefore, q.CoinReward, q.XPReward)
	}
	// Double claim must fail.
	if _, err := g.ClaimQuest(0, slot); err == nil {
		t.Fatalf("claimed the same quest twice in one day")
	}
	// Bad slot must fail.
	if _, err := g.ClaimQuest(0, 3); err == nil {
		t.Fatalf("claimed slot 3")
	}
	// Tomorrow the same slot is a fresh claim (board may differ, but the
	// claim flag must have reset): serve the new board's slot-0 quest and
	// claim it.
	board1 := QuestsForDay(1)
	q1 := board1[0]
	item := 0
	if q1.Kind == QuestItemServes {
		item = q1.ItemID
	}
	for g.ProgressFor(1, q1) < q1.Count {
		if _, _, err := g.Serve(1, item); err != nil {
			t.Fatalf("day-1 quest work: %v", err)
		}
	}
	if _, err := g.ClaimQuest(1, 0); err != nil {
		t.Fatalf("claim on day 1 failed: %v", err)
	}
}

func TestFeast(t *testing.T) {
	g := NewGnome("Hungry", 0)
	if err := g.Feast(0); err == nil {
		t.Fatalf("feasted with no coins")
	}
	for i := 0; i < 10; i++ { // 10 ales = 50 coins
		if _, _, err := g.Serve(0, 1); err != nil {
			t.Fatalf("serve ale: %v", err)
		}
	}
	xpBefore := g.XP
	if err := g.Feast(0); err != nil {
		t.Fatalf("feast: %v", err)
	}
	if g.Coins != 0 || g.XP != xpBefore+FeastXP {
		t.Fatalf("after feast: coins=%d xp=%d, want 0 and %d", g.Coins, g.XP, xpBefore+FeastXP)
	}
	if err := g.Feast(0); err == nil {
		t.Fatalf("feasted twice in one day")
	}
	if err := g.Feast(1); err == nil {
		t.Fatalf("feasted on day 1 with no coins")
	}
}

// Realm gnometavern is the Gnome Tavern: a small on-chain tavern game
// on Gno.land. Players register a gnome, work shifts serving drinks and
// food from the menu, complete a rotating daily quest board, level up,
// feast, and leave notes on the tavern wall.
//
// All game rules live in the pure package tavernlogic; this realm owns
// the persistent state and the caller authentication, and renders the
// tavern board for gnoweb.
package gnometavern

import (
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/g17dvvky49vjqj6a4cjhwcvzctteqjm9stee000h/tavernlogic"
)

// RealmPath is this realm's on-chain address, used in help text.
const RealmPath = "gno.land/r/g17dvvky49vjqj6a4cjhwcvzctteqjm9stee000h/gnometavern"

// MaxWallNotes caps how many wall notes are kept (oldest are dropped).
const MaxWallNotes = 30

// WallNote is one message pinned to the tavern wall.
type WallNote struct {
	Author string
	Text   string
	Day    int64
}

var (
	gnomes      = map[address]*tavernlogic.Gnome{}
	joinOrder   []address
	wall        []WallNote
	totalServes int
)

// --- helpers --------------------------------------------------------------

// callerOf returns the address of the user who directly called the
// realm. Calls routed through another realm are rejected: a gnome's
// career can only be advanced by its own owner.
func callerOf(cur realm) address {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("Gnome Tavern: only direct user calls are allowed")
	}
	return prev.Address()
}

// currentDay returns the current tavern day, derived from chain height.
func currentDay() int64 {
	return tavernlogic.DayAt(runtime.ChainHeight())
}

func mustGnome(addr address) *tavernlogic.Gnome {
	g, ok := gnomes[addr]
	if !ok {
		panic("Gnome Tavern: no gnome registered for your address; call Register first")
	}
	return g
}

func validName(name string) bool {
	if len(name) < 3 || len(name) > 16 {
		return false
	}
	for _, r := range name {
		ok := (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') ||
			(r >= '0' && r <= '9') || r == ' ' || r == '_' || r == '-'
		if !ok {
			return false
		}
	}
	return true
}

// --- actions --------------------------------------------------------------

// Register creates a gnome for the caller's address. One gnome per
// address, and names are unique across the tavern.
func Register(cur realm, name string) string {
	addr := callerOf(cur)
	if _, ok := gnomes[addr]; ok {
		panic("Gnome Tavern: you already have a gnome")
	}
	if !validName(name) {
		panic("Gnome Tavern: names are 3-16 chars of letters, digits, space, _ or -")
	}
	for _, other := range joinOrder {
		if gnomes[other].Name == name {
			panic("Gnome Tavern: that name is already taken")
		}
	}
	gnomes[addr] = tavernlogic.NewGnome(name, currentDay())
	joinOrder = append(joinOrder, addr)
	return "Welcome to the Gnome Tavern, " + name + "! You are gnome #" +
		strconv.Itoa(len(joinOrder)) + ". Start with Serve(0) or Serve(1), and check today's quests on the board."
}

// Serve serves one menu item to a tavern guest. The item is chosen by
// its menu ID (see the menu page). Pays coins and XP per the menu.
func Serve(cur realm, itemID int) string {
	addr := callerOf(cur)
	g := mustGnome(addr)
	coins, xp, err := g.Serve(currentDay(), itemID)
	if err != nil {
		panic("Gnome Tavern: " + err.Error())
	}
	item, _ := tavernlogic.MenuItemByID(itemID)
	totalServes++
	return g.Name + " served " + item.Name + ": +" + strconv.Itoa(coins) +
		" coins, +" + strconv.Itoa(xp) + " XP. (Level " + strconv.Itoa(g.Level()) +
		", " + strconv.Itoa(g.Coins) + " coins, " + strconv.Itoa(g.ServesToday) +
		" serves today.)"
}

// ClaimQuest claims the reward for today's quest in board slot 0, 1 or
// 2, once its requirement has been met by serving.
func ClaimQuest(cur realm, slot int) string {
	addr := callerOf(cur)
	g := mustGnome(addr)
	q, err := g.ClaimQuest(currentDay(), slot)
	if err != nil {
		panic("Gnome Tavern: " + err.Error())
	}
	return "Quest complete: " + q.Title + "! " + g.Name + " earned " +
		strconv.Itoa(q.CoinReward) + " coins and " + strconv.Itoa(q.XPReward) +
		" XP. (Level " + strconv.Itoa(g.Level()) + ", " + strconv.Itoa(g.Coins) + " coins.)"
}

// Feast spends 50 coins on a Gnome Feast, gaining 15 XP. Once per day.
func Feast(cur realm) string {
	addr := callerOf(cur)
	g := mustGnome(addr)
	if err := g.Feast(currentDay()); err != nil {
		panic("Gnome Tavern: " + err.Error())
	}
	return g.Name + " feasts like a true gnome: -" + strconv.Itoa(tavernlogic.FeastCost) +
		" coins, +" + strconv.Itoa(tavernlogic.FeastXP) + " XP. (Level " +
		strconv.Itoa(g.Level()) + ", " + strconv.Itoa(g.Coins) + " coins.)"
}

// PostNote pins a one-line note (max 140 chars) to the tavern wall.
func PostNote(cur realm, text string) string {
	addr := callerOf(cur)
	g := mustGnome(addr)
	if len(text) == 0 || len(text) > 140 {
		panic("Gnome Tavern: notes are 1-140 characters")
	}
	if strings.ContainsAny(text, "\n\r") {
		panic("Gnome Tavern: notes must fit on one line")
	}
	wall = append(wall, WallNote{Author: g.Name, Text: text, Day: currentDay()})
	if len(wall) > MaxWallNotes {
		wall = wall[len(wall)-MaxWallNotes:]
	}
	return "Note pinned to the tavern wall."
}

// --- views ----------------------------------------------------------------

// GnomeCount returns how many gnomes are registered.
func GnomeCount() int {
	return len(gnomes)
}

// TotalServes returns how many items have been served, all time.
func TotalServes() int {
	return totalServes
}

// CurrentDay returns the current tavern day number.
func CurrentDay() int64 {
	return currentDay()
}

// Profile returns a one-line summary of the gnome at addr.
func Profile(addr address) string {
	g, ok := gnomes[addr]
	if !ok {
		return "No gnome registered for " + addr.String() + "."
	}
	return g.Name + " — level " + strconv.Itoa(g.Level()) + ", " +
		strconv.Itoa(g.XP) + " XP, " + strconv.Itoa(g.Coins) + " coins, " +
		strconv.Itoa(g.TotalServes) + " lifetime serves."
}

package gnometavern

import (
	"strings"
	"testing"

	"gno.land/p/g17dvvky49vjqj6a4cjhwcvzctteqjm9stee000h/tavernlogic"
)

// The two test players are the project's real testnet accounts; only
// their public addresses are used here.
var (
	alice = address("g17dvvky49vjqj6a4cjhwcvzctteqjm9stee000h")
	bob   = address("g15g63hzg36z8n5qjnzq6kxg4as5kms3vgqy42gw")
)

func resetState() {
	gnomes = map[address]*tavernlogic.Gnome{}
	joinOrder = nil
	wall = nil
	totalServes = 0
}

// NOTE: testing.SetRealm must be called directly in the test function
// body — it mutates the test frame's realm in place, so wrapping it in a
// helper function would mutate the helper's frame instead and lose it.

// mustPanic asserts that f aborts. Realm functions are crossing
// functions, so their panics surface as aborts, which plain recover()
// cannot catch — the revive() builtin is the test-mode tool for this
// (same mechanism as p/nt/uassert's AbortsWithMessage).
func mustPanic(t *testing.T, what string, f func()) {
	t.Helper()
	if r := revive(f); r == nil {
		t.Fatalf("expected abort: %s", what)
	}
}

func TestRegister(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice))
	msg := Register(cross(cur), "Bram")
	if !strings.Contains(msg, "Bram") {
		t.Fatalf("welcome message does not name the gnome: %q", msg)
	}
	if GnomeCount() != 1 {
		t.Fatalf("GnomeCount = %d, want 1", GnomeCount())
	}
	if p := Profile(alice); !strings.Contains(p, "Bram") || !strings.Contains(p, "level 1") {
		t.Fatalf("profile wrong: %q", p)
	}
	// One gnome per address.
	mustPanic(t, "second gnome for same address", func() {
		Register(cross(cur), "Other")
	})
	// Invalid names.
	for _, bad := range []string{"ab", "SeventeenCharsLong", "Bad!Name", "with|pipe", ""} {
		testing.SetRealm(testing.NewUserRealm(bob))
		mustPanic(t, "invalid name "+bad, func() {
			Register(cross(cur), bad)
		})
	}
	// Name uniqueness across addresses.
	testing.SetRealm(testing.NewUserRealm(bob))
	mustPanic(t, "name already taken", func() {
		Register(cross(cur), "Bram")
	})
	Register(cross(cur), "Zed")
	if GnomeCount() != 2 {
		t.Fatalf("GnomeCount = %d, want 2", GnomeCount())
	}
	if p := Profile(bob); !strings.Contains(p, "No gnome") && !strings.Contains(p, "Zed") {
		t.Fatalf("bob profile wrong: %q", p)
	}
	if p := Profile(address("g1qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqq2rq73q")); !strings.Contains(p, "No gnome") {
		t.Fatalf("unknown profile wrong: %q", p)
	}
}

func TestServeFlow(cur realm, t *testing.T) {
	resetState()
	// Unregistered callers cannot serve.
	testing.SetRealm(testing.NewUserRealm(bob))
	mustPanic(t, "serve while unregistered", func() {
		Serve(cross(cur), 0)
	})
	testing.SetRealm(testing.NewUserRealm(alice))
	Register(cross(cur), "Bram")
	out := Serve(cross(cur), 0)
	if !strings.Contains(out, "Barley Soup") {
		t.Fatalf("serve output wrong: %q", out)
	}
	if gnomes[alice].Coins != 3 || TotalServes() != 1 {
		t.Fatalf("after one serve: coins=%d totalServes=%d", gnomes[alice].Coins, TotalServes())
	}
	// Level gate through the realm: Honeyed Ham needs level 2.
	mustPanic(t, "serve above level", func() {
		Serve(cross(cur), 2)
	})
	// Work up to level 2 with ales (3 XP each, 40 XP needed).
	for gnomes[alice].Level() < 2 {
		Serve(cross(cur), 1)
	}
	Serve(cross(cur), 2) // must not panic now
	if gnomes[alice].ItemToday[2] != 1 {
		t.Fatalf("ham serve not recorded")
	}
	// Unknown item.
	mustPanic(t, "serve unknown item", func() {
		Serve(cross(cur), 42)
	})
}

func TestQuestClaimViaRealm(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice))
	Register(cross(cur), "Questor")
	gnomes[alice].XP = 1000 // quest flow under test, not level gating

	day := currentDay()
	board := tavernlogic.QuestsForDay(day)
	// Work the cheapest quest on today's board.
	slot := 0
	for i, q := range board {
		if q.Count < board[slot].Count {
			slot = i
		}
	}
	q := board[slot]
	item := 0
	if q.Kind == tavernlogic.QuestItemServes {
		item = q.ItemID
	}
	// Claiming before doing the work must panic.
	mustPanic(t, "claim before work", func() {
		ClaimQuest(cross(cur), slot)
	})
	for gnomes[alice].ProgressFor(day, q) < q.Count {
		Serve(cross(cur), item)
	}
	coinsBefore := gnomes[alice].Coins
	out := ClaimQuest(cross(cur), slot)
	if !strings.Contains(out, q.Title) {
		t.Fatalf("claim output wrong: %q", out)
	}
	if gnomes[alice].Coins != coinsBefore+q.CoinReward {
		t.Fatalf("quest coins not paid: %d -> %d, reward %d",
			coinsBefore, gnomes[alice].Coins, q.CoinReward)
	}
	// Claiming twice must panic.
	mustPanic(t, "double claim", func() {
		ClaimQuest(cross(cur), slot)
	})
}

func TestFeastViaRealm(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice))
	Register(cross(cur), "Feaster")
	mustPanic(t, "feast with no coins", func() {
		Feast(cross(cur))
	})
	for i := 0; i < 10; i++ { // 10 ales = 50 coins
		Serve(cross(cur), 1)
	}
	xpBefore := gnomes[alice].XP
	out := Feast(cross(cur))
	if !strings.Contains(out, "feasts") {
		t.Fatalf("feast output wrong: %q", out)
	}
	if gnomes[alice].Coins != 0 || gnomes[alice].XP != xpBefore+tavernlogic.FeastXP {
		t.Fatalf("feast accounting wrong: coins=%d xp=%d", gnomes[alice].Coins, gnomes[alice].XP)
	}
	mustPanic(t, "second feast same day", func() {
		Feast(cross(cur))
	})
}

func TestWallAndRender(cur realm, t *testing.T) {
	resetState()
	// Notes need a registered gnome.
	testing.SetRealm(testing.NewUserRealm(bob))
	mustPanic(t, "note while unregistered", func() {
		PostNote(cross(cur), "hello?")
	})
	testing.SetRealm(testing.NewUserRealm(alice))
	Register(cross(cur), "Bram")
	PostNote(cross(cur), "First round is on me!")
	testing.SetRealm(testing.NewUserRealm(bob))
	Register(cross(cur), "Zed")
	PostNote(cross(cur), "Save me a seat by the fire.")

	home := Render("")
	for _, want := range []string{"The Gnome Tavern", "Bram", "First round is on me!", "Today's quest board", "Leaderboard"} {
		if !strings.Contains(home, want) {
			t.Fatalf("home render missing %q", want)
		}
	}
	if m := Render("menu"); !strings.Contains(m, "Dragonfire Stew") {
		t.Fatalf("menu render incomplete")
	}
	if q := Render("quests"); !strings.Contains(q, "Quest Board") {
		t.Fatalf("quests render wrong")
	}
	if lb := Render("leaderboard"); !strings.Contains(lb, "Bram") || !strings.Contains(lb, "Zed") {
		t.Fatalf("leaderboard render missing gnomes")
	}
	if w := Render("wall"); !strings.Contains(w, "Save me a seat by the fire.") {
		t.Fatalf("wall render missing note")
	}
	if card := Render("gnome/" + alice.String()); !strings.Contains(card, "Bram") {
		t.Fatalf("gnome card wrong: %q", card)
	}
	if card := Render("gnome/g1qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqq2rq73q"); !strings.Contains(card, "No gnome") {
		t.Fatalf("unknown gnome card wrong: %q", card)
	}
	if u := Render("cellar"); !strings.Contains(u, "Unknown page") {
		t.Fatalf("unknown page handling wrong: %q", u)
	}
	// Multi-line notes are refused.
	testing.SetRealm(testing.NewUserRealm(alice))
	mustPanic(t, "multi-line note", func() {
		PostNote(cross(cur), "line one\nline two")
	})
}

package gnometavern

import (
	"strconv"
	"strings"

	"gno.land/p/g17dvvky49vjqj6a4cjhwcvzctteqjm9stee000h/tavernlogic"
)

// Render draws the tavern for gnoweb. Pages:
//   ""               the tavern board (stats, today's quests, top 10, wall)
//   "menu"           the full menu with level requirements
//   "quests"         today's quest board in detail
//   "leaderboard"    every gnome, ranked
//   "wall"           the full message wall
//   "gnome/<addr>"   one gnome's card
func Render(path string) string {
	switch {
	case path == "":
		return renderHome()
	case path == "menu":
		return renderMenu()
	case path == "quests":
		return renderQuests()
	case path == "leaderboard":
		return renderLeaderboard()
	case path == "wall":
		return renderWall()
	case strings.HasPrefix(path, "gnome/"):
		return renderGnome(strings.TrimPrefix(path, "gnome/"))
	default:
		return "# The Gnome Tavern\n\nUnknown page `" + path +
			"`. Try the board at this realm's root, or the pages `menu`, `quests`, `leaderboard`, `wall`."
	}
}

// --- leaderboard ----------------------------------------------------------

type entry struct {
	addr  address
	gnome *tavernlogic.Gnome
}

// ranked returns all gnomes sorted by XP (then lifetime serves), best
// first. Insertion sort: the tavern is small and this stays
// dependency-free and deterministic (join order breaks full ties).
func ranked() []entry {
	out := make([]entry, 0, len(joinOrder))
	for _, addr := range joinOrder {
		out = append(out, entry{addr, gnomes[addr]})
	}
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && ranksBefore(out[j], out[j-1]); j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}

func ranksBefore(a, b entry) bool {
	if a.gnome.XP != b.gnome.XP {
		return a.gnome.XP > b.gnome.XP
	}
	return a.gnome.TotalServes > b.gnome.TotalServes
}

func leaderboardTable(limit int) string {
	board := ranked()
	if limit > 0 && len(board) > limit {
		board = board[:limit]
	}
	if len(board) == 0 {
		return "_No gnomes yet — be the first to register!_\n"
	}
	var sb strings.Builder
	sb.WriteString("| # | Gnome | Level | XP | Coins | Lifetime serves |\n")
	sb.WriteString("|---|-------|-------|----|----|----|\n")
	for i, e := range board {
		sb.WriteString("| " + strconv.Itoa(i+1) + " | " + e.gnome.Name +
			" | " + strconv.Itoa(e.gnome.Level()) +
			" | " + strconv.Itoa(e.gnome.XP) +
			" | " + strconv.Itoa(e.gnome.Coins) +
			" | " + strconv.Itoa(e.gnome.TotalServes) + " |\n")
	}
	return sb.String()
}

// --- pages ----------------------------------------------------------------

func renderHome() string {
	day := currentDay()
	var sb strings.Builder
	sb.WriteString("# The Gnome Tavern\n\n")
	sb.WriteString("Welcome, traveller. The Gnome Tavern is a tiny tavern that lives entirely on-chain: " +
		"register a gnome, work shifts serving the menu, finish the daily quest board, level up, and leave " +
		"a note on the wall for the next traveller. Every serve, quest and note is a real transaction, and " +
		"this page is rendered by the realm itself.\n\n")
	sb.WriteString("**Tavern day " + strconv.FormatInt(day, 10) + "** · " +
		strconv.Itoa(len(gnomes)) + " gnomes registered · " +
		strconv.Itoa(totalServes) + " items served all time\n\n")

	sb.WriteString("## Today's quest board\n\n")
	sb.WriteString(questList(day))
	sb.WriteString("\n")

	sb.WriteString("## Leaderboard (top 10)\n\n")
	sb.WriteString(leaderboardTable(10))
	sb.WriteString("\n")

	sb.WriteString("## From the wall\n\n")
	sb.WriteString(wallList(5))
	sb.WriteString("\n")

	sb.WriteString("## How to play\n\n")
	sb.WriteString("Call the realm with `gnokey` (testnet remote, chain id `onyx-1`):\n\n")
	sb.WriteString("1. `Register(\"YourName\")` — one gnome per address, names are unique.\n")
	sb.WriteString("2. `Serve(itemID)` — serve menu items to earn coins and XP. IDs and level requirements are on the `menu` page.\n")
	sb.WriteString("3. `ClaimQuest(slot)` — claim slots 0-2 of the quest board once you have done the work.\n")
	sb.WriteString("4. `Feast()` — spend 50 coins on +15 XP, once per tavern day.\n")
	sb.WriteString("5. `PostNote(\"...\")` — pin a note to the wall.\n\n")
	sb.WriteString("Pages: append `:menu`, `:quests`, `:leaderboard`, `:wall` or `:gnome/<address>` to this realm's URL. " +
		"A tavern day lasts " + strconv.FormatInt(tavernlogic.DayBlocks, 10) + " blocks; the quest board and daily counters reset when it rolls over.\n")
	return sb.String()
}

func renderMenu() string {
	var sb strings.Builder
	sb.WriteString("# Tavern Menu\n\n")
	sb.WriteString("Serve an item by calling `Serve(ID)`. Higher items pay more but need a higher gnome level.\n\n")
	sb.WriteString("| ID | Item | Min level | Pays | XP | About |\n")
	sb.WriteString("|----|------|----|----|----|----|\n")
	for _, item := range tavernlogic.Menu() {
		sb.WriteString("| " + strconv.Itoa(item.ID) + " | " + item.Name +
			" | " + strconv.Itoa(item.MinLevel) +
			" | " + strconv.Itoa(item.Coins) + " coins" +
			" | " + strconv.Itoa(item.XP) +
			" | " + item.Detail + " |\n")
	}
	sb.WriteString("\nLevels: every " + strconv.Itoa(tavernlogic.XPPerLevel) +
		" XP is a new level. A gnome may serve at most " +
		strconv.Itoa(tavernlogic.MaxServesPerDay) + " items per tavern day.\n")
	return sb.String()
}

func questList(day int64) string {
	board := tavernlogic.QuestsForDay(day)
	var sb strings.Builder
	for slot, q := range board {
		sb.WriteString(strconv.Itoa(slot) + ". **" + q.Title + "** — " + q.Desc +
			" Reward: " + strconv.Itoa(q.CoinReward) + " coins + " +
			strconv.Itoa(q.XPReward) + " XP.\n")
	}
	return sb.String()
}

func renderQuests() string {
	day := currentDay()
	var sb strings.Builder
	sb.WriteString("# Quest Board — tavern day " + strconv.FormatInt(day, 10) + "\n\n")
	sb.WriteString("The board rotates every tavern day (" +
		strconv.FormatInt(tavernlogic.DayBlocks, 10) +
		" blocks) and is the same for every gnome. Do the work by serving, then call `ClaimQuest(slot)`.\n\n")
	sb.WriteString(questList(day))
	sb.WriteString("\nQuests are drawn from a pool of " +
		strconv.Itoa(len(tavernlogic.QuestPool())) + "; tomorrow's board will differ.\n")
	return sb.String()
}

func renderLeaderboard() string {
	var sb strings.Builder
	sb.WriteString("# Leaderboard\n\n")
	sb.WriteString("Every gnome in the tavern, ranked by XP.\n\n")
	sb.WriteString(leaderboardTable(0))
	return sb.String()
}

func wallList(limit int) string {
	if len(wall) == 0 {
		return "_The wall is bare. Register a gnome and pin the first note._\n"
	}
	start := 0
	if limit > 0 && len(wall) > limit {
		start = len(wall) - limit
	}
	var sb strings.Builder
	for _, n := range wall[start:] {
		sb.WriteString("- **" + n.Author + "** (day " +
			strconv.FormatInt(n.Day, 10) + "): " +
			strings.ReplaceAll(n.Text, "|", "/") + "\n")
	}
	return sb.String()
}

func renderWall() string {
	var sb strings.Builder
	sb.WriteString("# The Tavern Wall\n\n")
	sb.WriteString("Notes from the gnomes. Pin your own with `PostNote(\"...\")`.\n\n")
	sb.WriteString(wallList(0))
	return sb.String()
}

func renderGnome(addrStr string) string {
	for _, addr := range joinOrder {
		if addr.String() == addrStr {
			g := gnomes[addr]
			var sb strings.Builder
			sb.WriteString("# " + g.Name + "\n\n")
			sb.WriteString("- **Address:** `" + addrStr + "`\n")
			sb.WriteString("- **Level:** " + strconv.Itoa(g.Level()) +
				" (" + strconv.Itoa(g.XP) + " XP; next level at " +
				strconv.Itoa(tavernlogic.XPForLevel(g.Level()+1)) + " XP)\n")
			sb.WriteString("- **Coins:** " + strconv.Itoa(g.Coins) + "\n")
			sb.WriteString("- **Lifetime serves:** " + strconv.Itoa(g.TotalServes) + "\n")
			servesToday := g.ServesToday
			if g.LastDay != currentDay() {
				servesToday = 0 // daily counters reset lazily on the next action
			}
			sb.WriteString("- **Serves today:** " + strconv.Itoa(servesToday) +
				" (tavern day " + strconv.FormatInt(currentDay(), 10) + ")\n")
			return sb.String()
		}
	}
	return "# The Gnome Tavern\n\nNo gnome is registered for `" + addrStr + "`."
}

// Package agentvault is the reusable spend-cap library behind the
// AgentVault realm: the first wallet an AI agent cannot drain.
//
// It is pure: no realm state, no chain calls, no imports from any
// realm. Every function takes explicit inputs (including the current
// unix time for day rollovers) so the logic is unit-testable without
// a chain. The vault realm in
// gno.land/r/g16740fm9kd28luuktn3g42jfq3r998fm35chclv/agentvault
// stores AgentBudget values and calls these functions; any other
// realm can import this package and get the same caps.
package agentvault

// DaySeconds is the length of one daily budget window, in seconds.
// Days are wall-clock UTC days counted from the Unix epoch.
const DaySeconds = int64(86400)

// AgentBudget is one agent's spend limit. It is a plain value type:
// the owning realm stores it and passes it back in. SpentToday and
// DayIndex are bookkeeping the realm must not forge; RefreshDay is
// the only function that moves them, and only forward in time.
type AgentBudget struct {
	PerTxCap   int64 // max ugnot in a single spend
	DailyCap   int64 // max ugnot per day
	SpentToday int64 // ugnot already spent in DayIndex
	DayIndex   int64 // unix day (nowUnix / DaySeconds) SpentToday belongs to
}

// Attempt is one entry in a vault's append-only spend log. Allowed
// false means the guard stopped the spend; Reason names why, so the
// blocked attempt is evidence, not just a failed transaction.
type Attempt struct {
	ID      int64
	Kind    string // "spend", "escrow", "release", "refund", "fund"
	Agent   address
	Name    string // resolved agent name, if the attempt named one
	Amount  int64
	Purpose string
	Allowed bool
	Reason  string
	Day     int64 // unix day of the attempt
}

// EscrowStatus is the lifecycle state of a name payment held in escrow.
type EscrowStatus int

const (
	EscrowHeld EscrowStatus = iota
	EscrowReleased
	EscrowRefunded
)

// Escrow is one name payment held by the vault until the named
// recipient confirms delivery (release) or the owner refunds it
// after the deadline block (refund). The coins never leave the vault
// while held; release sends them, refund only flips the status.
type Escrow struct {
	ID             int64
	Payer          address
	RecipientName  string
	Recipient      address
	Amount         int64
	DeadlineHeight int64
	Status         EscrowStatus
}

// DayIndex returns the unix day for a unix timestamp.
func DayIndex(nowUnix int64) int64 {
	return nowUnix / DaySeconds
}

// ValidateCaps reports "" when a cap pair is usable, otherwise the
// reason it is not. Both caps must be positive and the
// per-transaction cap must not exceed the daily cap (a per-tx cap
// above the daily cap could never be spent in full).
func ValidateCaps(perTxCap, dailyCap int64) string {
	if perTxCap <= 0 {
		return "per-transaction cap must be positive"
	}
	if dailyCap <= 0 {
		return "daily cap must be positive"
	}
	if perTxCap > dailyCap {
		return "per-transaction cap must not exceed daily cap"
	}
	return ""
}

// NewBudget builds a budget. Callers must validate first with
// ValidateCaps; an invalid pair panics rather than silently
// installing a budget that can never be spent.
func NewBudget(perTxCap, dailyCap int64) AgentBudget {
	if reason := ValidateCaps(perTxCap, dailyCap); reason != "" {
		panic(reason)
	}
	return AgentBudget{PerTxCap: perTxCap, DailyCap: dailyCap}
}

// RefreshDay resets SpentToday when the day has rolled over. Call it
// before CheckSpend so a stale day never blocks a new day's spend.
// It only ever moves the day forward and clears the spent amount;
// it never restores spent funds.
func RefreshDay(b *AgentBudget, nowUnix int64) {
	day := DayIndex(nowUnix)
	if b.DayIndex != day {
		b.SpentToday = 0
		b.DayIndex = day
	}
}

// CheckSpend reports whether amount may be spent under this budget.
// It does not mutate the budget; call RefreshDay first, then
// ApplySpend after a successful check. The order of the checks is
// deliberate: the cheapest, most specific rejection comes first so
// the logged reason tells the agent exactly which limit it hit.
func CheckSpend(b AgentBudget, amount int64) (bool, string) {
	if amount <= 0 {
		return false, "amount must be positive"
	}
	if amount > b.PerTxCap {
		return false, "exceeds per-transaction cap"
	}
	if b.SpentToday+amount > b.DailyCap {
		return false, "exceeds daily cap"
	}
	return true, "ok"
}

// ApplySpend records a spend that already passed CheckSpend.
func ApplySpend(b *AgentBudget, amount int64) {
	b.SpentToday += amount
}

// RemainingToday returns how much of the daily cap is left.
func RemainingToday(b AgentBudget, nowUnix int64) int64 {
	if DayIndex(nowUnix) != b.DayIndex {
		return b.DailyCap
	}
	rem := b.DailyCap - b.SpentToday
	if rem < 0 {
		return 0
	}
	return rem
}

// EscrowRefundable reports whether a held escrow may be refunded:
// the deadline block has passed and it is still held. A released or
// already-refunded escrow is never refundable again.
func EscrowRefundable(e Escrow, height int64) bool {
	return e.Status == EscrowHeld && height > e.DeadlineHeight
}

// EscrowStatusString renders an escrow status for the log and the
// Render page.
func EscrowStatusString(s EscrowStatus) string {
	switch s {
	case EscrowHeld:
		return "HELD"
	case EscrowReleased:
		return "RELEASED"
	case EscrowRefunded:
		return "REFUNDED"
	default:
		return "UNKNOWN"
	}
}

package agentvault

import (
	"testing"
)

func TestDayIndex(t *testing.T) {
	if DayIndex(0) != 0 {
		t.Fatal("day 0 expected for unix 0")
	}
	if DayIndex(86399) != 0 {
		t.Fatal("day 0 expected for unix 86399")
	}
	if DayIndex(86400) != 1 {
		t.Fatal("day 1 expected for unix 86400")
	}
	if DayIndex(172800) != 2 {
		t.Fatal("day 2 expected for unix 172800")
	}
}

func TestValidateCaps(t *testing.T) {
	if ValidateCaps(100, 1000) != "" {
		t.Fatal("valid caps rejected")
	}
	if ValidateCaps(0, 1000) == "" {
		t.Fatal("zero per-tx cap accepted")
	}
	if ValidateCaps(-5, 1000) == "" {
		t.Fatal("negative per-tx cap accepted")
	}
	if ValidateCaps(100, 0) == "" {
		t.Fatal("zero daily cap accepted")
	}
	if ValidateCaps(100, -1) == "" {
		t.Fatal("negative daily cap accepted")
	}
	if ValidateCaps(2000, 1000) == "" {
		t.Fatal("per-tx cap above daily cap accepted")
	}
	if ValidateCaps(1000, 1000) != "" {
		t.Fatal("per-tx cap equal to daily cap rejected")
	}
}

func TestNewBudget(t *testing.T) {
	b := NewBudget(100, 1000)
	if b.PerTxCap != 100 || b.DailyCap != 1000 {
		t.Fatal("budget caps not stored")
	}
	if b.SpentToday != 0 || b.DayIndex != 0 {
		t.Fatal("new budget must start unspent")
	}
}

func TestCheckSpend(t *testing.T) {
	b := NewBudget(100, 1000)

	// Within both caps: allowed.
	if ok, reason := CheckSpend(b, 50); !ok {
		t.Fatal("spend within caps rejected:", reason)
	}
	// Exactly at the per-tx cap: allowed.
	if ok, reason := CheckSpend(b, 100); !ok {
		t.Fatal("spend at per-tx cap rejected:", reason)
	}
	// One over the per-tx cap: rejected with the per-tx reason.
	if ok, reason := CheckSpend(b, 101); ok || reason != "exceeds per-transaction cap" {
		t.Fatal("spend over per-tx cap not rejected with per-tx reason:", ok, reason)
	}
	// Non-positive amounts: rejected.
	if ok, reason := CheckSpend(b, 0); ok || reason != "amount must be positive" {
		t.Fatal("zero spend not rejected:", ok, reason)
	}
	if ok, _ := CheckSpend(b, -10); ok {
		t.Fatal("negative spend allowed")
	}
	// Cumulative spend past the daily cap: rejected with the daily reason.
	// Spend 950 (within per-tx? no: 950 > 100). Use a budget with a
	// higher per-tx cap to isolate the daily check.
	b2 := NewBudget(1000, 1000)
	ApplySpend(&b2, 600)
	if ok, reason := CheckSpend(b2, 500); ok || reason != "exceeds daily cap" {
		t.Fatal("spend over daily cap not rejected with daily reason:", ok, reason)
	}
	// Exactly the remainder of the daily cap: allowed.
	if ok, reason := CheckSpend(b2, 400); !ok {
		t.Fatal("spend at daily remainder rejected:", reason)
	}
}

func TestRefreshDayAndRemaining(t *testing.T) {
	b := NewBudget(100, 1000)
	day0 := int64(1000)         // unix 1000 -> day 0
	day1 := int64(86400 + 1000) // unix 87400 -> day 1

	ApplySpend(&b, 400)
	b.DayIndex = DayIndex(day0)
	if RemainingToday(b, day0) != 600 {
		t.Fatal("remaining today wrong after spend:", RemainingToday(b, day0))
	}
	// Same day: refresh changes nothing.
	RefreshDay(&b, day0)
	if b.SpentToday != 400 {
		t.Fatal("refresh on same day cleared spent amount")
	}
	// Next day: refresh clears the spent amount.
	RefreshDay(&b, day1)
	if b.SpentToday != 0 {
		t.Fatal("refresh on new day did not clear spent amount")
	}
	if b.DayIndex != DayIndex(day1) {
		t.Fatal("refresh did not move day index")
	}
	if RemainingToday(b, day1) != 1000 {
		t.Fatal("remaining on new day is not the full daily cap")
	}
	// A budget that never spent: remaining is the full cap even
	// when the stored day is stale.
	stale := NewBudget(50, 500)
	if RemainingToday(stale, day1) != 500 {
		t.Fatal("stale-day budget remaining wrong")
	}
}

func TestApplySpend(t *testing.T) {
	b := NewBudget(100, 1000)
	ApplySpend(&b, 30)
	ApplySpend(&b, 20)
	if b.SpentToday != 50 {
		t.Fatal("spent today not accumulated:", b.SpentToday)
	}
}

func TestEscrowRefundable(t *testing.T) {
	e := Escrow{ID: 1, Amount: 500, DeadlineHeight: 100, Status: EscrowHeld}
	if EscrowRefundable(e, 100) {
		t.Fatal("escrow refundable at the deadline block itself")
	}
	if !EscrowRefundable(e, 101) {
		t.Fatal("escrow not refundable past the deadline")
	}
	if EscrowRefundable(e, 50) {
		t.Fatal("escrow refundable before the deadline")
	}
	e.Status = EscrowReleased
	if EscrowRefundable(e, 200) {
		t.Fatal("released escrow refundable")
	}
	e.Status = EscrowRefunded
	if EscrowRefundable(e, 200) {
		t.Fatal("refunded escrow refundable again")
	}
}

func TestEscrowStatusString(t *testing.T) {
	if EscrowStatusString(EscrowHeld) != "HELD" {
		t.Fatal("HELD string wrong")
	}
	if EscrowStatusString(EscrowReleased) != "RELEASED" {
		t.Fatal("RELEASED string wrong")
	}
	if EscrowStatusString(EscrowRefunded) != "REFUNDED" {
		t.Fatal("REFUNDED string wrong")
	}
	if EscrowStatusString(EscrowStatus(99)) != "UNKNOWN" {
		t.Fatal("unknown status string wrong")
	}
}

// Render is the vault's product page. Judges click the live realm;
// this page is the demo, so it shows the budgets as live bars, the
// spend log including blocked attempts, a public guard report, and
// the one-line import for the cap library.
//
// Every user-controlled string (agent names, purposes) is passed
// through tableCell before it is written into a table: InlineText
// for markdown safety, plus an escape for the pipe character, which
// InlineText does not escape and which would otherwise split a
// table cell. Reasons are NOT sanitized: they are internal constants
// from the cap checks (never user input), and sanitizing them would
// backslash-escape the hyphen in "exceeds per-transaction cap".
package agentvault

import (
	"strings"
	"time"

	caps "gno.land/p/g16740fm9kd28luuktn3g42jfq3r998fm35chclv/agentvault"
	sanitize "gno.land/p/nt/markdown/sanitize/v0"
	ufmt "gno.land/p/nt/ufmt/v0"
)

// tableCell sanitizes a user-controlled string for use inside a
// markdown table cell: InlineText first, then the pipe (which
// InlineText leaves raw) is escaped so it cannot split the cell.
func tableCell(s string) string {
	return strings.ReplaceAll(sanitize.InlineText(s), "|", "\\|")
}

// budgetBar draws the remaining fraction of a budget as a bar of
// block characters, e.g. "██████░░░░ 60%". Width is the bar length
// in characters.
func budgetBar(remaining, total int64, width int) string {
	if total <= 0 {
		return "no budget"
	}
	if remaining < 0 {
		remaining = 0
	}
	if remaining > total {
		remaining = total
	}
	filled := int(remaining * int64(width) / total)
	bar := ""
	for i := 0; i < filled; i++ {
		bar += "█"
	}
	for i := filled; i < width; i++ {
		bar += "░"
	}
	pct := int(remaining * 100 / total)
	return bar + " " + ufmt.Sprintf("%d%%", pct)
}

// Render returns the vault's product page in markdown. The path
// argument is ignored: the vault has one page.
func Render(_ string) string {
	out := "# AgentVault\n\n"
	out += "The wallet an AI agent cannot drain. The owner funds the vault, sets a per-transaction cap and a daily cap per agent, and every spend goes through the guard. Blocked attempts are logged on-chain and shown here, so a limit is a visible fact, not a promise.\n\n"
	out += "Owner: `" + sanitize.InlineText(owner.String()) + "`\n\n"
	out += ufmt.Sprintf("Vault balance: **%d ugnot** | Available: **%d ugnot** | Funded: %d ugnot | Spent: %d ugnot | Held in escrow: %d ugnot\n\n",
		VaultBalance(), AvailableBalance(), totalFunded, totalSpent, escrowedTotal)

	// Budgets.
	out += "## Budgets\n\n"
	if len(agentList) == 0 {
		out += "No agents yet. The owner sets caps with SetCap or SetCapByName.\n\n"
	} else {
		out += "| Agent | Per-tx cap | Daily cap | Spent today | Remaining | Budget left |\n"
		out += "|---|---|---|---|---|---|\n"
		for _, addr := range agentList {
			b := budgets[addr]
			remaining := caps.RemainingToday(b, time.Now().Unix())
			out += "| `" + sanitize.InlineText(addr.String()) + "` | " +
				ufmt.Sprintf("%d", b.PerTxCap) + " | " +
				ufmt.Sprintf("%d", b.DailyCap) + " | " +
				ufmt.Sprintf("%d", b.SpentToday) + " | " +
				ufmt.Sprintf("%d", remaining) + " | `" +
				budgetBar(remaining, b.DailyCap, 10) + "` |\n"
		}
		out += "\n"
	}

	// Guard report.
	allowed := 0
	blocked := 0
	reasonCount := make(map[string]int)
	var reasonOrder []string
	for _, a := range attempts {
		if a.Allowed {
			allowed++
		} else {
			blocked++
			if _, ok := reasonCount[a.Reason]; !ok {
				reasonOrder = append(reasonOrder, a.Reason)
			}
			reasonCount[a.Reason]++
		}
	}
	out += "## Guard report\n\n"
	out += ufmt.Sprintf("Attempts: **%d** (%d allowed, %d blocked)\n\n", len(attempts), allowed, blocked)
	if blocked > 0 {
		out += "Blocked by reason:\n\n"
		for _, r := range reasonOrder {
			// r is an internal cap-check constant, never user input.
			out += "- " + r + ": " + ufmt.Sprintf("%d", reasonCount[r]) + "\n"
		}
		out += "\n"
	}

	// Escrows.
	out += "## Escrows\n\n"
	es := Escrows()
	if len(es) == 0 {
		out += "No escrows yet. The owner pays a named agent with PayByName; the payment is held until the recipient confirms or the owner refunds after the deadline.\n\n"
	} else {
		out += "| ID | Recipient | Amount | Status | Deadline (height) |\n"
		out += "|---|---|---|---|---|\n"
		for _, e := range es {
			out += "| " + ufmt.Sprintf("%d", e.ID) + " | " +
				tableCell(e.RecipientName) + " (`" + sanitize.InlineText(e.Recipient.String()) + "`) | " +
				ufmt.Sprintf("%d", e.Amount) + " | **" + caps.EscrowStatusString(e.Status) + "** | " +
				ufmt.Sprintf("%d", e.DeadlineHeight) + " |\n"
		}
		out += "\n"
	}

	// Spend log, latest first.
	out += "## Spend log\n\n"
	if len(attempts) == 0 {
		out += "No attempts yet.\n\n"
	} else {
		out += "| # | Agent | Amount | Purpose | Result | Reason |\n"
		out += "|---|---|---|---|---|---|\n"
		shown := 0
		for i := len(attempts) - 1; i >= 0 && shown < 20; i-- {
			a := attempts[i]
			result := "ALLOWED"
			if !a.Allowed {
				result = "**BLOCKED**"
			}
			name := ""
			if a.Name != "" {
				name = " (" + tableCell(a.Name) + ")"
			}
			out += "| " + ufmt.Sprintf("%d", a.ID) + " | `" +
				sanitize.InlineText(a.Agent.String()) + "`" + name + " | " +
				ufmt.Sprintf("%d", a.Amount) + " | " +
				tableCell(a.Purpose) + " | " + result + " | " +
				a.Reason + " |\n"
			shown++
		}
		out += "\n"
	}

	// Import snippet for the cap library.
	out += "## Import the cap library\n\n"
	out += "```go\n"
	out += "import caps \"gno.land/p/g16740fm9kd28luuktn3g42jfq3r998fm35chclv/agentvault\"\n\n"
	out += "// b := caps.NewBudget(perTxCap, dailyCap)\n"
	out += "// caps.RefreshDay(&b, time.Now().Unix())\n"
	out += "// allowed, reason := caps.CheckSpend(b, amount)\n"
	out += "```\n"
	return out
}

// Package agentvault is the AgentVault spend-guard realm: the first
// wallet an AI agent cannot drain.
//
// The owner funds the vault in ugnot and sets a per-transaction cap
// and a daily cap per agent. Agents spend only through this realm.
// Every spend call checks both caps, logs the attempt, and rejects
// anything over the limit — the rejection is a logged return value,
// not a panicked transaction, so the blocked attempt stays visible
// on the Render page as evidence. Payments can address an agent by
// registered name (resolved on-chain through r/sys/users, with a
// local name map as fallback) and are held in escrow until the named
// recipient confirms delivery or the owner refunds after the
// deadline.
//
// Security rules followed here (see docs/resources/gno-security-guide.md
// and gno-ai-contract-review.md):
//   - Caller identity comes from cur.Previous(), never from an
//     address parameter. No IsCurrent guard: the runtime puts cur
//     into the current realm-context on entry, so it is always true
//     in a crossing function.
//   - Payments in use cur.Previous().IsUserCall() with
//     unsafe.OriginSend(): only a direct user call guarantees the
//     send envelope landed at this realm. unsafe.OriginSend is the
//     sanctioned payment-read API (effective-gno.md: "the OriginSend
//     amount check + IsUserCall guard is the only pattern
//     available"); unsafe is imported ONLY for OriginSend, never
//     for PreviousRealm, which the guide forbids in a crossing
//     function.
//   - Balances are read with banker.GetCoin for one denom, never
//     GetCoins(...).AmountOf on a caller-supplied address.
//   - Getters return values/copies, never pointers to internal
//     mutable state.
//   - No realm value is stored; only addresses and paths (strings).
//   - Render sanitizes every user-controlled string.
//   - The owner is set by an explicit SetOwner call after deployment
//     (the empty-owner bootstrap), not captured in init, because
//     there is no safe deployer getter in init.
package agentvault

import (
	"time"

	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	caps "gno.land/p/g16740fm9kd28luuktn3g42jfq3r998fm35chclv/agentvault"
	susers "gno.land/r/sys/users"
)

// currentPkgPath is this realm's package path; init derives the
// realm's own address from it.
const currentPkgPath = "gno.land/r/g16740fm9kd28luuktn3g42jfq3r998fm35chclv/agentvault"

// denom is the only coin this vault handles.
const denom = "ugnot"

// maxAttempts caps the append-only spend log so storage stays
// bounded; the oldest entries are dropped first.
const maxAttempts = 500

var (
	owner         address
	selfAddr      address
	budgets       map[address]caps.AgentBudget
	agentList     []address
	nameMap       map[string]address
	attempts      []caps.Attempt
	escrows       map[int64]caps.Escrow
	nextEscrowID  int64
	nextAttemptID int64
	totalFunded   int64
	totalSpent    int64
	escrowedTotal int64
)

func init() {
	// The realm's own address is derived from its package path.
	// The owner is NOT captured here: there is no safe deployer
	// getter in init, and capturing via unsafe.PreviousRealm is
	// against the security guide. The owner starts empty and the
	// deployer calls SetOwner right after deployment (SetOwner's
	// empty-owner bootstrap allows the first call without an owner
	// check). That call must happen promptly: until then anyone
	// could claim the vault by calling SetOwner.
	selfAddr = chain.PackageAddress(currentPkgPath)
	budgets = make(map[address]caps.AgentBudget)
	nameMap = make(map[string]address)
	escrows = make(map[int64]caps.Escrow)
	nextEscrowID = 1
	nextAttemptID = 1
}

// mustOwner panics unless the caller is the vault owner. No
// IsCurrent guard: in a crossing function cur is always current.
func mustOwner(cur realm) {
	if owner == "" {
		panic("owner not set: call SetOwner first")
	}
	if cur.Previous().Address() != owner {
		panic("not the owner")
	}
}

// Owner returns the vault owner's address.
func Owner() address {
	return owner
}

// SetOwner sets (first call, while the owner is unset) or changes
// (owner only) the vault owner. The deployer calls this right after
// addpkg, while the owner is still unset; afterwards only the owner
// can rotate it.
func SetOwner(cur realm, newOwner address) {
	if owner != "" && cur.Previous().Address() != owner {
		panic("not the owner")
	}
	if newOwner == "" {
		panic("new owner must not be empty")
	}
	owner = newOwner
}

// logAttempt appends one entry to the spend log, dropping the oldest
// entries once the log reaches maxAttempts.
func logAttempt(kind string, agent address, name string, amount int64, purpose string, allowed bool, reason string) {
	attempts = append(attempts, caps.Attempt{
		ID:      nextAttemptID,
		Kind:    kind,
		Agent:   agent,
		Name:    name,
		Amount:  amount,
		Purpose: purpose,
		Allowed: allowed,
		Reason:  reason,
		Day:     caps.DayIndex(time.Now().Unix()),
	})
	nextAttemptID++
	if len(attempts) > maxAttempts {
		attempts = attempts[len(attempts)-maxAttempts:]
	}
}

// VaultBalance returns the realm's actual ugnot balance.
// Single-denom read: GetCoin, not GetCoins.
func VaultBalance() int64 {
	return banker.NewReadonlyBanker().GetCoin(selfAddr, denom)
}

// AvailableBalance is the balance not held in escrow.
func AvailableBalance() int64 {
	avail := VaultBalance() - escrowedTotal
	if avail < 0 {
		return 0
	}
	return avail
}

// TotalFunded returns the ugnot the owner has funded into the vault.
func TotalFunded() int64 { return totalFunded }

// TotalSpent returns the ugnot paid out through successful spends.
func TotalSpent() int64 { return totalSpent }

// EscrowedTotal returns the ugnot currently held in escrow.
func EscrowedTotal() int64 { return escrowedTotal }

// Fund tops up the vault. Only the owner may fund, and only as a
// direct user call: IsUserCall guarantees the OriginSend envelope
// landed at this realm, so the attached amount is the funded amount.
// Returns the vault balance after funding.
func Fund(cur realm) int64 {
	mustOwner(cur)
	// Paired guards (see effective-gno.md: verifying inbound coin
	// payments). IsUserCall alone would let the owner fund nothing;
	// OriginSend alone could describe coins an intermediary consumed.
	if !cur.Previous().IsUserCall() {
		panic("fund must be a direct user call")
	}
	amount := unsafe.OriginSend().AmountOf(denom)
	if amount <= 0 {
		panic("fund amount must be positive")
	}
	totalFunded += amount
	logAttempt("fund", cur.Previous().Address(), "", amount, "vault top-up", true, "ok")
	return VaultBalance()
}

// SetCap sets (or updates) an agent's caps. Updating preserves the
// amount already spent today: re-setting caps must not reset the
// daily spend, or the owner could launder the limit away.
func SetCap(cur realm, agent address, perTxCap, dailyCap int64) {
	mustOwner(cur)
	if reason := caps.ValidateCaps(perTxCap, dailyCap); reason != "" {
		panic(reason)
	}
	if agent == "" {
		panic("agent address must not be empty")
	}
	if old, ok := budgets[agent]; ok {
		old.PerTxCap = perTxCap
		old.DailyCap = dailyCap
		budgets[agent] = old
		return
	}
	budgets[agent] = caps.NewBudget(perTxCap, dailyCap)
	agentList = append(agentList, agent)
}

// SetName maps a name to an address in the vault's local name map.
// The owner resolves names off-chain (or from the registry) and
// registers them here; PayByName and SetCapByName consult the
// on-chain registry first and this map second.
func SetName(cur realm, name string, addr address) {
	mustOwner(cur)
	if name == "" {
		panic("name must not be empty")
	}
	if addr == "" {
		panic("address must not be empty")
	}
	nameMap[name] = addr
}

// ResolveName resolves a name to an address. The on-chain registry
// (r/sys/users) is consulted first and only the user's CURRENT name
// counts; the vault's local name map is the fallback. Returns false
// when the name resolves nowhere.
func ResolveName(name string) (address, bool) {
	if data, isCurrent := susers.ResolveName(name); data != nil && isCurrent {
		return data.Addr(), true
	}
	if addr, ok := nameMap[name]; ok {
		return addr, true
	}
	return "", false
}

// SetCapByName sets an agent's caps by registered name.
func SetCapByName(cur realm, name string, perTxCap, dailyCap int64) {
	mustOwner(cur)
	agent, ok := ResolveName(name)
	if !ok {
		panic("name not found: " + name)
	}
	SetCap(cur, agent, perTxCap, dailyCap)
}

// Budget returns a copy of an agent's budget and whether one is set.
func Budget(agent address) (caps.AgentBudget, bool) {
	b, ok := budgets[agent]
	return b, ok
}

// BudgetByName returns a copy of an agent's budget by name.
func BudgetByName(name string) (caps.AgentBudget, bool) {
	agent, ok := ResolveName(name)
	if !ok {
		return caps.AgentBudget{}, false
	}
	return Budget(agent)
}

// Agents returns the agent addresses with budgets, in the order
// their caps were first set. A copy: callers cannot mutate vault state.
func Agents() []address {
	cp := make([]address, len(agentList))
	copy(cp, agentList)
	return cp
}

// Spend pays amount ugnot to the calling agent, if both caps allow
// it. The caller is the agent: identity comes from the live crossing
// frame. A blocked spend returns false with the reason and is logged;
// it does not panic, because a panicked transaction would erase the
// evidence the guard report is built from.
func Spend(cur realm, amount int64, purpose string) (bool, string) {
	caller := cur.Previous().Address()
	b, ok := budgets[caller]
	if !ok {
		logAttempt("spend", caller, "", amount, purpose, false, "no budget set for this agent")
		return false, "no budget set for this agent"
	}
	caps.RefreshDay(&b, time.Now().Unix())
	allowed, reason := caps.CheckSpend(b, amount)
	if !allowed {
		// Persist the refreshed day even on a blocked spend, so the
		// rollover sticks.
		budgets[caller] = b
		logAttempt("spend", caller, "", amount, purpose, false, reason)
		return false, reason
	}
	if amount > AvailableBalance() {
		budgets[caller] = b
		logAttempt("spend", caller, "", amount, purpose, false, "insufficient vault balance")
		return false, "insufficient vault balance"
	}
	caps.ApplySpend(&b, amount)
	budgets[caller] = b
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(cur.Address(), caller, chain.Coins{{Denom: denom, Amount: amount}})
	totalSpent += amount
	logAttempt("spend", caller, "", amount, purpose, true, "ok")
	return true, "ok"
}

// PayByName holds amount ugnot in escrow for a named recipient. The
// name resolves through the on-chain registry first, then the local
// name map. The coins stay in the vault while held; ConfirmEscrow
// releases them, RefundEscrow returns them to the free balance after
// the deadline. Returns the escrow id, whether it was created, and a
// reason.
func PayByName(cur realm, name string, amount int64, deadlineBlocks int64) (int64, bool, string) {
	mustOwner(cur)
	recipient, ok := ResolveName(name)
	if !ok {
		return -1, false, "name not found: " + name
	}
	if amount <= 0 {
		return -1, false, "amount must be positive"
	}
	if deadlineBlocks <= 0 {
		return -1, false, "deadline must be a positive block count"
	}
	if amount > AvailableBalance() {
		return -1, false, "insufficient vault balance"
	}
	id := nextEscrowID
	nextEscrowID++
	escrows[id] = caps.Escrow{
		ID:             id,
		Payer:          cur.Previous().Address(),
		RecipientName:  name,
		Recipient:      recipient,
		Amount:         amount,
		DeadlineHeight: runtime.ChainHeight() + deadlineBlocks,
		Status:         caps.EscrowHeld,
	}
	escrowedTotal += amount
	logAttempt("escrow", recipient, name, amount, "payment held in escrow", true, "ok")
	return id, true, "ok"
}

// ConfirmEscrow releases a held escrow to its named recipient. Only
// the recipient may confirm, and only while the escrow is held.
func ConfirmEscrow(cur realm, id int64) (bool, string) {
	e, ok := escrows[id]
	if !ok {
		return false, "escrow not found"
	}
	if e.Status != caps.EscrowHeld {
		return false, "escrow not held"
	}
	if cur.Previous().Address() != e.Recipient {
		return false, "only the recipient can confirm"
	}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(cur.Address(), e.Recipient, chain.Coins{{Denom: denom, Amount: e.Amount}})
	e.Status = caps.EscrowReleased
	escrows[id] = e
	escrowedTotal -= e.Amount
	logAttempt("release", e.Recipient, e.RecipientName, e.Amount, "escrow released to recipient", true, "ok")
	return true, "ok"
}

// RefundEscrow returns a held escrow to the vault's free balance.
// Only the owner may refund, and only after the deadline block has
// passed. The coins never left the vault, so refunding only flips
// the status and frees the held amount.
func RefundEscrow(cur realm, id int64) (bool, string) {
	mustOwner(cur)
	e, ok := escrows[id]
	if !ok {
		return false, "escrow not found"
	}
	if !caps.EscrowRefundable(e, runtime.ChainHeight()) {
		if e.Status != caps.EscrowHeld {
			return false, "escrow not held"
		}
		return false, "deadline has not passed"
	}
	e.Status = caps.EscrowRefunded
	escrows[id] = e
	escrowedTotal -= e.Amount
	logAttempt("refund", e.Recipient, e.RecipientName, e.Amount, "escrow refunded to vault", true, "ok")
	return true, "ok"
}

// Escrow returns a copy of one escrow and whether it exists.
func Escrow(id int64) (caps.Escrow, bool) {
	e, ok := escrows[id]
	return e, ok
}

// Escrows returns copies of all escrows, ordered by id. A copy:
// callers cannot mutate vault state.
func Escrows() []caps.Escrow {
	out := make([]caps.Escrow, 0, len(escrows))
	for _, e := range escrows {
		out = append(out, e)
	}
	// Insertion sort by id (escrow counts are small).
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && out[j].ID < out[j-1].ID; j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}

// Attempts returns a copy of the spend log, oldest first. A copy:
// callers cannot mutate vault state.
func Attempts() []caps.Attempt {
	cp := make([]caps.Attempt, len(attempts))
	copy(cp, attempts)
	return cp
}

package agentvault

import (
	"strings"
	"testing"

	"chain"
	"chain/banker"

	caps "gno.land/p/g16740fm9kd28luuktn3g42jfq3r998fm35chclv/agentvault"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// resetVault restores every package-level var to a fresh state.
// gno test reuses one machine per package, so state persists across
// test functions unless reset. This helper touches state only, so it
// is safe to call from anywhere.
//
// NOTE on testing.SetRealm: in gno test, SetRealm's effect is visible
// only to cross calls made in the same function frame (and functions
// called from it while it is active). A SetRealm inside a helper that
// returns before the cross call is lost: the caller stays stuck at
// whatever realm was set earlier. So every test below calls
// testing.SetRealm directly, immediately before each cross call.
// Never wrap SetRealm in a helper (asUser/setupVault did that and
// every multi-caller test failed with a stale caller).
func resetVault() {
	owner = ""
	budgets = make(map[address]caps.AgentBudget)
	agentList = nil
	nameMap = make(map[string]address)
	attempts = nil
	escrows = make(map[int64]caps.Escrow)
	nextEscrowID = 1
	nextAttemptID = 1
	totalFunded = 0
	totalSpent = 0
	escrowedTotal = 0
}

// fundRealm credits the realm in the test bank and mirrors it in the
// tracked total, so AvailableBalance agrees with the real balance.
// No SetRealm and no cross call, so it is safe as a helper.
func fundRealm() {
	testing.IssueCoins(selfAddr, chain.Coins{{Denom: "ugnot", Amount: 10000000}})
	totalFunded = 10000000
}

func balanceOf(addr address) int64 {
	return banker.NewReadonlyBanker().GetCoin(addr, denom)
}

func TestSpendWithinCaps(cur realm, t *testing.T) {
	resetVault()
	ownerAddr := testutils.TestAddress("owner")
	agent := testutils.TestAddress("agent")
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	SetOwner(cross(cur), ownerAddr)
	fundRealm()
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	SetCap(cross(cur), agent, 100, 1000)

	before := balanceOf(agent)
	testing.SetRealm(testing.NewUserRealm(agent))
	ok, reason := Spend(cross(cur), 50, "test run")
	if !ok {
		t.Fatal("spend within caps rejected:", reason)
	}
	if balanceOf(agent)-before != 50 {
		t.Fatal("agent did not receive the spend")
	}
	b, _ := Budget(agent)
	if b.SpentToday != 50 {
		t.Fatal("spent today not recorded:", b.SpentToday)
	}
	if totalSpent != 50 {
		t.Fatal("total spent not recorded:", totalSpent)
	}
	if len(Attempts()) != 1 || !Attempts()[0].Allowed {
		t.Fatal("spend not logged as allowed")
	}
}

func TestSpendOverPerTxCap(cur realm, t *testing.T) {
	resetVault()
	ownerAddr := testutils.TestAddress("owner")
	agent := testutils.TestAddress("agent")
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	SetOwner(cross(cur), ownerAddr)
	fundRealm()
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	SetCap(cross(cur), agent, 100, 1000)

	// The demo moment: 10x the per-transaction cap.
	before := balanceOf(agent)
	testing.SetRealm(testing.NewUserRealm(agent))
	ok, reason := Spend(cross(cur), 1000, "overspend demo")
	if ok {
		t.Fatal("10x overspend allowed")
	}
	if reason != "exceeds per-transaction cap" {
		t.Fatal("wrong rejection reason:", reason)
	}
	if balanceOf(agent) != before {
		t.Fatal("blocked spend moved coins")
	}
	b, _ := Budget(agent)
	if b.SpentToday != 0 {
		t.Fatal("blocked spend recorded as spent")
	}
	at := Attempts()
	if len(at) != 1 || at[0].Allowed || at[0].Reason != "exceeds per-transaction cap" {
		t.Fatal("blocked spend not logged with its reason")
	}
}

func TestSpendOverDailyCap(cur realm, t *testing.T) {
	resetVault()
	ownerAddr := testutils.TestAddress("owner")
	agent := testutils.TestAddress("agent")
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	SetOwner(cross(cur), ownerAddr)
	fundRealm()
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	SetCap(cross(cur), agent, 1000, 1000)

	testing.SetRealm(testing.NewUserRealm(agent))
	// Spend 600 of the 1000 daily cap.
	if ok, _ := Spend(cross(cur), 600, "first"); !ok {
		t.Fatal("first spend rejected")
	}
	// Another 500 would take the day to 1100: blocked by the daily cap.
	testing.SetRealm(testing.NewUserRealm(agent))
	ok, reason := Spend(cross(cur), 500, "second")
	if ok {
		t.Fatal("spend over daily cap allowed")
	}
	if reason != "exceeds daily cap" {
		t.Fatal("wrong rejection reason:", reason)
	}
	// Exactly the remainder is allowed.
	testing.SetRealm(testing.NewUserRealm(agent))
	if ok, reason := Spend(cross(cur), 400, "remainder"); !ok {
		t.Fatal("spend at daily remainder rejected:", reason)
	}
}

func TestSpendNoBudget(cur realm, t *testing.T) {
	resetVault()
	ownerAddr := testutils.TestAddress("owner")
	agent := testutils.TestAddress("agent")
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	SetOwner(cross(cur), ownerAddr)
	fundRealm()

	testing.SetRealm(testing.NewUserRealm(agent))
	ok, reason := Spend(cross(cur), 10, "no budget")
	if ok {
		t.Fatal("spend without a budget allowed")
	}
	if reason != "no budget set for this agent" {
		t.Fatal("wrong rejection reason:", reason)
	}
	if len(Attempts()) != 1 || Attempts()[0].Allowed {
		t.Fatal("unbudgeted spend not logged as blocked")
	}
}

func TestSpendInsufficientBalance(cur realm, t *testing.T) {
	resetVault()
	ownerAddr := testutils.TestAddress("owner")
	agent := testutils.TestAddress("agent")
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	SetOwner(cross(cur), ownerAddr)
	fundRealm()
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	SetCap(cross(cur), agent, 100000, 100000)
	// Hold (nearly) everything in escrow by direct state setup, so
	// the available balance is ~0 regardless of the test bank total.
	escrowedTotal = VaultBalance()
	testing.SetRealm(testing.NewUserRealm(agent))
	ok, reason := Spend(cross(cur), 10, "empty vault")
	if ok {
		t.Fatal("spend with no available balance allowed")
	}
	if reason != "insufficient vault balance" {
		t.Fatal("wrong rejection reason:", reason)
	}
}

func TestDailyReset(cur realm, t *testing.T) {
	resetVault()
	ownerAddr := testutils.TestAddress("owner")
	agent := testutils.TestAddress("agent")
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	SetOwner(cross(cur), ownerAddr)
	fundRealm()
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	SetCap(cross(cur), agent, 100, 1000)
	// Simulate yesterday's spend: the budget's day is one behind the
	// test machine's fixed time (unix 1234567890 -> day 14288).
	b, _ := Budget(agent)
	b.SpentToday = 900
	b.DayIndex = 14287
	budgets[agent] = b

	// A 50 spend would exceed the daily cap on yesterday's books,
	// but the day has rolled over, so it must be allowed.
	testing.SetRealm(testing.NewUserRealm(agent))
	ok, reason := Spend(cross(cur), 50, "new day")
	if !ok {
		t.Fatal("spend on a new day rejected:", reason)
	}
	b2, _ := Budget(agent)
	if b2.SpentToday != 50 {
		t.Fatal("spent today not reset then recorded:", b2.SpentToday)
	}
	if b2.DayIndex != 14288 {
		t.Fatal("day index not advanced:", b2.DayIndex)
	}
}

func TestEscrowConfirm(cur realm, t *testing.T) {
	resetVault()
	ownerAddr := testutils.TestAddress("owner")
	recipient := testutils.TestAddress("recipient")
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	SetOwner(cross(cur), ownerAddr)
	fundRealm()
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	SetName(cross(cur), "nym-george123", recipient)

	// Owner pays the named agent; the payment is held.
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	id, ok, reason := PayByName(cross(cur), "nym-george123", 500, 100)
	if !ok {
		t.Fatal("pay by name failed:", reason)
	}
	if EscrowedTotal() != 500 {
		t.Fatal("escrowed total not recorded:", EscrowedTotal())
	}
	if AvailableBalance() != VaultBalance()-500 {
		t.Fatal("available balance did not drop by the escrow")
	}
	e, found := Escrow(id)
	if !found || e.Status != caps.EscrowHeld {
		t.Fatal("escrow not held after creation")
	}
	if e.Recipient != recipient || e.RecipientName != "nym-george123" {
		t.Fatal("escrow recipient wrong")
	}

	// A stranger cannot confirm it.
	stranger := testutils.TestAddress("stranger")
	testing.SetRealm(testing.NewUserRealm(stranger))
	if ok, reason := ConfirmEscrow(cross(cur), id); ok {
		t.Fatal("stranger confirmed the escrow")
	} else if reason != "only the recipient can confirm" {
		t.Fatal("wrong confirm rejection:", reason)
	}

	// The recipient confirms; the coins arrive and the escrow releases.
	before := balanceOf(recipient)
	testing.SetRealm(testing.NewUserRealm(recipient))
	ok, reason = ConfirmEscrow(cross(cur), id)
	if !ok {
		t.Fatal("recipient confirm failed:", reason)
	}
	if balanceOf(recipient)-before != 500 {
		t.Fatal("recipient did not receive the escrow")
	}
	if EscrowedTotal() != 0 {
		t.Fatal("escrowed total not freed on release")
	}
	e, _ = Escrow(id)
	if e.Status != caps.EscrowReleased {
		t.Fatal("escrow not released")
	}
	// Confirming again fails: it is no longer held.
	testing.SetRealm(testing.NewUserRealm(recipient))
	if ok, _ := ConfirmEscrow(cross(cur), id); ok {
		t.Fatal("released escrow confirmed again")
	}
}

func TestEscrowRefund(cur realm, t *testing.T) {
	resetVault()
	ownerAddr := testutils.TestAddress("owner")
	recipient := testutils.TestAddress("recipient")
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	SetOwner(cross(cur), ownerAddr)
	fundRealm()
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	SetName(cross(cur), "nym-george123", recipient)
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	id, ok, reason := PayByName(cross(cur), "nym-george123", 300, 1000)
	if !ok {
		t.Fatal("pay by name failed:", reason)
	}

	// Before the deadline the owner cannot refund.
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	if ok, reason := RefundEscrow(cross(cur), id); ok {
		t.Fatal("refund before deadline allowed")
	} else if reason != "deadline has not passed" {
		t.Fatal("wrong refund rejection:", reason)
	}

	// Move the deadline into the past (the test machine's height is
	// fixed, so the deadline is set directly) and refund succeeds.
	e, _ := Escrow(id)
	e.DeadlineHeight = 1
	escrows[id] = e
	before := AvailableBalance()
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	ok, reason = RefundEscrow(cross(cur), id)
	if !ok {
		t.Fatal("refund after deadline failed:", reason)
	}
	if AvailableBalance()-before != 300 {
		t.Fatal("refund did not free the held amount")
	}
	e, _ = Escrow(id)
	if e.Status != caps.EscrowRefunded {
		t.Fatal("escrow not refunded")
	}
	// Refunding again fails.
	testing.SetRealm(testing.NewUserRealm(ownerAddr))
	if ok, _ := RefundEscrow(cross(cur), id); ok {
		t.Fatal("refunded escrow refunded again")
	}
}

