// Package gnosage is the on-chain review board for GnoSage, an autonomous
// open-source AI agent that reviews Gno realms and posts scored verdicts
// on-chain.
//
// Anyone can post a review. Reviews from registered agent keys are marked
// as agent reviews and are the ones the board surfaces as the headline
// verdict for each realm. Human reviews are kept alongside them.
//
// A review scores a realm 0-100 overall and in four categories (docs,
// tests, safety, code quality), carries a short verdict and a compact
// machine-readable check list, and is versioned per realm path so a
// re-review after a redeploy never overwrites history.
package gnosage

import (
	"chain"
	"errors"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ownable/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Limits keep review payloads small: storage on Gno.land costs a
// refundable deposit, and a review board must stay cheap to write.
const (
	maxPathLength    = 256
	maxVerdictLength = 1000
	maxChecksLength  = 2000
)

const (
	// ReviewPostedEvent is emitted on every accepted review.
	ReviewPostedEvent = "ReviewPosted"
	// ReviewerRegisteredEvent is emitted when the owner registers a reviewer.
	ReviewerRegisteredEvent = "ReviewerRegistered"
	// ReviewerRemovedEvent is emitted when the owner removes a reviewer.
	ReviewerRemovedEvent = "ReviewerRemoved"
)

var (
	ErrEmptyPath      = errors.New("pkgPath must not be empty")
	ErrPathTooLong    = errors.New("pkgPath is too long")
	ErrBadPath        = errors.New("pkgPath must start with gno.land/")
	ErrScoreOutOfRange = errors.New("scores must be between 0 and 100")
	ErrEmptyVerdict   = errors.New("verdict must not be empty")
	ErrVerdictTooLong = errors.New("verdict is too long")
	ErrChecksTooLong  = errors.New("checks list is too long")
	ErrNotOwner       = errors.New("caller is not the owner")
	ErrReviewNotFound = errors.New("review not found")
)

// Review is one scored verdict for one realm path at one version.
type Review struct {
	ID        uint64    // global sequence number across all reviews
	PkgPath   string    // reviewed realm path, e.g. gno.land/r/<addr>/foo
	Version   uint64    // review version for this path, starting at 1
	Reviewer  address   // who posted it
	Agent     bool      // true when the reviewer is a registered agent key
	Score     int       // 0-100 overall
	Docs      int       // 0-100 documentation
	Tests     int       // 0-100 tests
	Safety    int       // 0-100 safety
	Quality   int       // 0-100 code quality
	Verdict   string    // short human-readable summary
	Checks    string    // compact check list, "name:result;name:result"
	CreatedAt time.Time // block time of the review
}

var (
	// Ownable gates reviewer registration to the deployer.
	Ownable *ownable.Ownable

	// reviews holds every review, keyed by "pkgPath#%020d" (version).
	reviews *avl.Tree
	// versions holds the review count per path, keyed by pkgPath.
	versions *avl.Tree
	// latestAgent holds the latest agent review version per path.
	latestAgent *avl.Tree
	// reviewers holds registered agent reviewer addresses, keyed by address.
	reviewers *avl.Tree
	// reviewCount is the total number of reviews posted.
	reviewCount uint64
)

func init(cur realm) {
	reviews = avl.NewTree()
	versions = avl.NewTree()
	latestAgent = avl.NewTree()
	reviewers = avl.NewTree()
	reviewCount = 0
	// At real deploy time the previous realm is the deploying user, who
	// becomes the owner. Under `gno test` there is no user caller, so the
	// owner stays unset and tests set it explicitly.
	if cur.Previous().IsUserCall() {
		Ownable = ownable.NewWithAddress(cur.Previous().Address())
	}
}

// reviewKey builds the storage key for one version of one path. The
// zero-padded version keeps lexicographic order equal to version order,
// so range scans over a path return reviews oldest-first.
func reviewKey(pkgPath string, version uint64) string {
	return pkgPath + "#" + ufmt.Sprintf("%020d", version)
}

// assertOwner panics unless the caller is the realm owner.
func assertOwner(cur realm) {
	if !Ownable.OwnedBy(cur.Previous().Address()) {
		panic(ErrNotOwner)
	}
}

// RegisterReviewer marks an address as a trusted agent reviewer. Only
// the owner can register reviewers. Reviews from registered reviewers
// are the board's headline verdicts.
func RegisterReviewer(cur realm, reviewer address) {
	assertOwner(cur)
	reviewers.Set(reviewer.String(), true)
	chain.Emit(ReviewerRegisteredEvent,
		"reviewer", reviewer.String(),
	)
}

// UnregisterReviewer removes a registered agent reviewer. Only the owner.
func UnregisterReviewer(cur realm, reviewer address) {
	assertOwner(cur)
	reviewers.Remove(reviewer.String())
	chain.Emit(ReviewerRemovedEvent,
		"reviewer", reviewer.String(),
	)
}

// IsReviewer reports whether an address is a registered agent reviewer.
func IsReviewer(reviewer address) bool {
	v, ok := reviewers.Get(reviewer.String()).(bool)
	return ok && v
}

// PostReview records a scored verdict for a realm path. Any caller may
// post; the review is marked as an agent review only when the caller is
// a registered agent reviewer. Returns the new version for the path.
func PostReview(cur realm, pkgPath string, score, docs, tests, safety, quality int, verdict, checks string) (uint64, error) {
	if err := validateReview(pkgPath, score, docs, tests, safety, quality, verdict, checks); err != nil {
		return 0, err
	}

	caller := cur.Previous().Address()
	agent := IsReviewer(caller)

	version := uint64(1)
	if v, ok := versions.Get(pkgPath).(int); ok {
		version = uint64(v) + 1
	}
	versions.Set(pkgPath, int(version))

	reviewCount++
	review := &Review{
		ID:        reviewCount,
		PkgPath:   pkgPath,
		Version:   version,
		Reviewer:  caller,
		Agent:     agent,
		Score:     score,
		Docs:      docs,
		Tests:     tests,
		Safety:    safety,
		Quality:   quality,
		Verdict:   verdict,
		Checks:    checks,
		CreatedAt: time.Now(),
	}
	reviews.Set(reviewKey(pkgPath, version), review)

	if agent {
		latestAgent.Set(pkgPath, int(version))
	}

	chain.Emit(ReviewPostedEvent,
		"pkg", pkgPath,
		"version", ufmt.Sprintf("%d", version),
		"reviewer", caller.String(),
		"agent", ufmt.Sprintf("%t", agent),
		"score", ufmt.Sprintf("%d", score),
	)

	return version, nil
}

// validateReview checks every field of a review before it is stored.
func validateReview(pkgPath string, score, docs, tests, safety, quality int, verdict, checks string) error {
	if strings.TrimSpace(pkgPath) == "" {
		return ErrEmptyPath
	}
	if len(pkgPath) > maxPathLength {
		return ErrPathTooLong
	}
	if !strings.HasPrefix(pkgPath, "gno.land/") {
		return ErrBadPath
	}
	for _, s := range []int{score, docs, tests, safety, quality} {
		if s < 0 || s > 100 {
			return ErrScoreOutOfRange
		}
	}
	if strings.TrimSpace(verdict) == "" {
		return ErrEmptyVerdict
	}
	if len(verdict) > maxVerdictLength {
		return ErrVerdictTooLong
	}
	if len(checks) > maxChecksLength {
		return ErrChecksTooLong
	}
	return nil
}

// GetReview returns one review by path and version, or nil.
func GetReview(pkgPath string, version uint64) *Review {
	v, ok := reviews.Get(reviewKey(pkgPath, version)).(*Review)
	if !ok {
		return nil
	}
	return v
}

// LatestAgentReview returns the newest agent review for a path, or nil
// when no agent has reviewed it yet.
func LatestAgentReview(pkgPath string) *Review {
	v, ok := latestAgent.Get(pkgPath).(int)
	if !ok {
		return nil
	}
	return GetReview(pkgPath, uint64(v))
}

// VersionCount returns how many reviews a path has received.
func VersionCount(pkgPath string) int {
	v, ok := versions.Get(pkgPath).(int)
	if !ok {
		return 0
	}
	return v
}

// ReviewCount returns the total number of reviews on the board.
func ReviewCount() uint64 {
	return reviewCount
}

// ReviewedPaths returns every path that has at least one review, in
// lexicographic order.
func ReviewedPaths() []string {
	paths := []string{}
	versions.Iterate("", "", func(key string, _ any) bool {
		paths = append(paths, key)
		return false
	})
	return paths
}

package gnosage

import (
	"strings"
	"testing"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ownable/v0"
)

// Test addresses, reused from the gnolang/gno examples (valid bech32).
var (
	alice = address("g125em6arxsnj49vx35f0n0z34putv5ty3376fg5")
	bob   = address("g1skl80cuz8zq3lul9pgz5pc35l2pfzgxgfpsqkx")
	carol = address("g1wymu47drhr0kuq2098m792lytgtj2nyx77yrsm")
)

// resetState rebuilds realm state and makes alice the owner. Tests call
// it first because package state persists across tests in one run.
func resetState() {
	Ownable = ownable.NewWithAddress(alice)
	reviews = avl.NewTree()
	versions = avl.NewTree()
	latestAgent = avl.NewTree()
	reviewers = avl.NewTree()
	reviewCount = 0
}

func TestPostReviewAgent(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice))
	RegisterReviewer(cross(cur), bob)
	if !IsReviewer(bob) {
		t.Fatal("bob should be a registered reviewer")
	}

	testing.SetRealm(testing.NewUserRealm(bob))
	version, err := PostReview(cross(cur), "gno.land/r/demo/counter", 80, 70, 60, 90, 85, "Solid little realm.", "lint:pass;tests:present")
	if err != nil {
		t.Fatalf("PostReview failed: %v", err)
	}
	if version != 1 {
		t.Fatalf("version = %d, want 1", version)
	}
	r := GetReview("gno.land/r/demo/counter", 1)
	if r == nil {
		t.Fatal("GetReview returned nil")
	}
	if !r.Agent {
		t.Fatal("review by a registered reviewer should be marked agent")
	}
	if r.Score != 80 || r.Docs != 70 || r.Tests != 60 || r.Safety != 90 || r.Quality != 85 {
		t.Fatalf("scores mismatch: %+v", r)
	}
	if r.Reviewer != bob {
		t.Fatalf("reviewer = %s, want %s", r.Reviewer, bob)
	}
	latest := LatestAgentReview("gno.land/r/demo/counter")
	if latest == nil || latest.Version != 1 {
		t.Fatal("LatestAgentReview should return version 1")
	}
	if ReviewCount() != 1 {
		t.Fatalf("ReviewCount = %d, want 1", ReviewCount())
	}
}

func TestPostReviewHuman(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(carol))
	version, err := PostReview(cross(cur), "gno.land/r/demo/counter", 50, 50, 50, 50, 50, "Meh.", "lint:pass")
	if err != nil {
		t.Fatalf("PostReview failed: %v", err)
	}
	if version != 1 {
		t.Fatalf("version = %d, want 1", version)
	}
	r := GetReview("gno.land/r/demo/counter", 1)
	if r.Agent {
		t.Fatal("review by an unregistered caller should not be marked agent")
	}
	if LatestAgentReview("gno.land/r/demo/counter") != nil {
		t.Fatal("human reviews must not become the headline agent verdict")
	}
	if VersionCount("gno.land/r/demo/counter") != 1 {
		t.Fatal("VersionCount should count human reviews too")
	}
}

func TestPostReviewVersions(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice))
	RegisterReviewer(cross(cur), bob)
	testing.SetRealm(testing.NewUserRealm(bob))
	if _, err := PostReview(cross(cur), "gno.land/r/demo/counter", 70, 70, 70, 70, 70, "v1.", ""); err != nil {
		t.Fatalf("first PostReview failed: %v", err)
	}
	v2, err := PostReview(cross(cur), "gno.land/r/demo/counter", 85, 85, 85, 85, 85, "v2, improved.", "")
	if err != nil {
		t.Fatalf("second PostReview failed: %v", err)
	}
	if v2 != 2 {
		t.Fatalf("version = %d, want 2", v2)
	}
	if VersionCount("gno.land/r/demo/counter") != 2 {
		t.Fatal("VersionCount should be 2")
	}
	latest := LatestAgentReview("gno.land/r/demo/counter")
	if latest == nil || latest.Score != 85 {
		t.Fatal("latest agent review should be the v2 one")
	}
	// History is kept: v1 is still readable.
	old := GetReview("gno.land/r/demo/counter", 1)
	if old == nil || old.Score != 70 {
		t.Fatal("v1 review should still be stored")
	}
}

func TestPostReviewValidation(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(bob))
	cases := []struct {
		name    string
		path    string
		score   int
		verdict string
		checks  string
	}{
		{"empty path", "", 50, "ok", ""},
		{"bad prefix", "evil.com/r/x", 50, "ok", ""},
		{"score too high", "gno.land/r/a/b", 101, "ok", ""},
		{"score negative", "gno.land/r/a/b", -1, "ok", ""},
		{"empty verdict", "gno.land/r/a/b", 50, "   ", ""},
		{"verdict too long", "gno.land/r/a/b", 50, strings.Repeat("x", 1001), ""},
		{"checks too long", "gno.land/r/a/b", 50, "ok", strings.Repeat("x", 2001)},
	}
	for _, c := range cases {
		if _, err := PostReview(cross(cur), c.path, c.score, 50, 50, 50, 50, c.verdict, c.checks); err == nil {
			t.Fatalf("%s: expected an error, got none", c.name)
		}
	}
	if ReviewCount() != 0 {
		t.Fatalf("invalid reviews must not be stored, count = %d", ReviewCount())
	}
}

func TestUnregisterReviewer(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice))
	RegisterReviewer(cross(cur), bob)
	UnregisterReviewer(cross(cur), bob)
	if IsReviewer(bob) {
		t.Fatal("bob should no longer be a reviewer")
	}
	testing.SetRealm(testing.NewUserRealm(bob))
	if _, err := PostReview(cross(cur), "gno.land/r/demo/counter", 50, 50, 50, 50, 50, "ok", ""); err != nil {
		t.Fatalf("PostReview failed: %v", err)
	}
	if GetReview("gno.land/r/demo/counter", 1).Agent {
		t.Fatal("review after unregister should not be marked agent")
	}
}

func TestRenderIndexAndDetail(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(alice))
	RegisterReviewer(cross(cur), bob)
	testing.SetRealm(testing.NewUserRealm(bob))
	if _, err := PostReview(cross(cur), "gno.land/r/demo/counter", 80, 70, 60, 90, 85, "Solid.", "lint:pass"); err != nil {
		t.Fatalf("PostReview failed: %v", err)
	}
	index := Render("")
	if !strings.Contains(index, "gno.land/r/demo/counter") {
		t.Fatal("index should list the reviewed realm")
	}
	if !strings.Contains(index, "80") {
		t.Fatal("index should show the score")
	}
	detail := Render("gno.land/r/demo/counter")
	if !strings.Contains(detail, "Solid.") {
		t.Fatal("detail should show the verdict")
	}
	if !strings.Contains(detail, "v1") {
		t.Fatal("detail should show the version")
	}
	// A verdict with markdown-breaking characters must be flattened.
	testing.SetRealm(testing.NewUserRealm(bob))
	if _, err := PostReview(cross(cur), "gno.land/r/demo/counter", 10, 10, 10, 10, 10, "bad\n[link](http://x) | table", ""); err != nil {
		t.Fatalf("PostReview failed: %v", err)
	}
	detail = Render("gno.land/r/demo/counter")
	if strings.Contains(detail, "[link](http://x)") {
		t.Fatal("rendered verdict must not carry a live link")
	}
}

func TestReviewedPaths(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(bob))
	if _, err := PostReview(cross(cur), "gno.land/r/b/two", 50, 50, 50, 50, 50, "ok", ""); err != nil {
		t.Fatalf("PostReview failed: %v", err)
	}
	if _, err := PostReview(cross(cur), "gno.land/r/a/one", 50, 50, 50, 50, 50, "ok", ""); err != nil {
		t.Fatalf("PostReview failed: %v", err)
	}
	paths := ReviewedPaths()
	if len(paths) != 2 {
		t.Fatalf("ReviewedPaths = %v, want 2 paths", paths)
	}
	if paths[0] != "gno.land/r/a/one" || paths[1] != "gno.land/r/b/two" {
		t.Fatalf("ReviewedPaths = %v, want lexicographic order", paths)
	}
}

package gnosage

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

// Render serves the review board through gnoweb.
//
//   - Render("") lists every reviewed realm with its latest agent score.
//   - Render("<pkgPath>") shows the review history of one realm, e.g.
//     Render("gno.land/r/<addr>/foo").
//
// Caller-controlled text (verdicts) is flattened before rendering so a
// review can never break the board's markdown layout or smuggle links.
func Render(path string) string {
	if path != "" && VersionCount(path) > 0 {
		return renderDetail(path)
	}
	return renderIndex()
}

// renderIndex lists reviewed realms with their latest agent verdict.
func renderIndex() string {
	var b strings.Builder
	b.WriteString("# GnoSage review board\n\n")
	b.WriteString("Autonomous AI reviews of Gno realms. Scores are 0-100; the headline score is the latest review by a registered agent reviewer.\n\n")
	paths := ReviewedPaths()
	if len(paths) == 0 {
		b.WriteString("No reviews yet. The agent posts its first verdicts shortly after deploy.\n")
		return b.String()
	}
	b.WriteString("| Realm | Score | Docs | Tests | Safety | Quality | Reviews |\n")
	b.WriteString("|---|---|---|---|---|---|---|\n")
	for _, p := range paths {
		latest := LatestAgentReview(p)
		if latest == nil {
			b.WriteString(ufmt.Sprintf("| %s | — | — | — | — | — | %d |\n", p, VersionCount(p)))
			continue
		}
		b.WriteString(ufmt.Sprintf("| [%s](%s) | %d | %d | %d | %d | %d | %d |\n",
			p, p, latest.Score, latest.Docs, latest.Tests, latest.Safety, latest.Quality, VersionCount(p)))
	}
	b.WriteString(ufmt.Sprintf("\n%d review(s) on the board.\n", ReviewCount()))
	return b.String()
}

// renderDetail shows every review of one realm, newest first.
func renderDetail(pkgPath string) string {
	var b strings.Builder
	b.WriteString(ufmt.Sprintf("# %s\n\n", pkgPath))
	latest := LatestAgentReview(pkgPath)
	if latest != nil {
		b.WriteString(ufmt.Sprintf("Latest agent verdict (v%d, score %d/100): %s\n\n",
			latest.Version, latest.Score, flatten(latest.Verdict)))
	}
	b.WriteString("## Reviews\n\n")
	count := VersionCount(pkgPath)
	for v := count; v >= 1; v-- {
		r := GetReview(pkgPath, uint64(v))
		if r == nil {
			continue
		}
		kind := "human"
		if r.Agent {
			kind = "agent"
		}
		b.WriteString(ufmt.Sprintf("### v%d — %d/100 (%s, %s)\n\n", r.Version, r.Score, kind, r.Reviewer.String()))
		b.WriteString(ufmt.Sprintf("Docs %d · Tests %d · Safety %d · Quality %d\n\n", r.Docs, r.Tests, r.Safety, r.Quality))
		b.WriteString(flatten(r.Verdict) + "\n\n")
		if r.Checks != "" {
			b.WriteString("Checks: `" + flatten(r.Checks) + "`\n\n")
		}
	}
	return b.String()
}

// flatten removes markdown-breaking characters from caller text.
func flatten(s string) string {
	s = strings.ReplaceAll(s, "\n", " ")
	s = strings.ReplaceAll(s, "\r", " ")
	s = strings.ReplaceAll(s, "|", "/")
	s = strings.ReplaceAll(s, "[", "(")
	s = strings.ReplaceAll(s, "]", ")")
	return s
}

// Package gnosage is the on-chain review board for GnoSage, an autonomous
// open-source AI agent that reviews Gno realms and posts scored verdicts
// on-chain.
//
// Anyone can post a review. Reviews from registered agent keys are marked
// as agent reviews and are the ones the board surfaces as the headline
// verdict for each realm. Human reviews are kept alongside them.
//
// A review scores a realm 0-100 overall and in four categories (docs,
// tests, safety, code quality), carries a short verdict and a compact
// machine-readable check list, and is versioned per realm path so a
// re-review after a redeploy never overwrites history.
package gnosage

import (
	"chain"
	"errors"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ownable/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Limits keep review payloads small: storage on Gno.land costs a
// refundable deposit, and a review board must stay cheap to write.
const (
	maxPathLength    = 256
	maxVerdictLength = 1000
	maxChecksLength  = 2000
)

const (
	// ReviewPostedEvent is emitted on every accepted review.
	ReviewPostedEvent = "ReviewPosted"
	// ReviewerRegisteredEvent is emitted when the owner registers a reviewer.
	ReviewerRegisteredEvent = "ReviewerRegistered"
	// ReviewerRemovedEvent is emitted when the owner removes a reviewer.
	ReviewerRemovedEvent = "ReviewerRemoved"
)

var (
	ErrEmptyPath      = errors.New("pkgPath must not be empty")
	ErrPathTooLong    = errors.New("pkgPath is too long")
	ErrBadPath        = errors.New("pkgPath must start with gno.land/")
	ErrScoreOutOfRange = errors.New("scores must be between 0 and 100")
	ErrEmptyVerdict   = errors.New("verdict must not be empty")
	ErrVerdictTooLong = errors.New("verdict is too long")
	ErrChecksTooLong  = errors.New("checks list is too long")
	ErrNotOwner       = errors.New("caller is not the owner")
	ErrReviewNotFound = errors.New("review not found")
)

// Review is one scored verdict for one realm path at one version.
type Review struct {
	ID        uint64    // global sequence number across all reviews
	PkgPath   string    // reviewed realm path, e.g. gno.land/r/<addr>/foo
	Version   uint64    // review version for this path, starting at 1
	Reviewer  address   // who posted it
	Agent     bool      // true when the reviewer is a registered agent key
	Score     int       // 0-100 overall
	Docs      int       // 0-100 documentation
	Tests     int       // 0-100 tests
	Safety    int       // 0-100 safety
	Quality   int       // 0-100 code quality
	Verdict   string    // short human-readable summary
	Checks    string    // compact check list, "name:result;name:result"
	CreatedAt time.Time // block time of the review
}

var (
	// Ownable gates reviewer registration to the deployer.
	Ownable *ownable.Ownable

	// reviews holds every review, keyed by "pkgPath#%020d" (version).
	reviews *avl.Tree
	// versions holds the review count per path, keyed by pkgPath.
	versions *avl.Tree
	// latestAgent holds the latest agent review version per path.
	latestAgent *avl.Tree
	// reviewers holds registered agent reviewer addresses, keyed by address.
	reviewers *avl.Tree
	// reviewCount is the total number of reviews posted.
	reviewCount uint64
)

func init(cur realm) {
	reviews = avl.NewTree()
	versions = avl.NewTree()
	latestAgent = avl.NewTree()
	reviewers = avl.NewTree()
	reviewCount = 0
	// At real deploy time the previous realm is the deploying user, who
	// becomes the owner. Under `gno test` there is no user caller, so the
	// owner stays unset and tests set it explicitly.
	if cur.Previous().IsUserCall() {
		Ownable = ownable.NewWithAddress(cur.Previous().Address())
	}
}

// reviewKey builds the storage key for one version of one path. The
// zero-padded version keeps lexicographic order equal to version order,
// so range scans over a path return reviews oldest-first.
func reviewKey(pkgPath string, version uint64) string {
	return pkgPath + "#" + ufmt.Sprintf("%020d", version)
}

// assertOwner panics unless the caller is the realm owner.
func assertOwner(cur realm) {
	if !Ownable.OwnedBy(cur.Previous().Address()) {
		panic(ErrNotOwner)
	}
}

// RegisterReviewer marks an address as a trusted agent reviewer. Only
// the owner can register reviewers. Reviews from registered reviewers
// are the board's headline verdicts.
func RegisterReviewer(cur realm, reviewer address) {
	assertOwner(cur)
	reviewers.Set(reviewer.String(), true)
	chain.Emit(ReviewerRegisteredEvent,
		"reviewer", reviewer.String(),
	)
}

// UnregisterReviewer removes a registered agent reviewer. Only the owner.
func UnregisterReviewer(cur realm, reviewer address) {
	assertOwner(cur)
	reviewers.Remove(reviewer.String())
	chain.Emit(ReviewerRemovedEvent,
		"reviewer", reviewer.String(),
	)
}

// IsReviewer reports whether an address is a registered agent reviewer.
func IsReviewer(reviewer address) bool {
	v, ok := reviewers.Get(reviewer.String()).(bool)
	return ok && v
}

// PostReview records a scored verdict for a realm path. Any caller may
// post; the review is marked as an agent review only when the caller is
// a registered agent reviewer. Returns the new version for the path.
func PostReview(cur realm, pkgPath string, score, docs, tests, safety, quality int, verdict, checks string) (uint64, error) {
	if err := validateReview(pkgPath, score, docs, tests, safety, quality, verdict, checks); err != nil {
		return 0, err
	}

	caller := cur.Previous().Address()
	agent := IsReviewer(caller)

	version := uint64(1)
	if v, ok := versions.Get(pkgPath).(int); ok {
		version = uint64(v) + 1
	}
	versions.Set(pkgPath, int(version))

	reviewCount++
	review := &Review{
		ID:        reviewCount,
		PkgPath:   pkgPath,
		Version:   version,
		Reviewer:  caller,
		Agent:     agent,
		Score:     score,
		Docs:      docs,
		Tests:     tests,
		Safety:    safety,
		Quality:   quality,
		Verdict:   verdict,
		Checks:    checks,
		CreatedAt: time.Now(),
	}
	reviews.Set(reviewKey(pkgPath, version), review)

	if agent {
		latestAgent.Set(pkgPath, int(version))
	}

	chain.Emit(ReviewPostedEvent,
		"pkg", pkgPath,
		"version", ufmt.Sprintf("%d", version),
		"reviewer", caller.String(),
		"agent", ufmt.Sprintf("%t", agent),
		"score", ufmt.Sprintf("%d", score),
	)

	return version, nil
}

// validateReview checks every field of a review before it is stored.
func validateReview(pkgPath string, score, docs, tests, safety, quality int, verdict, checks string) error {
	if strings.TrimSpace(pkgPath) == "" {
		return ErrEmptyPath
	}
	if len(pkgPath) > maxPathLength {
		return ErrPathTooLong
	}
	if !strings.HasPrefix(pkgPath, "gno.land/") {
		return ErrBadPath
	}
	for _, s := range []int{score, docs, tests, safety, quality} {
		if s < 0 || s > 100 {
			return ErrScoreOutOfRange
		}
	}
	if strings.TrimSpace(verdict) == "" {
		return ErrEmptyVerdict
	}
	if len(verdict) > maxVerdictLength {
		return ErrVerdictTooLong
	}
	if len(checks) > maxChecksLength {
		return ErrChecksTooLong
	}
	return nil
}

// GetReview returns one review by path and version, or nil.
func GetReview(pkgPath string, version uint64) *Review {
	v, ok := reviews.Get(reviewKey(pkgPath, version)).(*Review)
	if !ok {
		return nil
	}
	return v
}

// LatestAgentReview returns the newest agent review for a path, or nil
// when no agent has reviewed it yet.
func LatestAgentReview(pkgPath string) *Review {
	v, ok := latestAgent.Get(pkgPath).(int)
	if !ok {
		return nil
	}
	return GetReview(pkgPath, uint64(v))
}

// VersionCount returns how many reviews a path has received.
func VersionCount(pkgPath string) int {
	v, ok := versions.Get(pkgPath).(int)
	if !ok {
		return 0
	}
	return v
}

// ReviewCount returns the total number of reviews on the board.
func ReviewCount() uint64 {
	return reviewCount
}

// ReviewedPaths returns every path that has at least one review, in
// lexicographic order.
func ReviewedPaths() []string {
	paths := []string{}
	versions.Iterate("", "", func(key string, _ any) bool {
		paths = append(paths, key)
		return false
	})
	return paths
}

