package nandloom

import (
	"errors"
	"sort"
	"strconv"

	"gno.land/p/nt/ufmt/v0"
)

// Compile validates wire references, rejects combinational cycles with Kahn's
// topological sort, recursively flattens imported sub-chips through resolve,
// enforces resource caps, and computes exact flattened NAND count & depth.
func Compile(c *Circuit, resolve ChipResolver) (*CompiledCircuit, error) {
	if c == nil {
		return nil, errors.New("nil circuit")
	}

	// 1. Top-level topological sort + column depth for schematic rendering.
	topOrder, stmtCol, maxCol, err := topoSort(c)
	if err != nil {
		return nil, err
	}

	// 2. Recursively flatten into primitive gates.
	flat := make([]FlatGate, 0, len(c.Statements)*2)
	stmtNANDs := make([]int, len(c.Statements))
	directChips := make(map[string]bool)
	visiting := make(map[string]bool)
	wireDepth := make(map[string]int)
	for i := 0; i < len(c.Inputs); i++ {
		wireDepth[c.Inputs[i]] = 0
	}

	instanceCounter := 0
	totalNANDs := 0

	appendFlat := func(g FlatGate) error {
		if len(flat)+1 > MaxFlatOps {
			return errors.New(ufmt.Sprintf("flattened circuit exceeds max %d total primitive ops", MaxFlatOps))
		}
		flat = append(flat, g)
		return nil
	}

	var flattenCircuit func(cur *Circuit, prefix string, inputMap map[string]string, depth int) error
	flattenCircuit = func(cur *Circuit, prefix string, inputMap map[string]string, depth int) error {
		if depth > MaxChipDepth {
			return errors.New(ufmt.Sprintf("chip composition exceeds max nesting depth %d", MaxChipDepth))
		}
		order, _, _, terr := topoSort(cur)
		if terr != nil {
			return terr
		}
		mapWire := func(w string) string {
			if mapped, ok := inputMap[w]; ok {
				return mapped
			}
			if prefix == "" {
				return w
			}
			return prefix + w
		}

		for oi := 0; oi < len(order); oi++ {
			si := order[oi]
			st := cur.Statements[si]
			nandBefore := totalNANDs

			switch st.Op {
			case OpConst0, OpConst1:
				outName := mapWire(st.Outputs[0])
				wireDepth[outName] = 0
				if aerr := appendFlat(FlatGate{
					Out:   outName,
					Op:    st.Op,
					Depth: 0,
				}); aerr != nil {
					return aerr
				}
			case OpBuf:
				aName := mapWire(st.Args[0])
				outName := mapWire(st.Outputs[0])
				d := wireDepth[aName]
				wireDepth[outName] = d
				if aerr := appendFlat(FlatGate{
					Out:   outName,
					Op:    OpBuf,
					A:     aName,
					Depth: d,
				}); aerr != nil {
					return aerr
				}
			case OpNAND:
				if totalNANDs+1 > MaxFlatGates {
					return errors.New(ufmt.Sprintf("flattened circuit exceeds max %d NAND gates", MaxFlatGates))
				}
				aName := mapWire(st.Args[0])
				bName := mapWire(st.Args[1])
				outName := mapWire(st.Outputs[0])
				da := wireDepth[aName]
				db := wireDepth[bName]
				d := da
				if db > d {
					d = db
				}
				d++
				wireDepth[outName] = d
				totalNANDs++
				if aerr := appendFlat(FlatGate{
					Out:   outName,
					Op:    OpNAND,
					A:     aName,
					B:     bName,
					Depth: d,
				}); aerr != nil {
					return aerr
				}
			case OpChip:
				if resolve == nil {
					return errors.New(ufmt.Sprintf("line %d: chip:%s cannot be resolved (no resolver)", st.Line, st.ChipSlug))
				}
				if visiting[st.ChipSlug] {
					return errors.New(ufmt.Sprintf("line %d: recursive chip cycle involving chip:%s", st.Line, st.ChipSlug))
				}
				if instanceCounter+1 > MaxChipInstances {
					return errors.New(ufmt.Sprintf("flattened circuit exceeds max %d chip instances", MaxChipInstances))
				}
				sub, ok := resolve(st.ChipSlug)
				if !ok || sub == nil {
					return errors.New(ufmt.Sprintf("line %d: unknown verified chip %q", st.Line, st.ChipSlug))
				}
				if len(st.Args) != len(sub.Inputs) {
					return errors.New(ufmt.Sprintf("line %d: chip:%s expects %d input(s), got %d", st.Line, st.ChipSlug, len(sub.Inputs), len(st.Args)))
				}
				if len(st.Outputs) != len(sub.Outputs) {
					return errors.New(ufmt.Sprintf("line %d: chip:%s produces %d output(s), got %d", st.Line, st.ChipSlug, len(sub.Outputs), len(st.Outputs)))
				}
				if depth == 0 {
					directChips[st.ChipSlug] = true
				}
				instanceCounter++
				subPrefix := "__c" + strconv.Itoa(instanceCounter) + "_"
				subInMap := make(map[string]string, len(sub.Inputs))
				for k := 0; k < len(sub.Inputs); k++ {
					subInMap[sub.Inputs[k]] = mapWire(st.Args[k])
				}
				visiting[st.ChipSlug] = true
				ferr := flattenCircuit(sub, subPrefix, subInMap, depth+1)
				delete(visiting, st.ChipSlug)
				if ferr != nil {
					return ferr
				}
				// Wire sub-chip outputs into caller's output wire names via zero-cost buffers.
				for k := 0; k < len(sub.Outputs); k++ {
					subOutWire := subPrefix + sub.Outputs[k]
					if mapped, exists := subInMap[sub.Outputs[k]]; exists {
						subOutWire = mapped
					}
					dstWire := mapWire(st.Outputs[k])
					d := wireDepth[subOutWire]
					wireDepth[dstWire] = d
					if aerr := appendFlat(FlatGate{
						Out:   dstWire,
						Op:    OpBuf,
						A:     subOutWire,
						Depth: d,
					}); aerr != nil {
						return aerr
					}
				}
			default:
				return errors.New(ufmt.Sprintf("line %d: unknown operation", st.Line))
			}

			if depth == 0 {
				stmtNANDs[si] = totalNANDs - nandBefore
			}
		}
		return nil
	}

	if err := flattenCircuit(c, "", map[string]string{}, 0); err != nil {
		return nil, err
	}

	// True critical-path propagation depth = max NAND depth across declared primary outputs.
	maxDepth := 0
	for i := 0; i < len(c.Outputs); i++ {
		if d := wireDepth[c.Outputs[i]]; d > maxDepth {
			maxDepth = d
		}
	}

	imported := make([]string, 0, len(directChips))
	for slug := range directChips {
		imported = append(imported, slug)
	}
	sort.Strings(imported)

	return &CompiledCircuit{
		AST:           c,
		TopOrder:      topOrder,
		StmtDepth:     stmtCol,
		StmtNANDs:     stmtNANDs,
		MaxCol:        maxCol,
		FlatGates:     flat,
		NANDCount:     totalNANDs,
		MaxDepth:      maxDepth,
		ImportedChips: imported,
		ModuleCount:   len(c.Statements),
	}, nil
}

// topoSort validates wire definitions and runs deterministic Kahn's topological sort
// over c.Statements, rejecting combinational cycles and computing visual column depths.
func topoSort(c *Circuit) ([]int, []int, int, error) {
	n := len(c.Statements)
	inputSet := make(map[string]bool, len(c.Inputs))
	for i := 0; i < len(c.Inputs); i++ {
		inputSet[c.Inputs[i]] = true
	}

	producer := make(map[string]int, n*2)
	for i := 0; i < n; i++ {
		st := c.Statements[i]
		for j := 0; j < len(st.Outputs); j++ {
			producer[st.Outputs[j]] = i
		}
	}

	inDeg := make([]int, n)
	adj := make([][]int, n)
	for i := 0; i < n; i++ {
		st := c.Statements[i]
		seenDep := make(map[int]bool)
		for j := 0; j < len(st.Args); j++ {
			arg := st.Args[j]
			if inputSet[arg] {
				continue
			}
			pIdx, ok := producer[arg]
			if !ok {
				return nil, nil, 0, errors.New(ufmt.Sprintf("line %d: undefined wire %q", st.Line, arg))
			}
			if pIdx == i {
				return nil, nil, 0, errors.New(ufmt.Sprintf("line %d: self-cycle on wire %q", st.Line, arg))
			}
			if !seenDep[pIdx] {
				seenDep[pIdx] = true
				adj[pIdx] = append(adj[pIdx], i)
				inDeg[i]++
			}
		}
	}

	// Deterministic queue: process ready indices in ascending source order.
	queue := make([]int, 0, n)
	colDepth := make([]int, n)
	for i := 0; i < n; i++ {
		if inDeg[i] == 0 {
			queue = append(queue, i)
			colDepth[i] = 1
		}
	}

	order := make([]int, 0, n)
	maxCol := 1
	for head := 0; head < len(queue); head++ {
		u := queue[head]
		order = append(order, u)
		if colDepth[u] > maxCol {
			maxCol = colDepth[u]
		}
		for k := 0; k < len(adj[u]); k++ {
			v := adj[u][k]
			if colDepth[u]+1 > colDepth[v] {
				colDepth[v] = colDepth[u] + 1
			}
			inDeg[v]--
			if inDeg[v] == 0 {
				queue = append(queue, v)
			}
		}
	}

	if len(order) != n {
		// Find first statement stuck in cycle for actionable diagnostics.
		for i := 0; i < n; i++ {
			if inDeg[i] > 0 {
				return nil, nil, 0, errors.New(ufmt.Sprintf("line %d: combinational cycle detected involving wire %q", c.Statements[i].Line, c.Statements[i].Outputs[0]))
			}
		}
		return nil, nil, 0, errors.New("combinational cycle detected")
	}

	return order, colDepth, maxCol, nil
}

// Package nandloom implements a deterministic, pure-Gno digital logic circuit
// parser, composable sub-chip compiler, levelized simulator, challenge verifier,
// Gno code exporter, and SVG schematic/waveform renderer.
//
// Circuits are written in a strict line-oriented netlist DSL using universal
// NAND gates and previously verified on-chain sub-chips:
//
//	in a, b
//	out sum, carry
//	w1 = nand(a, b)
//	w2 = nand(a, w1)
//	w3 = nand(b, w1)
//	sum = nand(w2, w3)
//	carry = nand(w1, w1)
//
// Composite chips import other verified circuits by slug via a ChipResolver:
//
//	in a, b, cin
//	out sum, cout
//	s1, c1 = chip:half_adder_ref(a, b)
//	sum, c2 = chip:half_adder_ref(s1, cin)
//	cout = chip:or2_ref(c1, c2)
//
// Every circuit is cycle-checked with Kahn's topological sort, flattened to
// primitive NAND gates for uncheatable gate-count and critical-path depth
// scoring, bounded by strict resource caps, and rendered directly to gnoweb-safe
// SVG data URIs via gno.land/p/nt/svg/v0.
package nandloom

package nandloom

import (
	"strings"
	"testing"
)

func buildReferenceRegistry(t *testing.T) (map[string]*Circuit, map[string]*CompiledCircuit) {
	t.Helper()
	circuits := make(map[string]*Circuit)
	compiled := make(map[string]*CompiledCircuit)
	resolve := func(slug string) (*Circuit, bool) {
		c, ok := circuits[slug]
		return c, ok
	}

	challenges := make(map[string]ChallengeSpec)
	for _, ch := range DefaultChallenges() {
		challenges[ch.ID] = ch
	}

	for _, ref := range DefaultReferenceChips() {
		ast, err := Parse(ref.Netlist)
		if err != nil {
			t.Fatalf("parse ref %s failed: %v", ref.Slug, err)
		}
		cc, err := Compile(ast, resolve)
		if err != nil {
			t.Fatalf("compile ref %s failed: %v", ref.Slug, err)
		}
		ch, ok := challenges[ref.ChallengeID]
		if !ok {
			t.Fatalf("missing challenge %s for ref %s", ref.ChallengeID, ref.Slug)
		}
		vr := Verify(cc, ch)
		if !vr.Passed {
			t.Fatalf("verify ref %s failed: %s", ref.Slug, vr.ErrorMessage)
		}
		circuits[ref.Slug] = ast
		compiled[ref.Slug] = cc
	}
	return circuits, compiled
}

func TestDefaultReferencesAndCompositionMetrics(t *testing.T) {
	_, compiled := buildReferenceRegistry(t)

	// Verify exact flattened NAND counts & depths through 4 levels of composition.
	cases := []struct {
		slug  string
		nands int
		depth int
		imps  int
	}{
		{"not1_ref", 1, 1, 0},
		{"and2_ref", 2, 2, 1},
		{"or2_ref", 3, 2, 1},
		{"xor2_ref", 4, 3, 0},
		{"mux2_ref", 4, 3, 1},
		{"half_adder_ref", 6, 3, 2},
		{"full_adder_ref", 15, 7, 2},
		{"adder4_ref", 60, 19, 1},
	}

	for _, tc := range cases {
		cc, ok := compiled[tc.slug]
		if !ok {
			t.Fatalf("missing compiled ref %s", tc.slug)
		}
		if cc.NANDCount != tc.nands {
			t.Errorf("%s: NANDCount got %d, want %d", tc.slug, cc.NANDCount, tc.nands)
		}
		if cc.MaxDepth != tc.depth {
			t.Errorf("%s: MaxDepth got %d, want %d", tc.slug, cc.MaxDepth, tc.depth)
		}
		if len(cc.ImportedChips) != tc.imps {
			t.Errorf("%s: ImportedChips got %d (%v), want %d", tc.slug, len(cc.ImportedChips), cc.ImportedChips, tc.imps)
		}
	}
}

func TestOptimalDesignsBeatReferenceRecords(t *testing.T) {
	circuits, _ := buildReferenceRegistry(t)
	resolve := func(slug string) (*Circuit, bool) {
		c, ok := circuits[slug]
		return c, ok
	}
	challenges := make(map[string]ChallengeSpec)
	for _, ch := range DefaultChallenges() {
		challenges[ch.ID] = ch
	}

	// 5-NAND shared-gate Half Adder (beats 6-NAND reference!)
	haOptNetlist := `
# Optimal 5-NAND Half Adder sharing w1 = nand(a, b)
in a, b
out sum, carry
w1 = nand(a, b)
w2 = nand(a, w1)
w3 = nand(b, w1)
sum = nand(w2, w3)
carry = nand(w1, w1)
`
	haAST, err := Parse(haOptNetlist)
	if err != nil {
		t.Fatalf("parse haOpt: %v", err)
	}
	haCC, err := Compile(haAST, resolve)
	if err != nil {
		t.Fatalf("compile haOpt: %v", err)
	}
	if vr := Verify(haCC, challenges["half_adder"]); !vr.Passed {
		t.Fatalf("verify haOpt failed: %s", vr.ErrorMessage)
	}
	if haCC.NANDCount != 5 || haCC.MaxDepth != 3 {
		t.Fatalf("haOpt metrics got (%d, %d), want (5, 3)", haCC.NANDCount, haCC.MaxDepth)
	}
	circuits["half_adder_opt"] = haAST

	// 9-NAND optimal Full Adder (beats 15-NAND reference!)
	faOptNetlist := `
# Optimal 9-NAND Full Adder
in a, b, cin
out sum, cout
w1 = nand(a, b)
w2 = nand(a, w1)
w3 = nand(b, w1)
w4 = nand(w2, w3)
w5 = nand(w4, cin)
w6 = nand(w4, w5)
w7 = nand(cin, w5)
sum = nand(w6, w7)
cout = nand(w5, w1)
`
	faAST, err := Parse(faOptNetlist)
	if err != nil {
		t.Fatalf("parse faOpt: %v", err)
	}
	faCC, err := Compile(faAST, resolve)
	if err != nil {
		t.Fatalf("compile faOpt: %v", err)
	}
	if vr := Verify(faCC, challenges["full_adder"]); !vr.Passed {
		t.Fatalf("verify faOpt failed: %s", vr.ErrorMessage)
	}
	if faCC.NANDCount != 9 || faCC.MaxDepth != 6 {
		t.Fatalf("faOpt metrics got (%d, %d), want (9, 6)", faCC.NANDCount, faCC.MaxDepth)
	}
	circuits["full_adder_opt"] = faAST

	// 36-NAND optimal 4-Bit Ripple Carry Adder composing 4x full_adder_opt!
	a4OptNetlist := `
in a0, a1, a2, a3, b0, b1, b2, b3, cin
out s0, s1, s2, s3, cout
s0, c1 = chip:full_adder_opt(a0, b0, cin)
s1, c2 = chip:full_adder_opt(a1, b1, c1)
s2, c3 = chip:full_adder_opt(a2, b2, c2)
s3, cout = chip:full_adder_opt(a3, b3, c3)
`
	a4AST, err := Parse(a4OptNetlist)
	if err != nil {
		t.Fatalf("parse a4Opt: %v", err)
	}
	a4CC, err := Compile(a4AST, resolve)
	if err != nil {
		t.Fatalf("compile a4Opt: %v", err)
	}
	if vr := Verify(a4CC, challenges["adder4"]); !vr.Passed {
		t.Fatalf("verify a4Opt failed: %s", vr.ErrorMessage)
	}
	if a4CC.NANDCount != 36 || a4CC.MaxDepth != 12 {
		t.Fatalf("a4Opt metrics got (%d, %d), want (36, 12)", a4CC.NANDCount, a4CC.MaxDepth)
	}

	// Live spot check: 15 + 0 + 1 = 16 -> s=0000, cout=1 -> "00001"
	tr, err := EvalBits(a4CC, "111100001")
	if err != nil {
		t.Fatalf("EvalBits failed: %v", err)
	}
	if tr.OutputBits != "00001" {
		t.Fatalf("15+0+1 got %s, want 00001", tr.OutputBits)
	}
}

func TestAdversarialRejections(t *testing.T) {
	// 1. Combinational 2-node cycle
	cyc, err := Parse("in a\nout y\nx = nand(a, y)\ny = nand(x, a)")
	if err != nil {
		t.Fatalf("unexpected parse err: %v", err)
	}
	if _, err := Compile(cyc, nil); err == nil || !strings.Contains(err.Error(), "cycle") {
		t.Fatalf("expected cycle error, got: %v", err)
	}

	// 2. Self-cycle
	selfCyc, err := Parse("in a\nout y\ny = nand(y, a)")
	if err != nil {
		t.Fatalf("unexpected parse err: %v", err)
	}
	if _, err := Compile(selfCyc, nil); err == nil || !strings.Contains(err.Error(), "cycle") {
		t.Fatalf("expected self-cycle error, got: %v", err)
	}

	// 3. Recursive chip import cycle
	cA, _ := Parse("in a\nout y\ny = chip:chip_b(a)")
	cB, _ := Parse("in a\nout y\ny = chip:chip_a(a)")
	reg := map[string]*Circuit{"chip_a": cA, "chip_b": cB}
	if _, err := Compile(cA, func(s string) (*Circuit, bool) { c, ok := reg[s]; return c, ok }); err == nil || !strings.Contains(err.Error(), "cycle") {
		t.Fatalf("expected recursive chip cycle error, got: %v", err)
	}

	// 4. Flattened gate cap exhaustion (> 128 NANDs hidden via nested sub-chips)
	// Build a 16-NAND dummy chip, then call it 9 times = 144 NANDs > 128 cap.
	var sb strings.Builder
	sb.WriteString("in a\nout y\nw0 = nand(a, a)\n")
	for i := 1; i < 15; i++ {
		sb.WriteString("w")
		sb.WriteString(itoaSimple(i))
		sb.WriteString(" = nand(w")
		sb.WriteString(itoaSimple(i - 1))
		sb.WriteString(", a)\n")
	}
	sb.WriteString("y = nand(w14, a)\n")
	big16, err := Parse(sb.String())
	if err != nil {
		t.Fatalf("parse big16: %v", err)
	}
	bombSrc := `in a
out y
w1 = chip:big16(a)
w2 = chip:big16(w1)
w3 = chip:big16(w2)
w4 = chip:big16(w3)
w5 = chip:big16(w4)
w6 = chip:big16(w5)
w7 = chip:big16(w6)
w8 = chip:big16(w7)
y = chip:big16(w8)`
	bombAST, err := Parse(bombSrc)
	if err != nil {
		t.Fatalf("parse bomb: %v", err)
	}
	if _, err := Compile(bombAST, func(s string) (*Circuit, bool) {
		if s == "big16" {
			return big16, true
		}
		return nil, false
	}); err == nil || !strings.Contains(err.Error(), "128") {
		t.Fatalf("expected max 128 gate cap error, got: %v", err)
	}

	// 5. Parser rejects invalid syntax, duplicate assignment, non-ASCII, bad ops
	badInputs := []string{
		"",
		"in a\nout y\ny = xor(a, a)",                 // unsupported op
		"in a\nout y\nw = nand(a, a)\nw = nand(a,a)", // duplicate wire
		"in a\nout y\na = nand(a, a)\ny = buf(a)",    // assigning input
		"in a\nout y\ny = nand(a)",                   // arity mismatch
		"in a\nout y\ny = nand(a, a)\n\x00",          // control byte
		"in _bad\nout y\ny = nand(_bad, _bad)",       // leading underscore reserved
	}
	for i, src := range badInputs {
		if _, err := Parse(src); err == nil {
			t.Errorf("badInput[%d] unexpectedly parsed cleanly", i)
		}
	}

	// 6. Wrong truth table caught with exact counterexample
	badXOR, _ := Parse("in a, b\nout y\ny = nand(a, b)")
	badCC, _ := Compile(badXOR, nil)
	challenges := DefaultChallenges()
	vr := Verify(badCC, challenges[3]) // xor2
	if vr.Passed {
		t.Fatalf("expected NAND to fail XOR challenge")
	}
	if vr.FailInput != "00" || vr.FailExpected != "0" || vr.FailActual != "1" {
		t.Fatalf("unexpected counterexample: in=%s exp=%s act=%s", vr.FailInput, vr.FailExpected, vr.FailActual)
	}

	// 7. Zero-NAND buf/chip fan-out bomb must be stopped by MaxChipInstances / MaxFlatOps
	bufLeaf, _ := Parse("in a\nout y\nw1 = buf(a)\nw2 = buf(w1)\nw3 = buf(w2)\nw4 = buf(w3)\ny = buf(w4)")
	bufMid1, _ := Parse("in a\nout y\nt1 = chip:leaf(a)\nt2 = chip:leaf(t1)\nt3 = chip:leaf(t2)\nt4 = chip:leaf(t3)\nt5 = chip:leaf(t4)\ny = buf(t5)")
	bufMid2, _ := Parse("in a\nout y\nt1 = chip:mid1(a)\nt2 = chip:mid1(t1)\nt3 = chip:mid1(t2)\nt4 = chip:mid1(t3)\nt5 = chip:mid1(t4)\ny = buf(t5)")
	bufBomb, _ := Parse("in a\nout y\nt1 = chip:mid2(a)\nt2 = chip:mid2(t1)\nt3 = chip:mid2(t2)\nt4 = chip:mid2(t3)\nt5 = chip:mid2(t4)\ny = buf(t5)")
	bombReg := map[string]*Circuit{"leaf": bufLeaf, "mid1": bufMid1, "mid2": bufMid2}
	if _, err := Compile(bufBomb, func(s string) (*Circuit, bool) { c, ok := bombReg[s]; return c, ok }); err == nil {
		t.Fatalf("expected nested zero-NAND buf bomb to hit instance/op cap")
	}

	// 8. ExportGno safely mangles Go keywords used as wire identifiers
	kwAST, err := Parse("in if, map\nout return\nfor = nand(if, map)\nreturn = nand(for, for)")
	if err != nil {
		t.Fatalf("parse keyword circuit: %v", err)
	}
	kwCC, err := Compile(kwAST, nil)
	if err != nil {
		t.Fatalf("compile keyword circuit: %v", err)
	}
	kwGo := ExportGno("kw_test", kwCC)
	if !strings.Contains(kwGo, "func ChipKwTest(w_if, w_map bool) (w_return bool)") || !strings.Contains(kwGo, "w_for := !(w_if && w_map)") {
		t.Fatalf("ExportGno failed to mangle Go keywords:\n%s", kwGo)
	}
}

func TestSVGRenderingAndEscaping(t *testing.T) {
	_, compiled := buildReferenceRegistry(t)
	fa := compiled["full_adder_ref"]
	tr, err := EvalBits(fa, "111")
	if err != nil {
		t.Fatalf("eval full_adder_ref: %v", err)
	}
	if tr.OutputBits != "11" {
		t.Fatalf("1+1+1 got %s, want 11", tr.OutputBits)
	}

	rawSVG := RenderSchematicRawSVG(`Full <script>alert(1)</script> & Adder`, fa, tr)
	if !strings.HasPrefix(rawSVG, "<svg ") || !strings.HasSuffix(rawSVG, "</svg>") {
		t.Fatalf("invalid SVG wrapper")
	}
	if strings.Contains(rawSVG, "<script>") {
		t.Fatalf("SVG failed to escape <script> tag")
	}
	if !strings.Contains(rawSVG, "&lt;script&gt;") {
		t.Fatalf("expected escaped script text in SVG")
	}
	if !strings.Contains(rawSVG, "#10b981") {
		t.Fatalf("expected live HIGH wire highlight color in SVG")
	}
	if !strings.Contains(rawSVG, "IC · 6 NAND") {
		t.Fatalf("expected composite IC sub-chip badge in SVG")
	}

	mdImg := RenderSchematicSVG("Full Adder", fa, tr)
	if !strings.HasPrefix(mdImg, "![") || !strings.Contains(mdImg, "data:image/svg+xml;base64,") {
		t.Fatalf("unexpected Markdown SVG output: %s", mdImg[:60])
	}

	// Waveform rendering
	ch := DefaultChallenges()[6] // full_adder
	wfRaw := RenderWaveformRawSVG("full_adder_ref", fa, ch, 8)
	if !strings.HasPrefix(wfRaw, "<svg ") || !strings.Contains(wfRaw, "<polyline") {
		t.Fatalf("expected valid waveform SVG with polylines")
	}

	// Pure-Gno exporter
	exported := ExportGno("full_adder_ref", fa)
	if !strings.Contains(exported, "func ChipFullAdderRef(a, b, cin bool) (sum, cout bool)") {
		t.Fatalf("unexpected ExportGno signature:\n%s", exported)
	}
}

func itoaSimple(n int) string {
	if n == 0 {
		return "0"
	}
	var d []byte
	for n > 0 {
		d = append([]byte{byte('0' + n%10)}, d...)
		n /= 10
	}
	return string(d)
}

package nandloom

import (
	"errors"
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

// IsValidIdent reports whether s is a valid wire identifier:
// lowercase ASCII letter followed by lowercase letters, digits, or underscores,
// bounded by MaxIdentLen. Leading underscores are reserved for internal flattening.
func IsValidIdent(s string) bool {
	if len(s) == 0 || len(s) > MaxIdentLen {
		return false
	}
	c0 := s[0]
	if c0 < 'a' || c0 > 'z' {
		return false
	}
	for i := 1; i < len(s); i++ {
		c := s[i]
		ok := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_'
		if !ok {
			return false
		}
	}
	return true
}

// IsValidSlug reports whether s is a valid chip or challenge slug:
// lowercase ASCII letter followed by lowercase letters, digits, underscores, or hyphens.
func IsValidSlug(s string) bool {
	if len(s) == 0 || len(s) > MaxSlugLen {
		return false
	}
	c0 := s[0]
	if c0 < 'a' || c0 > 'z' {
		return false
	}
	for i := 1; i < len(s); i++ {
		c := s[i]
		ok := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_' || c == '-'
		if !ok {
			return false
		}
	}
	return true
}

func isReservedName(s string) bool {
	switch s {
	case "in", "out", "nand", "buf", "const0", "const1", "chip":
		return true
	default:
		return false
	}
}

func splitIdentList(raw string, lineNum int, kind string) ([]string, error) {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		return nil, errors.New(ufmt.Sprintf("line %d: empty %s list", lineNum, kind))
	}
	parts := strings.Split(trimmed, ",")
	out := make([]string, 0, len(parts))
	for i := 0; i < len(parts); i++ {
		tok := strings.TrimSpace(parts[i])
		if !IsValidIdent(tok) || isReservedName(tok) {
			return nil, errors.New(ufmt.Sprintf("line %d: invalid %s identifier %q", lineNum, kind, tok))
		}
		out = append(out, tok)
	}
	return out, nil
}

// Parse validates and parses a Nandloom netlist into an immutable Circuit AST.
func Parse(src string) (*Circuit, error) {
	if len(src) == 0 {
		return nil, errors.New("netlist is empty")
	}
	if len(src) > MaxNetlistBytes {
		return nil, errors.New(ufmt.Sprintf("netlist exceeds %d bytes", MaxNetlistBytes))
	}

	// Reject non-printable ASCII control bytes other than tab, LF, CR.
	for i := 0; i < len(src); i++ {
		b := src[i]
		if b < 0x20 && b != '\n' && b != '\r' && b != '\t' {
			return nil, errors.New("netlist contains disallowed control characters")
		}
		if b >= 0x7f {
			return nil, errors.New("netlist must be plain ASCII")
		}
	}

	norm := strings.ReplaceAll(src, "\r\n", "\n")
	norm = strings.ReplaceAll(norm, "\r", "\n")
	lines := strings.Split(norm, "\n")
	if len(lines) > MaxLines {
		return nil, errors.New(ufmt.Sprintf("netlist exceeds %d lines", MaxLines))
	}

	c := &Circuit{Raw: strings.TrimSpace(norm)}
	hasIn := false
	hasOut := false
	inputSet := make(map[string]bool)
	outputSet := make(map[string]bool)
	assigned := make(map[string]int) // wire -> line number

	for idx := 0; idx < len(lines); idx++ {
		lineNum := idx + 1
		line := lines[idx]
		if hash := strings.Index(line, "#"); hash >= 0 {
			line = line[:hash]
		}
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}

		// Header: "in a, b"
		if strings.HasPrefix(line, "in ") || strings.HasPrefix(line, "in\t") {
			if hasIn {
				return nil, errors.New(ufmt.Sprintf("line %d: duplicate 'in' declaration", lineNum))
			}
			if len(c.Statements) > 0 {
				return nil, errors.New(ufmt.Sprintf("line %d: 'in' must appear before statements", lineNum))
			}
			names, err := splitIdentList(line[2:], lineNum, "input")
			if err != nil {
				return nil, err
			}
			if len(names) > MaxInputs {
				return nil, errors.New(ufmt.Sprintf("line %d: too many inputs (%d > %d)", lineNum, len(names), MaxInputs))
			}
			for i := 0; i < len(names); i++ {
				if inputSet[names[i]] {
					return nil, errors.New(ufmt.Sprintf("line %d: duplicate input %q", lineNum, names[i]))
				}
				inputSet[names[i]] = true
			}
			c.Inputs = names
			hasIn = true
			continue
		}

		// Header: "out sum, carry"
		if strings.HasPrefix(line, "out ") || strings.HasPrefix(line, "out\t") {
			if hasOut {
				return nil, errors.New(ufmt.Sprintf("line %d: duplicate 'out' declaration", lineNum))
			}
			if len(c.Statements) > 0 {
				return nil, errors.New(ufmt.Sprintf("line %d: 'out' must appear before statements", lineNum))
			}
			names, err := splitIdentList(line[3:], lineNum, "output")
			if err != nil {
				return nil, err
			}
			if len(names) > MaxOutputs {
				return nil, errors.New(ufmt.Sprintf("line %d: too many outputs (%d > %d)", lineNum, len(names), MaxOutputs))
			}
			for i := 0; i < len(names); i++ {
				if outputSet[names[i]] {
					return nil, errors.New(ufmt.Sprintf("line %d: duplicate output %q", lineNum, names[i]))
				}
				if inputSet[names[i]] {
					return nil, errors.New(ufmt.Sprintf("line %d: output %q cannot share name with an input", lineNum, names[i]))
				}
				outputSet[names[i]] = true
			}
			c.Outputs = names
			hasOut = true
			continue
		}

		if !hasIn || !hasOut {
			return nil, errors.New(ufmt.Sprintf("line %d: declare 'in' and 'out' before statements", lineNum))
		}
		if len(c.Statements) >= MaxStatements {
			return nil, errors.New(ufmt.Sprintf("line %d: exceeds maximum %d statements", lineNum, MaxStatements))
		}

		// Statement: lhs = op(args)
		eq := strings.Index(line, "=")
		if eq <= 0 || eq == len(line)-1 {
			return nil, errors.New(ufmt.Sprintf("line %d: expected 'wire = op(args)'", lineNum))
		}
		lhsRaw := strings.TrimSpace(line[:eq])
		rhsRaw := strings.TrimSpace(line[eq+1:])

		lhs, err := splitIdentList(lhsRaw, lineNum, "wire")
		if err != nil {
			return nil, err
		}
		for i := 0; i < len(lhs); i++ {
			w := lhs[i]
			if inputSet[w] {
				return nil, errors.New(ufmt.Sprintf("line %d: cannot assign to input wire %q", lineNum, w))
			}
			if prev, exists := assigned[w]; exists {
				return nil, errors.New(ufmt.Sprintf("line %d: wire %q already assigned on line %d", lineNum, w, prev))
			}
			assigned[w] = lineNum
		}

		lp := strings.Index(rhsRaw, "(")
		rp := strings.LastIndex(rhsRaw, ")")
		if lp <= 0 || rp != len(rhsRaw)-1 || rp < lp+1 {
			return nil, errors.New(ufmt.Sprintf("line %d: malformed call %q", lineNum, rhsRaw))
		}
		opName := strings.TrimSpace(rhsRaw[:lp])
		argsRaw := strings.TrimSpace(rhsRaw[lp+1 : rp])

		var args []string
		if argsRaw != "" {
			args, err = splitIdentList(argsRaw, lineNum, "argument")
			if err != nil {
				return nil, err
			}
		}

		stmt := Statement{
			Line:    lineNum,
			Outputs: lhs,
			Args:    args,
		}

		if opName == "nand" {
			if len(lhs) != 1 {
				return nil, errors.New(ufmt.Sprintf("line %d: nand produces exactly 1 output", lineNum))
			}
			if len(args) != 2 {
				return nil, errors.New(ufmt.Sprintf("line %d: nand requires exactly 2 arguments", lineNum))
			}
			stmt.Op = OpNAND
		} else if opName == "buf" {
			if len(lhs) != 1 {
				return nil, errors.New(ufmt.Sprintf("line %d: buf produces exactly 1 output", lineNum))
			}
			if len(args) != 1 {
				return nil, errors.New(ufmt.Sprintf("line %d: buf requires exactly 1 argument", lineNum))
			}
			stmt.Op = OpBuf
		} else if opName == "const0" {
			if len(lhs) != 1 || len(args) != 0 {
				return nil, errors.New(ufmt.Sprintf("line %d: const0 takes 0 arguments and produces 1 output", lineNum))
			}
			stmt.Op = OpConst0
		} else if opName == "const1" {
			if len(lhs) != 1 || len(args) != 0 {
				return nil, errors.New(ufmt.Sprintf("line %d: const1 takes 0 arguments and produces 1 output", lineNum))
			}
			stmt.Op = OpConst1
		} else if strings.HasPrefix(opName, "chip:") {
			slug := strings.TrimSpace(opName[5:])
			if !IsValidSlug(slug) {
				return nil, errors.New(ufmt.Sprintf("line %d: invalid chip slug %q", lineNum, slug))
			}
			if len(args) == 0 {
				return nil, errors.New(ufmt.Sprintf("line %d: chip:%s requires at least 1 input argument", lineNum, slug))
			}
			stmt.Op = OpChip
			stmt.ChipSlug = slug
		} else {
			return nil, errors.New(ufmt.Sprintf("line %d: unsupported operation %q (allowed: nand, buf, const0, const1, chip:<slug>)", lineNum, opName))
		}

		c.Statements = append(c.Statements, stmt)
	}

	if !hasIn {
		return nil, errors.New("missing 'in' declaration")
	}
	if !hasOut {
		return nil, errors.New("missing 'out' declaration")
	}
	if len(c.Statements) == 0 {
		return nil, errors.New("netlist has no gate or chip statements")
	}

	// Ensure every declared output is produced by a statement.
	for i := 0; i < len(c.Outputs); i++ {
		outW := c.Outputs[i]
		if _, ok := assigned[outW]; !ok {
			return nil, errors.New(ufmt.Sprintf("declared output %q is never assigned", outW))
		}
	}

	return c, nil
}

package nandloom

import (
	"errors"
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

// ParseBits parses a '0'/'1' bitstring of exact expectedLen.
func ParseBits(bits string, expectedLen int) ([]bool, error) {
	if len(bits) != expectedLen {
		return nil, errors.New(ufmt.Sprintf("expected %d input bits, got %d", expectedLen, len(bits)))
	}
	out := make([]bool, expectedLen)
	for i := 0; i < expectedLen; i++ {
		if bits[i] == '1' {
			out[i] = true
		} else if bits[i] == '0' {
			out[i] = false
		} else {
			return nil, errors.New(ufmt.Sprintf("invalid bit character %q at index %d (use 0 or 1)", string(bits[i]), i))
		}
	}
	return out, nil
}

// FormatBits converts a boolean slice into a '0'/'1' bitstring.
func FormatBits(vals []bool) string {
	var b strings.Builder
	for i := 0; i < len(vals); i++ {
		if vals[i] {
			b.WriteByte('1')
		} else {
			b.WriteByte('0')
		}
	}
	return b.String()
}

// Eval runs a single deterministic levelized pass over a CompiledCircuit.
func Eval(cc *CompiledCircuit, inputs []bool) (*Trace, error) {
	if cc == nil || cc.AST == nil {
		return nil, errors.New("nil compiled circuit")
	}
	if len(inputs) != len(cc.AST.Inputs) {
		return nil, errors.New(ufmt.Sprintf("expected %d inputs, got %d", len(cc.AST.Inputs), len(inputs)))
	}

	wires := make(map[string]bool, len(cc.AST.Inputs)+len(cc.FlatGates))
	inCopy := make([]bool, len(inputs))
	for i := 0; i < len(cc.AST.Inputs); i++ {
		wires[cc.AST.Inputs[i]] = inputs[i]
		inCopy[i] = inputs[i]
	}

	for i := 0; i < len(cc.FlatGates); i++ {
		g := cc.FlatGates[i]
		switch g.Op {
		case OpConst0:
			wires[g.Out] = false
		case OpConst1:
			wires[g.Out] = true
		case OpBuf:
			wires[g.Out] = wires[g.A]
		case OpNAND:
			wires[g.Out] = !(wires[g.A] && wires[g.B])
		}
	}

	outVals := make([]bool, len(cc.AST.Outputs))
	for i := 0; i < len(cc.AST.Outputs); i++ {
		outVals[i] = wires[cc.AST.Outputs[i]]
	}

	// Keep only top-level visible wires in Trace.WireValues so callers/renderers
	// stay clean and small.
	visible := make(map[string]bool, len(cc.AST.Inputs)+len(cc.AST.Statements)*2)
	for i := 0; i < len(cc.AST.Inputs); i++ {
		name := cc.AST.Inputs[i]
		visible[name] = wires[name]
	}
	for i := 0; i < len(cc.AST.Statements); i++ {
		st := cc.AST.Statements[i]
		for j := 0; j < len(st.Outputs); j++ {
			name := st.Outputs[j]
			visible[name] = wires[name]
		}
	}

	return &Trace{
		InputBits:  FormatBits(inCopy),
		OutputBits: FormatBits(outVals),
		WireValues: visible,
		OutputVals: outVals,
		InputVals:  inCopy,
	}, nil
}

// EvalBits evaluates a compiled circuit using a '0'/'1' bitstring.
func EvalBits(cc *CompiledCircuit, bits string) (*Trace, error) {
	if cc == nil || cc.AST == nil {
		return nil, errors.New("nil compiled circuit")
	}
	vals, err := ParseBits(bits, len(cc.AST.Inputs))
	if err != nil {
		return nil, err
	}
	return Eval(cc, vals)
}

// Verify checks pin signatures and runs all test vectors in spec against cc.
func Verify(cc *CompiledCircuit, spec ChallengeSpec) VerifyResult {
	res := VerifyResult{
		TotalVectors: len(spec.Vectors),
		FailedIndex:  -1,
	}
	if cc == nil || cc.AST == nil {
		res.ErrorMessage = "nil compiled circuit"
		return res
	}
	res.NANDCount = cc.NANDCount
	res.Depth = cc.MaxDepth

	if len(cc.AST.Inputs) != len(spec.Inputs) {
		res.ErrorMessage = ufmt.Sprintf("input pin count mismatch: challenge requires [%s], got [%s]",
			strings.Join(spec.Inputs, ", "), strings.Join(cc.AST.Inputs, ", "))
		return res
	}
	for i := 0; i < len(spec.Inputs); i++ {
		if cc.AST.Inputs[i] != spec.Inputs[i] {
			res.ErrorMessage = ufmt.Sprintf("input pin %d mismatch: expected %q, got %q", i, spec.Inputs[i], cc.AST.Inputs[i])
			return res
		}
	}
	if len(cc.AST.Outputs) != len(spec.Outputs) {
		res.ErrorMessage = ufmt.Sprintf("output pin count mismatch: challenge requires [%s], got [%s]",
			strings.Join(spec.Outputs, ", "), strings.Join(cc.AST.Outputs, ", "))
		return res
	}
	for i := 0; i < len(spec.Outputs); i++ {
		if cc.AST.Outputs[i] != spec.Outputs[i] {
			res.ErrorMessage = ufmt.Sprintf("output pin %d mismatch: expected %q, got %q", i, spec.Outputs[i], cc.AST.Outputs[i])
			return res
		}
	}

	limit := len(spec.Vectors)
	if limit > MaxTestVectors {
		limit = MaxTestVectors
	}
	res.TotalVectors = limit

	for i := 0; i < limit; i++ {
		vec := spec.Vectors[i]
		tr, err := Eval(cc, vec.In)
		if err != nil {
			res.FailedIndex = i
			res.ErrorMessage = err.Error()
			return res
		}
		expStr := FormatBits(vec.Out)
		if tr.OutputBits != expStr {
			res.FailedIndex = i
			res.FailLabel = vec.Label
			res.FailInput = FormatBits(vec.In)
			res.FailExpected = expStr
			res.FailActual = tr.OutputBits
			res.ErrorMessage = ufmt.Sprintf("vector #%d (%s) failed: in=%s expected=%s actual=%s",
				i+1, vec.Label, res.FailInput, expStr, tr.OutputBits)
			return res
		}
		res.PassedVectors++
	}

	res.Passed = true
	return res
}

// ExportGno emits a standalone, zero-dependency pure-Gno function equivalent to
// the verified compiled circuit so any realm can copy or embed it directly.
func ExportGno(slug string, cc *CompiledCircuit) string {
	if cc == nil || cc.AST == nil {
		return ""
	}
	fnName := toExportedGoName(slug)
	// Map every wire name to a Go-safe identifier so Go keywords (if, map, func,
	// return, etc.) never emit uncompilable exported code.
	safeMap := make(map[string]string)
	usedSafe := make(map[string]bool)
	mapIdent := func(raw string) string {
		if v, ok := safeMap[raw]; ok {
			return v
		}
		cand := raw
		if isGoKeywordOrPredeclared(cand) {
			cand = "w_" + cand
		}
		for usedSafe[cand] {
			cand = cand + "_"
		}
		safeMap[raw] = cand
		usedSafe[cand] = true
		return cand
	}

	safeInputs := make([]string, len(cc.AST.Inputs))
	for i := 0; i < len(cc.AST.Inputs); i++ {
		safeInputs[i] = mapIdent(cc.AST.Inputs[i])
	}
	safeOutputs := make([]string, len(cc.AST.Outputs))
	for i := 0; i < len(cc.AST.Outputs); i++ {
		safeOutputs[i] = mapIdent(cc.AST.Outputs[i])
	}

	var b strings.Builder
	b.WriteString(ufmt.Sprintf("// Generated by Nandloom (%d NANDs, depth %d)\n", cc.NANDCount, cc.MaxDepth))
	b.WriteString("func " + fnName + "(")
	b.WriteString(strings.Join(safeInputs, ", "))
	b.WriteString(" bool) (")
	b.WriteString(strings.Join(safeOutputs, ", "))
	b.WriteString(" bool) {\n")

	declared := make(map[string]bool)
	for i := 0; i < len(safeInputs); i++ {
		declared[safeInputs[i]] = true
	}
	for i := 0; i < len(safeOutputs); i++ {
		declared[safeOutputs[i]] = true
	}

	for i := 0; i < len(cc.FlatGates); i++ {
		g := cc.FlatGates[i]
		outID := mapIdent(g.Out)
		opAssign := ":="
		if declared[outID] {
			opAssign = "="
		} else {
			declared[outID] = true
		}
		switch g.Op {
		case OpConst0:
			b.WriteString(ufmt.Sprintf("\t%s %s false\n", outID, opAssign))
		case OpConst1:
			b.WriteString(ufmt.Sprintf("\t%s %s true\n", outID, opAssign))
		case OpBuf:
			b.WriteString(ufmt.Sprintf("\t%s %s %s\n", outID, opAssign, mapIdent(g.A)))
		case OpNAND:
			b.WriteString(ufmt.Sprintf("\t%s %s !(%s && %s)\n", outID, opAssign, mapIdent(g.A), mapIdent(g.B)))
		}
	}
	b.WriteString("\treturn\n}\n")
	return b.String()
}

func isGoKeywordOrPredeclared(s string) bool {
	switch s {
	case "break", "default", "func", "interface", "select",
		"case", "defer", "go", "map", "struct",
		"chan", "else", "goto", "package", "switch",
		"const", "fallthrough", "if", "range", "type",
		"continue", "for", "import", "return", "var",
		"bool", "true", "false", "nil", "iota":
		return true
	default:
		return false
	}
}

func toExportedGoName(slug string) string {
	parts := strings.FieldsFunc(slug, func(r rune) bool {
		return r == '_' || r == '-'
	})
	var b strings.Builder
	b.WriteString("Chip")
	for i := 0; i < len(parts); i++ {
		p := parts[i]
		if len(p) == 0 {
			continue
		}
		first := p[0]
		if first >= 'a' && first <= 'z' {
			first = first - 'a' + 'A'
		}
		b.WriteByte(first)
		b.WriteString(p[1:])
	}
	return b.String()
}

package nandloom

import (
	"encoding/base64"
	"strings"

	"gno.land/p/nt/svg/v0"
	"gno.land/p/nt/ufmt/v0"
)

func xmlEscape(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, `"`, "&quot;")
	s = strings.ReplaceAll(s, "'", "&#39;")
	return s
}

type point struct {
	x int
	y int
}

// RenderSchematicRawSVG produces a deterministic blueprint-style SVG schematic
// of cc evaluated on trace (trace may be nil for static unpowered rendering).
func RenderSchematicRawSVG(title string, cc *CompiledCircuit, trace *Trace) string {
	if cc == nil || cc.AST == nil {
		return ""
	}
	c := cc.AST
	numCols := cc.MaxCol + 2 // col 0 = inputs, 1..MaxCol = statements, MaxCol+1 = outputs

	// Group top-level statements by visual column depth.
	cols := make([][]int, cc.MaxCol+1)
	maxRows := len(c.Inputs)
	if len(c.Outputs) > maxRows {
		maxRows = len(c.Outputs)
	}
	for oi := 0; oi < len(cc.TopOrder); oi++ {
		si := cc.TopOrder[oi]
		col := cc.StmtDepth[si]
		cols[col] = append(cols[col], si)
		if len(cols[col]) > maxRows {
			maxRows = len(cols[col])
		}
	}

	colWidth := 168
	leftPad := 24
	topHeader := 54
	rowPitch := 68
	if maxRows > 6 {
		rowPitch = 56
	}
	width := leftPad*2 + numCols*colWidth
	if width < 640 {
		width = 640
	}
	height := topHeader + maxRows*rowPitch + 34
	if height < 240 {
		height = 240
	}

	canvas := svg.NewCanvas(width, height).WithViewBox(0, 0, width, height)
	canvas.AddStyle("text", "font-family:ui-monospace,SFMono-Regular,Menlo,monospace")

	// Blueprint background & subtle vertical column guides.
	bg := svg.NewRectangle(0, 0, width, height, "#0b1120")
	bg.RX = 10
	bg.RY = 10
	canvas.Append(bg)

	// Header strip
	hdr := svg.NewRectangle(0, 0, width, 40, "#111c33")
	hdr.RX = 10
	hdr.RY = 10
	canvas.Append(hdr)
	hdrBottom := svg.NewRectangle(0, 30, width, 10, "#111c33")
	canvas.Append(hdrBottom)
	hdrLine := svg.NewPath(ufmt.Sprintf("M 0 40 L %d 40", width), "none")
	hdrLine.Attr.Stroke = "#1e293b"
	hdrLine.Attr.StrokeWidth = "1"
	canvas.Append(hdrLine)

	titleTxt := svg.NewText(18, 25, xmlEscape(title), "#f8fafc")
	titleTxt.Attr.Style = "font-size:13px;font-weight:700"
	canvas.Append(titleTxt)

	metaStr := ufmt.Sprintf("NANDs: %d  |  Depth: %d  |  Modules: %d", cc.NANDCount, cc.MaxDepth, cc.ModuleCount)
	if trace != nil {
		metaStr = ufmt.Sprintf("%s  |  %s -> %s", metaStr, trace.InputBits, trace.OutputBits)
	}
	metaTxt := svg.NewText(width-18, 25, xmlEscape(metaStr), "#94a3b8")
	metaTxt.Attr.Style = "font-size:11px;text-anchor:end"
	canvas.Append(metaTxt)

	// Column helper x-centers.
	colCenterX := func(col int) int {
		if numCols <= 1 {
			return width / 2
		}
		usable := width - leftPad*2 - 110
		return leftPad + 55 + (col*usable)/(numCols-1)
	}
	rowCenterY := func(idx, count int) int {
		avail := height - topHeader - 24
		return topHeader + (avail*(idx+1))/(count+1)
	}

	// Subtle blueprint grid lines.
	for gx := 40; gx < width; gx += 40 {
		gl := svg.NewPath(ufmt.Sprintf("M %d 41 L %d %d", gx, gx, height-1), "none")
		gl.Attr.Stroke = "#162036"
		gl.Attr.StrokeWidth = "1"
		canvas.Append(gl)
	}

	// Track output anchor position for every visible wire so wires route cleanly.
	wireSrc := make(map[string]point)

	// Pre-compute input pin positions (column 0).
	inPos := make([]point, len(c.Inputs))
	for i := 0; i < len(c.Inputs); i++ {
		cx := colCenterX(0)
		cy := rowCenterY(i, len(c.Inputs))
		inPos[i] = point{x: cx, y: cy}
		wireSrc[c.Inputs[i]] = point{x: cx + 44, y: cy}
	}

	// Pre-compute statement box positions (columns 1..MaxCol).
	stmtPos := make([]point, len(c.Statements))
	stmtBoxW := make([]int, len(c.Statements))
	stmtBoxH := make([]int, len(c.Statements))
	for col := 1; col <= cc.MaxCol; col++ {
		list := cols[col]
		cx := colCenterX(col)
		for idx := 0; idx < len(list); idx++ {
			si := list[idx]
			st := c.Statements[si]
			cy := rowCenterY(idx, len(list))
			stmtPos[si] = point{x: cx, y: cy}
			bw := 84
			bh := 36
			if st.Op == OpChip {
				bw = 114
				bh = 44
				if len(st.Outputs) > 2 || len(st.Args) > 3 {
					bh = 52
				}
			}
			stmtBoxW[si] = bw
			stmtBoxH[si] = bh
			// Register output port anchor for each output wire of this statement.
			outCount := len(st.Outputs)
			for oi := 0; oi < outCount; oi++ {
				oy := cy
				if outCount > 1 {
					oy = cy - bh/2 + ((oi+1)*bh)/(outCount+1)
				}
				anchorX := cx + bw/2
				if st.Op == OpNAND {
					anchorX = cx + bw/2 + 8 // after inversion bubble
				}
				wireSrc[st.Outputs[oi]] = point{x: anchorX, y: oy}
			}
		}
	}

	// Pre-compute output pin positions (last column).
	outPos := make([]point, len(c.Outputs))
	for i := 0; i < len(c.Outputs); i++ {
		cx := colCenterX(numCols - 1)
		cy := rowCenterY(i, len(c.Outputs))
		outPos[i] = point{x: cx, y: cy}
	}

	wireColor := func(w string) (string, string) {
		if trace == nil {
			return "#64748b", "1.8"
		}
		if trace.WireValues[w] {
			return "#10b981", "2.6"
		}
		return "#475569", "1.5"
	}

	// Helper to draw clean cubic-bezier signal traces from p1 -> p2.
	drawWire := func(w string, p1, p2 point) {
		col, sw := wireColor(w)
		midX := (p1.x + p2.x) / 2
		d := ufmt.Sprintf("M %d %d C %d %d, %d %d, %d %d", p1.x, p1.y, midX, p1.y, midX, p2.y, p2.x, p2.y)
		p := svg.NewPath(d, "none")
		p.Attr.Stroke = col
		p.Attr.StrokeWidth = sw
		canvas.Append(p)
	}

	// 1. Draw wires first so nodes sit cleanly on top.
	for oi := 0; oi < len(cc.TopOrder); oi++ {
		si := cc.TopOrder[oi]
		st := c.Statements[si]
		cx := stmtPos[si].x
		cy := stmtPos[si].y
		bw := stmtBoxW[si]
		bh := stmtBoxH[si]
		argCount := len(st.Args)
		for ai := 0; ai < argCount; ai++ {
			src, ok := wireSrc[st.Args[ai]]
			if !ok {
				continue
			}
			iy := cy
			if argCount > 1 {
				iy = cy - bh/2 + ((ai+1)*bh)/(argCount+1)
			}
			dst := point{x: cx - bw/2, y: iy}
			drawWire(st.Args[ai], src, dst)
		}
	}
	// Wires to primary output pads.
	for i := 0; i < len(c.Outputs); i++ {
		outName := c.Outputs[i]
		src, ok := wireSrc[outName]
		if !ok {
			continue
		}
		dst := point{x: outPos[i].x - 44, y: outPos[i].y}
		drawWire(outName, src, dst)
	}

	// 2. Draw primary input pins (column 0).
	for i := 0; i < len(c.Inputs); i++ {
		name := c.Inputs[i]
		p := inPos[i]
		high := trace != nil && trace.WireValues[name]
		border := "#475569"
		pillFill := "#1e293b"
		bitLabel := "-"
		bitColor := "#94a3b8"
		if trace != nil {
			if high {
				border = "#10b981"
				pillFill = "#064e3b"
				bitLabel = "1"
				bitColor = "#6ee7b7"
			} else {
				bitLabel = "0"
				bitColor = "#94a3b8"
			}
		}
		box := svg.NewRectangle(p.x-44, p.y-15, 88, 30, pillFill)
		box.RX = 6
		box.RY = 6
		box.Attr.Stroke = border
		box.Attr.StrokeWidth = "1.6"
		canvas.Append(box)

		lbl := svg.NewText(p.x-34, p.y+4, xmlEscape(name), "#e2e8f0")
		lbl.Attr.Style = "font-size:11px;font-weight:600"
		canvas.Append(lbl)

		val := svg.NewText(p.x+34, p.y+4, bitLabel, bitColor)
		val.Attr.Style = "font-size:12px;font-weight:700;text-anchor:end"
		canvas.Append(val)
	}

	// 3. Draw logic gates and composite IC chips.
	for oi := 0; oi < len(cc.TopOrder); oi++ {
		si := cc.TopOrder[oi]
		st := c.Statements[si]
		cx := stmtPos[si].x
		cy := stmtPos[si].y
		bw := stmtBoxW[si]
		bh := stmtBoxH[si]

		if st.Op == OpNAND {
			high := trace != nil && trace.WireValues[st.Outputs[0]]
			fill := "#172554"
			stroke := "#3b82f6"
			if high {
				fill = "#064e3b"
				stroke = "#10b981"
			}
			// Classic D-shaped NAND gate body.
			x0 := cx - bw/2
			y0 := cy - bh/2
			xMid := cx + bw/2 - bh/2
			r := bh / 2
			d := ufmt.Sprintf("M %d %d L %d %d A %d %d 0 0 1 %d %d L %d %d Z",
				x0, y0, xMid, y0, r, r, xMid, y0+bh, x0, y0+bh)
			body := svg.NewPath(d, fill)
			body.Attr.Stroke = stroke
			body.Attr.StrokeWidth = "1.8"
			canvas.Append(body)

			// Inversion bubble.
			bub := svg.NewCircle(cx+bw/2+4, cy, 4, fill)
			bub.Attr.Stroke = stroke
			bub.Attr.StrokeWidth = "1.8"
			canvas.Append(bub)

			glbl := svg.NewText(cx-4, cy-1, "NAND", "#e2e8f0")
			glbl.Attr.Style = "font-size:10px;font-weight:700;text-anchor:middle"
			canvas.Append(glbl)

			wlbl := svg.NewText(cx-4, cy+11, xmlEscape(st.Outputs[0]), "#94a3b8")
			wlbl.Attr.Style = "font-size:9px;text-anchor:middle"
			canvas.Append(wlbl)
		} else if st.Op == OpChip {
			// Composite imported IC chip package in warm amber/gold.
			anyHigh := false
			if trace != nil {
				for k := 0; k < len(st.Outputs); k++ {
					if trace.WireValues[st.Outputs[k]] {
						anyHigh = true
					}
				}
			}
			fill := "#1c1917"
			stroke := "#f59e0b"
			if anyHigh {
				fill = "#292014"
				stroke = "#fbbf24"
			}
			box := svg.NewRectangle(cx-bw/2, cy-bh/2, bw, bh, fill)
			box.RX = 6
			box.RY = 6
			box.Attr.Stroke = stroke
			box.Attr.StrokeWidth = "2"
			canvas.Append(box)

			// IC notch accent at top center.
			notch := svg.NewCircle(cx, cy-bh/2, 3, "#0b1120")
			notch.Attr.Stroke = stroke
			notch.Attr.StrokeWidth = "1.4"
			canvas.Append(notch)

			chipLabel := st.ChipSlug
			if len(chipLabel) > 14 {
				chipLabel = chipLabel[:13] + "."
			}
			t1 := svg.NewText(cx, cy-2, xmlEscape(chipLabel), "#fef3c7")
			t1.Attr.Style = "font-size:10px;font-weight:700;text-anchor:middle"
			canvas.Append(t1)

			t2 := svg.NewText(cx, cy+12, ufmt.Sprintf("IC · %d NAND", cc.StmtNANDs[si]), "#f59e0b")
			t2.Attr.Style = "font-size:9px;text-anchor:middle"
			canvas.Append(t2)
		} else {
			// OpBuf / OpConst0 / OpConst1 compact block.
			box := svg.NewRectangle(cx-bw/2, cy-bh/2, bw, bh, "#1e293b")
			box.RX = 6
			box.RY = 6
			box.Attr.Stroke = "#64748b"
			box.Attr.StrokeWidth = "1.5"
			canvas.Append(box)

			t1 := svg.NewText(cx, cy+4, xmlEscape(st.Op.String()+" -> "+st.Outputs[0]), "#cbd5e1")
			t1.Attr.Style = "font-size:9px;text-anchor:middle"
			canvas.Append(t1)
		}
	}

	// 4. Draw primary output LED pads (last column).
	for i := 0; i < len(c.Outputs); i++ {
		name := c.Outputs[i]
		p := outPos[i]
		high := trace != nil && trace.WireValues[name]
		border := "#475569"
		fill := "#1e293b"
		ledFill := "#334155"
		bitLabel := "-"
		if trace != nil {
			if high {
				border = "#10b981"
				fill = "#064e3b"
				ledFill = "#10b981"
				bitLabel = "1"
			} else {
				ledFill = "#475569"
				bitLabel = "0"
			}
		}
		box := svg.NewRectangle(p.x-44, p.y-15, 88, 30, fill)
		box.RX = 15
		box.RY = 15
		box.Attr.Stroke = border
		box.Attr.StrokeWidth = "1.8"
		canvas.Append(box)

		led := svg.NewCircle(p.x-28, p.y, 5, ledFill)
		canvas.Append(led)

		lbl := svg.NewText(p.x-16, p.y+4, xmlEscape(name), "#f8fafc")
		lbl.Attr.Style = "font-size:11px;font-weight:600"
		canvas.Append(lbl)

		val := svg.NewText(p.x+34, p.y+4, bitLabel, "#f8fafc")
		val.Attr.Style = "font-size:12px;font-weight:700;text-anchor:end"
		canvas.Append(val)
	}

	return canvas.String()
}

// RenderSchematicSVG returns a gnoweb-safe Markdown data:image/svg+xml image.
func RenderSchematicSVG(title string, cc *CompiledCircuit, trace *Trace) string {
	raw := RenderSchematicRawSVG(title, cc, trace)
	if raw == "" {
		return ""
	}
	return wrapSVGMarkdown("Nandloom schematic: "+title, raw)
}

// RenderWaveformRawSVG renders an oscilloscope-style digital timing diagram
// across up to maxSamples test vectors from spec.
func RenderWaveformRawSVG(title string, cc *CompiledCircuit, spec ChallengeSpec, maxSamples int) string {
	if cc == nil || cc.AST == nil || len(spec.Vectors) == 0 {
		return ""
	}
	samples := len(spec.Vectors)
	if maxSamples > 0 && samples > maxSamples {
		samples = maxSamples
	}

	// Build signal channels: all inputs + all outputs.
	nIn := len(cc.AST.Inputs)
	nOut := len(cc.AST.Outputs)
	totalCh := nIn + nOut
	if totalCh == 0 {
		return ""
	}

	// Evaluate each sample vector.
	actualOut := make([][]bool, samples)
	vecPass := make([]bool, samples)
	for s := 0; s < samples; s++ {
		tr, err := Eval(cc, spec.Vectors[s].In)
		if err != nil {
			actualOut[s] = make([]bool, nOut)
			vecPass[s] = false
			continue
		}
		actualOut[s] = tr.OutputVals
		vecPass[s] = tr.OutputBits == FormatBits(spec.Vectors[s].Out)
	}

	labelW := 96
	slotW := 66
	if samples > 8 {
		slotW = 54
	}
	rightPad := 20
	headerH := 42
	chH := 30
	width := labelW + samples*slotW + rightPad
	if width < 560 {
		width = 560
		slotW = (width - labelW - rightPad) / samples
	}
	height := headerH + totalCh*chH + 26

	canvas := svg.NewCanvas(width, height).WithViewBox(0, 0, width, height)
	canvas.AddStyle("text", "font-family:ui-monospace,SFMono-Regular,Menlo,monospace")

	bg := svg.NewRectangle(0, 0, width, height, "#0b1120")
	bg.RX = 10
	bg.RY = 10
	canvas.Append(bg)

	hdr := svg.NewRectangle(0, 0, width, 34, "#111c33")
	hdr.RX = 10
	hdr.RY = 10
	canvas.Append(hdr)
	tHdr := svg.NewText(14, 22, xmlEscape("WAVEFORM · "+title), "#f8fafc")
	tHdr.Attr.Style = "font-size:12px;font-weight:700"
	canvas.Append(tHdr)

	// Column headers per test vector.
	for s := 0; s < samples; s++ {
		x0 := labelW + s*slotW
		gx := svg.NewPath(ufmt.Sprintf("M %d 36 L %d %d", x0, x0, height-14), "none")
		gx.Attr.Stroke = "#1e293b"
		gx.Attr.StrokeWidth = "1"
		canvas.Append(gx)

		col := "#6ee7b7"
		if !vecPass[s] {
			col = "#f87171"
		}
		lbl := spec.Vectors[s].Label
		if len(lbl) > 8 {
			lbl = lbl[:8]
		}
		vt := svg.NewText(x0+slotW/2, height-5, xmlEscape(lbl), col)
		vt.Attr.Style = "font-size:9px;text-anchor:middle"
		canvas.Append(vt)
	}

	// Render each signal trace.
	for ch := 0; ch < totalCh; ch++ {
		yTop := headerH + ch*chH
		yHigh := yTop + 6
		yLow := yTop + chH - 6
		isOut := ch >= nIn

		name := ""
		strokeCol := "#38bdf8"
		if !isOut {
			name = "IN " + cc.AST.Inputs[ch]
		} else {
			name = "OUT " + cc.AST.Outputs[ch-nIn]
			strokeCol = "#10b981"
		}

		// Row separator.
		sep := svg.NewPath(ufmt.Sprintf("M 10 %d L %d %d", yTop+chH, width-10, yTop+chH), "none")
		sep.Attr.Stroke = "#162036"
		sep.Attr.StrokeWidth = "1"
		canvas.Append(sep)

		lbl := svg.NewText(14, yTop+18, xmlEscape(name), strokeCol)
		lbl.Attr.Style = "font-size:10px;font-weight:600"
		canvas.Append(lbl)

		var pts strings.Builder
		anyFail := false
		for s := 0; s < samples; s++ {
			var bit bool
			if !isOut {
				bit = spec.Vectors[s].In[ch]
			} else {
				oi := ch - nIn
				bit = actualOut[s][oi]
				if bit != spec.Vectors[s].Out[oi] {
					anyFail = true
				}
			}
			y := yLow
			if bit {
				y = yHigh
			}
			x0 := labelW + s*slotW
			x1 := x0 + slotW
			if s > 0 {
				pts.WriteString(" ")
			}
			pts.WriteString(ufmt.Sprintf("%d,%d %d,%d", x0, y, x1, y))

			bTxt := "0"
			if bit {
				bTxt = "1"
			}
			bt := svg.NewText(x0+slotW/2, yTop+19, bTxt, "#64748b")
			bt.Attr.Style = "font-size:9px;text-anchor:middle"
			canvas.Append(bt)
		}

		if anyFail {
			strokeCol = "#ef4444"
		}
		wave := svg.NewPolyline(pts.String(), "none")
		wave.Attr.Stroke = strokeCol
		wave.Attr.StrokeWidth = "2.2"
		canvas.Append(wave)
	}

	return canvas.String()
}

// RenderWaveformSVG returns a gnoweb-safe Markdown data:image/svg+xml image.
func RenderWaveformSVG(title string, cc *CompiledCircuit, spec ChallengeSpec, maxSamples int) string {
	raw := RenderWaveformRawSVG(title, cc, spec, maxSamples)
	if raw == "" {
		return ""
	}
	return wrapSVGMarkdown("Nandloom waveform: "+title, raw)
}

// wrapSVGMarkdown encodes a raw <svg> string into a base64 Markdown image.
func wrapSVGMarkdown(alt, rawSVG string) string {
	return ufmt.Sprintf("![%s](data:image/svg+xml;base64,%s)", alt, base64.StdEncoding.EncodeToString([]byte(rawSVG)))
}

package nandloom

// Resource caps enforced during parsing, compilation, and simulation to keep
// execution gas bounded inside GnoVM.
const (
	MaxNetlistBytes  = 4096
	MaxLines         = 128
	MaxStatements    = 64
	MaxInputs        = 12
	MaxOutputs       = 8
	MaxFlatGates     = 128
	MaxFlatOps       = 512
	MaxChipInstances = 64
	MaxChipDepth     = 6
	MaxTestVectors   = 64
	MaxIdentLen      = 24
	MaxSlugLen       = 32
)

// OpKind identifies the operation executed by a netlist statement.
type OpKind int

const (
	OpNAND OpKind = iota
	OpConst0
	OpConst1
	OpBuf
	OpChip
)

// String returns the canonical DSL name of an operation.
func (op OpKind) String() string {
	switch op {
	case OpNAND:
		return "nand"
	case OpConst0:
		return "const0"
	case OpConst1:
		return "const1"
	case OpBuf:
		return "buf"
	case OpChip:
		return "chip"
	default:
		return "unknown"
	}
}

// Statement is one parsed assignment in a netlist:
//
//	out0[, out1...] = op(arg0[, arg1...])
type Statement struct {
	Line     int
	Outputs  []string
	Op       OpKind
	ChipSlug string // populated only when Op == OpChip
	Args     []string
}

// Circuit is a parsed, syntactically valid netlist AST.
type Circuit struct {
	Inputs     []string
	Outputs    []string
	Statements []Statement
	Raw        string
}

// ChipResolver looks up a verified sub-chip circuit by slug.
// Returning (nil, false) marks the slug as unknown.
type ChipResolver func(slug string) (*Circuit, bool)

// FlatGate is a single primitive operation in the flattened, topologically
// ordered evaluation graph.
type FlatGate struct {
	Out   string
	Op    OpKind // OpNAND, OpConst0, OpConst1, or OpBuf
	A     string
	B     string
	Depth int // propagation depth in NAND layers from primary inputs
}

// CompiledCircuit holds a cycle-checked, flattened circuit with exact
// uncheatable metrics (true flattened NAND count and critical-path depth).
type CompiledCircuit struct {
	AST           *Circuit
	TopOrder      []int // topological order of AST.Statements indices
	StmtDepth     []int // column depth (1..MaxCol) per AST.Statements index
	StmtNANDs     []int // flattened NAND cost contributed by each AST statement
	MaxCol        int   // max visual column among statements
	FlatGates     []FlatGate
	NANDCount     int      // total flattened NAND primitive gates
	MaxDepth      int      // longest NAND gate chain from input to output
	ImportedChips []string // sorted unique direct sub-chip slugs
	ModuleCount   int      // number of top-level statements
}

// Trace records every wire value produced by a single evaluation run.
type Trace struct {
	InputBits   string
	OutputBits  string
	WireValues  map[string]bool // primary inputs + all top-level statement outputs
	OutputVals  []bool
	InputVals   []bool
}

// TestVector defines one input-to-expected-output check for a challenge.
type TestVector struct {
	In    []bool
	Out   []bool
	Label string
}

// ChallengeSpec describes a verifiable digital logic challenge.
type ChallengeSpec struct {
	ID             string
	Title          string
	Summary        string
	Difficulty     string
	Inputs         []string
	Outputs        []string
	ParNANDs       int
	ParDepth       int
	Vectors        []TestVector
	StarterNetlist string
}

// VerifyResult summarizes exhaustive test-vector verification for a compiled circuit.
type VerifyResult struct {
	Passed        bool
	TotalVectors  int
	PassedVectors int
	FailedIndex   int // -1 when Passed == true
	FailLabel     string
	FailInput     string
	FailExpected  string
	FailActual    string
	NANDCount     int
	Depth         int
	ErrorMessage  string
}

// ReferenceChip pairs a challenge with a seeded reference netlist.
type ReferenceChip struct {
	ChallengeID string
	Slug        string
	Title       string
	Notes       string
	Netlist     string
}

package nandloom

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	nl "gno.land/p/g1jxrrf695x7r3h0wqvmkq2vyyqy39wjraxyph3j/nandloom/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	realmPathPrefix = "/r/g1jxrrf695x7r3h0wqvmkq2vyyqy39wjraxyph3j/nandloom/v0"
	EventChipVerify = "ChipVerified"
)

var (
	challenges       *avl.Tree // challengeID -> *ChallengeState
	challengeOrder   []string
	chips            *avl.Tree // slug -> *ChipEntry
	builders         *avl.Tree // addr.String() -> *BuilderProfile
	totalSubmissions int
	totalReuses      int
)

func init(cur realm) {
	challenges = avl.NewTree()
	chips = avl.NewTree()
	builders = avl.NewTree()

	specs := nl.DefaultChallenges()
	challengeOrder = make([]string, 0, len(specs))
	for i := 0; i < len(specs); i++ {
		sp := specs[i]
		challengeOrder = append(challengeOrder, sp.ID)
		challenges.Set(sp.ID, &ChallengeState{
			Spec: sp,
		})
	}

	seedAuthor := cur.Previous().Address()
	if !seedAuthor.IsValid() {
		seedAuthor = cur.Address()
	}

	refs := nl.DefaultReferenceChips()
	for i := 0; i < len(refs); i++ {
		r := refs[i]
		mustInsertChip(seedAuthor, r.ChallengeID, r.Slug, r.Title, r.Notes, r.Netlist)
	}
}

func resolveChip(slug string) (*nl.Circuit, bool) {
	v := chips.Get(slug)
	if v == nil {
		return nil, false
	}
	entry := v.(*ChipEntry)
	return entry.AST, true
}

func getOrCreateBuilder(addr address) *BuilderProfile {
	key := addr.String()
	if v := builders.Get(key); v != nil {
		return v.(*BuilderProfile)
	}
	bp := &BuilderProfile{
		Address:          addr,
		SolvedChallenges: make(map[string]bool),
	}
	builders.Set(key, bp)
	return bp
}

func mustInsertChip(author address, challengeID, slug, title, notes, netlist string) (*ChipEntry, bool) {
	chVal := challenges.Get(challengeID)
	if chVal == nil {
		panic("unknown challenge: " + challengeID)
	}
	ch := chVal.(*ChallengeState)

	if !nl.IsValidSlug(slug) {
		panic("invalid chip slug: must match [a-z][a-z0-9_-]{0,31}")
	}
	if chips.Has(slug) {
		panic("chip slug already exists (verified chips are immutable): " + slug)
	}
	title = sanitizeIngressText(title)
	notes = sanitizeIngressText(notes)
	if title == "" {
		panic("chip title cannot be empty")
	}
	if len(title) > MaxTitleLen {
		panic(ufmt.Sprintf("chip title exceeds %d chars", MaxTitleLen))
	}
	if len(notes) > MaxNotesLen {
		panic(ufmt.Sprintf("chip notes exceed %d chars", MaxNotesLen))
	}
	if len(ch.SubmissionSlugs) >= MaxSubmissionsPerChallenge {
		panic(ufmt.Sprintf("challenge %s reached max %d submissions", challengeID, MaxSubmissionsPerChallenge))
	}
	bpCheck := getOrCreateBuilder(author)
	if bpCheck.ChipsSubmitted >= MaxSubmissionsPerBuilder {
		panic(ufmt.Sprintf("builder reached max %d verified submissions", MaxSubmissionsPerBuilder))
	}

	ast, err := nl.Parse(netlist)
	if err != nil {
		panic("netlist parse error: " + err.Error())
	}
	cc, err := nl.Compile(ast, resolveChip)
	if err != nil {
		panic("netlist compile error: " + err.Error())
	}
	vr := nl.Verify(cc, ch.Spec)
	if !vr.Passed {
		panic("verification failed: " + vr.ErrorMessage)
	}

	entry := &ChipEntry{
		Slug:          slug,
		ChallengeID:   challengeID,
		Title:         title,
		Notes:         notes,
		Author:        author,
		BlockHeight:   runtime.ChainHeight(),
		Netlist:       ast.Raw,
		AST:           ast,
		Compiled:      cc,
		NANDCount:     cc.NANDCount,
		Depth:         cc.MaxDepth,
		ModuleCount:   cc.ModuleCount,
		ImportedChips: cc.ImportedChips,
	}
	chips.Set(slug, entry)
	ch.SubmissionSlugs = append(ch.SubmissionSlugs, slug)
	totalSubmissions++

	// Update builder stats.
	bp := getOrCreateBuilder(author)
	bp.ChipsSubmitted++
	bp.SolvedChallenges[challengeID] = true

	// Credit composable sub-chip reuse on every direct dependency.
	for i := 0; i < len(cc.ImportedChips); i++ {
		depSlug := cc.ImportedChips[i]
		if dv := chips.Get(depSlug); dv != nil {
			dep := dv.(*ChipEntry)
			dep.ReuseCount++
			if len(dep.Importers) < MaxImportersCap {
				dep.Importers = append(dep.Importers, slug)
			}
			totalReuses++
			depBuilder := getOrCreateBuilder(dep.Author)
			depBuilder.TotalReuses++
		}
	}

	// Deterministic record rule: fewer flattened NANDs wins; ties broken by shallower depth,
	// then earlier submission (strictly < required to unseat an existing record).
	newRecord := false
	if ch.BestSlug == "" ||
		entry.NANDCount < ch.BestNANDs ||
		(entry.NANDCount == ch.BestNANDs && entry.Depth < ch.BestDepth) {
		if ch.BestSlug != "" {
			if prevB := builders.Get(ch.BestAuthor.String()); prevB != nil {
				pb := prevB.(*BuilderProfile)
				if pb.RecordsHeld > 0 {
					pb.RecordsHeld--
				}
			}
		}
		ch.BestSlug = slug
		ch.BestNANDs = entry.NANDCount
		ch.BestDepth = entry.Depth
		ch.BestAuthor = author
		bp.RecordsHeld++
		newRecord = true
	}

	return entry, newRecord
}

// SubmitChip parses, compiles (resolving verified chip:<slug> imports), verifies
// against every challenge test vector, and permanently registers the chip on-chain.
//
// Crossing safety: enforces cur.IsCurrent() and derives caller strictly from
// cur.Previous().Address().
func SubmitChip(cur realm, challengeID, slug, title, notes, netlist string) string {
	if !cur.IsCurrent() {
		panic("unauthorized crossing context")
	}
	caller := cur.Previous().Address()
	if !caller.IsValid() {
		panic("invalid caller address")
	}

	entry, newRecord := mustInsertChip(caller, challengeID, slug, title, notes, netlist)

	recStr := "false"
	if newRecord {
		recStr = "true"
	}
	chain.Emit(
		EventChipVerify,
		"slug", entry.Slug,
		"challenge", entry.ChallengeID,
		"author", caller.String(),
		"nands", strconv.Itoa(entry.NANDCount),
		"depth", strconv.Itoa(entry.Depth),
		"new_record", recStr,
	)

	if newRecord {
		return ufmt.Sprintf("VERIFIED NEW RECORD: %s (%d NANDs, depth %d) for %s",
			entry.Slug, entry.NANDCount, entry.Depth, entry.ChallengeID)
	}
	return ufmt.Sprintf("VERIFIED: %s (%d NANDs, depth %d) for %s",
		entry.Slug, entry.NANDCount, entry.Depth, entry.ChallengeID)
}

// EvalChip is a cross-realm composable API allowing any other Gno realm or
// off-chain vm/qeval client to run a verified on-chain chip on a bitstring.
func EvalChip(slug, bits string) string {
	v := chips.Get(slug)
	if v == nil {
		panic("unknown chip: " + slug)
	}
	entry := v.(*ChipEntry)
	tr, err := nl.EvalBits(entry.Compiled, bits)
	if err != nil {
		panic(err.Error())
	}
	return tr.OutputBits
}

// VerifyExternal runs a pure read-only parse, compile, and exhaustive vector check
// against the live verified chip registry without mutating chain state.
func VerifyExternal(challengeID, netlist string) string {
	chVal := challenges.Get(challengeID)
	if chVal == nil {
		return "FAIL|unknown challenge: " + challengeID
	}
	ch := chVal.(*ChallengeState)
	ast, err := nl.Parse(netlist)
	if err != nil {
		return "FAIL|parse: " + err.Error()
	}
	cc, err := nl.Compile(ast, resolveChip)
	if err != nil {
		return "FAIL|compile: " + err.Error()
	}
	vr := nl.Verify(cc, ch.Spec)
	if !vr.Passed {
		return "FAIL|" + vr.ErrorMessage
	}
	beats := "false"
	if ch.BestSlug == "" || cc.NANDCount < ch.BestNANDs || (cc.NANDCount == ch.BestNANDs && cc.MaxDepth < ch.BestDepth) {
		beats = "true"
	}
	return ufmt.Sprintf("PASS|nands=%d|depth=%d|vectors=%d/%d|beats_record=%s|imports=%s",
		cc.NANDCount, cc.MaxDepth, vr.PassedVectors, vr.TotalVectors, beats, strings.Join(cc.ImportedChips, ","))
}

// GetChipInfo returns typed metadata for a verified chip (cross-realm API).
func GetChipInfo(slug string) (challengeID, title, author string, nands, depth, reuses int, ok bool) {
	v := chips.Get(slug)
	if v == nil {
		return "", "", "", 0, 0, 0, false
	}
	e := v.(*ChipEntry)
	return e.ChallengeID, e.Title, e.Author.String(), e.NANDCount, e.Depth, e.ReuseCount, true
}

// SnapshotJSON returns a deterministic JSON snapshot of live on-chain challenges,
// verified chips, and builder stats for zero-backend RPC web clients (vm/qeval).
func SnapshotJSON() string {
	var b strings.Builder
	b.WriteString("{")
	b.WriteString(ufmt.Sprintf(`"chain_height":%d,"total_chips":%d,"total_reuses":%d,"challenges":[`,
		runtime.ChainHeight(), chips.Size(), totalReuses))

	for i := 0; i < len(challengeOrder); i++ {
		if i > 0 {
			b.WriteByte(',')
		}
		ch := challenges.Get(challengeOrder[i]).(*ChallengeState)
		b.WriteString("{")
		b.WriteString(`"id":` + jsonStr(ch.Spec.ID))
		b.WriteString(`,"title":` + jsonStr(ch.Spec.Title))
		b.WriteString(`,"summary":` + jsonStr(ch.Spec.Summary))
		b.WriteString(`,"difficulty":` + jsonStr(ch.Spec.Difficulty))
		b.WriteString(`,"inputs":` + jsonStrSlice(ch.Spec.Inputs))
		b.WriteString(`,"outputs":` + jsonStrSlice(ch.Spec.Outputs))
		b.WriteString(ufmt.Sprintf(`,"par_nands":%d,"par_depth":%d,"vectors":%d`,
			ch.Spec.ParNANDs, ch.Spec.ParDepth, len(ch.Spec.Vectors)))
		b.WriteString(`,"best_slug":` + jsonStr(ch.BestSlug))
		b.WriteString(ufmt.Sprintf(`,"best_nands":%d,"best_depth":%d`, ch.BestNANDs, ch.BestDepth))
		b.WriteString(`,"best_author":` + jsonStr(ch.BestAuthor.String()))
		b.WriteString(`,"starter_netlist":` + jsonStr(ch.Spec.StarterNetlist))
		b.WriteString(ufmt.Sprintf(`,"submission_count":%d`, len(ch.SubmissionSlugs)))
		b.WriteString("}")
	}

	b.WriteString(`],"chips":[`)
	firstChip := true
	chipCount := 0
	chips.Iterate("", "", func(_ string, v any) bool {
		if chipCount >= MaxSnapshotChips {
			return true
		}
		chipCount++
		e := v.(*ChipEntry)
		if !firstChip {
			b.WriteByte(',')
		}
		firstChip = false
		b.WriteString("{")
		b.WriteString(`"slug":` + jsonStr(e.Slug))
		b.WriteString(`,"challenge_id":` + jsonStr(e.ChallengeID))
		b.WriteString(`,"title":` + jsonStr(e.Title))
		b.WriteString(`,"notes":` + jsonStr(e.Notes))
		b.WriteString(`,"author":` + jsonStr(e.Author.String()))
		b.WriteString(ufmt.Sprintf(`,"block_height":%d,"nands":%d,"depth":%d,"modules":%d,"reuses":%d`,
			e.BlockHeight, e.NANDCount, e.Depth, e.ModuleCount, e.ReuseCount))
		b.WriteString(`,"imports":` + jsonStrSlice(e.ImportedChips))
		b.WriteString(`,"importers":` + jsonStrSlice(e.Importers))
		b.WriteString(`,"netlist":` + jsonStr(e.Netlist))
		b.WriteString("}")
		return false
	})

	b.WriteString(`],"builders":[`)
	sortedB := sortedBuilders()
	limitB := len(sortedB)
	if limitB > MaxDisplayRows {
		limitB = MaxDisplayRows
	}
	for i := 0; i < limitB; i++ {
		if i > 0 {
			b.WriteByte(',')
		}
		bp := sortedB[i]
		b.WriteString("{")
		b.WriteString(`"address":` + jsonStr(bp.Address.String()))
		b.WriteString(ufmt.Sprintf(`,"chips":%d,"records":%d,"reuses":%d,"solved":%d`,
			bp.ChipsSubmitted, bp.RecordsHeld, bp.TotalReuses, len(bp.SolvedChallenges)))
		b.WriteString("}")
	}
	b.WriteString("]}")
	return b.String()
}

func sanitizeIngressText(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\n' || c == '\r' || c == '\t' {
			b.WriteByte(' ')
		} else if c >= 0x20 && c != 0x7f {
			b.WriteByte(c)
		}
	}
	return strings.TrimSpace(b.String())
}

func builderBetter(a, b *BuilderProfile) bool {
	if a.RecordsHeld != b.RecordsHeld {
		return a.RecordsHeld > b.RecordsHeld
	}
	if a.TotalReuses != b.TotalReuses {
		return a.TotalReuses > b.TotalReuses
	}
	if len(a.SolvedChallenges) != len(b.SolvedChallenges) {
		return len(a.SolvedChallenges) > len(b.SolvedChallenges)
	}
	return a.Address.String() < b.Address.String()
}

func mergeSortBuilders(arr []*BuilderProfile) []*BuilderProfile {
	if len(arr) <= 1 {
		return arr
	}
	mid := len(arr) / 2
	left := mergeSortBuilders(arr[:mid])
	right := mergeSortBuilders(arr[mid:])
	res := make([]*BuilderProfile, 0, len(arr))
	i, j := 0, 0
	for i < len(left) && j < len(right) {
		if builderBetter(left[i], right[j]) {
			res = append(res, left[i])
			i++
		} else {
			res = append(res, right[j])
			j++
		}
	}
	res = append(res, left[i:]...)
	res = append(res, right[j:]...)
	return res
}

func sortedBuilders() []*BuilderProfile {
	out := make([]*BuilderProfile, 0, builders.Size())
	builders.Iterate("", "", func(_ string, v any) bool {
		out = append(out, v.(*BuilderProfile))
		return false
	})
	return mergeSortBuilders(out)
}

func chipBetter(a, b *ChipEntry) bool {
	if a.NANDCount != b.NANDCount {
		return a.NANDCount < b.NANDCount
	}
	if a.Depth != b.Depth {
		return a.Depth < b.Depth
	}
	if a.BlockHeight != b.BlockHeight {
		return a.BlockHeight < b.BlockHeight
	}
	return a.Slug < b.Slug
}

func mergeSortChips(arr []*ChipEntry, less func(a, b *ChipEntry) bool) []*ChipEntry {
	if len(arr) <= 1 {
		return arr
	}
	mid := len(arr) / 2
	left := mergeSortChips(arr[:mid], less)
	right := mergeSortChips(arr[mid:], less)
	res := make([]*ChipEntry, 0, len(arr))
	i, j := 0, 0
	for i < len(left) && j < len(right) {
		if less(left[i], right[j]) {
			res = append(res, left[i])
			i++
		} else {
			res = append(res, right[j])
			j++
		}
	}
	res = append(res, left[i:]...)
	res = append(res, right[j:]...)
	return res
}

func sortedChallengeChips(slugs []string) []*ChipEntry {
	out := make([]*ChipEntry, 0, len(slugs))
	for i := 0; i < len(slugs); i++ {
		if v := chips.Get(slugs[i]); v != nil {
			out = append(out, v.(*ChipEntry))
		}
	}
	return mergeSortChips(out, chipBetter)
}

func jsonStr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		default:
			if c < 0x20 {
				b.WriteString(ufmt.Sprintf(`\u%04x`, int(c)))
			} else {
				b.WriteByte(c)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

func jsonStrSlice(ss []string) string {
	var b strings.Builder
	b.WriteByte('[')
	for i := 0; i < len(ss); i++ {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(jsonStr(ss[i]))
	}
	b.WriteByte(']')
	return b.String()
}

package nandloom

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

func TestSeededStateAndHomeRender(t *testing.T) {
	if challenges.Size() != 8 {
		t.Fatalf("expected 8 seeded challenges, got %d", challenges.Size())
	}
	if chips.Size() != 8 {
		t.Fatalf("expected 8 seeded reference chips, got %d", chips.Size())
	}

	// Verify cross-chip reuse counters were automatically populated during seeding:
	// not1_ref is imported by and2_ref, or2_ref, mux2_ref -> 3 reuses.
	_, _, _, nands, depth, reuses, ok := GetChipInfo("not1_ref")
	if !ok || nands != 1 || depth != 1 || reuses != 3 {
		t.Fatalf("not1_ref unexpected info: ok=%v nands=%d depth=%d reuses=%d", ok, nands, depth, reuses)
	}

	// Home page renders featured live schematic SVG + all 8 challenges.
	home := Render("")
	if !strings.Contains(home, "data:image/svg+xml;base64,") {
		t.Fatalf("home render missing embedded SVG schematic")
	}
	if !strings.Contains(home, "4-Bit Ripple Carry Adder") || !strings.Contains(home, "adder4_ref") {
		t.Fatalf("home render missing featured adder4 challenge")
	}
}

func TestMultiUserSubmitBeatsRecordAndTracksReuse(cur realm, t *testing.T) {
	bob := testutils.TestAddress("bob")
	testing.SetRealm(testing.NewUserRealm(bob))

	// Bob submits an optimal 5-NAND Half Adder beating the 6-NAND reference!
	ha5 := `in a, b
out sum, carry
w1 = nand(a, b)
w2 = nand(a, w1)
w3 = nand(b, w1)
sum = nand(w2, w3)
carry = nand(w1, w1)`

	out := SubmitChip(cross(cur), "half_adder", "bob_ha5", "Bob 5-NAND Half Adder", "Shares nand(a,b).", ha5)
	if !strings.Contains(out, "NEW RECORD") || !strings.Contains(out, "5 NANDs") {
		t.Fatalf("expected NEW RECORD 5 NANDs, got: %s", out)
	}

	// Bob submits a 9-NAND Full Adder beating the 15-NAND reference!
	fa9 := `in a, b, cin
out sum, cout
w1 = nand(a, b)
w2 = nand(a, w1)
w3 = nand(b, w1)
w4 = nand(w2, w3)
w5 = nand(w4, cin)
w6 = nand(w4, w5)
w7 = nand(cin, w5)
sum = nand(w6, w7)
cout = nand(w5, w1)`

	out2 := SubmitChip(cross(cur), "full_adder", "bob_fa9", "Bob 9-NAND Full Adder", "Shared carry term.", fa9)
	if !strings.Contains(out2, "NEW RECORD") || !strings.Contains(out2, "9 NANDs") {
		t.Fatalf("expected NEW RECORD 9 NANDs, got: %s", out2)
	}

	// Alice composes Bob's verified chip:bob_fa9 to build a 36-NAND 4-bit adder!
	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))
	a4Opt := `in a0, a1, a2, a3, b0, b1, b2, b3, cin
out s0, s1, s2, s3, cout
s0, c1 = chip:bob_fa9(a0, b0, cin)
s1, c2 = chip:bob_fa9(a1, b1, c1)
s2, c3 = chip:bob_fa9(a2, b2, c2)
s3, cout = chip:bob_fa9(a3, b3, c3)`

	out3 := SubmitChip(cross(cur), "adder4", "alice_adder36", "Alice 36-NAND Ripple Adder", "Composes 4x chip:bob_fa9.", a4Opt)
	if !strings.Contains(out3, "NEW RECORD") || !strings.Contains(out3, "36 NANDs") {
		t.Fatalf("expected NEW RECORD 36 NANDs, got: %s", out3)
	}

	// Verify bob_fa9 reuse count incremented to 1!
	_, _, _, _, _, faReuses, ok := GetChipInfo("bob_fa9")
	if !ok || faReuses != 1 {
		t.Fatalf("expected bob_fa9 reuse count 1, got %d (ok=%v)", faReuses, ok)
	}

	// Cross-realm EvalChip API check: 15 + 15 + 1 = 31 -> s=1111, cout=1 -> "11111"
	got := EvalChip("alice_adder36", "111111111")
	if got != "11111" {
		t.Fatalf("EvalChip(alice_adder36, 111111111) got %s, want 11111", got)
	}
}

func TestZeroWalletRenderSimulationAndSanitization(cur realm, t *testing.T) {
	// Zero-tx interactive bit toggle simulation on chip route
	page := Render("chip/half_adder_ref?in=11")
	if !strings.Contains(page, "11 -> 01") {
		t.Fatalf("expected live evaluation 11 -> 01 in chip page")
	}
	if !strings.Contains(page, "data:image/svg+xml;base64,") {
		t.Fatalf("expected embedded SVG schematic & waveform in chip page")
	}
	if !strings.Contains(page, "gno-button") {
		t.Fatalf("expected interactive bit-toggle buttons in chip page")
	}

	// Zero-wallet sandbox form query route
	sbPage := Render("sandbox?challenge=not1&bits=1&netlist=in+a%0Aout+y%0Ay+%3D+nand(a%2C+a)")
	if !strings.Contains(sbPage, "VERIFIED") {
		t.Fatalf("expected sandbox verification pass, got:\n%s", sbPage[:400])
	}

	// VerifyExternal read-only API
	okRes := VerifyExternal("not1", "in a\nout y\ny = nand(a, a)")
	if !strings.HasPrefix(okRes, "PASS|nands=1|depth=1|") {
		t.Fatalf("unexpected VerifyExternal PASS: %s", okRes)
	}
	badRes := VerifyExternal("not1", "in a\nout y\ny = buf(a)")
	if !strings.HasPrefix(badRes, "FAIL|") {
		t.Fatalf("expected VerifyExternal FAIL on identity gate, got: %s", badRes)
	}

	// Markdown injection test in title/notes
	mallory := testutils.TestAddress("mallory")
	testing.SetRealm(testing.NewUserRealm(mallory))
	SubmitChip(cross(cur), "not1", "mal_not", "Evil <gno-button href=\"http://bad\" /> | col", "Injected\n# Heading", "in a\nout y\ny = nand(a, a)")
	libPage := Render("chips")
	if strings.Contains(libPage, `<gno-button href="http://bad"`) {
		t.Fatalf("markdown/gno-button injection was not escaped in chips table")
	}

	// SnapshotJSON sanity check
	snap := SnapshotJSON()
	if !strings.HasPrefix(snap, "{") || !strings.Contains(snap, `"adder4"`) || !strings.Contains(snap, `"mal_not"`) {
		t.Fatalf("invalid SnapshotJSON output")
	}
}

func TestRejectsDuplicateAndBrokenCircuit(cur realm, t *testing.T) {
	u := testutils.TestAddress("tester")
	testing.SetRealm(testing.NewUserRealm(u))

	// Duplicate slug aborts atomically
	uassert.AbortsContains(t, cur, "already exists", func(cur realm) {
		SubmitChip(cross(cur), "not1", "not1_ref", "Dup", "", "in a\nout y\ny = nand(a, a)")
	})

	// Combinational cycle aborts atomically
	uassert.AbortsContains(t, cur, "cycle", func(cur realm) {
		SubmitChip(cross(cur), "not1", "cyc_not", "Cycle", "", "in a\nout y\nx = nand(a, y)\ny = nand(x, a)")
	})

	// Wrong truth table aborts with counterexample
	uassert.AbortsContains(t, cur, "verification failed", func(cur realm) {
		SubmitChip(cross(cur), "xor2", "bad_xor", "Broken XOR", "", "in a, b\nout y\ny = nand(a, b)")
	})
}

package nandloom

import (
	"strings"

	nl "gno.land/p/g1jxrrf695x7r3h0wqvmkq2vyyqy39wjraxyph3j/nandloom/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/mux/v0"
	"gno.land/p/nt/ufmt/v0"
)

var router *mux.Router

func init() {
	router = mux.NewRouter()
	router.HandleFunc("", renderHome)
	router.HandleFunc("chip/{slug}", renderChip)
	router.HandleFunc("challenge/{id}", renderChallenge)
	router.HandleFunc("sandbox", renderSandbox)
	router.HandleFunc("chips", renderChips)
	router.HandleFunc("leaderboard", renderLeaderboard)
	router.HandleFunc("submit", renderSubmit)
	router.SetNotFoundHandler(renderNotFound)
}

// Render serves the full zero-frontend interactive Nandloom application inside gnoweb.
func Render(path string) string {
	return router.Render(path)
}

func realmLink(sub string) string {
	if sub == "" {
		return realmPathPrefix
	}
	return realmPathPrefix + ":" + sub
}

func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "..." + s[len(s)-5:]
}

func renderNav(active string) string {
	var b strings.Builder
	btn := func(id, sub, label string) {
		variant := "outline"
		if id == active {
			variant = "success"
		}
		b.WriteString(ufmt.Sprintf(`<gno-button href="%s" label="%s" variant="%s" /> `, realmLink(sub), label, variant))
	}
	btn("home", "", "Workbench")
	btn("sandbox", "sandbox", "Live Sandbox (Zero-Wallet)")
	btn("chips", "chips", "Chip Library")
	btn("leaderboard", "leaderboard", "Leaderboard")
	btn("submit", "submit", "Submit Chip")
	b.WriteString("\n\n")
	return b.String()
}

func defaultDemoBits(spec nl.ChallengeSpec) string {
	if spec.ID == "adder4" {
		// 15 + 0 + 1 = 16 -> full 4-bit carry ripple across all 4 full-adder blocks!
		return "111100001"
	}
	if spec.ID == "full_adder" {
		return "111"
	}
	if spec.ID == "half_adder" {
		return "11"
	}
	if spec.ID == "mux2" {
		return "101"
	}
	if len(spec.Vectors) > 0 {
		return nl.FormatBits(spec.Vectors[len(spec.Vectors)-1].In)
	}
	return strings.Repeat("1", len(spec.Inputs))
}

func flipBit(bits string, idx int) string {
	buf := []byte(bits)
	if idx >= 0 && idx < len(buf) {
		if buf[idx] == '1' {
			buf[idx] = '0'
		} else {
			buf[idx] = '1'
		}
	}
	return string(buf)
}

func renderHome(res *mux.ResponseWriter, _ *mux.Request) {
	var b strings.Builder
	b.WriteString("# Nandloom — Composable On-Chain Silicon on Gno.land\n\n")
	b.WriteString("Build digital logic chips from universal **NAND** gates, import other builders' verified circuits as on-chain IC blocks (`chip:<slug>`), and simulate live schematics **directly inside gnoweb with zero wallet or gas**.\n\n")
	b.WriteString(renderNav("home"))

	b.WriteString(ufmt.Sprintf("> [!TIP]\n> **%d Challenges** · **%d Verified Immutable Chips** · **%d Cross-Chip Imports** · **Zero-Wallet Live Simulation** via `Render(path)`\n\n",
		len(challengeOrder), chips.Size(), totalReuses))

	// Featured live schematic: current record holder of 4-Bit Ripple Adder evaluated on full carry ripple (15+0+1).
	if chVal := challenges.Get("adder4"); chVal != nil {
		ch := chVal.(*ChallengeState)
		if ch.BestSlug != "" {
			if eVal := chips.Get(ch.BestSlug); eVal != nil {
				entry := eVal.(*ChipEntry)
				demoBits := defaultDemoBits(ch.Spec)
				tr, err := nl.EvalBits(entry.Compiled, demoBits)
				if err == nil {
					b.WriteString("## Featured Live Silicon: " + sanitize.InlineText(entry.Title) + " (`" + entry.Slug + "`)\n\n")
					b.WriteString("Simulated live inside GnoVM on `15 + 0 + 1 = 16` (`111100001 -> 00001`, full carry ripple):\n\n")
					b.WriteString(nl.RenderSchematicSVG(entry.Slug+" · "+entry.Title, entry.Compiled, tr) + "\n\n")
					b.WriteString(ufmt.Sprintf(`<gno-button href="%s" label="Simulate & Toggle Pins (Zero-Wallet)" variant="tip" /> `, realmLink("chip/"+entry.Slug+"?in="+demoBits)))
					b.WriteString(ufmt.Sprintf(`<gno-button href="%s" label="Beat This Record" variant="outline" />`, realmLink("challenge/adder4")))
					b.WriteString("\n\n")
				}
			}
		}
	}

	b.WriteString("## Challenge Ladder (NAND → 4-Bit Ripple Carry Adder)\n\n")
	b.WriteString("| Tier | Challenge | Pins | Par (NAND / Depth) | Current Record | Record Holder | Actions |\n")
	b.WriteString("|---|---|---|---|---|---|---|\n")
	for i := 0; i < len(challengeOrder); i++ {
		ch := challenges.Get(challengeOrder[i]).(*ChallengeState)
		pins := ufmt.Sprintf("%d in → %d out", len(ch.Spec.Inputs), len(ch.Spec.Outputs))
		par := ufmt.Sprintf("%d / %d", ch.Spec.ParNANDs, ch.Spec.ParDepth)
		rec := "—"
		holder := "—"
		if ch.BestSlug != "" {
			rec = ufmt.Sprintf("[%s](%s) (**%d** / %d)", ch.BestSlug, realmLink("chip/"+ch.BestSlug), ch.BestNANDs, ch.BestDepth)
			holder = "`" + shortAddr(ch.BestAuthor) + "`"
		}
		actions := ufmt.Sprintf("[Inspect](%s) · [Sandbox](%s)", realmLink("challenge/"+ch.Spec.ID), realmLink("sandbox?challenge="+ch.Spec.ID))
		b.WriteString(ufmt.Sprintf("| %s | **%s** | %s | %s | %s | %s | %s |\n",
			sanitize.TableCell(ch.Spec.Difficulty),
			sanitize.TableCell(ch.Spec.Title),
			pins, par, rec, holder, actions))
	}

	b.WriteString("\n## Why Composable On-Chain Silicon?\n\n")
	b.WriteString("<gno-columns>\n")
	b.WriteString("### 1. Zero-Wallet Live Simulation\n")
	b.WriteString("Click any chip pin toggle or submit custom netlists in the **Sandbox** — GnoVM evaluates the circuit and paints live emerald/slate SVG wires with zero gas.\n")
	b.WriteString("|||\n")
	b.WriteString("### 2. True Flattened Scoring\n")
	b.WriteString("Importing `chip:half_adder_ref` expands recursively to primitive NAND gates before scoring — no hidden-gate cheating, exact critical-path delay.\n")
	b.WriteString("|||\n")
	b.WriteString("### 3. Cross-Realm Composability\n")
	b.WriteString("Every verified chip is immutable and callable from other Gno realms via `EvalChip(slug, bits)` or exported as standalone pure-Gno code.\n")
	b.WriteString("</gno-columns>\n")

	res.Write(b.String())
}

func renderChip(res *mux.ResponseWriter, req *mux.Request) {
	slug := req.GetVar("slug")
	v := chips.Get(slug)
	if v == nil {
		renderNotFound(res, req)
		return
	}
	entry := v.(*ChipEntry)
	ch := challenges.Get(entry.ChallengeID).(*ChallengeState)

	bits := strings.TrimSpace(req.Query.Get("in"))
	if bits == "" {
		bits = defaultDemoBits(ch.Spec)
	}
	tr, evalErr := nl.EvalBits(entry.Compiled, bits)
	if evalErr != nil {
		// Fall back safely to default demo vector and display warning.
		bits = defaultDemoBits(ch.Spec)
		tr, _ = nl.EvalBits(entry.Compiled, bits)
	}

	var b strings.Builder
	b.WriteString(ufmt.Sprintf("# Chip `%s` — %s\n\n", entry.Slug, sanitize.InlineText(entry.Title)))
	b.WriteString(renderNav("chips"))

	if evalErr != nil {
		b.WriteString("> [!WARNING]\n> Invalid `?in=` query (" + sanitize.InlineText(evalErr.Error()) + "); showing default vector `" + bits + "`.\n\n")
	}

	isRecord := ch.BestSlug == entry.Slug
	recBadge := "Verified Submission"
	if isRecord {
		recBadge = "ACTIVE CHALLENGE RECORD"
	}
	b.WriteString(ufmt.Sprintf("**Status:** `%s` · **Challenge:** [%s](%s) · **Area:** **%d NANDs** · **Critical-Path Depth:** **%d** · **Reused By:** **%d** chips · **Author:** `%s` (block #%d)\n\n",
		recBadge, sanitize.InlineText(ch.Spec.Title), realmLink("challenge/"+ch.Spec.ID),
		entry.NANDCount, entry.Depth, entry.ReuseCount, shortAddr(entry.Author), entry.BlockHeight))

	if entry.Notes != "" {
		b.WriteString("> " + sanitize.InlineText(entry.Notes) + "\n\n")
	}

	// 1. Live Interactive SVG Schematic
	b.WriteString("## Live Schematic (Zero-TX GnoVM Simulation)\n\n")
	b.WriteString(nl.RenderSchematicSVG(entry.Slug+" · "+entry.Title, entry.Compiled, tr) + "\n\n")

	// 2. Interactive Bit-Toggle Buttons (zero-wallet!)
	b.WriteString("### Toggle Input Pins (Click — No Wallet Required)\n\n")
	for i := 0; i < len(entry.AST.Inputs); i++ {
		pin := entry.AST.Inputs[i]
		curBit := "0"
		nextBit := "1"
		variant := "outline"
		if tr != nil && tr.InputVals[i] {
			curBit = "1"
			nextBit = "0"
			variant = "success"
		}
		flipped := flipBit(bits, i)
		b.WriteString(ufmt.Sprintf(`<gno-button href="%s" label="%s=%s (→%s)" variant="%s" /> `,
			realmLink("chip/"+entry.Slug+"?in="+flipped), pin, curBit, nextBit, variant))
	}
	b.WriteString("\n\n**Presets:** ")
	allZero := strings.Repeat("0", len(entry.AST.Inputs))
	allOne := strings.Repeat("1", len(entry.AST.Inputs))
	b.WriteString(ufmt.Sprintf(`<gno-button href="%s" label="All 0 (%s)" variant="outline" /> `, realmLink("chip/"+entry.Slug+"?in="+allZero), allZero))
	b.WriteString(ufmt.Sprintf(`<gno-button href="%s" label="All 1 (%s)" variant="outline" /> `, realmLink("chip/"+entry.Slug+"?in="+allOne), allOne))
	if ch.Spec.ID == "adder4" {
		b.WriteString(ufmt.Sprintf(`<gno-button href="%s" label="Carry Ripple 15+0+1" variant="info" /> `, realmLink("chip/"+entry.Slug+"?in=111100001")))
		b.WriteString(ufmt.Sprintf(`<gno-button href="%s" label="Alt 5+10+1" variant="info" /> `, realmLink("chip/"+entry.Slug+"?in=101001011")))
	}
	b.WriteString("\n\n")

	if tr != nil {
		b.WriteString(ufmt.Sprintf("**Live Probe:** `%s` → `%s` (`%s`)\n\n",
			formatPinVals(entry.AST.Inputs, tr.InputVals),
			formatPinVals(entry.AST.Outputs, tr.OutputVals),
			tr.InputBits+" -> "+tr.OutputBits))
	}

	// 3. Oscilloscope Timing Waveform SVG
	b.WriteString("## Verified Timing Waveform\n\n")
	b.WriteString(nl.RenderWaveformSVG(entry.Slug, entry.Compiled, ch.Spec, 8) + "\n\n")

	// 4. Composition Dependency Graph
	b.WriteString("## On-Chain Composition Graph\n\n")
	b.WriteString("<gno-columns>\n")
	b.WriteString("**Imports (Sub-Chips Used)**\n\n")
	if len(entry.ImportedChips) == 0 {
		b.WriteString("- Primitive pure-NAND architecture (0 sub-chips)\n")
	} else {
		for i := 0; i < len(entry.ImportedChips); i++ {
			dep := entry.ImportedChips[i]
			b.WriteString(ufmt.Sprintf("- [`chip:%s`](%s)\n", dep, realmLink("chip/"+dep)))
		}
	}
	b.WriteString("|||\n")
	b.WriteString("**Imported By (Chips Reusing This Block)**\n\n")
	if len(entry.Importers) == 0 {
		b.WriteString("- None yet — import `chip:" + entry.Slug + "(...)` in your next circuit!\n")
	} else {
		for i := 0; i < len(entry.Importers); i++ {
			imp := entry.Importers[i]
			b.WriteString(ufmt.Sprintf("- [`%s`](%s)\n", imp, realmLink("chip/"+imp)))
		}
	}
	b.WriteString("</gno-columns>\n\n")

	// 5. Netlist Source & Exported Gno Code
	b.WriteString("## Verified Netlist Source\n\n")
	b.WriteString("```text\n" + entry.Netlist + "\n```\n\n")

	b.WriteString("## Export as Standalone Pure-Gno Code\n\n")
	b.WriteString("Copy directly into any Gno realm or package with zero external dependencies:\n\n")
	b.WriteString("```go\n" + nl.ExportGno(entry.Slug, entry.Compiled) + "```\n")

	res.Write(b.String())
}

func renderChallenge(res *mux.ResponseWriter, req *mux.Request) {
	id := req.GetVar("id")
	v := challenges.Get(id)
	if v == nil {
		renderNotFound(res, req)
		return
	}
	ch := v.(*ChallengeState)
	ranked := sortedChallengeChips(ch.SubmissionSlugs)

	var b strings.Builder
	b.WriteString(ufmt.Sprintf("# Challenge: %s (`%s`)\n\n", sanitize.InlineText(ch.Spec.Title), ch.Spec.ID))
	b.WriteString(renderNav("home"))

	b.WriteString(sanitize.InlineText(ch.Spec.Summary) + "\n\n")
	b.WriteString(ufmt.Sprintf("- **Difficulty:** %s\n- **Required Inputs:** `%s`\n- **Required Outputs:** `%s`\n- **Par Target:** **%d NANDs** / depth **%d**\n- **Verification Vectors:** **%d** deterministic cases\n",
		sanitize.InlineText(ch.Spec.Difficulty),
		strings.Join(ch.Spec.Inputs, ", "),
		strings.Join(ch.Spec.Outputs, ", "),
		ch.Spec.ParNANDs, ch.Spec.ParDepth, len(ch.Spec.Vectors)))

	if ch.BestSlug != "" {
		b.WriteString(ufmt.Sprintf("- **Current Record:** [`%s`](%s) — **%d NANDs**, depth **%d** by `%s`\n",
			ch.BestSlug, realmLink("chip/"+ch.BestSlug), ch.BestNANDs, ch.BestDepth, shortAddr(ch.BestAuthor)))
	}
	b.WriteString("\n")
	b.WriteString(ufmt.Sprintf(`<gno-button href="%s" label="Test Solution in Zero-Wallet Sandbox" variant="tip" />`, realmLink("sandbox?challenge="+ch.Spec.ID)))
	b.WriteString("\n\n")

	// Ranked Submissions
	b.WriteString("## Verified Submissions (Sorted by NANDs ↑, Depth ↑)\n\n")
	b.WriteString("| Rank | Chip | Title | NANDs | Depth | Sub-Chips | Reuses | Author |\n")
	b.WriteString("|---|---|---|---|---|---|---|---|\n")
	rankedLimit := len(ranked)
	if rankedLimit > MaxDisplayRows {
		rankedLimit = MaxDisplayRows
	}
	for i := 0; i < rankedLimit; i++ {
		e := ranked[i]
		rankStr := ufmt.Sprintf("#%d", i+1)
		if i == 0 {
			rankStr = "#1 ★"
		}
		b.WriteString(ufmt.Sprintf("| %s | [`%s`](%s) | %s | **%d** | %d | %d | %d | `%s` |\n",
			rankStr, e.Slug, realmLink("chip/"+e.Slug),
			sanitize.TableCell(e.Title), e.NANDCount, e.Depth,
			len(e.ImportedChips), e.ReuseCount, shortAddr(e.Author)))
	}
	if len(ranked) > rankedLimit {
		b.WriteString(ufmt.Sprintf("\n*Showing top %d of %d verified submissions.*\n", rankedLimit, len(ranked)))
	}

	// Sample Truth Table (up to 8 vectors)
	b.WriteString("\n## Truth Table Preview\n\n")
	b.WriteString("| Case | Inputs (`" + strings.Join(ch.Spec.Inputs, " ") + "`) | Expected Outputs (`" + strings.Join(ch.Spec.Outputs, " ") + "`) |\n")
	b.WriteString("|---|---|---|\n")
	lim := len(ch.Spec.Vectors)
	if lim > 8 {
		lim = 8
	}
	for i := 0; i < lim; i++ {
		vec := ch.Spec.Vectors[i]
		b.WriteString(ufmt.Sprintf("| %s | `%s` | `%s` |\n",
			sanitize.TableCell(vec.Label), nl.FormatBits(vec.In), nl.FormatBits(vec.Out)))
	}
	if len(ch.Spec.Vectors) > lim {
		b.WriteString(ufmt.Sprintf("\n*Showing first %d of %d verified vectors.*\n", lim, len(ch.Spec.Vectors)))
	}

	b.WriteString("\n## Publish Your Solution On-Chain\n\n")
	b.WriteString(renderSubmitForm(ch.Spec.ID, ch.Spec.StarterNetlist))

	res.Write(b.String())
}

func renderSandbox(res *mux.ResponseWriter, req *mux.Request) {
	chID := strings.TrimSpace(req.Query.Get("challenge"))
	if chID == "" || challenges.Get(chID) == nil {
		chID = "half_adder"
	}
	ch := challenges.Get(chID).(*ChallengeState)
	netlist := strings.TrimSpace(req.Query.Get("netlist"))
	bits := strings.TrimSpace(req.Query.Get("bits"))

	submitted := netlist != ""
	if !submitted {
		netlist = ch.Spec.StarterNetlist
	}
	if bits == "" {
		bits = defaultDemoBits(ch.Spec)
	}

	var b strings.Builder
	b.WriteString("# Zero-Wallet Live Circuit Sandbox\n\n")
	b.WriteString("Paste or edit any NAND / `chip:<slug>` netlist below and click **Submit to Realm**. GnoVM parses, cycle-checks, flattens sub-chips, verifies every test vector, and paints the live SVG schematic — **no wallet and zero gas required**.\n\n")
	b.WriteString(renderNav("sandbox"))

	// Evaluate immediately so judges see live output on first visit AND after editing!
	ast, parseErr := nl.Parse(netlist)
	if parseErr != nil {
		b.WriteString("> [!CAUTION]\n> **Parse Error:** " + sanitize.InlineText(parseErr.Error()) + "\n\n")
	} else {
		cc, compErr := nl.Compile(ast, resolveChip)
		if compErr != nil {
			b.WriteString("> [!CAUTION]\n> **Compile Error:** " + sanitize.InlineText(compErr.Error()) + "\n\n")
		} else {
			vr := nl.Verify(cc, ch.Spec)
			tr, evalErr := nl.EvalBits(cc, bits)
			if evalErr != nil {
				bits = defaultDemoBits(ch.Spec)
				tr, _ = nl.EvalBits(cc, bits)
			}
			if vr.Passed {
				beats := ch.BestSlug == "" || cc.NANDCount < ch.BestNANDs || (cc.NANDCount == ch.BestNANDs && cc.MaxDepth < ch.BestDepth)
				msg := ufmt.Sprintf("**VERIFIED (%d/%d vectors passed)** — **%d NANDs**, critical-path depth **%d**.",
					vr.PassedVectors, vr.TotalVectors, cc.NANDCount, cc.MaxDepth)
				if beats {
					msg += " **BEATS CURRENT RECORD!**"
				} else {
					msg += ufmt.Sprintf(" Current record: %d NANDs / depth %d (`%s`).", ch.BestNANDs, ch.BestDepth, ch.BestSlug)
				}
				b.WriteString("> [!TIP]\n> " + msg + "\n\n")
			} else {
				b.WriteString("> [!WARNING]\n> **VERIFICATION FAILED:** " + sanitize.InlineText(vr.ErrorMessage) + "\n\n")
			}

			b.WriteString(nl.RenderSchematicSVG("Sandbox · "+ch.Spec.ID, cc, tr) + "\n\n")
			if vr.ErrorMessage == "" || vr.FailedIndex >= 0 {
				b.WriteString(nl.RenderWaveformSVG("Sandbox · "+ch.Spec.ID, cc, ch.Spec, 8) + "\n\n")
			}
		}
	}

	b.WriteString("## Edit & Simulate (Zero-TX Form)\n\n")
	b.WriteString("<gno-form path=\"sandbox\">\n")
	for i := 0; i < len(challengeOrder); i++ {
		cid := challengeOrder[i]
		sel := ""
		if cid == chID {
			sel = ` selected="true"`
		}
		b.WriteString(ufmt.Sprintf(`<gno-select name="challenge" value="%s"%s />`+"\n", cid, sel))
	}
	b.WriteString(ufmt.Sprintf(`<gno-input name="bits" description="Input bitstring for live SVG probe" placeholder="e.g. %s" value="%s" />`+"\n", defaultDemoBits(ch.Spec), escapeAttrVal(bits)))
	b.WriteString(ufmt.Sprintf(`<gno-textarea name="netlist" description="NAND + chip:<slug> netlist" placeholder="Enter NAND netlist..." value="%s" rows="8" />`+"\n", escapeTextareaVal(netlist)))
	b.WriteString("</gno-form>\n\n")

	b.WriteString("### Quick DSL Reference\n\n")
	b.WriteString("- Declare pins first: `in a, b` and `out sum, carry`\n")
	b.WriteString("- Primitives: `w = nand(a, b)`, `z = const0()`, `o = const1()`, `y = buf(w)`\n")
	b.WriteString("- Import any verified on-chain chip: `s1, c1 = chip:half_adder_ref(a, b)`\n")
	b.WriteString(ufmt.Sprintf("- Caps: ≤%d flattened NANDs, ≤%d nesting depth, acyclic combinational only.\n", nl.MaxFlatGates, nl.MaxChipDepth))

	res.Write(b.String())
}

func renderChips(res *mux.ResponseWriter, _ *mux.Request) {
	all := make([]*ChipEntry, 0, chips.Size())
	chips.Iterate("", "", func(_ string, v any) bool {
		all = append(all, v.(*ChipEntry))
		return false
	})
	all = mergeSortChips(all, chipLibraryBetter)
	limit := len(all)
	if limit > MaxDisplayRows {
		limit = MaxDisplayRows
	}

	var b strings.Builder
	b.WriteString("# Verified Composable Chip Library\n\n")
	b.WriteString(ufmt.Sprintf("Showing top %d of %d verified chips permanently importable via `chip:<slug>(...)`.\n\n", limit, len(all)))
	b.WriteString(renderNav("chips"))

	b.WriteString("| Chip | Challenge | Title | NANDs | Depth | Imports | Reused By | Author |\n")
	b.WriteString("|---|---|---|---|---|---|---|---|\n")
	for i := 0; i < limit; i++ {
		e := all[i]
		b.WriteString(ufmt.Sprintf("| [`%s`](%s) | [`%s`](%s) | %s | **%d** | %d | %d | **%d** | `%s` |\n",
			e.Slug, realmLink("chip/"+e.Slug),
			e.ChallengeID, realmLink("challenge/"+e.ChallengeID),
			sanitize.TableCell(e.Title), e.NANDCount, e.Depth,
			len(e.ImportedChips), e.ReuseCount, shortAddr(e.Author)))
	}
	res.Write(b.String())
}

func renderLeaderboard(res *mux.ResponseWriter, _ *mux.Request) {
	var b strings.Builder
	b.WriteString("# Deterministic Silicon Leaderboard\n\n")
	b.WriteString("100% objective and rule-decided: ranked by **Records Held** (lowest flattened NAND count, tie-broken by shallowest critical-path depth), then **Cross-Chip Reuse Count**.\n\n")
	b.WriteString(renderNav("leaderboard"))

	b.WriteString("## Top Architects\n\n")
	b.WriteString("| Rank | Builder | Records Held | Sub-Chip Reuses | Challenges Solved | Verified Chips |\n")
	b.WriteString("|---|---|---|---|---|---|\n")
	sb := sortedBuilders()
	limitB := len(sb)
	if limitB > MaxDisplayRows {
		limitB = MaxDisplayRows
	}
	for i := 0; i < limitB; i++ {
		bp := sb[i]
		b.WriteString(ufmt.Sprintf("| #%d | `%s` | **%d** | **%d** | %d / %d | %d |\n",
			i+1, shortAddr(bp.Address), bp.RecordsHeld, bp.TotalReuses,
			len(bp.SolvedChallenges), len(challengeOrder), bp.ChipsSubmitted))
	}

	b.WriteString("\n## Challenge Records\n\n")
	b.WriteString("| Challenge | Record Chip | NANDs (Par) | Depth (Par) | Holder |\n")
	b.WriteString("|---|---|---|---|---|\n")
	for i := 0; i < len(challengeOrder); i++ {
		ch := challenges.Get(challengeOrder[i]).(*ChallengeState)
		if ch.BestSlug == "" {
			continue
		}
		b.WriteString(ufmt.Sprintf("| [%s](%s) | [`%s`](%s) | **%d** (%d) | **%d** (%d) | `%s` |\n",
			sanitize.TableCell(ch.Spec.Title), realmLink("challenge/"+ch.Spec.ID),
			ch.BestSlug, realmLink("chip/"+ch.BestSlug),
			ch.BestNANDs, ch.Spec.ParNANDs, ch.BestDepth, ch.Spec.ParDepth, shortAddr(ch.BestAuthor)))
	}
	res.Write(b.String())
}

func renderSubmit(res *mux.ResponseWriter, req *mux.Request) {
	chID := strings.TrimSpace(req.Query.Get("challenge"))
	if chID == "" || challenges.Get(chID) == nil {
		chID = "half_adder"
	}
	ch := challenges.Get(chID).(*ChallengeState)

	var b strings.Builder
	b.WriteString("# Submit a Verified Chip On-Chain\n\n")
	b.WriteString("Submitting calls `SubmitChip(challengeID, slug, title, notes, netlist)`. Invalid syntax, cycles, gate-cap violations, or any failing test vector revert atomically.\n\n")
	b.WriteString(renderNav("submit"))
	b.WriteString(renderSubmitForm(ch.Spec.ID, ch.Spec.StarterNetlist))
	res.Write(b.String())
}

func renderSubmitForm(defaultChallenge, starterNetlist string) string {
	var b strings.Builder
	b.WriteString("<gno-form exec=\"SubmitChip\">\n")
	for i := 0; i < len(challengeOrder); i++ {
		cid := challengeOrder[i]
		sel := ""
		if cid == defaultChallenge {
			sel = ` selected="true"`
		}
		b.WriteString(ufmt.Sprintf(`<gno-select name="challengeID" value="%s"%s />`+"\n", cid, sel))
	}
	b.WriteString(`<gno-input name="slug" description="Unique chip slug (lowercase letters, digits, _ or -)" placeholder="e.g. half_adder_v1" required="true" />` + "\n")
	b.WriteString(`<gno-input name="title" description="Short descriptive title" placeholder="e.g. 5-NAND Shared Half Adder" required="true" />` + "\n")
	b.WriteString(`<gno-input name="notes" description="Optional architecture notes" placeholder="How you optimized gates or depth" />` + "\n")
	b.WriteString(ufmt.Sprintf(`<gno-textarea name="netlist" description="NAND + chip:<slug> netlist" placeholder="Paste netlist..." value="%s" rows="8" required="true" />`+"\n", escapeTextareaVal(starterNetlist)))
	b.WriteString("</gno-form>\n")
	return b.String()
}

func renderNotFound(res *mux.ResponseWriter, req *mux.Request) {
	var b strings.Builder
	b.WriteString("# Route Not Found\n\n")
	b.WriteString(renderNav(""))
	b.WriteString("Unknown path `" + sanitize.InlineText(req.RawPath) + "`.\n")
	res.Write(b.String())
}

func escapeAttrVal(s string) string {
	s = strings.ReplaceAll(s, "\r", "")
	s = strings.ReplaceAll(s, "\n", " ")
	return sanitize.HTMLEscape(s)
}

func escapeTextareaVal(s string) string {
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	s = sanitize.HTMLEscape(s)
	s = strings.ReplaceAll(s, "\t", `\t`)
	s = strings.ReplaceAll(s, "\n", `\n`)
	return s
}

func chipLibraryBetter(a, b *ChipEntry) bool {
	if a.ReuseCount != b.ReuseCount {
		return a.ReuseCount > b.ReuseCount
	}
	if a.NANDCount != b.NANDCount {
		return a.NANDCount < b.NANDCount
	}
	return a.Slug < b.Slug
}

func formatPinVals(names []string, vals []bool) string {
	parts := make([]string, len(names))
	for i := 0; i < len(names); i++ {
		bit := "0"
		if vals[i] {
			bit = "1"
		}
		parts[i] = names[i] + "=" + bit
	}
	return strings.Join(parts, " ")
}

package nandloom

import (
	nl "gno.land/p/g1jxrrf695x7r3h0wqvmkq2vyyqy39wjraxyph3j/nandloom/v0"
)

const (
	MaxTitleLen                = 64
	MaxNotesLen                = 200
	MaxImportersCap            = 64
	MaxSubmissionsPerBuilder   = 64
	MaxSubmissionsPerChallenge = 512
	MaxDisplayRows             = 100
	MaxSnapshotChips           = 200
)

// ChipEntry stores an immutable verified circuit published on-chain.
// Immutability guarantees that higher-level chips importing chip:<slug> never
// break retroactively.
type ChipEntry struct {
	Slug          string
	ChallengeID   string
	Title         string
	Notes         string
	Author        address
	BlockHeight   int64
	Netlist       string
	AST           *nl.Circuit
	Compiled      *nl.CompiledCircuit
	NANDCount     int
	Depth         int
	ModuleCount   int
	ImportedChips []string
	ReuseCount    int
	Importers     []string
}

// ChallengeState tracks the specification, current record holder, and all
// verified chips solving a challenge.
type ChallengeState struct {
	Spec            nl.ChallengeSpec
	BestSlug        string
	BestNANDs       int
	BestDepth       int
	BestAuthor      address
	SubmissionSlugs []string
}

// BuilderProfile tracks objective, deterministic builder achievements.
type BuilderProfile struct {
	Address          address
	ChipsSubmitted   int
	RecordsHeld      int
	TotalReuses      int
