}

// Package onyx is the GNO Ordnance map realm (v2).
// One labelled snapshot, loaded atomically in a single transaction.
// Districts are defined independently of plots, so empty ones render as open ground.
// Render paths: "" overview | "<district>" detail | "data/districts" | "data/plots"
package ordnance

import (
	"chain/runtime/unsafe"
	"strconv"
	"strings"
)

type District struct {
	Name string
	X, Z int // world centre
	R    int // radius
}

type Plot struct {
	Path, District, Name, Last string
	Txs                        int
	X, Z                       int // offset from district centre
}

var (
	admin     address
	label     string
	date      string
	districts []District
	plots     []Plot
	maxTxs    int
)

const openGround = 2

func init() {
	admin = unsafe.PreviousRealm().Address()
}

func atoi(s string) int {
	n, err := strconv.Atoi(strings.TrimSpace(s))
	if err != nil {
		panic("onyx: bad number: " + s)
	}
	return n
}

// LoadSnapshot replaces the whole map in one transaction.
// districtsCSV rows: name,x,z,radius
// plotsCSV rows:     path,district,name,txs,x,z,last   (last may contain commas)
func LoadSnapshot(cur realm, snapLabel, snapDate, districtsCSV, plotsCSV string) {
	if cur.Previous().Address() != admin {
		panic("onyx: admin only")
	}

	var ds []District
	seen := map[string]bool{}
	for _, row := range strings.Split(districtsCSV, "\n") {
		row = strings.TrimSpace(row)
		if row == "" {
			continue
		}
		f := strings.Split(row, ",")
		if len(f) != 4 {
			panic("onyx: district row needs 4 fields: " + row)
		}
		name := strings.ToLower(strings.TrimSpace(f[0]))
		if seen[name] {
			panic("onyx: duplicate district " + name)
		}
		seen[name] = true
		ds = append(ds, District{name, atoi(f[1]), atoi(f[2]), atoi(f[3])})
	}
	if len(ds) == 0 {
		panic("onyx: no districts")
	}

	var ps []Plot
	mx := 0
	for _, row := range strings.Split(plotsCSV, "\n") {
		row = strings.TrimSpace(row)
		if row == "" {
			continue
		}
		f := strings.SplitN(row, ",", 7)
		if len(f) != 7 {
			panic("onyx: plot row needs 7 fields: " + row)
		}
		d := strings.ToLower(strings.TrimSpace(f[1]))
		if !seen[d] {
			panic("onyx: unknown district " + d)
		}
		txs := atoi(f[3])
		if txs < 0 {
			panic("onyx: negative txs")
		}
		if txs > mx {
			mx = txs
		}
		ps = append(ps, Plot{strings.TrimSpace(f[0]), d, strings.TrimSpace(f[2]),
			strings.TrimSpace(f[6]), txs, atoi(f[4]), atoi(f[5])})
	}

	// all parsed and validated: commit
	label, date, districts, plots, maxTxs = snapLabel, snapDate, ds, ps, mx
}

func height(txs int) int {
	if maxTxs == 0 {
		return 0
	}
	v := txs * 10000 / maxTxs
	r := 0
	for (r+1)*(r+1) <= v {
		r++
	}
	return r
}

func tier(h int) string {
	switch {
	case h >= 70:
		return "Mountain"
	case h >= 40:
		return "Ridge"
	case h >= 15:
		return "Hill"
	}
	return "Mound"
}

func in(d string) []Plot {
	var out []Plot
	for _, p := range plots {
		if p.District == d {
			out = append(out, p)
		}
	}
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && out[j].Txs > out[j-1].Txs; j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}

func find(name string) (District, bool) {
	for _, d := range districts {
		if d.Name == name {
			return d, true
		}
	}
	return District{}, false
}

func clean(s string) string { return strings.ReplaceAll(s, ",", ";") }

func Render(path string) string {
	if len(districts) == 0 {
		return "# GNO Ordnance\n\nNo snapshot loaded yet."
	}
	switch path {
	case "":
		return overview()
	case "data/districts":
		s := "name,x,z,radius,realms\n"
		for _, d := range districts {
			s += d.Name + "," + strconv.Itoa(d.X) + "," + strconv.Itoa(d.Z) + "," +
				strconv.Itoa(d.R) + "," + strconv.Itoa(len(in(d.Name))) + "\n"
		}
		return s
	case "data/plots":
		s := "path,district,name,txs,height,tier,x,z,last\n"
		for _, p := range plots {
			d, _ := find(p.District)
			h := height(p.Txs)
			s += p.Path + "," + p.District + "," + p.Name + "," + strconv.Itoa(p.Txs) + "," +
				strconv.Itoa(h) + "," + tier(h) + "," + strconv.Itoa(d.X+p.X) + "," +
				strconv.Itoa(d.Z+p.Z) + "," + clean(p.Last) + "\n"
		}
		return s
	}
	d, ok := find(strings.ToLower(path))
	if !ok {
		return "# Not on the map\n\nNo district `" + path + "`.\n\n[Back to map](:)"
	}
	return detail(d)
}

func overview() string {
	s := "# GNO Ordnance\n\nSnapshot: **" + label + "** (" + date + ")  \n"
	s += strconv.Itoa(len(plots)) + " realms across " + strconv.Itoa(len(districts)) + " districts.\n\n"
	for _, d := range districts {
		ps := in(d.Name)
		s += "## [" + d.Name + "](:" + d.Name + ")\n"
		if len(ps) == 0 {
			s += "**Open ground**: nothing built yet.\n\n"
			continue
		}
		pk := height(ps[0].Txs)
		s += strconv.Itoa(len(ps)) + " realms, peak " + ps[0].Name + " (" + tier(pk) + ", " + strconv.Itoa(pk) + ")"
		if len(ps) <= openGround {
			s += "  \n**Open ground**: barely built."
		}
		s += "\n\n"
	}
	return s
}

func detail(d District) string {
	ps := in(d.Name)
	s := "# " + d.Name + " district\n\nSnapshot: " + label + " (" + date + ")\n\n"
	if len(ps) == 0 {
		return s + "> Open ground: no realms here yet.\n\n[Back to map](:)"
	}
	if len(ps) <= openGround {
		s += "> Open ground: only " + strconv.Itoa(len(ps)) + " realm(s).\n\n"
	}
	for _, p := range ps {
		h := height(p.Txs)
		s += "### " + p.Name + " (" + tier(h) + ", " + strconv.Itoa(h) + ")\n"
		s += strconv.Itoa(p.Txs) + " txs. " + p.Last + "  \n"
		s += "[Enter realm](/" + strings.TrimPrefix(p.Path, "gno.land/") + ")\n\n"
	}
	return s + "[Back to map](:)"
}

// Package escrow holds the rules of a single-builder bounty escrow: the
// Quest type, its states and every legal move between them.
//
// The package is pure. It holds no coins, no banker and no storage. A realm
// that imports it keeps the *Quest values, moves the coins, and asks this
// package whether a move is allowed. Every move takes the acting address and
// the current block height as arguments, so the rules can be tested without a
// chain and cannot be bypassed by the caller's own logic.
//
// Moves that can release money (Cancel, Unclaim, Release, Approve, Reject,
// ClaimPayout) return a Payout telling the realm exactly whom to pay and how
// much; a zero Payout (Due() == false) means no coins move. A non-zero Payout
// is only ever returned together with a move into a final state (Paid or
// Cancelled), and a final quest accepts no further move, so a quest can
// produce at most one non-zero Payout.
//
// A realm using this package must:
//   - lock exactly Reward() in its own balance before calling NewQuest,
//   - apply the move first and send the coins of the returned Payout after,
//   - treat any returned error as fatal (panic) so the transaction reverts.
//
// States and moves:
//
//	(none)    Post (NewQuest)  anyone                        -> Open
//	Open      Claim            anyone except the poster      -> Claimed
//	Open      Cancel           poster                        -> Cancelled  refund Reward to poster
//	Claimed   Cancel ("close") poster                        -> Claimed, closing
//	Submitted Cancel ("close") poster                        -> Submitted, closing
//	Claimed   Submit(link)     builder, until work deadline  -> Submitted
//	Claimed   Unclaim          builder                       -> Open (closing: Cancelled, refund)
//	Claimed   Release          anyone, after work deadline   -> Open (closing: Cancelled, refund)
//	Submitted Approve          poster                        -> Paid       pay Reward to builder
//	Submitted Reject(reason)   poster, until review deadline -> Open (closing: Cancelled, refund)
//	Submitted ClaimPayout      builder, after review deadline-> Paid       pay Reward to builder
//
// Closing: a poster cannot take the reward back while a builder holds the
// quest, but can close it. The current builder keeps every right (submit,
// get approved, claim the timeout payout); any move that would put the quest
// back to Open ends it instead and refunds the poster. So a builder can hold
// a closing quest for at most one work window, and nobody can re-claim it.
// Closing cannot be undone.
//
// Deadlines are block heights. "Until" a deadline includes the deadline block
// itself; "after" a deadline starts at the next block.
package escrow

import (
	"errors"
	"strings"
	"unicode"
	"unicode/utf8"
)

// Limits. Text limits count Unicode characters (runes).
const (
	MaxTitleLen   = 80
	MaxDetailsLen = 1000
	MaxLinkLen    = 300
	MaxReasonLen  = 300

	// Windows are in blocks. Measured block time on 2026-11-23 was about
	// 3.4 s (Onyx) to 3.5 s (mainnet); the values below assume 3.5 s.
	// See docs/gno-notes.md for the maths.

	// MinWorkBlocks and MaxWorkBlocks bound the work window a poster may set:
	// about 1 hour and about 90 days.
	MinWorkBlocks int64 = 1_000
	MaxWorkBlocks int64 = 2_200_000

	// ReviewBlocks is the fixed review window every quest gets after Submit,
	// about 7 days. If the poster neither approves nor rejects within it, the
	// builder may call ClaimPayout.
	ReviewBlocks int64 = 172_800
)

// State is the stage a quest is in.
type State uint8

const (
	// Open: waiting for a builder.
	Open State = iota + 1
	// Claimed: a builder is working on it.
	Claimed
	// Submitted: work link sent, waiting for the poster's review.
	Submitted
	// Paid: reward paid to the builder. Final.
	Paid
	// Cancelled: reward refunded to the poster. Final.
	Cancelled
)

// String returns the state name.
func (s State) String() string {
	switch s {
	case Open:
		return "Open"
	case Claimed:
		return "Claimed"
	case Submitted:
		return "Submitted"
	case Paid:
		return "Paid"
	case Cancelled:
		return "Cancelled"
	}
	return "Unknown"
}

// IsFinal reports whether no further move is possible from s.
func (s State) IsFinal() bool {
	return s == Paid || s == Cancelled
}

// PayoutKind says why coins must move.
type PayoutKind uint8

const (
	// PayBuilder: send the reward to the builder (Approve, ClaimPayout).
	PayBuilder PayoutKind = iota + 1
	// RefundPoster: send the reward back to the poster (Cancel).
	RefundPoster
)

// String returns the payout kind name.
func (k PayoutKind) String() string {
	switch k {
	case PayBuilder:
		return "PayBuilder"
	case RefundPoster:
		return "RefundPoster"
	}
	return "Unknown"
}

// Payout is the transfer a realm must make after a successful move. The zero
// Payout means no transfer. When Due, Amount is always the quest's stored
// Reward.
type Payout struct {
	Kind   PayoutKind
	To     address
	Amount int64
}

// Due reports whether coins must move.
func (p Payout) Due() bool {
	return p.Kind != 0
}

// Errors returned by the moves. Realms usually panic with err.Error().
var (
	ErrInvalidPoster     = errors.New("escrow: invalid poster address")
	ErrInvalidActor      = errors.New("escrow: invalid caller address")
	ErrInvalidReward     = errors.New("escrow: reward must be positive")
	ErrInvalidHeight     = errors.New("escrow: invalid block height")
	ErrTitleEmpty        = errors.New("escrow: title is empty")
	ErrTitleTooLong      = errors.New("escrow: title is too long")
	ErrTitleControlChar  = errors.New("escrow: title must not contain control characters such as newlines or tabs")
	ErrDetailsTooLong    = errors.New("escrow: details are too long")
	ErrWorkBlocksTooLow  = errors.New("escrow: work window is below the minimum")
	ErrWorkBlocksTooHigh = errors.New("escrow: work window is above the maximum")
	ErrLinkEmpty         = errors.New("escrow: work link is empty")
	ErrLinkTooLong       = errors.New("escrow: work link is too long")
	ErrLinkNotHTTPS      = errors.New("escrow: work link must start with https://")
	ErrLinkInvalid       = errors.New("escrow: work link contains spaces or control characters")
	ErrReasonEmpty       = errors.New("escrow: reject reason is empty")
	ErrReasonTooLong     = errors.New("escrow: reject reason is too long")
	ErrInvalidText       = errors.New("escrow: text is not valid UTF-8")

	ErrWrongState              = errors.New("escrow: move not allowed in the quest's current state")
	ErrNotPoster               = errors.New("escrow: only the poster can do this")
	ErrNotBuilder              = errors.New("escrow: only the builder can do this")
	ErrPosterCannotClaim       = errors.New("escrow: the poster cannot claim their own quest")
	ErrWorkDeadlinePassed      = errors.New("escrow: work deadline has passed")
	ErrWorkDeadlineNotPassed   = errors.New("escrow: work deadline has not passed yet")
	ErrReviewDeadlinePassed    = errors.New("escrow: review deadline has passed")
	ErrReviewDeadlineNotPassed = errors.New("escrow: review deadline has not passed yet")
	ErrAlreadyClosing          = errors.New("escrow: the quest is already closing")
)

// Quest is one bounty. Its fields are private so that only the moves below
// can change it; read them with the getters.
type Quest struct {
	id          uint64
	poster      address
	title       string
	details     string
	reward      int64
	state       State
	builder     address
	workLink    string
	workBlocks  int64
	createdAt   int64
	claimedAt   int64
	submittedAt int64

	rejectCount      int
	lastRejectReason string

	closing bool // set by Cancel on a Claimed or Submitted quest
}

// NewQuest validates a new quest and returns it in the Open state. The caller
// must already hold reward (in its own coin) for this quest. id is chosen by
// the caller and is not checked for uniqueness here.
func NewQuest(id uint64, poster address, title, details string, reward, workBlocks, height int64) (*Quest, error) {
	if !poster.IsValid() {
		return nil, ErrInvalidPoster
	}
	if reward <= 0 {
		return nil, ErrInvalidReward
	}
	if height < 0 {
		return nil, ErrInvalidHeight
	}
	if err := ValidateTitle(title); err != nil {
		return nil, err
	}
	if err := ValidateDetails(details); err != nil {
		return nil, err
	}
	if err := ValidateWorkBlocks(workBlocks); err != nil {
		return nil, err
	}
	return &Quest{
		id:         id,
		poster:     poster,
		title:      title,
		details:    details,
		reward:     reward,
		state:      Open,
		workBlocks: workBlocks,
		createdAt:  height,
	}, nil
}

// Claim lets anyone except the poster take an Open quest. The work window
// starts at height.
func (q *Quest) Claim(actor address, height int64) error {
	if q.state != Open {
		return ErrWrongState
	}
	if !actor.IsValid() {
		return ErrInvalidActor
	}
	if actor == q.poster {
		return ErrPosterCannotClaim
	}
	if height < q.createdAt {
		return ErrInvalidHeight
	}
	q.state = Claimed
	q.builder = actor
	q.claimedAt = height
	return nil
}

// Cancel is the poster's way out.
//   - On an Open quest it ends the quest at once: Cancelled, and the returned
//     Payout refunds the reward to the poster.
//   - On a Claimed or Submitted quest it only marks the quest as closing and
//     returns a zero Payout: the current builder keeps every right, and the
//     reward goes back to the poster when the builder's turn ends without
//     approval (Unclaim, Release or Reject). A second call fails.
func (q *Quest) Cancel(actor address, height int64) (Payout, error) {
	switch q.state {
	case Open, Claimed, Submitted:
	default:
		return Payout{}, ErrWrongState
	}
	if actor != q.poster {
		return Payout{}, ErrNotPoster
	}
	if q.state == Open {
		return q.cancel(), nil
	}
	if q.closing {
		return Payout{}, ErrAlreadyClosing
	}
	q.closing = true
	return Payout{}, nil
}

// Submit lets the builder hand in a work link, up to and including the work
// deadline block. The review window starts at height.
func (q *Quest) Submit(actor address, link string, height int64) error {
	if q.state != Claimed {
		return ErrWrongState
	}
	if actor != q.builder {
		return ErrNotBuilder
	}
	if height < q.claimedAt {
		return ErrInvalidHeight
	}
	if height > q.WorkDeadline() {
		return ErrWorkDeadlinePassed
	}
	if err := ValidateLink(link); err != nil {
		return err
	}
	q.state = Submitted
	q.workLink = link
	q.submittedAt = height
	return nil
}

// Unclaim lets the builder give a Claimed quest back. It becomes Open again,
// or, if it is closing, Cancelled with a refund to the poster.
func (q *Quest) Unclaim(actor address, height int64) (Payout, error) {
	if q.state != Claimed {
		return Payout{}, ErrWrongState
	}
	if actor != q.builder {
		return Payout{}, ErrNotBuilder
	}
	return q.endTurn(), nil
}

// Release lets anyone end the builder's turn on a Claimed quest once the
// work deadline has passed (from WorkDeadline()+1 on) without a submission.
// The quest becomes Open again, or, if it is closing, Cancelled with a refund
// to the poster.
func (q *Quest) Release(actor address, height int64) (Payout, error) {
	if q.state != Claimed {
		return Payout{}, ErrWrongState
	}
	if !actor.IsValid() {
		return Payout{}, ErrInvalidActor
	}
	if height <= q.WorkDeadline() {
		return Payout{}, ErrWorkDeadlineNotPassed
	}
	return q.endTurn(), nil
}

// Approve lets the poster accept the submitted work. The returned Payout pays
// the reward to the builder. Approving after the review deadline is allowed:
// it pays the same builder as ClaimPayout would.
func (q *Quest) Approve(actor address, height int64) (Payout, error) {
	if q.state != Submitted {
		return Payout{}, ErrWrongState
	}
	if actor != q.poster {
		return Payout{}, ErrNotPoster
	}
	q.state = Paid
	return Payout{Kind: PayBuilder, To: q.builder, Amount: q.reward}, nil
}

// Reject lets the poster refuse the submitted work, up to and including the
// review deadline block. The builder is cleared, and the reject count and
// last reason are kept on the quest for everyone to see. The quest becomes
// Open again, or, if it is closing, Cancelled with a refund to the poster.
func (q *Quest) Reject(actor address, reason string, height int64) (Payout, error) {
	if q.state != Submitted {
		return Payout{}, ErrWrongState
	}
	if actor != q.poster {
		return Payout{}, ErrNotPoster
	}
	if height > q.ReviewDeadline() {
		return Payout{}, ErrReviewDeadlinePassed
	}
	if err := ValidateReason(reason); err != nil {
		return Payout{}, err
	}
	q.rejectCount++
	q.lastRejectReason = reason
	return q.endTurn(), nil
}

// ClaimPayout lets the builder take the reward when the poster has not
// answered within the review window (from ReviewDeadline()+1 on). The
// returned Payout pays the reward to the builder.
func (q *Quest) ClaimPayout(actor address, height int64) (Payout, error) {
	if q.state != Submitted {
		return Payout{}, ErrWrongState
	}
	if actor != q.builder {
		return Payout{}, ErrNotBuilder
	}
	if height <= q.ReviewDeadline() {
		return Payout{}, ErrReviewDeadlineNotPassed
	}
	q.state = Paid
	return Payout{Kind: PayBuilder, To: q.builder, Amount: q.reward}, nil
}

// endTurn ends the current builder's turn: it clears the builder and the
// work, then puts the quest back to Open, or, if it is closing, cancels it
// and returns the refund.
func (q *Quest) endTurn() Payout {
	q.builder = ""
	q.workLink = ""
	q.claimedAt = 0
	q.submittedAt = 0
	if q.closing {
		return q.cancel()
	}
	q.state = Open
	return Payout{}
}

// cancel ends the quest and returns the refund to the poster. It is the only
// place that returns a RefundPoster payout.
func (q *Quest) cancel() Payout {
	q.state = Cancelled
	return Payout{Kind: RefundPoster, To: q.poster, Amount: q.reward}
}

// WorkDeadline is the last block at which the builder may submit. It is 0
// unless the quest is Claimed or Submitted.
func (q *Quest) WorkDeadline() int64 {
	if q.state != Claimed && q.state != Submitted {
		return 0
	}
	return q.claimedAt + q.workBlocks
}

// ReviewDeadline is the last block at which the poster may reject. It is 0
// unless the quest is Submitted.
func (q *Quest) ReviewDeadline() int64 {
	if q.state != Submitted {
		return 0
	}
	return q.submittedAt + ReviewBlocks
}

// CanRelease reports whether Release would succeed at height.
func (q *Quest) CanRelease(height int64) bool {
	return q.state == Claimed && height > q.WorkDeadline()
}

// CanClaimPayout reports whether the builder could call ClaimPayout at height.
func (q *Quest) CanClaimPayout(height int64) bool {
	return q.state == Submitted && height > q.ReviewDeadline()
}

// Getters.

func (q *Quest) ID() uint64               { return q.id }
func (q *Quest) Poster() address          { return q.poster }
func (q *Quest) Title() string            { return q.title }
func (q *Quest) Details() string          { return q.details }
func (q *Quest) Reward() int64            { return q.reward }
func (q *Quest) State() State             { return q.state }
func (q *Quest) Builder() address         { return q.builder }
func (q *Quest) WorkLink() string         { return q.workLink }
func (q *Quest) WorkBlocks() int64        { return q.workBlocks }
func (q *Quest) CreatedAt() int64         { return q.createdAt }
func (q *Quest) ClaimedAt() int64         { return q.claimedAt }
func (q *Quest) SubmittedAt() int64       { return q.submittedAt }
func (q *Quest) RejectCount() int         { return q.rejectCount }
func (q *Quest) LastRejectReason() string { return q.lastRejectReason }

// Closing reports whether the poster has closed the quest while a builder
// held it: the reward returns to the poster when the builder's turn ends
// without approval.
func (q *Quest) Closing() bool { return q.closing }

// HoldsFunds reports whether the quest's reward is still held in escrow
// (Open, Claimed or Submitted). The sum of Reward() over quests that hold
// funds must equal what the realm holds for them.
func (q *Quest) HoldsFunds() bool {
	return !q.state.IsFinal()
}

// Validators. They are exported so a realm can check input early.

// ValidateTitle checks a quest title: not blank, at most MaxTitleLen
// characters, and no control characters (newline, tab, etc.) or Unicode line
// and paragraph separators, because titles are shown inside Markdown tables
// and links.
func ValidateTitle(s string) error {
	if !utf8.ValidString(s) {
		return ErrInvalidText
	}
	if strings.TrimSpace(s) == "" {
		return ErrTitleEmpty
	}
	if utf8.RuneCountInString(s) > MaxTitleLen {
		return ErrTitleTooLong
	}
	for _, r := range s {
		if unicode.IsControl(r) || r == '\u2028' || r == '\u2029' {
			return ErrTitleControlChar
		}
	}
	return nil
}

// ValidateDetails checks quest details: at most MaxDetailsLen characters (may be empty).
func ValidateDetails(s string) error {
	if !utf8.ValidString(s) {
		return ErrInvalidText
	}
	if utf8.RuneCountInString(s) > MaxDetailsLen {
		return ErrDetailsTooLong
	}
	return nil
}

// ValidateWorkBlocks checks that w is within [MinWorkBlocks, MaxWorkBlocks].
func ValidateWorkBlocks(w int64) error {
	if w < MinWorkBlocks {
		return ErrWorkBlocksTooLow
	}
	if w > MaxWorkBlocks {
		return ErrWorkBlocksTooHigh
	}
	return nil
}

// ValidateLink checks a work link: starts with "https://", has something
// after it, at most MaxLinkLen characters, and has no spaces or control
// characters.
func ValidateLink(s string) error {
	if s == "" {
		return ErrLinkEmpty
	}
	if !utf8.ValidString(s) {
		return ErrInvalidText
	}
	if utf8.RuneCountInString(s) > MaxLinkLen {
		return ErrLinkTooLong
	}
	if !strings.HasPrefix(s, "https://") || len(s) == len("https://") {
		return ErrLinkNotHTTPS
	}
	for _, r := range s {
		if r <= ' ' || r == 0x7f {
			return ErrLinkInvalid
		}
	}
	return nil
}

// ValidateReason checks a reject reason: not blank, at most MaxReasonLen characters.
func ValidateReason(s string) error {
	if !utf8.ValidString(s) {
		return ErrInvalidText
	}
	if strings.TrimSpace(s) == "" {
		return ErrReasonEmpty
	}
	if utf8.RuneCountInString(s) > MaxReasonLen {
		return ErrReasonTooLong
	}
	return nil
}

package escrow

import (
	"chain"
	"errors"
	"strings"
	"testing"
)

var (
	poster   = chain.PackageAddress("questmaster/test/poster")
	builder  = chain.PackageAddress("questmaster/test/builder")
	builder2 = chain.PackageAddress("questmaster/test/builder2")
	stranger = chain.PackageAddress("questmaster/test/stranger")
)

const (
	reward     int64 = 5_000_000
	workBlocks int64 = 2_000
	h0         int64 = 1000 // post height
)

// --- helpers ---

var errUnexpectedPayout = errors.New("test: unexpected payout")

// nopay turns a (Payout, error) move into an error, failing on any payout:
// for moves that must not release money (quests that are not closing).
func nopay(p Payout, err error) error {
	if err == nil && p.Due() {
		return errUnexpectedPayout
	}
	return err
}

func mustErr(t *testing.T, want, got error, what string) {
	t.Helper()
	if got != want {
		t.Fatalf("%s: want error %v, got %v", what, want, got)
	}
}

func mustOK(t *testing.T, err error, what string) {
	t.Helper()
	if err != nil {
		t.Fatalf("%s: unexpected error %v", what, err)
	}
}

func mustState(t *testing.T, q *Quest, want State) {
	t.Helper()
	if q.State() != want {
		t.Fatalf("state: want %s, got %s", want, q.State())
	}
}

func newOpen(t *testing.T) *Quest {
	t.Helper()
	q, err := NewQuest(1, poster, "Fix the docs typo", "Details here", reward, workBlocks, h0)
	mustOK(t, err, "NewQuest")
	return q
}

// claimed at h0+10, work deadline h0+10+workBlocks
func newClaimed(t *testing.T) *Quest {
	t.Helper()
	q := newOpen(t)
	mustOK(t, q.Claim(builder, h0+10), "Claim")
	return q
}

// submitted at h0+20, review deadline h0+20+ReviewBlocks
func newSubmitted(t *testing.T) *Quest {
	t.Helper()
	q := newClaimed(t)
	mustOK(t, q.Submit(builder, "https://github.com/x/y/pull/1", h0+20), "Submit")
	return q
}

func newPaid(t *testing.T) *Quest {
	t.Helper()
	q := newSubmitted(t)
	if _, err := q.Approve(poster, h0+30); err != nil {
		t.Fatalf("Approve: %v", err)
	}
	return q
}

func newCancelled(t *testing.T) *Quest {
	t.Helper()
	q := newOpen(t)
	if _, err := q.Cancel(poster, h0+5); err != nil {
		t.Fatalf("Cancel: %v", err)
	}
	return q
}

func mustPayout(t *testing.T, p Payout, kind PayoutKind, to address, amount int64) {
	t.Helper()
	if p.Kind != kind || p.To != to || p.Amount != amount {
		t.Fatalf("payout: want {%s %s %d}, got {%s %s %d}", kind, to, amount, p.Kind, p.To, p.Amount)
	}
}

// --- Post ---

func TestPost(t *testing.T) {
	q := newOpen(t)
	mustState(t, q, Open)
	if q.ID() != 1 || q.Poster() != poster || q.Reward() != reward || q.WorkBlocks() != workBlocks || q.CreatedAt() != h0 {
		t.Fatalf("fields not stored: %+v", q)
	}
	if q.Builder() != "" || q.WorkLink() != "" || q.RejectCount() != 0 {
		t.Fatalf("new quest must have no builder, link or rejects")
	}
	if !q.HoldsFunds() {
		t.Fatalf("open quest must hold funds")
	}
}

func TestPostInvalid(t *testing.T) {
	long := func(n int) string { return strings.Repeat("a", n) }
	cases := []struct {
		name    string
		poster  address
		title   string
		details string
		reward  int64
		work    int64
		height  int64
		want    error
	}{
		{"bad poster", "", "t", "", reward, workBlocks, h0, ErrInvalidPoster},
		{"bad poster 2", "notanaddress", "t", "", reward, workBlocks, h0, ErrInvalidPoster},
		{"zero reward", poster, "t", "", 0, workBlocks, h0, ErrInvalidReward},
		{"negative reward", poster, "t", "", -1, workBlocks, h0, ErrInvalidReward},
		{"negative height", poster, "t", "", reward, workBlocks, -1, ErrInvalidHeight},
		{"empty title", poster, "", "", reward, workBlocks, h0, ErrTitleEmpty},
		{"blank title", poster, "   ", "", reward, workBlocks, h0, ErrTitleEmpty},
		{"title too long", poster, long(MaxTitleLen + 1), "", reward, workBlocks, h0, ErrTitleTooLong},
		{"details too long", poster, "t", long(MaxDetailsLen + 1), reward, workBlocks, h0, ErrDetailsTooLong},
		{"invalid utf8", poster, "t\xff", "", reward, workBlocks, h0, ErrInvalidText},
		{"title newline", poster, "a\nb", "", reward, workBlocks, h0, ErrTitleControlChar},
		{"title tab", poster, "a\tb", "", reward, workBlocks, h0, ErrTitleControlChar},
		{"title CR", poster, "a\rb", "", reward, workBlocks, h0, ErrTitleControlChar},
		{"title NUL", poster, "a\x00b", "", reward, workBlocks, h0, ErrTitleControlChar},
		{"title DEL", poster, "a\x7fb", "", reward, workBlocks, h0, ErrTitleControlChar},
		{"title C1 NEL", poster, "a\u0085b", "", reward, workBlocks, h0, ErrTitleControlChar},
		{"title line separator", poster, "a\u2028b", "", reward, workBlocks, h0, ErrTitleControlChar},
		{"title paragraph separator", poster, "a\u2029b", "", reward, workBlocks, h0, ErrTitleControlChar},
		{"work too low", poster, "t", "", reward, MinWorkBlocks - 1, h0, ErrWorkBlocksTooLow},
		{"work too high", poster, "t", "", reward, MaxWorkBlocks + 1, h0, ErrWorkBlocksTooHigh},
	}
	for _, c := range cases {
		q, err := NewQuest(1, c.poster, c.title, c.details, c.reward, c.work, c.height)
		if err != c.want {
			t.Errorf("%s: want %v, got %v", c.name, c.want, err)
		}
		if err != nil && q != nil {
			t.Errorf("%s: quest returned with error", c.name)
		}
	}
}

// Titles may hold ordinary punctuation and non-ASCII letters; details and
// reject reasons may keep newlines (the realm's Render escapes them).
func TestTextAllowed(t *testing.T) {
	_, err := NewQuest(1, poster, "Fix | table [link](x) — ünïcode 日本", "line 1\nline 2\ttab", reward, workBlocks, h0)
	mustOK(t, err, "title punctuation, details with newline")
	q := newSubmitted(t)
	mustOK(t, nopay(q.Reject(poster, "first line\nsecond line", h0+30)), "reason with newline")
}

// The window constants are pinned so a change is a deliberate, reviewed edit.
func TestWindowConstants(t *testing.T) {
	if MinWorkBlocks != 1_000 || MaxWorkBlocks != 2_200_000 || ReviewBlocks != 172_800 {
		t.Fatalf("window constants changed: min %d max %d review %d", MinWorkBlocks, MaxWorkBlocks, ReviewBlocks)
	}
}

func TestPostLimitsExact(t *testing.T) {
	// exactly at the limits is allowed; limits count characters, not bytes
	title := strings.Repeat("é", MaxTitleLen) // 80 chars, 160 bytes
	details := strings.Repeat("a", MaxDetailsLen)
	_, err := NewQuest(1, poster, title, details, 1, MinWorkBlocks, 0)
	mustOK(t, err, "limits exact, min work")
	_, err = NewQuest(1, poster, "t", "", 1, MaxWorkBlocks, 0)
	mustOK(t, err, "max work, empty details")
}

// --- section 4 table, row by row ---

func TestOpenClaim(t *testing.T) {
	q := newOpen(t)
	mustOK(t, q.Claim(builder, h0+10), "Claim")
	mustState(t, q, Claimed)
	if q.Builder() != builder || q.ClaimedAt() != h0+10 || q.WorkDeadline() != h0+10+workBlocks {
		t.Fatalf("claim fields wrong")
	}
}

func TestOpenCancel(t *testing.T) {
	q := newOpen(t)
	p, err := q.Cancel(poster, h0+5)
	mustOK(t, err, "Cancel")
	mustState(t, q, Cancelled)
	mustPayout(t, p, RefundPoster, poster, reward)
	if q.HoldsFunds() {
		t.Fatalf("cancelled quest must not hold funds")
	}
}

func TestClaimedSubmit(t *testing.T) {
	q := newClaimed(t)
	mustOK(t, q.Submit(builder, "https://example.com/work", h0+20), "Submit")
	mustState(t, q, Submitted)
	if q.WorkLink() != "https://example.com/work" || q.SubmittedAt() != h0+20 || q.ReviewDeadline() != h0+20+ReviewBlocks {
		t.Fatalf("submit fields wrong")
	}
}

func TestClaimedUnclaim(t *testing.T) {
	q := newClaimed(t)
	mustOK(t, nopay(q.Unclaim(builder, h0+15)), "Unclaim")
	mustState(t, q, Open)
	if q.Builder() != "" || q.ClaimedAt() != 0 || q.WorkDeadline() != 0 {
		t.Fatalf("unclaim must clear builder")
	}
	// someone else can claim it now
	mustOK(t, q.Claim(builder2, h0+16), "re-claim")
}

func TestClaimedRelease(t *testing.T) {
	q := newClaimed(t)
	mustOK(t, nopay(q.Release(stranger, q.WorkDeadline()+1)), "Release")
	mustState(t, q, Open)
	if q.Builder() != "" {
		t.Fatalf("release must clear builder")
	}
}

func TestSubmittedApprove(t *testing.T) {
	q := newSubmitted(t)
	p, err := q.Approve(poster, h0+30)
	mustOK(t, err, "Approve")
	mustState(t, q, Paid)
	mustPayout(t, p, PayBuilder, builder, reward)
	if q.HoldsFunds() {
		t.Fatalf("paid quest must not hold funds")
	}
}

func TestSubmittedReject(t *testing.T) {
	q := newSubmitted(t)
	mustOK(t, nopay(q.Reject(poster, "missing tests", h0+30)), "Reject")
	mustState(t, q, Open)
	if q.Builder() != "" || q.WorkLink() != "" || q.SubmittedAt() != 0 {
		t.Fatalf("reject must clear builder and work")
	}
	if q.RejectCount() != 1 || q.LastRejectReason() != "missing tests" {
		t.Fatalf("reject count/reason wrong: %d %q", q.RejectCount(), q.LastRejectReason())
	}
	// count keeps going up over several rounds
	mustOK(t, q.Claim(builder2, h0+40), "claim 2")
	mustOK(t, q.Submit(builder2, "https://example.com/2", h0+41), "submit 2")
	mustOK(t, nopay(q.Reject(poster, "still wrong", h0+42)), "reject 2")
	if q.RejectCount() != 2 || q.LastRejectReason() != "still wrong" {
		t.Fatalf("second reject: %d %q", q.RejectCount(), q.LastRejectReason())
	}
}

func TestSubmittedClaimPayout(t *testing.T) {
	q := newSubmitted(t)
	p, err := q.ClaimPayout(builder, q.ReviewDeadline()+1)
	mustOK(t, err, "ClaimPayout")
	mustState(t, q, Paid)
	mustPayout(t, p, PayBuilder, builder, reward)
}

// --- plan section 10 cases ---

// 1. happy path: post, claim, submit, approve; payout is the reward to the builder.
func TestHappyPath(t *testing.T) {
	q := newOpen(t)
	mustOK(t, q.Claim(builder, h0+1), "claim")
	mustOK(t, q.Submit(builder, "https://example.com/pr", h0+2), "submit")
	p, err := q.Approve(poster, h0+3)
	mustOK(t, err, "approve")
	mustPayout(t, p, PayBuilder, builder, reward)
	mustState(t, q, Paid)
}

// 2. cancel an open quest: refund to the poster.  (see TestOpenCancel)
// 3. reject reopens, clears builder, counts.        (see TestSubmittedReject)

// 4. ClaimPayout fails up to and including the review deadline, works one block after.
func TestClaimPayoutDeadline(t *testing.T) {
	q := newSubmitted(t)
	d := q.ReviewDeadline()
	for _, h := range []int64{q.SubmittedAt(), d - 1, d} {
		_, err := q.ClaimPayout(builder, h)
		mustErr(t, ErrReviewDeadlineNotPassed, err, "ClaimPayout early")
		if q.CanClaimPayout(h) {
			t.Fatalf("CanClaimPayout(%d) must be false", h)
		}
	}
	mustState(t, q, Submitted)
	if !q.CanClaimPayout(d + 1) {
		t.Fatalf("CanClaimPayout(d+1) must be true")
	}
	_, err := q.ClaimPayout(builder, d+1)
	mustOK(t, err, "ClaimPayout at d+1")
	mustState(t, q, Paid)
}

// Reject is allowed up to and including the review deadline, not after.
func TestRejectDeadline(t *testing.T) {
	q := newSubmitted(t)
	d := q.ReviewDeadline()
	mustErr(t, ErrReviewDeadlinePassed, nopay(q.Reject(poster, "late", d+1)), "reject at d+1")
	mustState(t, q, Submitted)
	mustOK(t, nopay(q.Reject(poster, "on time", d)), "reject at d")

	q = newSubmitted(t)
	mustOK(t, nopay(q.Reject(poster, "early", q.ReviewDeadline()-1)), "reject at d-1")
}

// Approve stays possible after the review deadline (it pays the builder either way).
func TestApproveAfterReviewDeadline(t *testing.T) {
	q := newSubmitted(t)
	p, err := q.Approve(poster, q.ReviewDeadline()+1000)
	mustOK(t, err, "late approve")
	mustPayout(t, p, PayBuilder, builder, reward)
}

// 5. Release fails up to and including the work deadline, works one block after.
func TestReleaseDeadline(t *testing.T) {
	q := newClaimed(t)
	d := q.WorkDeadline()
	for _, h := range []int64{q.ClaimedAt(), d - 1, d} {
		mustErr(t, ErrWorkDeadlineNotPassed, nopay(q.Release(stranger, h)), "release early")
		if q.CanRelease(h) {
			t.Fatalf("CanRelease(%d) must be false", h)
		}
	}
	mustState(t, q, Claimed)
	if !q.CanRelease(d + 1) {
		t.Fatalf("CanRelease(d+1) must be true")
	}
	mustOK(t, nopay(q.Release(stranger, d+1)), "release at d+1")
	mustState(t, q, Open)
}

// Submit is allowed up to and including the work deadline, not after.
func TestSubmitDeadline(t *testing.T) {
	q := newClaimed(t)
	d := q.WorkDeadline()
	mustErr(t, ErrWorkDeadlinePassed, q.Submit(builder, "https://x.io", d+1), "submit at d+1")
	mustState(t, q, Claimed)
	mustOK(t, q.Submit(builder, "https://x.io", d), "submit at d")

	q = newClaimed(t)
	mustOK(t, q.Submit(builder, "https://x.io", q.WorkDeadline()-1), "submit at d-1")
}

// Release may be called by anyone, including the poster and the builder.
func TestReleaseByAnyone(t *testing.T) {
	for _, who := range []address{poster, builder, stranger} {
		q := newClaimed(t)
		mustOK(t, nopay(q.Release(who, q.WorkDeadline()+1)), "release by "+who.String())
	}
	q := newClaimed(t)
	mustErr(t, ErrInvalidActor, nopay(q.Release("", q.WorkDeadline()+1)), "release by empty")
}

// 6. a stranger cannot approve, reject, cancel, submit, unclaim or claim payout.
func TestStranger(t *testing.T) {
	q := newOpen(t)
	_, err := q.Cancel(stranger, h0+1)
	mustErr(t, ErrNotPoster, err, "stranger cancel")
	_, err = q.Cancel(builder, h0+1)
	mustErr(t, ErrNotPoster, err, "builder-to-be cancel")
	mustState(t, q, Open)

	q = newClaimed(t)
	mustErr(t, ErrNotBuilder, q.Submit(stranger, "https://x.io", h0+11), "stranger submit")
	mustErr(t, ErrNotBuilder, q.Submit(poster, "https://x.io", h0+11), "poster submit")
	mustErr(t, ErrNotBuilder, nopay(q.Unclaim(stranger, h0+11)), "stranger unclaim")
	mustErr(t, ErrNotBuilder, nopay(q.Unclaim(poster, h0+11)), "poster unclaim")
	mustState(t, q, Claimed)

	q = newSubmitted(t)
	_, err = q.Approve(stranger, h0+21)
	mustErr(t, ErrNotPoster, err, "stranger approve")
	_, err = q.Approve(builder, h0+21)
	mustErr(t, ErrNotPoster, err, "builder approve")
	mustErr(t, ErrNotPoster, nopay(q.Reject(stranger, "no", h0+21)), "stranger reject")
	mustErr(t, ErrNotPoster, nopay(q.Reject(builder, "no", h0+21)), "builder reject")
	_, err = q.ClaimPayout(stranger, q.ReviewDeadline()+1)
	mustErr(t, ErrNotBuilder, err, "stranger claim payout")
	_, err = q.ClaimPayout(poster, q.ReviewDeadline()+1)
	mustErr(t, ErrNotBuilder, err, "poster claim payout")
	mustState(t, q, Submitted)
}

// 7. the poster cannot claim their own quest.
func TestPosterCannotClaim(t *testing.T) {
	q := newOpen(t)
	mustErr(t, ErrPosterCannotClaim, q.Claim(poster, h0+1), "poster claim")
	mustErr(t, ErrInvalidActor, q.Claim("", h0+1), "empty claim")
	mustErr(t, ErrInvalidHeight, q.Claim(builder, h0-1), "claim before post")
	mustState(t, q, Open)
}

// 9. a payout cannot happen twice.
func TestNoDoublePayout(t *testing.T) {
	q := newSubmitted(t)
	_, err := q.Approve(poster, h0+30)
	mustOK(t, err, "approve")
	_, err = q.Approve(poster, h0+31)
	mustErr(t, ErrWrongState, err, "approve twice")
	_, err = q.ClaimPayout(builder, q.SubmittedAt()+ReviewBlocks+1)
	mustErr(t, ErrWrongState, err, "approve then claim payout")
	_, err = q.Cancel(poster, h0+32)
	mustErr(t, ErrWrongState, err, "approve then cancel")

	q = newSubmitted(t)
	_, err = q.ClaimPayout(builder, q.ReviewDeadline()+1)
	mustOK(t, err, "claim payout")
	_, err = q.ClaimPayout(builder, h0+ReviewBlocks+100)
	mustErr(t, ErrWrongState, err, "claim payout twice")
	_, err = q.Approve(poster, h0+ReviewBlocks+100)
	mustErr(t, ErrWrongState, err, "claim payout then approve")

	q = newOpen(t)
	_, err = q.Cancel(poster, h0+1)
	mustOK(t, err, "cancel")
	_, err = q.Cancel(poster, h0+2)
	mustErr(t, ErrWrongState, err, "cancel twice")
}

// 10. cancel after Claimed (and after Submitted) fails.
// 10. cancel after Claimed or Submitted does not refund: it only closes the
// quest (no coins move, the builder keeps their turn).
func TestCancelAfterClaimOnlyCloses(t *testing.T) {
	for _, q := range []*Quest{newClaimed(t), newSubmitted(t)} {
		st := q.State()
		p, err := q.Cancel(poster, h0+25)
		mustOK(t, err, "close")
		if p.Due() {
			t.Fatalf("closing must not pay: %+v", p)
		}
		mustState(t, q, st)
		if !q.Closing() || q.HoldsFunds() != true {
			t.Fatalf("closing quest must still hold the reward")
		}
	}
}

// --- closing ---

func newClosing(t *testing.T, mk func(*testing.T) *Quest) *Quest {
	t.Helper()
	q := mk(t)
	p, err := q.Cancel(poster, h0+25)
	mustOK(t, err, "close")
	if p.Due() || !q.Closing() {
		t.Fatalf("close: payout %+v closing %v", p, q.Closing())
	}
	return q
}

// afterRefund checks the quest ended Cancelled and refuses every move.
func afterRefund(t *testing.T, q *Quest, p Payout, what string) {
	t.Helper()
	mustPayout(t, p, RefundPoster, poster, reward)
	mustState(t, q, Cancelled)
	if q.HoldsFunds() || q.Builder() != "" {
		t.Fatalf("%s: cancelled quest must hold nothing and have no builder", what)
	}
	far := h0 + MaxWorkBlocks + ReviewBlocks + 10
	mustErr(t, ErrWrongState, q.Claim(builder2, far), what+": claim again")
	_, err := q.Cancel(poster, far)
	mustErr(t, ErrWrongState, err, what+": cancel again")
	_, err = q.Approve(poster, far)
	mustErr(t, ErrWrongState, err, what+": approve after refund")
	_, err = q.ClaimPayout(builder, far)
	mustErr(t, ErrWrongState, err, what+": payout after refund")
	_, err = q.Release(stranger, far)
	mustErr(t, ErrWrongState, err, what+": release after refund")
}

func TestCloseThenUnclaimRefunds(t *testing.T) {
	q := newClosing(t, newClaimed)
	p, err := q.Unclaim(builder, h0+30)
	mustOK(t, err, "unclaim while closing")
	afterRefund(t, q, p, "unclaim")
}

// A squatter holds a closing quest until the work deadline; then anyone can
// end it and the refund goes to the poster, not to the caller.
func TestCloseThenReleaseRefundsPoster(t *testing.T) {
	q := newClosing(t, newClaimed)
	_, err := q.Release(stranger, q.WorkDeadline())
	mustErr(t, ErrWorkDeadlineNotPassed, err, "release at deadline")
	mustState(t, q, Claimed)
	p, err := q.Release(stranger, q.WorkDeadline()+1)
	mustOK(t, err, "release after deadline")
	afterRefund(t, q, p, "release")
}

func TestCloseThenRejectRefunds(t *testing.T) {
	q := newClosing(t, newSubmitted)
	p, err := q.Reject(poster, "junk", h0+30)
	mustOK(t, err, "reject while closing")
	afterRefund(t, q, p, "reject")
	if q.RejectCount() != 1 || q.LastRejectReason() != "junk" {
		t.Fatalf("reject while closing must still be recorded")
	}
}

// The builder who holds a closing quest keeps every right.
func TestCloseKeepsBuilderRights(t *testing.T) {
	q := newClosing(t, newClaimed)
	mustOK(t, q.Submit(builder, "https://example.com/w", h0+30), "submit while closing")
	p, err := q.Approve(poster, h0+31)
	mustOK(t, err, "approve while closing")
	mustPayout(t, p, PayBuilder, builder, reward)
	mustState(t, q, Paid)

	q = newClosing(t, newSubmitted)
	p, err = q.ClaimPayout(builder, q.ReviewDeadline()+1)
	mustOK(t, err, "timeout payout while closing")
	mustPayout(t, p, PayBuilder, builder, reward)
	mustState(t, q, Paid)
}

func TestCloseRules(t *testing.T) {
	q := newClaimed(t)
	_, err := q.Cancel(stranger, h0+20)
	mustErr(t, ErrNotPoster, err, "stranger close")
	_, err = q.Cancel(builder, h0+20)
	mustErr(t, ErrNotPoster, err, "builder close")
	if q.Closing() {
		t.Fatalf("refused close must not mark the quest")
	}
	q = newClosing(t, newClaimed)
	_, err = q.Cancel(poster, h0+26)
	mustErr(t, ErrAlreadyClosing, err, "close twice")
	if newOpen(t).Closing() {
		t.Fatalf("open quest is not closing")
	}
	// cancelling an Open quest is immediate and never "closing"
	o := newOpen(t)
	p, err := o.Cancel(poster, h0+1)
	mustOK(t, err, "cancel open")
	if o.Closing() {
		t.Fatalf("open cancel must not set closing")
	}
	mustPayout(t, p, RefundPoster, poster, reward)
}

// Without closing, the moves that reopen a quest never pay.
func TestReopenMovesNeverPay(t *testing.T) {
	q := newClaimed(t)
	mustOK(t, nopay(q.Unclaim(builder, h0+11)), "unclaim")
	mustState(t, q, Open)
	q = newClaimed(t)
	mustOK(t, nopay(q.Release(stranger, q.WorkDeadline()+1)), "release")
	mustState(t, q, Open)
	q = newSubmitted(t)
	mustOK(t, nopay(q.Reject(poster, "no", h0+21)), "reject")
	mustState(t, q, Open)
}

// The timeout rule, documented: a builder who submits anything (even junk)
// is paid after the review window if the poster does nothing. A reject at the
// last block of the window prevents it.
func TestJunkSubmissionTimeout(t *testing.T) {
	q := newClaimed(t)
	mustOK(t, q.Submit(builder, "https://x", h0+11), "junk submit")
	p, err := q.ClaimPayout(builder, q.ReviewDeadline()+1)
	mustOK(t, err, "silent poster")
	mustPayout(t, p, PayBuilder, builder, reward)

	q = newClaimed(t)
	mustOK(t, q.Submit(builder, "https://x", h0+11), "junk submit")
	mustOK(t, nopay(q.Reject(poster, "junk", q.ReviewDeadline())), "reject at the last block")
	_, err = q.ClaimPayout(builder, q.SubmittedAt()+ReviewBlocks+1)
	mustErr(t, ErrWrongState, err, "no payout after reject")
}

// 11. text over the limits fails; a link without https:// fails.
func TestLinkAndReasonValidation(t *testing.T) {
	bad := []struct {
		link string
		want error
	}{
		{"", ErrLinkEmpty},
		{"http://example.com", ErrLinkNotHTTPS},
		{"HTTPS://example.com", ErrLinkNotHTTPS},
		{"ftp://example.com", ErrLinkNotHTTPS},
		{"example.com", ErrLinkNotHTTPS},
		{"https://", ErrLinkNotHTTPS},
		{" https://example.com", ErrLinkNotHTTPS},
		{"javascript:alert(1)", ErrLinkNotHTTPS},
		{"https://example.com/a b", ErrLinkInvalid},
		{"https://example.com/\nx", ErrLinkInvalid},
		{"https://example.com/\x7f", ErrLinkInvalid},
		{"https://" + strings.Repeat("a", MaxLinkLen-len("https://")+1), ErrLinkTooLong},
	}
	for _, c := range bad {
		q := newClaimed(t)
		mustErr(t, c.want, q.Submit(builder, c.link, h0+20), "link "+c.link)
		mustState(t, q, Claimed)
	}
	q := newClaimed(t)
	mustOK(t, q.Submit(builder, "https://"+strings.Repeat("a", MaxLinkLen-len("https://")), h0+20), "link at max")

	q = newSubmitted(t)
	mustErr(t, ErrReasonEmpty, nopay(q.Reject(poster, "", h0+30)), "empty reason")
	mustErr(t, ErrReasonEmpty, nopay(q.Reject(poster, " \t", h0+30)), "blank reason")
	mustErr(t, ErrReasonTooLong, nopay(q.Reject(poster, strings.Repeat("r", MaxReasonLen+1), h0+30)), "long reason")
	mustState(t, q, Submitted)
	mustOK(t, nopay(q.Reject(poster, strings.Repeat("r", MaxReasonLen), h0+30)), "reason at max")
}

// --- at least one illegal move from every state (rule 8) ---

func TestIllegalMovesPerState(t *testing.T) {
	far := h0 + MaxWorkBlocks + ReviewBlocks + 10 // past every deadline
	type move struct {
		name string
		do   func(q *Quest) error
	}
	pay := func(p Payout, err error) error { return err }
	moves := []move{
		{"Claim", func(q *Quest) error { return q.Claim(builder2, far) }},
		{"Cancel", func(q *Quest) error { return pay(q.Cancel(poster, far)) }},
		{"Submit", func(q *Quest) error { return q.Submit(q.Builder(), "https://x.io", q.ClaimedAt()+1) }},
		{"Unclaim", func(q *Quest) error { return nopay(q.Unclaim(q.Builder(), far)) }},
		{"Release", func(q *Quest) error { return nopay(q.Release(stranger, far)) }},
		{"Approve", func(q *Quest) error { return pay(q.Approve(poster, far)) }},
		{"Reject", func(q *Quest) error { return nopay(q.Reject(poster, "no", q.SubmittedAt()+1)) }},
		{"ClaimPayout", func(q *Quest) error { return pay(q.ClaimPayout(q.Builder(), far)) }},
	}
	// allowed moves per state (section 4); everything else must be ErrWrongState
	allowed := map[State]map[string]bool{
		Open:      {"Claim": true, "Cancel": true},
		Claimed:   {"Submit": true, "Unclaim": true, "Release": true, "Cancel": true},
		Submitted: {"Approve": true, "Reject": true, "ClaimPayout": true, "Cancel": true},
		Paid:      {},
		Cancelled: {},
	}
	makers := map[State]func(*testing.T) *Quest{
		Open:      newOpen,
		Claimed:   newClaimed,
		Submitted: newSubmitted,
		Paid:      newPaid,
		Cancelled: newCancelled,
	}
	for _, st := range []State{Open, Claimed, Submitted, Paid, Cancelled} {
		for _, m := range moves {
			q := makers[st](t)
			err := m.do(q)
			if allowed[st][m.name] {
				if err != nil {
					t.Errorf("%s from %s: want ok, got %v", m.name, st, err)
				}
				continue
			}
			if err != ErrWrongState {
				t.Errorf("%s from %s: want ErrWrongState, got %v", m.name, st, err)
			}
			if q.State() != st {
				t.Errorf("%s from %s: state changed to %s", m.name, st, q.State())
			}
		}
	}
}

// --- escrow accounting at package level (towards rule 12) ---

func TestHeldFundsAccounting(t *testing.T) {
	var qs []*Quest
	held := int64(0) // what a realm would hold
	post := func(r int64) *Quest {
		q, err := NewQuest(uint64(len(qs)+1), poster, "q", "", r, workBlocks, h0)
		mustOK(t, err, "post")
		qs = append(qs, q)
		held += r
		return q
	}
	pay := func(p Payout, err error) {
		mustOK(t, err, "payout move")
		held -= p.Amount
	}
	a, b, c, d, e := post(1), post(20), post(300), post(4000), post(50000)
	pay(a.Cancel(poster, h0+1))
	mustOK(t, b.Claim(builder, h0+1), "b claim")
	mustOK(t, b.Submit(builder, "https://x.io", h0+2), "b submit")
	pay(b.Approve(poster, h0+3))
	mustOK(t, c.Claim(builder, h0+1), "c claim")
	mustOK(t, c.Submit(builder, "https://x.io", h0+2), "c submit")
	pay(c.ClaimPayout(builder, c.ReviewDeadline()+1))
	mustOK(t, d.Claim(builder, h0+1), "d claim")
	mustOK(t, nopay(d.Release(stranger, d.WorkDeadline()+1)), "d release")
	mustOK(t, e.Claim(builder2, h0+1), "e claim")
	mustOK(t, e.Submit(builder2, "https://x.io", h0+2), "e submit")
	mustOK(t, nopay(e.Reject(poster, "no", h0+3)), "e reject")

	sum := int64(0)
	for _, q := range qs {
		if q.HoldsFunds() {
			sum += q.Reward()
		}
	}
	if sum != held || held != 4000+50000 {
		t.Fatalf("held %d, sum of open escrows %d", held, sum)
	}
}

func TestStateStrings(t *testing.T) {
	names := map[State]string{Open: "Open", Claimed: "Claimed", Submitted: "Submitted", Paid: "Paid", Cancelled: "Cancelled", State(0): "Unknown"}
	for s, n := range names {
		if s.String() != n {
			t.Errorf("State(%d).String() = %q, want %q", s, s.String(), n)
		}
	}
	if !Paid.IsFinal() || !Cancelled.IsFinal() || Open.IsFinal() || Claimed.IsFinal() || Submitted.IsFinal() {
		t.Errorf("IsFinal wrong")
	}
	if PayBuilder.String() != "PayBuilder" || RefundPoster.String() != "RefundPoster" {
		t.Errorf("PayoutKind strings wrong")
	}
}

// PKGPATH: gno.land/r/example/bounty

// This is the "Using p/escrow in your own realm" example from README.md, kept
// here so that `gno test` compiles and runs it. The realm part (everything
// above main) is what the README shows; main plays two users through one
// quest and prints the result.
package bounty

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"testing"

	"gno.land/p/g1llc3lq3zmjtjdk29dk52munrzxt5ne746cl7r8/escrow"
	"gno.land/p/nt/avl/v0"
)

var (
	quests avl.Tree // id -> *escrow.Quest
	lastID uint64
)

// Post locks the ugnot sent with the call as the reward.
func Post(cur realm, title string, workBlocks int64) uint64 {
	if !cur.Previous().IsUserCall() {
		panic("direct user calls only")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != "ugnot" {
		panic("send the reward as one ugnot coin")
	}
	lastID++
	q, err := escrow.NewQuest(lastID, cur.Previous().Address(), title, "", sent[0].Amount, workBlocks, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	quests.Set(strconv.FormatUint(lastID, 10), q)
	return lastID
}

func Claim(cur realm, id uint64) {
	check(get(id).Claim(cur.Previous().Address(), runtime.ChainHeight()))
}

func Submit(cur realm, id uint64, link string) {
	check(get(id).Submit(cur.Previous().Address(), link, runtime.ChainHeight()))
}

// Approve applies the move first, then pays exactly what the escrow says.
func Approve(cur realm, id uint64) {
	p, err := get(id).Approve(cur.Previous().Address(), runtime.ChainHeight())
	check(err)
	pay(p, cur)
}

func pay(p escrow.Payout, rlm realm) {
	b := banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	b.SendCoins(rlm.Address(), p.To, chain.Coins{{Denom: "ugnot", Amount: p.Amount}})
}

func get(id uint64) *escrow.Quest {
	v := quests.Get(strconv.FormatUint(id, 10))
	if v == nil {
		panic("unknown quest")
	}
	return v.(*escrow.Quest)
}

func check(err error) {
	if err != nil {
		panic(err.Error())
	}
}

// ---- test driver (not part of the README example)

func main(cur realm) {
	poster := address("g1jg8mtutu9khhfwc4nxmuhcpftf0pajdhfvsqf5")
	builder := address("g1us8428u2a5satrlxzagqqa5m6vmuze025anjlj")
	reward := chain.Coins{{Denom: "ugnot", Amount: 2_000_000}}
	testing.IssueCoins(cur.Address(), reward) // what -send does on chain

	testing.SetRealm(testing.NewUserRealm(poster))
	testing.SetOriginSend(reward)
	id := Post(cross(cur), "Write a guide", escrow.MinWorkBlocks)
	testing.SetOriginSend(nil)

	testing.SetRealm(testing.NewUserRealm(builder))
	Claim(cross(cur), id)
	Submit(cross(cur), id, "https://example.com/guide")

	testing.SetRealm(testing.NewUserRealm(poster))
	Approve(cross(cur), id)

	bk := banker.NewReadonlyBanker()
	println(get(id).State().String(), bk.GetCoin(builder, "ugnot"), bk.GetCoin(cur.Address(), "ugnot"))
}

