	uassert.Equal(t, bobBefore+4*gnot, bal(bob))
	uassert.Equal(t, realmBefore-4*gnot, bal(realmAddr))
	uassert.Equal(t, escrow.Paid.String(), GetQuest(id).State.String())
	checkInvariants(t, "timeout payout")
}

